    protected override void OnCreate(Bundle? savedInstanceState)
    {
        base.OnCreate(savedInstanceState);

        // Initialize the settings store before the ViewportSurfaceView is
        // created so the first renderer appearance can be hydrated from
        // persisted values.
        AppSettings.Initialize(ApplicationContext!);
        _lastInteractiveMeasureMode = MeasureModeFromSettings();
        global::Android.Util.Log.Info("FA.Cloud", "Using FA Cloud config: " + AppSettings.CloudServerConfigPath);
#if DEBUG
        if (AppSettings.CloudServerUrl.StartsWith("http://", StringComparison.OrdinalIgnoreCase))
            global::Android.Util.Log.Warn("FA.Cloud", "Debug build is configured for cleartext FA Cloud HTTP: " + AppSettings.CloudServerUrl);
#endif

        _services = AppServices.Build(ApplicationContext!);
        _import = _services.GetRequiredService<ImportPipeline>();
        _cloudClient = _services.GetRequiredService<CloudApiClient>();
        _cloudClient.SessionChanged += OnCloudSessionChanged;
        _cloudNotifications = _services.GetRequiredService<CloudNotificationClient>();
        _cloudNotifications.EventReceived += OnCloudNotificationReceived;
        _cloudClient.PurgeCloudOpenCache();
        _import.DeleteCloudImportCacheFiles();
        _viewerStateSave = new AndroidViewerStateSaveService();
        _camera = _services.GetRequiredService<CameraState>();
        _sections = _services.GetRequiredService<SectionService>();
        _sections.FillVisible = AppSettings.SectionFillVisible;
        _sections.EdgesVisible = AppSettings.SectionEdgesVisible;
        _sections.Changed += OnSectionsChanged;
        _bodyMove = new BodyMoveService(() => _runtimeScene);
        _bodyMove.MovesCommitted += OnBodyMovesCommitted;
        _packageSession = _services.GetRequiredService<PackageSessionState>();
        _undoSelectionState = new SelectionState();
        _undoSelectionState.SelectionChanged += OnUndoSelectionChanged;
        _visibilityStateAccess = new AndroidVisibilityStateAccess(this);
        _measurementStoreAccess = new AndroidMeasurementStoreAccess(this);
        _undoService = new UndoService(new SceneContext(
            () => _runtimeScene,
            _undoSelectionState,
            _visibilityStateAccess,
            _sections,
            _bodyMove,
            _measurementStoreAccess));
        _undoService.HistoryChanged += OnUndoHistoryChanged;
        _undoService.UndoFailed += OnUndoFailed;
        CaptureSavedViewerState(savedInstanceState);

        SetContentView(Resource.Layout.activity_main);
        _picker = new SafFilePicker(this);
        CreateLoadingOverlay();
        BindViewportChrome();
        BindLeftToolPanel();

        var container = FindViewById<FrameLayout>(Resource.Id.viewportContainer)
            ?? throw new InvalidOperationException("viewportContainer not found");

        _viewport = new ViewportSurfaceView(this);
        _viewport.Renderer.Camera = _camera;
        _viewport.RendererSurfaceCreated += OnViewportSurfaceCreated;
        container.AddView(_viewport, new FrameLayout.LayoutParams(
            ViewGroup.LayoutParams.MatchParent,
            ViewGroup.LayoutParams.MatchParent));

        _measurementLabelLayer = new MeasurementLabelLayer(this, this)
        {
            Clickable = false,
            Focusable = false,
        };
        container.AddView(_measurementLabelLayer, new FrameLayout.LayoutParams(
            ViewGroup.LayoutParams.MatchParent,
            ViewGroup.LayoutParams.MatchParent));

        _zoomWindowOverlay = new ZoomWindowOverlayView(this)
        {
            Visibility = ViewStates.Gone,
            Clickable = false,
            Focusable = false,
        };
        container.AddView(_zoomWindowOverlay, new FrameLayout.LayoutParams(
            ViewGroup.LayoutParams.MatchParent,
            ViewGroup.LayoutParams.MatchParent));
        _contextMenuAnchor = new View(this)
        {
            Alpha = 0f,
            Clickable = false,
            Focusable = false,
            ImportantForAccessibility = ImportantForAccessibility.No,
        };
        container.AddView(_contextMenuAnchor, new FrameLayout.LayoutParams(1, 1));
        CreateRenderBusyOverlay(container);

        // Touch input: pointer source feeds the gesture recognizer, the
        // adapter translates recognized events into CameraState calls.
        _pointerSource = new AndroidPointerSource(this);
        ApplySpenPalmRejectionState(showToast: false);
        _interaction = new ViewportInteractionAdapter(
            _camera,
            boundsAccessor: () => GetVisibleSceneBounds(),
            aspectAccessor: () => _viewport is { Width: > 0, Height: > 0 }
                ? (double)_viewport.Width / _viewport.Height
                : 1.0,
            requestRender: () => _viewport?.RequestRender(),
            interactionStateChanged: SetInteractiveNavigationActive,
            pivotPicker: PickPivotAt,
            viewportWidthDipAccessor: GetViewportWidthDip,
            isFixedViewLockedAccessor: () => _isInFixedView,
            isNavigationSuppressedAccessor: ShouldSuppressNavigationGestures,
            clipBoundsAccessor: () => GetCameraClipBounds(),
            isDoubleTapFitEnabledAccessor: () => AppSettings.DoubleTapFitScreenEnabled);
        _pointerSource.GestureRecognized += OnGestureForToolbarTools;
        _pointerSource.GestureRecognized += OnGestureForNavigation;
        _pointerSource.GestureRecognized += OnGestureForSelection;
        _viewport.SetOnTouchListener(new TouchProxy(_pointerSource, this));
        _viewport.SetOnHoverListener(new HoverProxy(this));
        _viewport.SetOnGenericMotionListener(new GenericMotionProxy(_pointerSource, this));

        _measure = new AndroidMeasureIntegration(
            () => _runtimeScene,
            RefreshMeasurementOverlays,
            GetActiveSectionPlanes,
            _undoService);
        ApplyMeasurementSettings();
        _sectionRaycaster = new AndroidMeasureRaycaster(() => _runtimeScene, GetActiveSectionPlanes);
        _sectionSnapPicker = new MeshMeasurePicker(
            _sectionRaycaster,
            MeasurementTolerances.Default,
            AndroidMeasureIntegration.AndroidEdgeSnapAngularTolerance,
            AndroidMeasureIntegration.AndroidEndpointSnapAngularTolerance);
        _camera.PropertyChanged += OnCameraChanged;
        global::Android.Util.Log.Info("FA.Measure", "Measurement diagnostics ready.");

        _navOpenButton = FindViewById<MaterialButton>(Resource.Id.navOpenButton);
        if (_navOpenButton is not null) _navOpenButton.Click += OnOpenClicked;

        _navRecentButton = FindViewById<MaterialButton>(Resource.Id.navRecentButton);
        if (_navRecentButton is not null) _navRecentButton.Click += OnRecentClicked;

        _navCloudButton = FindViewById<MaterialButton>(Resource.Id.navCloudButton);
        if (_navCloudButton is not null) _navCloudButton.Click += OnCloudClicked;

        _navUndoButton = FindViewById<MaterialButton>(Resource.Id.navUndoButton);
        if (_navUndoButton is not null) _navUndoButton.Click += OnUndoClicked;

        _navRedoButton = FindViewById<MaterialButton>(Resource.Id.navRedoButton);
        if (_navRedoButton is not null) _navRedoButton.Click += OnRedoClicked;

        _navModelExplorerButton = FindViewById<MaterialButton>(Resource.Id.navModelExplorerButton);
        if (_navModelExplorerButton is not null) _navModelExplorerButton.Click += OnModelExplorerClicked;

        _navBomButton = FindViewById<MaterialButton>(Resource.Id.navBomButton);
        if (_navBomButton is not null) _navBomButton.Click += OnBomClicked;

        _navBomFlatButton = FindViewById<MaterialButton>(Resource.Id.navBomFlatButton);
        if (_navBomFlatButton is not null) _navBomFlatButton.Click += OnBomFlatClicked;

        _navSpenPalmButton = FindViewById<MaterialButton>(Resource.Id.navSpenPalmButton);
        if (_navSpenPalmButton is not null)
        {
            _navSpenPalmButton.Click += OnSpenPalmClicked;
            _navSpenPalmButton.Visibility = HasStylusInputDevice()
                ? ViewStates.Visible
                : ViewStates.Gone;
        }

        _navSettingsButton = FindViewById<MaterialButton>(Resource.Id.navSettingsButton);
        if (_navSettingsButton is not null)
            _navSettingsButton.Click += OnSettingsClicked;

        _cloudAccountButton = FindViewById<MaterialButton>(Resource.Id.cloudAccountButton);
        if (_cloudAccountButton is not null)
            _cloudAccountButton.Click += OnCloudAccountClicked;
        _saveButton = FindViewById<MaterialButton>(Resource.Id.saveButton);
        if (_saveButton is not null)
            _saveButton.Click += OnSaveClicked;
        UpdateCloudAccountButton();
        UpdateUndoRedoButtons();
        UpdateSaveButton();
        RestoreCloudSessionFromRefreshToken();

        BindPropertiesPanel();

        BindBottomToolbar();

        // All supported window sizes use the persistent side toolbar.
#if DEBUG
        if (!TryLoadDebugIntentModel(Intent))
            RestoreSavedModel(savedInstanceState);
#else
        RestoreSavedModel(savedInstanceState);
#endif
    }

    public override bool DispatchTouchEvent(MotionEvent? ev)
    {
        TrackMouseTouchDispatch(ev);
        return base.DispatchTouchEvent(ev);
    }

    public override bool DispatchGenericMotionEvent(MotionEvent? ev)
    {
        if (base.DispatchGenericMotionEvent(ev))
            return true;

        return HandleUnhandledMouseClick(ev);
    }

#if DEBUG
    protected override void OnNewIntent(Intent? intent)
    {
        base.OnNewIntent(intent);
        TryLoadDebugIntentModel(intent);
    }

    private bool TryLoadDebugIntentModel(Intent? intent)
    {
        string? uriText = intent?.GetStringExtra(DebugIntentModelUriExtra);
        AndroidUri? uri = !string.IsNullOrWhiteSpace(uriText)
            ? AndroidUri.Parse(uriText)
            : intent?.Data;
        if (uri is null)
            return false;

        _lastLoadedUriText = uri.ToString();
        global::Android.Util.Log.Info("FA.Import", "Loading debug intent model: " + uri);
        ObserveLifecycleTask(OpenModelUriAsync(uri), "debug-intent-model");
        return true;
    }
#endif

    private void CaptureSavedViewerState(Bundle? savedInstanceState)
    {
        if (savedInstanceState is null)
            return;

        _activeModelDisplayName = savedInstanceState.GetString(SavedStateModelDisplayNameKey);
        _pendingRestoredSectionPlanes = savedInstanceState.GetStringArray(SavedStateSectionPlanesKey);
        _pendingRestoredSelectedSectionPlanes = savedInstanceState.GetStringArray(SavedStateSelectedSectionPlanesKey);
        _pendingRestoredPackageId = savedInstanceState.GetString(SavedStatePackageIdKey);
        _pendingRestoredHiddenOccurrences = savedInstanceState.GetStringArray(SavedStateHiddenOccurrencesKey);
        _pendingRestoredIsolatedOccurrences = savedInstanceState.GetStringArray(SavedStateIsolatedOccurrencesKey);
        _pendingRestoredCamera = savedInstanceState.GetDoubleArray(SavedStateCameraKey);
        _pendingRestoredSelectedNodeIds = savedInstanceState.GetIntArray(SavedStateSelectedNodeIdsKey);
        _pendingRestoredSelectedOccurrences = savedInstanceState.GetStringArray(SavedStateSelectedOccurrencesKey);
        if (savedInstanceState.ContainsKey(SavedStateExplodeAmountKey))
            _pendingRestoredExplodeAmount = savedInstanceState.GetDouble(SavedStateExplodeAmountKey);
        string? sectionSubMode = savedInstanceState.GetString(SavedStateSectionSubModeKey);
        if (!string.IsNullOrWhiteSpace(sectionSubMode)
            && Enum.TryParse(sectionSubMode, ignoreCase: false, out SectionSubMode parsedSubMode))
        {
            _pendingRestoredSectionSubMode = parsedSubMode;
        }
    }

    private void OnUndoFailed(UndoFailureInfo info)
        => global::Android.Util.Log.Warn(
            "FA.Undo",
            $"Undo failed: label={info.Label}, subsystem={info.Subsystem}, error={info.Exception.Message}");

    private void OnUndoHistoryChanged()
    {
        if (Looper.MyLooper() == Looper.MainLooper)
        {
            UpdateUndoRedoButtons();
            return;
        }

        RunOnUiThread(UpdateUndoRedoButtons);
    }

    private Task RunOnUiThreadAsync(Action action)
    {
        if (Looper.MyLooper() == Looper.MainLooper)
        {
            action();
            return Task.CompletedTask;
        }

        var tcs = new TaskCompletionSource<object?>(TaskCreationOptions.RunContinuationsAsynchronously);
        RunOnUiThread(() =>
        {
            try
            {
                action();
                tcs.TrySetResult(null);
            }
            catch (Exception ex)
            {
                tcs.TrySetException(ex);
            }
        });
        return tcs.Task;
    }

    private void OnUndoSelectionChanged(object? sender, SelectionChangedEventArgs e)
    {
        if (_syncingUndoSelectionState || _undoSelectionState is null)
            return;

        if (Looper.MyLooper() != Looper.MainLooper)
        {
            RunOnUiThread(() => OnUndoSelectionChanged(sender, e));
            return;
        }

        ReplaceSelectedNodeIds(
            _runtimeScene,
            _undoSelectionState.SelectedNodeIds,
            scrollModelExplorerToSelection: false);
    }

    private void RestoreSavedModel(Bundle? savedInstanceState)
    {
        string? uriText = savedInstanceState?.GetString(SavedStateLastLoadedUriKey);
        if (string.IsNullOrWhiteSpace(uriText))
            return;
        if (IsCloudTempUriText(uriText))
        {
            _lastLoadedUriText = null;
            return;
        }

        _lastLoadedUriText = uriText;
        AndroidUri? uri = AndroidUri.Parse(uriText);
        if (uri is null)
            return;

        global::Android.Util.Log.Info("FA.Import", "Restoring last model after activity recreation.");
        ObserveLifecycleTask(OpenModelUriAsync(uri), "restore-saved-model");
    }

