    private void SetPropertiesPanelExpanded(bool expanded)
    {
        bool hasPanel = _propertiesPanel is not null || _propertiesPanelDivider is not null;
        _propertiesPanelExpanded = expanded && hasPanel;
        ViewStates visibility = _propertiesPanelExpanded ? ViewStates.Visible : ViewStates.Gone;

        if (_propertiesPanel is not null)
            _propertiesPanel.Visibility = visibility;

        if (_propertiesPanelDivider is not null)
            _propertiesPanelDivider.Visibility = visibility;

        if (_propertiesToggle is not null)
        {
            _propertiesToggle.Selected = _propertiesPanelExpanded;
            _propertiesToggle.Rotation = _propertiesPanelExpanded ? 0f : 180f;
            _propertiesToggle.ContentDescription = GetString(_propertiesPanelExpanded
                ? Resource.String.cd_close_properties
                : Resource.String.cd_open_properties);
        }
    }

    private void SetPropertiesPanelWidth(int widthPx)
    {
        _propertiesPanelWidthPx = ClampPropertiesPanelWidth(widthPx);

        if (_propertiesPanel?.LayoutParameters is ViewGroup.LayoutParams layoutParams)
        {
            if (layoutParams.Width == _propertiesPanelWidthPx)
                return;

            layoutParams.Width = _propertiesPanelWidthPx;
            _propertiesPanel.LayoutParameters = layoutParams;
            _propertiesPanel.RequestLayout();
            _viewport?.RequestLayout();
            _viewport?.Post(() => _viewport?.RequestRender());
        }
    }

    private int ClampPropertiesPanelWidth(int requestedWidth)
    {
        int min = Resources?.GetDimensionPixelSize(Resource.Dimension.fa_properties_panel_min_width) ?? Dp(240);
        int configuredMax = Resources?.GetDimensionPixelSize(Resource.Dimension.fa_properties_panel_max_width) ?? Dp(560);
        int max = configuredMax;

        if (_propertiesPanel?.Parent is View parent && parent.Width > 0)
        {
            int navWidth = _navRail?.Visibility == ViewStates.Visible ? _navRail.Width : 0;
            int navDividerWidth = _navRailDivider?.Visibility == ViewStates.Visible ? _navRailDivider.Width : 0;
            int minViewportWidth = Dp(160);
            int available = parent.Width - navWidth - navDividerWidth - minViewportWidth;
            int boundedMin = Math.Min(min, Math.Max(1, available));
            int boundedMax = Math.Min(configuredMax, Math.Max(boundedMin, available));
            return Math.Max(boundedMin, Math.Min(requestedWidth, boundedMax));
        }

        int displayWidth = Resources?.DisplayMetrics?.WidthPixels ?? 0;
        if (displayWidth > 0)
        {
            int minViewportWidth = Dp(160);
            int available = displayWidth - minViewportWidth;
            int boundedMin = Math.Min(min, Math.Max(1, available));
            max = Math.Min(configuredMax, Math.Max(boundedMin, available));
            return Math.Max(boundedMin, Math.Min(requestedWidth, max));
        }

        return Math.Max(min, Math.Min(requestedWidth, max));
    }

    private void OnFitClicked(object? sender, EventArgs e)
    {
        if (_isInFixedView && _activeFixedView is { } activeView)
        {
            SetStandardView(activeView, fitAll: true);
            return;
        }

        if (_camera is null)
            return;

        BoundingBox fitBounds = GetVisibleSceneBounds();
        if (!fitBounds.IsValid)
            return;

        double aspect = GetViewportAspect();
        BoundingBox clipBounds = GetCameraClipBounds();
        lock (_camera)
        {
            FitCameraToBoundsPreservingView(_camera, fitBounds, aspect);
            if (clipBounds.IsValid)
                AndroidCameraClipPlanes.Update(_camera, clipBounds);
        }

        RefreshMeasurementOverlays();
        _viewport?.RequestRender();
        global::Android.Util.Log.Info("FA.Toolbar", $"Fit view: diag={fitBounds.Diagonal:0.###}.");
    }

    private void SetInteractiveNavigationActive(bool active)
    {
        ViewportSurfaceView? viewport = _viewport;
        if (viewport is null)
            return;

        string source = DescribeLastNavigationGesture();
        LogSectionCapUiDiagnostic(
            $"interactive navigation request: active={active}, source={source}, version={_interactiveNavigationVersion}, rendererActive={viewport.Renderer.InteractiveNavigationActive}");

        if (active)
        {
            _interactiveNavigationVersion++;
            ApplyInteractiveNavigationActive(viewport, true, source);
            return;
        }

        int version = ++_interactiveNavigationVersion;
        viewport.PostDelayed(() =>
        {
            if (_isDestroyed || _interactiveNavigationVersion != version)
            {
                LogSectionCapUiDiagnostic(
                    $"interactive navigation deactivation skipped: staleVersion={version}, currentVersion={_interactiveNavigationVersion}, destroyed={_isDestroyed}, source={source}");
                return;
            }
            ApplyInteractiveNavigationActive(viewport, false, source);
        }, 220);
    }

    private void ApplyInteractiveNavigationActive(ViewportSurfaceView viewport, bool active, string source)
    {
        if (viewport.Renderer.InteractiveNavigationActive == active)
        {
            LogSectionCapUiDiagnostic(
                $"interactive navigation unchanged: active={active}, source={source}");
            return;
        }

        LogSectionCapUiDiagnostic(
            $"interactive navigation applied: active={active}, source={source}");
        viewport.Renderer.InteractiveNavigationActive = active;
        viewport.RequestRender();
    }

    private string DescribeLastNavigationGesture()
    {
        if (_lastNavigationGestureKind is not { } kind)
            return "none";

        double ageMs = _lastNavigationGestureTicks == 0
            ? -1.0
            : (Stopwatch.GetTimestamp() - _lastNavigationGestureTicks) * 1000.0 / Stopwatch.Frequency;
        return $"{kind}@({_lastNavigationGesturePositionDip.X:0.#},{_lastNavigationGesturePositionDip.Y:0.#}) ageMs={ageMs:0.0}";
    }

    private bool ShouldLogSectionCapUiDiagnostics()
        => AppSettings.SectionCurvesVisible
           || AppSettings.SectionCapsVisible
           || (_sections?.Planes.Count ?? 0) > 0;

    private void LogSectionCapUiDiagnostic(string message)
    {
        if (!ShouldLogSectionCapUiDiagnostics())
            return;

        global::Android.Util.Log.Info(
            "FA.SectionCap",
            $"ui: {message}, curves={AppSettings.SectionCurvesVisible}, caps={AppSettings.SectionCapsVisible}, sectionPlanes={_sections?.Planes.Count ?? 0}, activeTool={_activeModalTool}, sectionSubMode={_activeSectionSubMode}.");
    }

