    private void ToggleRecentPanel()
    {
        if (IsImportUiBusy())
            return;

        if (_leftToolPanelKind == LeftToolPanelKind.Recent)
        {
            SetLeftToolPanelExpanded(false, animate: true);
            return;
        }

        var panel = new RecentFilesBottomSheet
        {
            OnRecentFileSelected = entry =>
            {
                SetLeftToolPanelExpanded(false, animate: true);
                _ = OpenRecentFileAsync(entry);
            },
        };
        ShowLeftToolPanel(LeftToolPanelKind.Recent, panel.CreateEmbeddedView(this), panel);
    }

    private void ToggleCloudPanel()
    {
        if (IsImportUiBusy())
            return;

        if (_leftToolPanelKind == LeftToolPanelKind.Cloud)
        {
            SetLeftToolPanelExpanded(false, animate: true);
            return;
        }

        if (_cloudClient is null)
            return;

        var panel = new CloudFilesPanel(_cloudClient)
        {
            SignInRequested = ShowCloudAccountDialog,
            PackageSelected = package =>
            {
                SetLeftToolPanelExpanded(false, animate: true);
                ObserveLifecycleTask(OpenCloudPackageAsync(package), "open-cloud-package");
            },
            PackageCounterSelected = (package, counter) =>
            {
                SetLeftToolPanelExpanded(false, animate: true);
                ObserveLifecycleTask(OpenCloudPackageAsync(package, counter), "open-cloud-package-counter");
            },
        };
        _cloudPanel = panel;
        ShowLeftToolPanel(LeftToolPanelKind.Cloud, panel.CreateView(this), panel);
    }

    private void OnCloudSessionChanged()
    {
        RunOnUiThread(() =>
        {
            if (_cloudClient?.IsSignedIn != true)
            {
                _cloudReloadAvailablePackageId = null;
                _cloudReloadAvailableCounter = null;
                ObserveLifecycleTask(_cloudNotifications?.StopAsync() ?? Task.CompletedTask, "cloud-notifications-stop");
                if (_activeCloudSession is not null)
                {
                    BeginCloudSessionEnded(
                        "Cloud session ended",
                        "Your FA Cloud session ended. Sign in again to continue.",
                        "cloud session ended");
                }
                else
                {
                    PurgeTransientCloudCache();
                }
            }

            UpdateCloudAccountButton();
            UpdateSaveButton();
            _cloudPanel?.Refresh();
        });
    }

    private void OnCloudNotificationReceived(CloudNotificationEnvelope envelope)
    {
        string eventName = envelope.Event ?? "";
        string? scopeType = envelope.Scope?.Type;
        string? scopeId = envelope.Scope?.Id;
        global::Android.Util.Log.Info(
            "FA.Cloud.SignalR",
            $"Received {eventName} for {scopeType ?? "unknown"}:{scopeId ?? "unknown"} C{envelope.Scope?.Counter?.ToString(CultureInfo.InvariantCulture) ?? "?"}.");

        if (string.Equals(eventName, "session.revoked", StringComparison.OrdinalIgnoreCase))
        {
            RunOnUiThread(() =>
            {
                BeginCloudSessionEnded(
                    "Cloud session ended",
                    "Your FA Cloud session was revoked. Sign in again to continue.",
                    "session revoked");
            });
            return;
        }

        if (string.Equals(eventName, "access.revoked", StringComparison.OrdinalIgnoreCase))
        {
            BeginCloudAccessRevoked(envelope.Scope);
            return;
        }

        if (!IsCloudVersionChangeEvent(eventName) || string.IsNullOrWhiteSpace(scopeId))
            return;

        CloudOpenSession? session = _activeCloudSession;
        if (session is null
            || !string.Equals(session.PackageId, scopeId, StringComparison.OrdinalIgnoreCase))
        {
            return;
        }

        int? counter = envelope.Scope?.Counter;
        if (counter is not null && counter <= session.Counter)
            return;

        RunOnUiThread(() => ShowCloudReloadAvailable(scopeId, counter));
    }

    private static bool IsCloudVersionChangeEvent(string eventName)
        => string.Equals(eventName, "package.version_committed", StringComparison.OrdinalIgnoreCase)
           || string.Equals(eventName, "version.new_counter", StringComparison.OrdinalIgnoreCase);

    private void RestoreCloudSessionFromRefreshToken()
    {
        if (_cloudClient is null || !AppSettings.CloudRememberCredentials)
            return;

        ObserveLifecycleTask(RestoreCloudSessionFromRefreshTokenAsync(), "cloud-session-restore");
    }

    private async Task RestoreCloudSessionFromRefreshTokenAsync()
    {
        if (_cloudClient is null)
            return;

        try
        {
            bool restored = await _cloudClient.TryRestoreSessionAsync(CancellationToken.None).ConfigureAwait(false);
            if (restored)
            {
                global::Android.Util.Log.Info("FA.Cloud", "Restored cloud session from refresh token.");
            }
            else
            {
                RunOnUiThread(PurgeTransientCloudCache);
            }
        }
        catch (Exception ex) when (ex is not System.OperationCanceledException and not OutOfMemoryException and not StackOverflowException)
        {
            global::Android.Util.Log.Warn("FA.Cloud", "Cloud session restore failed: " + ex.GetBaseException().Message);
        }
    }

    private void UpdateCloudAccountButton()
    {
        if (_cloudAccountButton is null)
            return;

        bool signedIn = _cloudClient?.IsSignedIn == true;
        _cloudAccountButton.Selected = signedIn;
        _cloudAccountButton.Alpha = signedIn ? 1f : 0.78f;
        _cloudAccountButton.ContentDescription = signedIn
            ? "FA Cloud account signed in"
            : GetString(Resource.String.cd_cloud_account);
    }

    private void UpdateAppTitle()
    {
        if (_topAppBar is null)
            return;

        string appName = GetString(Resource.String.app_name) ?? "Fabrication Assistant";
        string? modelName = NormalizeToolbarModelName(_activeModelDisplayName);
        _topAppBar.Title = string.IsNullOrWhiteSpace(modelName)
            ? appName
            : appName + " - " + modelName;
    }

    private static string? NormalizeToolbarModelName(string? modelName)
    {
        if (string.IsNullOrWhiteSpace(modelName))
            return null;

        string value = modelName.Trim();
        const int maxLength = 72;
        if (value.Length <= maxLength)
            return value;

        const int head = 34;
        const int tail = 35;
        return value[..head] + "..." + value[^tail..];
    }

    private void ShowCloudAccountDialog()
    {
        if (_cloudClient is not { } cloudClient || _isDestroyed)
            return;

        var dialog = new global::Android.App.Dialog(this);
        dialog.RequestWindowFeature((int)WindowFeatures.NoTitle);
        dialog.Window?.SetBackgroundDrawable(new ColorDrawable(Color.Transparent));
        dialog.Window?.SetSoftInputMode(SoftInput.AdjustResize);

        var root = new LinearLayout(this)
        {
            Orientation = Orientation.Vertical,
            Background = CreateCloudDialogBackground(),
        };
        root.SetPadding(Dp(16), Dp(14), Dp(16), Dp(14));

        var header = new LinearLayout(this)
        {
            Orientation = Orientation.Horizontal,
        };
        header.SetGravity(GravityFlags.CenterVertical);
        SetMarginBottom(header, Dp(12));

        var iconBox = new FrameLayout(this)
        {
            Background = CreateCloudDialogIconBackground(),
        };
        var icon = new ImageView(this);
        icon.SetImageResource(Resource.Drawable.ic_cloud);
        icon.ImageTintList = ColorStateList.ValueOf(GetColorCompat(Resource.Color.fa_accent_500));
        iconBox.AddView(icon, new FrameLayout.LayoutParams(Dp(24), Dp(24), GravityFlags.Center));
        var iconParams = new LinearLayout.LayoutParams(Dp(44), Dp(44));
        iconParams.RightMargin = Dp(12);
        header.AddView(iconBox, iconParams);

        var titleGroup = new LinearLayout(this) { Orientation = Orientation.Vertical };
        header.AddView(titleGroup, new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WrapContent, 1f));

        var title = new TextView(this)
        {
            Text = "FA Cloud",
            Ellipsize = TextUtils.TruncateAt.End,
        };
        title.SetSingleLine(true);
        title.SetTypeface(Typeface.Default, TypefaceStyle.Bold);
        title.SetTextColor(GetColorCompat(Resource.Color.fa_text_primary));
        title.SetTextSize(ComplexUnitType.Px, Dp(20));
        titleGroup.AddView(title);

        var subtitle = new TextView(this)
        {
            Text = cloudClient.IsSignedIn
                ? cloudClient.SignedInEmail ?? AppSettings.CloudUserEmail
                : "Not signed in",
            Ellipsize = TextUtils.TruncateAt.End,
        };
        subtitle.SetSingleLine(true);
        subtitle.SetTextColor(GetColorCompat(cloudClient.IsSignedIn ? Resource.Color.fa_accent_500 : Resource.Color.fa_text_secondary));
        subtitle.SetTextSize(ComplexUnitType.Px, Dp(13));
        titleGroup.AddView(subtitle);

        root.AddView(header);

        EditText emailInput = AddCloudDialogField(root, "User / email", AppSettings.CloudUserEmail, isPassword: false, hint: "user@example.com");
        EditText passwordInput = AddCloudDialogField(
            root,
            "Password",
            "",
            isPassword: true,
            hint: "Password");
        TextView forgotPassword = CreateCloudDialogLinkButton("Forgot password?");
        var forgotParams = new LinearLayout.LayoutParams(ViewGroup.LayoutParams.WrapContent, Dp(36));
        forgotParams.Gravity = GravityFlags.End;
        forgotParams.TopMargin = Dp(2);
        root.AddView(forgotPassword, forgotParams);
        EditText projectInput = AddCloudDialogField(root, "Default project", AppSettings.CloudDefaultProjectName, isPassword: false, hint: "Project name");

        var rememberCheck = new CheckBox(this)
        {
            Text = "Keep me signed in",
            Checked = AppSettings.CloudRememberCredentials,
        };
        rememberCheck.SetTextColor(GetColorCompat(Resource.Color.fa_text_primary));
        rememberCheck.SetTextSize(ComplexUnitType.Px, Dp(13));
        rememberCheck.ButtonTintList = ColorStateList.ValueOf(GetColorCompat(Resource.Color.fa_accent_500));
        rememberCheck.ContentDescription = rememberCheck.Checked
            ? "Keep me signed in, on"
            : "Keep me signed in, off";
        rememberCheck.CheckedChange += (_, e) =>
        {
            rememberCheck.ContentDescription = e.IsChecked
                ? "Keep me signed in, on"
                : "Keep me signed in, off";
        };
        SetMarginTop(rememberCheck, Dp(4));
        root.AddView(rememberCheck, new LinearLayout.LayoutParams(
            ViewGroup.LayoutParams.MatchParent,
            Dp(42)));

        var status = new TextView(this);
        status.SetTextSize(ComplexUnitType.Px, Dp(13));
        status.SetTextColor(GetColorCompat(Resource.Color.fa_text_secondary));
        status.Text = cloudClient.IsSignedIn
            ? "Signed in as " + (cloudClient.SignedInEmail ?? AppSettings.CloudUserEmail)
            : "Not signed in";
        status.SetSingleLine(false);
        status.SetMaxLines(2);
        SetMarginTop(status, Dp(6));
        root.AddView(status);

        var actions = new LinearLayout(this) { Orientation = Orientation.Horizontal };
        actions.SetGravity(GravityFlags.End | GravityFlags.CenterVertical);
        SetMarginTop(actions, Dp(14));

        TextView signOut = CreateCloudDialogCommandButton("Sign out", primary: false);
        signOut.Visibility = cloudClient.IsSignedIn ? ViewStates.Visible : ViewStates.Gone;
        actions.AddView(signOut, new LinearLayout.LayoutParams(Dp(104), Dp(44)));

        TextView close = CreateCloudDialogCommandButton("Close", primary: false);
        var closeParams = new LinearLayout.LayoutParams(Dp(92), Dp(44));
        closeParams.LeftMargin = Dp(8);
        actions.AddView(close, closeParams);

        TextView signIn = CreateCloudDialogCommandButton("Sign in", primary: true);
        var signInParams = new LinearLayout.LayoutParams(Dp(104), Dp(44));
        signInParams.LeftMargin = Dp(8);
        actions.AddView(signIn, signInParams);
        root.AddView(actions);

        dialog.SetContentView(root);
        ShowOwnedDialog(dialog);
        int screenWidth = Resources?.DisplayMetrics?.WidthPixels ?? Dp(460);
        int width = Math.Min(Dp(520), Math.Max(Dp(340), screenWidth - Dp(56)));
        dialog.Window?.SetBackgroundDrawable(new ColorDrawable(Color.Transparent));
        dialog.Window?.SetLayout(width, ViewGroup.LayoutParams.WrapContent);

        close.Click += (_, _) => dialog.Dismiss();

        void SetBusy(bool busy)
        {
            SetCloudDialogCommandEnabled(signIn, !busy);
            SetCloudDialogCommandEnabled(close, !busy);
            SetCloudDialogCommandEnabled(signOut, !busy);
            SetCloudDialogCommandEnabled(forgotPassword, !busy);
            emailInput.Enabled = !busy;
            passwordInput.Enabled = !busy;
            projectInput.Enabled = !busy;
            rememberCheck.Enabled = !busy;
        }

        forgotPassword.Click += async (_, _) =>
        {
            SetBusy(true);
            status.SetTextColor(GetColorCompat(Resource.Color.fa_text_secondary));
            status.Text = "Opening password reset...";
            try
            {
                string email = emailInput.Text?.Trim() ?? "";
                if (cloudClient.IsSignedIn)
                {
                    await CloseActiveCloudSessionAsync("password reset").ConfigureAwait(true);
                    if (_isDestroyed || !dialog.IsShowing)
                        return;
                    SignOutCloudLocally();
                }

                if (_isDestroyed || !dialog.IsShowing)
                    return;

                dialog.Dismiss();
                ShowCloudPasswordResetStartDialog(email);
            }
            catch (Exception ex)
            {
                if (_isDestroyed || !dialog.IsShowing)
                    return;
                status.SetTextColor(GetColorCompat(Resource.Color.fa_warning));
                status.Text = ex.GetBaseException().Message;
            }
            finally
            {
                if (!_isDestroyed && dialog.IsShowing)
                    SetBusy(false);
            }
        };

        signIn.Click += async (_, _) =>
        {
            SetBusy(true);
            status.SetTextColor(GetColorCompat(Resource.Color.fa_text_secondary));
            status.Text = "Signing in...";
            try
            {
                string email = emailInput.Text?.Trim() ?? "";
                string password = passwordInput.Text ?? "";
                string project = projectInput.Text?.Trim() ?? "";
                CloudSignInOutcome outcome = await cloudClient.SignInAsync(AppSettings.CloudServerUrl, email, password, rememberCheck.Checked, _activityDestroyCts.Token);
                if (_isDestroyed || !dialog.IsShowing)
                    return;
                if (!string.IsNullOrWhiteSpace(project))
                    AppSettings.CloudDefaultProjectName = project;

                if (outcome.Kind == CloudSignInOutcomeKind.TotpEnrollmentRequired)
                {
                    dialog.Dismiss();
                    ShowCloudTotpEnrollmentDialog(outcome, project);
                    return;
                }

                if (outcome.Kind == CloudSignInOutcomeKind.TotpRequired)
                {
                    dialog.Dismiss();
                    ShowCloudTotpSignInDialog(outcome, project);
                    return;
                }

                subtitle.Text = email;
                subtitle.SetTextColor(GetColorCompat(Resource.Color.fa_accent_500));
                status.Text = "Signed in as " + email;
                Toast.MakeText(this, "Cloud sign-in complete", ToastLength.Short)?.Show();
                dialog.Dismiss();
                if (_leftToolPanelKind == LeftToolPanelKind.Cloud)
                {
                    SetLeftToolPanelExpanded(false, animate: false);
                    ToggleCloudPanel();
                }
            }
            catch (Exception ex)
            {
                if (_isDestroyed || !dialog.IsShowing)
                    return;
                status.SetTextColor(GetColorCompat(Resource.Color.fa_warning));
                status.Text = ex.GetBaseException().Message;
            }
            finally
            {
                if (!_isDestroyed && dialog.IsShowing)
                    SetBusy(false);
            }
        };

        signOut.Click += async (_, _) =>
        {
            SetBusy(true);
            status.SetTextColor(GetColorCompat(Resource.Color.fa_text_secondary));
            status.Text = "Signing out...";
            await CloseActiveCloudSessionAsync("signout");
            if (_isDestroyed || !dialog.IsShowing)
                return;
            SignOutCloudLocally();
            status.Text = "Signed out";
            Toast.MakeText(this, "Cloud signed out", ToastLength.Short)?.Show();
            dialog.Dismiss();
            if (_leftToolPanelKind == LeftToolPanelKind.Cloud)
            {
                SetLeftToolPanelExpanded(false, animate: false);
                ToggleCloudPanel();
            }
            if (!_isDestroyed && dialog.IsShowing)
                SetBusy(false);
        };
    }

