            Hint = hint ?? "",
            Background = CreateCloudDialogInputBackground(),
        };
        input.SetSingleLine(true);
        input.SetTextColor(GetColorCompat(Resource.Color.fa_text_primary));
        input.SetHintTextColor(GetColorCompat(Resource.Color.fa_text_disabled));
        input.SetPadding(Dp(12), 0, Dp(12), 0);
        input.InputType = isPassword
            ? InputTypes.ClassText | InputTypes.TextVariationPassword
            : InputTypes.ClassText | InputTypes.TextVariationUri;
