        if (!string.IsNullOrEmpty(input.Text))
            input.SetSelection(input.Text.Length);
        parent.AddView(input, new LinearLayout.LayoutParams(
            LinearLayout.LayoutParams.MatchParent,
            Dp(46)));
        return input;
    }

