    private async Task SaveCurrentModelAsync()
    {
        if (_viewerStateSave is null || _camera is null || _sections is null || _packageSession is null)
            return;
        if (_saveCts is not null)
            return;

        string? archivePath = GetCurrentFaArchivePath();
        if (string.IsNullOrWhiteSpace(archivePath))
        {
            Toast.MakeText(this, "Only .fa models can be saved.", ToastLength.Short)?.Show();
            return;
        }

        if (_activeCloudSession is { IsReadOnly: true })
        {
            ShowError("Cloud save unavailable", "This cloud counter is read-only. Open the latest cloud counter before saving.");
            return;
        }

        var cts = new CancellationTokenSource();
        _saveCts = cts;
        _isSaveInProgress = true;
        UpdateSaveButton();
        UpdateUndoRedoButtons();
        ShowLoading("Saving model...");

        try
        {
            AndroidViewerStateSnapshot snapshot = CaptureViewerStateSnapshot();
            if (_activeCloudSession is { } cloudSession)
                await SaveCloudModelAsync(cloudSession, snapshot, cts.Token).ConfigureAwait(true);
            else
                await SaveLocalModelAsync(archivePath, snapshot, cts.Token).ConfigureAwait(true);

            Toast.MakeText(this, "Model saved", ToastLength.Short)?.Show();
        }
        catch (System.OperationCanceledException) when (cts.IsCancellationRequested)
        {
        }
        catch (Exception ex)
        {
            ShowError("Save failed", ex.GetBaseException().Message);
        }
        finally
        {
            if (ReferenceEquals(_saveCts, cts))
                _saveCts = null;
            _isSaveInProgress = false;
            cts.Dispose();
            HideLoading();
            UpdateSaveButton();
            UpdateUndoRedoButtons();
        }
    }

    private AndroidViewerStateSnapshot CaptureViewerStateSnapshot()
        => new(
            _camera ?? throw new InvalidOperationException("Camera is not available."),
            _packageSession ?? throw new InvalidOperationException("Package session is not available."),
            _sections ?? throw new InvalidOperationException("Section service is not available."),
            _measure?.Store.Snapshot() ?? Array.Empty<MeasurementResult>());

    private string? GetCurrentFaArchivePath()
    {
        ScenePackageInfoDto? packageInfo = _runtimeScene?.PackageInfo;
        if (!AndroidScenePackageState.IsFa(packageInfo))
            return null;

        string? path = packageInfo?.ArchiveFilePath;
        return string.IsNullOrWhiteSpace(path) || !File.Exists(path) ? null : path;
    }

    private static bool SameFilePath(string left, string right)
    {
        try
        {
            left = System.IO.Path.GetFullPath(left);
            right = System.IO.Path.GetFullPath(right);
        }
        catch
        {
            // Fall through to ordinal comparison if either path is not normalizable.
        }

        return string.Equals(left, right, StringComparison.Ordinal);
    }

    private async Task SaveLocalModelAsync(
        string archivePath,
        AndroidViewerStateSnapshot snapshot,
        CancellationToken ct)
    {
        UpdateLoadingDetail("Writing viewer state...");
        await _viewerStateSave!.SaveAsync(archivePath, snapshot, ct).ConfigureAwait(false);

        AndroidUri? destination = _currentLocalSaveUri;
        if (destination is null)
            throw new InvalidOperationException("No writable local file is associated with this model.");

        UpdateLoadingDetail("Updating local file...");
        await CopyArchiveToLocalDestinationAsync(archivePath, destination, ct).ConfigureAwait(false);
    }

    private async Task SaveCloudModelAsync(
        CloudOpenSession session,
        AndroidViewerStateSnapshot snapshot,
        CancellationToken ct)
    {
        if (session.IsReadOnly)
            throw new CloudApiException("This cloud counter is read-only. Open the latest cloud counter before saving.");
        if (_cloudClient is null)
            throw new CloudApiException("Sign in to FA Cloud first.");

        await ReleaseCloudReaderForWriterSaveAsync(session, ct).ConfigureAwait(false);

        CloudLockResponse? writerLock = null;
        string recoveryBaseVersionId = session.VersionId;
        string? recoveryLockId = null;
        bool localSaved = false;
        try
        {
            UpdateLoadingDetail("Writing viewer state...");
            await _viewerStateSave!.SaveAsync(
                session.LocalPath,
                snapshot,
                ct,
                preserveGeometryPayload: true,
                updateArchiveManifest: false).ConfigureAwait(false);
            localSaved = true;

            UpdateLoadingDetail("Acquiring writer lock...");
            writerLock = await _cloudClient.AcquireWriterLockAsync(session.PackageId, session.VersionId, ct).ConfigureAwait(false);
            string writerLockId = writerLock.LockId!;
            recoveryLockId = writerLockId;
            string baseVersionId = string.IsNullOrWhiteSpace(writerLock.BaseVersionId)
                ? session.VersionId
                : writerLock.BaseVersionId!;
            recoveryBaseVersionId = baseVersionId;

#if DEBUG
            await ReleaseCloudWriterBeforeUploadForDebugTestAsync(session.PackageId, writerLockId).ConfigureAwait(false);
#endif

            CloudOperationResponse operation = await _cloudClient.UploadWriterSaveAsync(
                session.PackageId,
                baseVersionId,
                writerLockId,
                session.LocalPath,
                new Progress<string>(UpdateLoadingDetail),
                ct).ConfigureAwait(false);

            if (!string.Equals(operation.Status, "committed", StringComparison.OrdinalIgnoreCase))
            {
                string detail = !string.IsNullOrWhiteSpace(operation.ValidationErrorMessage)
                    ? operation.ValidationErrorMessage!
                    : operation.Status ?? "Cloud validation failed.";
                throw new CloudApiException(detail, code: operation.ValidationErrorCode);
            }

            UpdateLoadingDetail("Refreshing cloud session...");
            await ReleaseCloudLockBestEffortAsync(session.PackageId, writerLockId, "writer save complete").ConfigureAwait(false);
            writerLock = null;

            CloudPackageSummary updated = await _cloudClient.LoadPackageSummaryAsync(session.PackageId, ct).ConfigureAwait(false);
            string versionId = updated.CurrentVersionId ?? operation.FinalPackageVersionId ?? session.VersionId;
            string readerLock = await _cloudClient.AcquireReaderLockAsync(session.PackageId, versionId, ct).ConfigureAwait(false);
            _activeCloudSession = new CloudOpenSession(
                session.PackageId,
                session.ProjectId,
                versionId,
                readerLock,
                session.LocalPath,
                $"{updated.DisplayName} - C{updated.CurrentCounter}",
                updated.CurrentCounter,
                false,
                session.ImportCacheNameToken,
                DateTimeOffset.UtcNow);
            _activeModelDisplayName = _activeCloudSession.DisplayName;
            ClearCloudReloadAvailable(session.PackageId);
            RunOnUiThread(UpdateAppTitle);
            StartCloudHeartbeat();
        }
        catch (Exception ex) when (ex is not System.OperationCanceledException)
        {
            bool invalidWriterLock = IsInvalidCloudWriterLockException(ex)
                                     || recoveryLockId is not null && IsCloudPermissionDeniedException(ex);
            if (localSaved)
            {
                string? errorCode = invalidWriterLock
                    ? "lock_not_held_by_caller"
                    : CloudSaveErrorCode(ex);
                await PreserveCloudRecoveryCopyAsync(session.LocalPath, session.PackageId, recoveryBaseVersionId, recoveryLockId, errorCode, CancellationToken.None).ConfigureAwait(false);
            }

            if (IsStaleCloudVersionException(ex))
            {
                global::Android.Util.Log.Warn("FA.Cloud", "Cloud writer save rejected stale base version " + session.VersionId + ".");
                throw new CloudApiException(
                    "Cloud model changed on the server before Android save could acquire a writer lock. Reopen the latest cloud version before saving again.",
                    ex is CloudApiException cloud ? cloud.StatusCode : null,
                    "base_version_not_current");
            }

            if (invalidWriterLock)
            {
                global::Android.Util.Log.Warn("FA.Cloud", "Cloud writer save rejected missing or invalid writer lock.");
                throw new CloudApiException(
                    "No valid cloud writer lock. Reopen or reacquire writer access before saving.",
                    ex is CloudApiException cloud ? cloud.StatusCode : null,
                    "lock_not_held_by_caller");
            }

            await ReacquireCloudReaderAfterFailedSaveAsync(session).ConfigureAwait(false);
            throw;
        }
        finally
        {
            if (writerLock?.LockId is { Length: > 0 } lockId)
                await ReleaseCloudLockBestEffortAsync(session.PackageId, lockId, "writer save cleanup").ConfigureAwait(false);
        }
    }

    private async Task ReleaseCloudReaderForWriterSaveAsync(CloudOpenSession expectedSession, CancellationToken ct)
    {
        await _cloudSessionGate.WaitAsync(ct).ConfigureAwait(false);
        try
        {
            CloudOpenSession? current = _activeCloudSession;
            if (current is null || !string.Equals(current.PackageId, expectedSession.PackageId, StringComparison.Ordinal))
                throw new CloudApiException("The active cloud model changed before save could start.");

            _activeCloudSession = current with { LockId = null };
            StopCloudHeartbeat();
            if (_cloudClient is not null && !string.IsNullOrWhiteSpace(current.LockId))
            {
                try
                {
                    await _cloudClient.ReleaseLockAsync(current.PackageId, current.LockId, CancellationToken.None).ConfigureAwait(false);
                    global::Android.Util.Log.Info("FA.Cloud", "Released cloud reader session for writer save.");
                }
                catch (Exception ex) when (ex is not OutOfMemoryException and not StackOverflowException)
                {
                    global::Android.Util.Log.Warn("FA.Cloud", "Cloud reader release before writer save failed: " + ex.GetBaseException().Message);
                }
            }
        }
        finally
        {
            _cloudSessionGate.Release();
        }
    }

    private async Task ReacquireCloudReaderAfterFailedSaveAsync(CloudOpenSession session)
    {
        if (_cloudClient is null || _isDestroyed)
            return;

        try
        {
            string readerLock = await _cloudClient.AcquireReaderLockAsync(session.PackageId, session.VersionId, CancellationToken.None).ConfigureAwait(false);
            _activeCloudSession = session with
            {
                LockId = readerLock,
                LastHeartbeatUtc = DateTimeOffset.UtcNow,
            };
            StartCloudHeartbeat();
        }
        catch (Exception ex) when (ex is not OutOfMemoryException and not StackOverflowException)
        {
            global::Android.Util.Log.Warn("FA.Cloud", "Could not reacquire reader session after failed save: " + ex.GetBaseException().Message);
        }
    }

    private async Task PreserveCloudRecoveryCopyAsync(
        string localPath,
        string packageId,
        string baseVersionId,
        string? lockId,
        string? errorCode,
        CancellationToken ct)
    {
        if (_cloudClient is null)
            return;

        try
        {
            string recoveryPath = await _cloudClient.PreserveWriterRecoveryCopyAsync(
                localPath,
                packageId,
                baseVersionId,
                lockId,
                errorCode,
                ct).ConfigureAwait(false);
            global::Android.Util.Log.Warn("FA.Cloud", "Preserved cloud writer recovery copy: " + recoveryPath);
        }
        catch (Exception ex) when (ex is not OutOfMemoryException and not StackOverflowException and not System.OperationCanceledException)
        {
            global::Android.Util.Log.Warn("FA.Cloud", "Could not preserve cloud writer recovery copy: " + ex.GetBaseException().Message);
        }
    }

    private async Task ReleaseCloudLockBestEffortAsync(string packageId, string lockId, string reason)
    {
        if (_cloudClient is null || string.IsNullOrWhiteSpace(lockId))
            return;

        try
        {
            await _cloudClient.ReleaseLockAsync(packageId, lockId, CancellationToken.None).ConfigureAwait(false);
            global::Android.Util.Log.Info("FA.Cloud", "Released cloud lock: " + reason);
        }
        catch (Exception ex) when (ex is not OutOfMemoryException and not StackOverflowException)
        {
            if (IsIdempotentCloudLockReleaseMiss(ex))
            {
                global::Android.Util.Log.Info("FA.Cloud", "Cloud lock already released: " + reason);
                return;
            }

            global::Android.Util.Log.Warn("FA.Cloud", "Cloud lock release failed: " + ex.GetBaseException().Message);
        }
    }

    private static bool IsIdempotentCloudLockReleaseMiss(Exception ex)
        => ex is CloudApiException { StatusCode: 404 }
           || ex is CloudApiException { Code: "lock_not_found" };

    private static string? CloudErrorCode(Exception ex)
        => ex is CloudApiException cloud ? cloud.Code : ex.GetType().Name;

    private static string? CloudSaveErrorCode(Exception ex)
        => IsStaleCloudVersionException(ex)
            ? "base_version_not_current"
            : IsInvalidCloudWriterLockException(ex)
                ? "lock_not_held_by_caller"
            : CloudErrorCode(ex);

    private async Task ReleaseCloudWriterBeforeUploadForDebugTestAsync(string packageId, string writerLockId)
    {
        if (_cloudClient is null)
            return;

        Java.IO.File? filesDir = FilesDir;
        string? root = filesDir?.AbsolutePath;
        if (string.IsNullOrWhiteSpace(root))
            return;

        string flagPath = global::System.IO.Path.Combine(root, "fa-debug-release-writer-before-upload");
        if (!global::System.IO.File.Exists(flagPath))
            return;

        try
        {
            global::System.IO.File.Delete(flagPath);
        }
        catch (Exception ex) when (ex is not OutOfMemoryException and not StackOverflowException)
        {
            global::Android.Util.Log.Warn("FA.Cloud", "Could not remove writer-lock debug flag: " + ex.GetBaseException().Message);
        }

        await _cloudClient.ReleaseLockAsync(packageId, writerLockId, CancellationToken.None).ConfigureAwait(false);
        global::Android.Util.Log.Warn("FA.Cloud", "Debug test released cloud writer lock before upload.");
    }

    private static bool IsInvalidCloudWriterLockException(Exception ex)
    {
        Exception baseException = ex.GetBaseException();
        if (baseException is CloudApiException cloud)
        {
            if (string.Equals(cloud.Code, "lock_not_held_by_caller", StringComparison.OrdinalIgnoreCase)
                || string.Equals(cloud.Code, "lock_not_found", StringComparison.OrdinalIgnoreCase)
                || string.Equals(cloud.Code, "lock_expired", StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }

            if ((cloud.StatusCode == 403 || cloud.StatusCode == 404 || cloud.StatusCode == 409)
                && cloud.Message.Contains("lock", StringComparison.OrdinalIgnoreCase)
                && (cloud.Message.Contains("held", StringComparison.OrdinalIgnoreCase)
                    || cloud.Message.Contains("found", StringComparison.OrdinalIgnoreCase)
                    || cloud.Message.Contains("expired", StringComparison.OrdinalIgnoreCase)))
            {
                return true;
            }
        }

        return baseException.Message.Contains("writer lock", StringComparison.OrdinalIgnoreCase)
               && (baseException.Message.Contains("valid", StringComparison.OrdinalIgnoreCase)
                   || baseException.Message.Contains("held", StringComparison.OrdinalIgnoreCase)
                   || baseException.Message.Contains("expired", StringComparison.OrdinalIgnoreCase));
    }

    private static bool IsCloudPermissionDeniedException(Exception ex)
    {
        Exception baseException = ex.GetBaseException();
        return baseException is CloudApiException cloud
               && (cloud.StatusCode == 403
                   || string.Equals(cloud.Code, "permission_denied", StringComparison.OrdinalIgnoreCase)
                   || cloud.Message.Contains("permission denied", StringComparison.OrdinalIgnoreCase));
    }

    private static bool IsStaleCloudVersionException(Exception ex)
    {
        Exception baseException = ex.GetBaseException();
        if (baseException is CloudApiException cloud)
        {
            if (string.Equals(cloud.Code, "base_version_not_current", StringComparison.OrdinalIgnoreCase)
                || string.Equals(cloud.Code, "version_not_current", StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }

            if (cloud.StatusCode == 409
                && cloud.Message.Contains("current package version", StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }
        }

        return baseException.Message.Contains("current package version", StringComparison.OrdinalIgnoreCase)
               || baseException.Message.Contains("base version", StringComparison.OrdinalIgnoreCase)
                  && baseException.Message.Contains("current", StringComparison.OrdinalIgnoreCase);
    }

    private async Task CopyArchiveToLocalDestinationAsync(string archivePath, AndroidUri destination, CancellationToken ct)
    {
        string scheme = destination.Scheme ?? "";
        if (string.Equals(scheme, "file", StringComparison.OrdinalIgnoreCase))
        {
            string? destinationPath = destination.Path;
            if (string.IsNullOrWhiteSpace(destinationPath))
                throw new IOException("Local file destination path is empty.");
            if (string.Equals(global::System.IO.Path.GetFullPath(archivePath), global::System.IO.Path.GetFullPath(destinationPath), StringComparison.OrdinalIgnoreCase))
                return;

            await using FileStream input = File.OpenRead(archivePath);
            await using FileStream output = new(destinationPath, FileMode.Create, FileAccess.Write, FileShare.None, 1024 * 128, useAsync: true);
            await input.CopyToAsync(output, ct).ConfigureAwait(false);
            await output.FlushAsync(ct).ConfigureAwait(false);
            return;
        }

        await using Stream inputStream = File.OpenRead(archivePath);
        await using Stream outputStream = ContentResolver?.OpenOutputStream(destination, "wt")
            ?? throw new IOException("Could not open the selected local file for writing.");
        await inputStream.CopyToAsync(outputStream, ct).ConfigureAwait(false);
        await outputStream.FlushAsync(ct).ConfigureAwait(false);
    }

    private async Task SubscribeCloudPackageNotificationsAsync(string packageId)
    {
        if (_cloudNotifications is null || string.IsNullOrWhiteSpace(packageId))
            return;

        try
        {
            await _cloudNotifications.SubscribePackageAsync(packageId, CancellationToken.None).ConfigureAwait(false);
        }
        catch (Exception ex) when (ex is not OutOfMemoryException and not StackOverflowException)
        {
            global::Android.Util.Log.Warn("FA.Cloud.SignalR", "Package notification subscribe failed: " + ex.GetBaseException().Message);
        }
    }

    private async Task UnsubscribeCloudPackageNotificationsAsync(string packageId, string reason)
    {
        if (_cloudNotifications is null || string.IsNullOrWhiteSpace(packageId))
            return;

        try
        {
            await _cloudNotifications.UnsubscribePackageAsync(packageId, CancellationToken.None).ConfigureAwait(false);
            global::Android.Util.Log.Info("FA.Cloud.SignalR", "Package notification unsubscribe: " + reason);
        }
        catch (Exception ex) when (ex is not OutOfMemoryException and not StackOverflowException)
        {
            global::Android.Util.Log.Warn("FA.Cloud.SignalR", "Package notification unsubscribe failed: " + ex.GetBaseException().Message);
        }
    }

    private void ShowCloudReloadAvailable(string packageId, int? counter)
    {
        if (_isDestroyed)
            return;

        _cloudReloadAvailablePackageId = packageId;
        _cloudReloadAvailableCounter = counter;
        UpdateSaveButton();
        _cloudPanel?.Refresh();

        if (_cloudReloadPromptShowing)
            return;

        _cloudReloadPromptShowing = true;
        string message = counter is null
            ? "A newer cloud version is available. Reload to open the latest model."
            : $"Cloud counter C{counter.Value} is available. Reload to open the latest model.";
        AlertDialog dialog = new AlertDialog.Builder(this)
            .SetTitle("Cloud model updated")!
            .SetMessage(message)!
            .SetPositiveButton("Reload", (_, _) =>
            {
                _cloudReloadPromptShowing = false;
                ObserveLifecycleTask(ReloadCloudPackageFromNotificationAsync(packageId), "cloud-reload-notification");
            })!
            .SetNegativeButton("Later", (_, _) => _cloudReloadPromptShowing = false)!
            .Create();
        dialog.SetOnDismissListener(new DialogDismissListener(() => _cloudReloadPromptShowing = false));
        ShowOwnedDialog(dialog);
    }

    private async Task ReloadCloudPackageFromNotificationAsync(string packageId)
    {
        if (_cloudClient is null || string.IsNullOrWhiteSpace(packageId))
            return;

        try
        {
            CloudPackageSummary package = await _cloudClient.LoadPackageSummaryAsync(packageId, CancellationToken.None).ConfigureAwait(false);
            RunOnUiThread(() => ObserveLifecycleTask(OpenCloudPackageAsync(package), "open-cloud-package-reload"));
        }
        catch (Exception ex) when (ex is not OutOfMemoryException and not StackOverflowException)
        {
            RunOnUiThread(() => ShowError("Cloud reload failed", ex.GetBaseException().Message));
        }
    }

    private void ClearCloudReloadAvailable(string packageId)
    {
        if (!string.IsNullOrWhiteSpace(_cloudReloadAvailablePackageId)
            && !string.Equals(_cloudReloadAvailablePackageId, packageId, StringComparison.OrdinalIgnoreCase))
        {
            return;
        }

        _cloudReloadAvailablePackageId = null;
        _cloudReloadAvailableCounter = null;
        RunOnUiThread(UpdateSaveButton);
    }

    private bool IsCloudReloadAvailableForActiveSession()
    {
        CloudOpenSession? session = _activeCloudSession;
        return session is not null
               && !string.IsNullOrWhiteSpace(_cloudReloadAvailablePackageId)
               && string.Equals(_cloudReloadAvailablePackageId, session.PackageId, StringComparison.OrdinalIgnoreCase)
               && (_cloudReloadAvailableCounter is null || _cloudReloadAvailableCounter > session.Counter);
    }

    private Task OpenCloudPackageAsync(CloudPackageSummary package)
        => OpenCloudPackageAsync(package, counter: null);

    private async Task OpenCloudPackageAsync(CloudPackageSummary package, int? counter)
    {
        if (_cloudClient is null || IsImportUiBusy())
            return;

        var cts = new CancellationTokenSource();
        CancellationTokenSource? previousCloudOpen = Interlocked.Exchange(ref _cloudOpenCts, cts);
        previousCloudOpen?.Cancel();
        previousCloudOpen?.Dispose();
        bool handedOffToImporter = false;
        bool sessionCommitted = false;
        CloudDownloadedModel? downloaded = null;

        ShowLoading("Preparing cloud model...");
        try
        {
            await PresentLoadingOverlayBeforeWorkAsync(cts.Token);
            await CloseActiveCloudSessionAsync("opening cloud model");
            cts.Token.ThrowIfCancellationRequested();
            if (_cloudClient is null || _isDestroyed)
                return;

            var progress = new Progress<string>(UpdateLoadingDetail);
            downloaded = counter is null
                ? await _cloudClient.DownloadForOpenAsync(package, progress, cts.Token)
                : await _cloudClient.DownloadVersionForOpenAsync(package, counter.Value, progress, cts.Token);
            cts.Token.ThrowIfCancellationRequested();
            if (_isDestroyed)
                return;

            Interlocked.CompareExchange(ref _cloudOpenCts, null, cts);
            handedOffToImporter = true;

            var uri = AndroidUri.FromFile(new Java.IO.File(downloaded.LocalPath))
                ?? throw new InvalidOperationException("Could not create a local URI for the downloaded cloud model.");
            bool loaded = await OpenModelUriAsync(
                uri,
                replaceActiveLoad: true,
                addToRecent: false,
                displayNameOverride: downloaded.DisplayName,
                persistForRestore: false,
                presentationFrameCount: 3);

            if (!loaded)
            {
                if (!string.IsNullOrWhiteSpace(downloaded.LockId))
                    await _cloudClient.ReleaseLockAsync(downloaded.Package.PackageId, downloaded.LockId, CancellationToken.None);
                _cloudClient.DeleteCloudTempFile(downloaded.LocalPath);
                return;
            }

            string sessionLocalPath = GetCurrentFaArchivePath() ?? downloaded.LocalPath;
            if (!SameFilePath(sessionLocalPath, downloaded.LocalPath))
                _cloudClient.DeleteCloudTempFile(downloaded.LocalPath);

            _activeCloudSession = new CloudOpenSession(
                downloaded.Package.PackageId,
                downloaded.Package.ProjectId,
                downloaded.VersionId,
                downloaded.LockId,
                sessionLocalPath,
                downloaded.DisplayName,
                downloaded.Counter,
                downloaded.IsReadOnly,
                downloaded.ImportCacheNameToken,
                DateTimeOffset.UtcNow);
            sessionCommitted = true;
            ClearCloudReloadAvailable(downloaded.Package.PackageId);
            if (string.IsNullOrWhiteSpace(downloaded.LockId))
                StopCloudHeartbeat();
            else
                StartCloudHeartbeat();
            try
            {
                await SubscribeCloudPackageNotificationsAsync(downloaded.Package.PackageId);
            }
            catch (Exception subscribeEx)
            {
                global::Android.Util.Log.Warn(
                    "FA.Cloud.SignalR",
                    $"Cloud notification subscribe failed for package {downloaded.Package.PackageId}: {subscribeEx.GetBaseException().Message}");
            }

            UpdateSaveButton();
            Toast.MakeText(this, downloaded.IsReadOnly ? "Opened read-only cloud counter" : "Opened cloud model", ToastLength.Short)?.Show();
        }
        catch (System.OperationCanceledException)
        {
            if (downloaded is not null && !sessionCommitted)
            {
                if (!string.IsNullOrWhiteSpace(downloaded.LockId))
                    await _cloudClient.ReleaseLockAsync(downloaded.Package.PackageId, downloaded.LockId, CancellationToken.None);
                _cloudClient.DeleteCloudTempFile(downloaded.LocalPath);
            }
        }
        catch (Exception ex)
        {
            if (downloaded is not null && !sessionCommitted)
            {
                if (!string.IsNullOrWhiteSpace(downloaded.LockId))
                    await _cloudClient.ReleaseLockAsync(downloaded.Package.PackageId, downloaded.LockId, CancellationToken.None);
                _cloudClient.DeleteCloudTempFile(downloaded.LocalPath);
            }

            if (!_isDestroyed)
                await RunOnUiThreadAsync(() => ShowError("Cloud open failed", ex.GetBaseException().Message));
        }
        finally
        {
            Interlocked.CompareExchange(ref _cloudOpenCts, null, cts);
            cts.Dispose();
            if (!handedOffToImporter && !_isDestroyed)
                HideLoading();
        }
    }

    private void StartCloudHeartbeat()
    {
        StopCloudHeartbeat();
        var cts = new CancellationTokenSource();
        CancellationTokenSource? previous = Interlocked.Exchange(ref _cloudHeartbeatCts, cts);
        previous?.Cancel();
        previous?.Dispose();
        ObserveLifecycleTask(CloudHeartbeatLoopAsync(cts.Token), "cloud-heartbeat-loop");
    }

    private void StopCloudHeartbeat()
    {
        CancellationTokenSource? cts = Interlocked.Exchange(ref _cloudHeartbeatCts, null);
        cts?.Cancel();
        cts?.Dispose();
    }

    private async Task CloudHeartbeatLoopAsync(CancellationToken ct)
    {
        try
        {
            while (!ct.IsCancellationRequested)
            {
                await Task.Delay(TimeSpan.FromMinutes(2), ct);
                await SendCloudHeartbeatAsync("timer", ct);
            }
        }
        catch (System.OperationCanceledException)
        {
        }
    }

    private Task SendCloudHeartbeatAsync(string reason)
        => SendCloudHeartbeatAsync(reason, CancellationToken.None);

    private async Task SendCloudHeartbeatAsync(string reason, CancellationToken ct)
    {
        CloudOpenSession? session = _activeCloudSession;
        string? lockId = session?.LockId;
        if (_cloudClient is null || session is null || string.IsNullOrWhiteSpace(lockId))
            return;

        try
        {
            await _cloudClient.HeartbeatAsync(session.PackageId, lockId, ct);
            MarkCloudHeartbeat(lockId);
            global::Android.Util.Log.Info("FA.Cloud", "Cloud reader heartbeat sent: " + reason);
        }
        catch (System.OperationCanceledException)
        {
        }
        catch (Exception ex)
        {
            global::Android.Util.Log.Warn("FA.Cloud", "Cloud reader heartbeat failed: " + ex.GetBaseException().Message);
        }
    }

    private void MarkCloudHeartbeat(string lockId)
    {
        CloudOpenSession? current = _activeCloudSession;
        if (current is not null && string.Equals(current.LockId, lockId, StringComparison.Ordinal))
            _activeCloudSession = current with { LastHeartbeatUtc = DateTimeOffset.UtcNow };
    }

    private async Task EnsureActiveCloudSessionOnResumeAsync()
    {
        CloudOpenSession? session = _activeCloudSession;
        if (_cloudClient is null || session is null)
            return;
        if (session.IsReadOnly)
            return;

        bool needsReacquire = string.IsNullOrWhiteSpace(session.LockId)
            || session.LastHeartbeatUtc is null
            || DateTimeOffset.UtcNow - session.LastHeartbeatUtc.Value > TimeSpan.FromMinutes(14);

        if (needsReacquire)
            await ReacquireActiveCloudSessionAsync("resume").ConfigureAwait(false);
        else
            await SendCloudHeartbeatAsync("resume", CancellationToken.None).ConfigureAwait(false);
    }

    private async Task ReacquireActiveCloudSessionAsync(string reason)
    {
        await _cloudSessionGate.WaitAsync().ConfigureAwait(false);
        try
        {
            CloudOpenSession? session = _activeCloudSession;
            if (_cloudClient is null || session is null)
                return;
            if (session.IsReadOnly)
                return;

            if (!string.IsNullOrWhiteSpace(session.LockId)
                && session.LastHeartbeatUtc is not null
                && DateTimeOffset.UtcNow - session.LastHeartbeatUtc.Value <= TimeSpan.FromMinutes(14))
            {
                return;
            }

            string lockId = await _cloudClient.AcquireReaderLockAsync(
                session.PackageId,
                session.VersionId,
                CancellationToken.None).ConfigureAwait(false);
            _activeCloudSession = session with
            {
                LockId = lockId,
                LastHeartbeatUtc = DateTimeOffset.UtcNow,
            };
            StartCloudHeartbeat();
            global::Android.Util.Log.Info("FA.Cloud", "Reacquired cloud reader session: " + reason);
        }
        catch (Exception ex) when (ex is not OutOfMemoryException and not StackOverflowException)
        {
            global::Android.Util.Log.Warn("FA.Cloud", "Cloud reader reacquire failed: " + ex.GetBaseException().Message);
        }
        finally
        {
            _cloudSessionGate.Release();
        }
    }

    private async Task SuspendActiveCloudSessionAsync(string reason)
    {
        await _cloudSessionGate.WaitAsync().ConfigureAwait(false);
        try
        {
            CloudOpenSession? session = _activeCloudSession;
            string? lockId = session?.LockId;
            if (_cloudClient is null || session is null || string.IsNullOrWhiteSpace(lockId))
                return;

            _activeCloudSession = session with { LockId = null };
            StopCloudHeartbeat();

            try
            {
                await _cloudClient.ReleaseLockAsync(session.PackageId, lockId, CancellationToken.None).ConfigureAwait(false);
                global::Android.Util.Log.Info("FA.Cloud", "Released cloud reader session: " + reason);
            }
            catch (Exception ex) when (ex is not OutOfMemoryException and not StackOverflowException)
            {
                global::Android.Util.Log.Warn("FA.Cloud", "Cloud reader release failed: " + ex.GetBaseException().Message);
            }
        }
        finally
        {
            _cloudSessionGate.Release();
        }
    }

    private async Task CloseActiveCloudSessionAsync(string reason)
    {
        await _cloudSessionGate.WaitAsync().ConfigureAwait(false);
        CloudOpenSession? session = null;
        try
        {
            session = _activeCloudSession;
            if (session is null)
                return;

            _activeCloudSession = null;
            ClearCloudReloadAvailable(session.PackageId);
            StopCloudHeartbeat();
            await UnsubscribeCloudPackageNotificationsAsync(session.PackageId, reason).ConfigureAwait(false);

            string? lockId = session.LockId;
            if (_cloudClient is not null && !string.IsNullOrWhiteSpace(lockId))
            {
                try
                {
                    await _cloudClient.ReleaseLockAsync(session.PackageId, lockId, CancellationToken.None).ConfigureAwait(false);
                    global::Android.Util.Log.Info("FA.Cloud", "Released cloud reader session: " + reason);
                }
                catch (Exception ex) when (ex is not OutOfMemoryException and not StackOverflowException)
                {
                    global::Android.Util.Log.Warn("FA.Cloud", "Cloud reader release failed: " + ex.GetBaseException().Message);
                }
            }
        }
        finally
        {
            DeleteCloudImportCacheCopies(session);
            _cloudClient?.DeleteCloudTempFile(session?.LocalPath);
            _cloudSessionGate.Release();
            RunOnUiThread(UpdateSaveButton);
        }
    }

    private void ReleaseActiveCloudSessionForDestroy()
    {
        CloudOpenSession? session = _activeCloudSession;
        if (session is null)
            return;

        CloudNotificationClient? notifications = _cloudNotifications;
        CloudApiClient? cloudClient = _cloudClient;
        _activeCloudSession = null;
        ClearCloudReloadAvailable(session.PackageId);
        StopCloudHeartbeat();

        _ = Task.Run(async () =>
        {
            try
            {
                using var timeoutCts = new CancellationTokenSource(TimeSpan.FromSeconds(4));
                if (notifications is not null)
                    await notifications.StopAsync(timeoutCts.Token).ConfigureAwait(false);

                if (!string.IsNullOrWhiteSpace(session.LockId) && cloudClient is not null)
                {
                    await cloudClient.ReleaseLockAsync(session.PackageId, session.LockId, timeoutCts.Token).ConfigureAwait(false);
                    global::Android.Util.Log.Info("FA.Cloud", "Released cloud reader session: activity destroy");
                }
            }
            catch (Exception ex) when (ex is not OutOfMemoryException and not StackOverflowException)
            {
                global::Android.Util.Log.Warn("FA.Cloud", "Cloud reader release during destroy failed: " + ex.GetBaseException().Message);
            }
        });

        DeleteCloudImportCacheCopies(session);
        cloudClient?.DeleteCloudTempFile(session.LocalPath);
    }

    private void DeleteCloudImportCacheCopies(CloudOpenSession? session)
    {
        _import?.DeleteCloudImportCacheFiles();

        if (session is null || string.IsNullOrWhiteSpace(session.ImportCacheNameToken))
            return;

        _import?.DeleteImportCacheFilesContaining(session.ImportCacheNameToken);
    }

    private void BeginCloudSessionEnded(string title, string message, string reason)
    {
        if (Interlocked.CompareExchange(ref _cloudSessionEndInProgress, 1, 0) != 0)
            return;

        ObserveLifecycleTask(HandleCloudSessionEndedAsync(title, message, reason), "cloud-session-ended");
    }

    private void BeginCloudAccessRevoked(CloudNotificationScope? scope)
    {
        if (Interlocked.CompareExchange(ref _cloudAccessRevocationInProgress, 1, 0) != 0)
            return;

        ObserveLifecycleTask(HandleCloudAccessRevokedAsync(scope), "cloud-access-revoked");
    }

    private async Task HandleCloudAccessRevokedAsync(CloudNotificationScope? scope)
    {
        try
        {
            CloudOpenSession? session = _activeCloudSession;
            bool closeActiveModel = CloudAccessRevocationAffectsSession(scope, session);

            if (closeActiveModel)
            {
                StopCloudHeartbeat();
                await CloseActiveCloudSessionAsync("access revoked").ConfigureAwait(false);
                await ClearActiveModelViewAsync("access revoked").ConfigureAwait(false);
            }

            PurgeTransientCloudCache();
            await RunOnUiThreadAsync(() =>
            {
                UpdateCloudAccountButton();
                UpdateSaveButton();
                _cloudPanel?.Refresh();
                ShowError("Cloud access changed", "Your access to this cloud model or project was revoked.");
            }).ConfigureAwait(false);
        }
        finally
        {
            Interlocked.Exchange(ref _cloudAccessRevocationInProgress, 0);
        }
    }

    private static bool CloudAccessRevocationAffectsSession(CloudNotificationScope? scope, CloudOpenSession? session)
    {
        if (session is null)
            return false;

        string? scopeType = scope?.Type;
        string? scopeId = scope?.Id;
        if (string.IsNullOrWhiteSpace(scopeType) || string.IsNullOrWhiteSpace(scopeId))
            return true;

        if (string.Equals(scopeType, "package", StringComparison.OrdinalIgnoreCase))
            return string.Equals(session.PackageId, scopeId, StringComparison.OrdinalIgnoreCase);

        if (string.Equals(scopeType, "project", StringComparison.OrdinalIgnoreCase))
            return string.Equals(session.ProjectId, scopeId, StringComparison.OrdinalIgnoreCase);

        if (string.Equals(scopeType, "user", StringComparison.OrdinalIgnoreCase))
            return true;

        return string.Equals(session.PackageId, scopeId, StringComparison.OrdinalIgnoreCase)
               || string.Equals(session.ProjectId, scopeId, StringComparison.OrdinalIgnoreCase);
    }

    private async Task HandleCloudSessionEndedAsync(string title, string message, string reason)
    {
        try
        {
            StopCloudHeartbeat();
            await CloseActiveCloudSessionAsync(reason).ConfigureAwait(false);
            SignOutCloudLocally();
            await ClearActiveModelViewAsync(reason).ConfigureAwait(false);
            await RunOnUiThreadAsync(() =>
            {
                UpdateCloudAccountButton();
                UpdateSaveButton();
                ShowError(title, message);
            }).ConfigureAwait(false);
        }
        finally
        {
            Interlocked.Exchange(ref _cloudSessionEndInProgress, 0);
        }
    }

    private async Task ClearActiveModelViewAsync(string reason)
    {
        await ClearRendererSceneAsync(reason).ConfigureAwait(false);
        await RunOnUiThreadAsync(() =>
        {
            _lastLoadedUriText = null;
            _currentLocalSaveUri = null;
            _lastLoadedDocument = null;
            _lastLoadedDocumentReleasedForMemoryPressure = false;
            _activeModelDisplayName = null;
            UpdateAppTitle();
            AttachRuntimeScene(null);
            UpdateSaveButton();
            UpdateUndoRedoButtons();
        }).ConfigureAwait(false);
    }

    private Task ClearRendererSceneAsync(string reason)
    {
        ViewportSurfaceView? viewport = _viewport;
        if (viewport is null)
            return Task.CompletedTask;

        var tcs = new TaskCompletionSource<object?>(TaskCreationOptions.RunContinuationsAsynchronously);
        bool queued = viewport.QueueRendererCommand(
            "clear-cloud-model-" + reason,
            _ =>
            {
                try
                {
                    GpuScene? oldScene = viewport.Renderer.Scene;
                    viewport.Renderer.Scene = null;
                    viewport.Renderer.SelectedMeshIndex = 0;
                    viewport.Renderer.SelectedMeshIndices = Array.Empty<int>();
                    viewport.Renderer.HoveredMeshIndex = 0;
                    oldScene?.Dispose();
                    tcs.TrySetResult(null);
                }
                catch (Exception ex)
                {
                    tcs.TrySetException(ex);
                }
            },
            logSlow: false);

        return queued ? tcs.Task : Task.CompletedTask;
    }

    private void SignOutCloudLocally()
    {
        _cloudClient?.SignOut();
        _import?.DeleteCloudImportCacheFiles();
    }

    private void PurgeTransientCloudCache()
    {
        _cloudClient?.PurgeCloudCache();
        _import?.DeleteCloudImportCacheFiles();
    }

    private void ToggleModelExplorerPanel()
    {
        if (IsImportUiBusy())
            return;

        if (_leftToolPanelKind == LeftToolPanelKind.ModelExplorer)
        {
            SetLeftToolPanelExpanded(false, animate: true);
            return;
        }

        if (_activeModalTool != AndroidModalTool.Select)
            ActivateSelectTool("model explorer opened");

        _modelExplorerPanel ??= new AndroidModelExplorerPanel(() => _runtimeScene)
        {
            NodeSelected = SelectModelExplorerNode,
            VisibilityChanged = SetModelExplorerNodeVisibility,
            SelectionResyncRequested = () => SyncModelExplorerSelectionFromViewport(scrollToSelection: false),
        };

        ShowLeftToolPanel(
            LeftToolPanelKind.ModelExplorer,
            _modelExplorerPanel.CreateView(this),
            _modelExplorerPanel.CreateViewDisposer());
        SyncModelExplorerSelectionFromViewport(scrollToSelection: false);
    }

    private void SelectModelExplorerNode(AndroidModelExplorerNode node)
    {
        Scene? scene = _runtimeScene;
        if (scene is null || _modelExplorerPanel is null)
            return;

        if (_activeModalTool != AndroidModalTool.Select)
            ActivateSelectTool("model explorer selection");

        int[] sceneNodeIds;
        if (AndroidScenePackageState.IsFa(scene.PackageInfo) && _packageSession is not null)
        {
            string[] occurrenceIds = _modelExplorerPanel.GetOccurrenceIdsForSelection(scene, node);
            _packageSession.SetSelection(occurrenceIds);
            sceneNodeIds = occurrenceIds.Length == 0
                ? _modelExplorerPanel.GetSceneNodeIdsForSelection(scene, node)
                : AndroidScenePackageState.GetNodeIdsForOccurrences(scene, occurrenceIds);
        }
        else
        {
            sceneNodeIds = _modelExplorerPanel.GetSceneNodeIdsForSelection(scene, node);
        }

        SelectSceneNodesFromModelExplorer(scene, sceneNodeIds, node.Id);
    }

    private void SelectSceneNodesFromModelExplorer(Scene scene, IReadOnlyList<int> nodeIds, int presentedNodeId)
    {
        ClearSelectedMeasurement("model explorer selection");
        ReplaceSelectedNodeIds(
            scene,
            nodeIds,
            scrollModelExplorerToSelection: false,
            explicitPresentedId: presentedNodeId,
            expandModelExplorerPath: false);
    }

    private void SetModelExplorerNodeVisibility(AndroidModelExplorerNode node, bool isVisible)
    {
        Scene? scene = _runtimeScene;
        if (scene is null || _modelExplorerPanel is null)
            return;

        using IUndoTransaction? undo = _undoService?.Begin(isVisible ? "Show model node" : "Hide model node");
        VisibilityStateSnapshot before = CaptureVisibilitySnapshot();
        bool hadXray = _xrayOpaqueNodeIds.Count > 0 || _xrayBackgroundNodeIds.Length > 0;
        int changedCount;

        if (AndroidScenePackageState.IsFa(scene.PackageInfo) && _packageSession is not null)
        {
            string[] occurrenceIds = _modelExplorerPanel.GetOccurrenceIdsForVisibility(scene, node);
            if (occurrenceIds.Length == 0)
                return;

            ClearXrayIsolationState();
            var hiddenOccurrenceIds = new HashSet<string>(_packageSession.HiddenOccurrenceIds, StringComparer.Ordinal);
            if (isVisible)
                hiddenOccurrenceIds.ExceptWith(occurrenceIds);
            else
                hiddenOccurrenceIds.UnionWith(occurrenceIds);

            bool stateChanged = AndroidScenePackageState.ApplyVisibilityState(
                scene,
                _packageSession,
                hiddenOccurrenceIds,
                _packageSession.IsolatedOccurrenceIds);
            if (!stateChanged && !hadXray)
            {
                undo?.Abort();
                return;
            }
            changedCount = occurrenceIds.Length;
        }
        else
        {
            int[] nodeIds = _modelExplorerPanel.GetSceneNodeIdsForVisibility(scene, node);
            if (nodeIds.Length == 0)
                return;

            ClearXrayIsolationState();
            changedCount = 0;
            foreach (int nodeId in nodeIds)
            {
                if (scene.GetNode(nodeId) is not SceneNode sceneNode)
                    continue;

                if (sceneNode.Visible == isVisible)
                    continue;

                sceneNode.Visible = isVisible;
                changedCount++;
            }
            if (changedCount == 0 && !hadXray)
            {
                undo?.Abort();
                return;
            }
        }

        _modelExplorerPanel.RefreshVisibility();
        AddVisibilityUndo(undo, before, isVisible ? "Show model node" : "Hide model node");
        FinalizeVisibilityMutation(isVisible ? "model-explorer-show" : "model-explorer-hide", changedCount);
    }

    private void ToggleBomPanel(AndroidBomPanelKind bomKind)
    {
        if (IsImportUiBusy())
            return;

        LeftToolPanelKind panelKind = bomKind == AndroidBomPanelKind.Hierarchy
            ? LeftToolPanelKind.Bom
            : LeftToolPanelKind.BomFlat;
        if (_leftToolPanelKind == panelKind)
        {
            SetLeftToolPanelExpanded(false, animate: true);
            return;
        }

        var panel = new AndroidBomPanel(
            _services!.GetRequiredService<FaPackageQueryService>(),
            () => _runtimeScene,
            bomKind)
        {
            ActionRequested = HandleBomPanelAction,
        };
        ShowLeftToolPanel(panelKind, panel.CreateView(this), panel);
    }

    private void ToggleSettingsPanel()
    {
        if (IsImportUiBusy())
            return;

        if (_leftToolPanelKind == LeftToolPanelKind.Settings)
        {
            SetLeftToolPanelExpanded(false, animate: true);
            return;
        }

        var panel = new PreferencesBottomSheet
        {
            OnSettingsChanged = ApplySettingsToScene,
        };
        ShowLeftToolPanel(LeftToolPanelKind.Settings, panel.CreateEmbeddedView(this), panel);
    }

    private void HandleBomPanelAction(AndroidBomPanelTarget target, AndroidBomPanelAction action)
    {
        Scene? scene = _runtimeScene;
        if (scene is null)
            return;

        int[] nodeIds = ResolveBomTargetNodeIds(scene, target);
        if (nodeIds.Length == 0)
        {
            Toast.MakeText(this, "No matching model geometry for this BOM row.", ToastLength.Short)?.Show();
            global::Android.Util.Log.Warn("FA.BOM", $"No node match: kind={target.Kind}, key='{target.Key}', partKey='{target.PartKey}', ordinal={target.PartOrdinal}/{target.PartOccurrenceCount}, label='{target.Label}'.");
            return;
        }

        SelectNodesFromBom(scene, nodeIds);
        ZoomToSelection();

        if (action == AndroidBomPanelAction.Isolate)
            IsolateSelectedNodes();
        else if (action == AndroidBomPanelAction.IsolateXray)
            IsolateXraySelectedNodes();

        global::Android.Util.Log.Info(
            "FA.BOM",
            $"Action {action}: kind={target.Kind}, key='{target.Key}', partKey='{target.PartKey}', ordinal={target.PartOrdinal}/{target.PartOccurrenceCount}, nodes=[{string.Join(",", nodeIds)}].");
    }

    private int[] ResolveBomTargetNodeIds(Scene scene, AndroidBomPanelTarget target)
    {
        IEnumerable<SceneNode> matches = target.Kind == AndroidBomPanelKind.Hierarchy
            ? ResolveHierarchyBomTargetNodes(scene, target)
            : scene.NodesById.Values.Where(node =>
                SameTextIgnoreCase(node.Metadata?.SourceKey, target.Key)
                || SameTextIgnoreCase(node.Metadata?.SourceFullPath, target.Key));

        return matches
            .Select(node => node.Id)
            .Distinct()
            .OrderBy(id => id)
            .ToArray();
    }

    private static IEnumerable<SceneNode> ResolveHierarchyBomTargetNodes(Scene scene, AndroidBomPanelTarget target)
    {
        string key = target.Key.Trim();
        if (key.Length == 0)
            return Array.Empty<SceneNode>();

        SceneNode[] allNodes = scene.NodesById.Values.ToArray();
        SceneNode[] directBomMatches = allNodes
            .Where(node => SameText(node.Metadata?.BomOccurrencePath, key)
                           && BomTargetPartMatches(node, target))
            .ToArray();
        if (directBomMatches.Length > 0)
            return directBomMatches;

        string[] pathCandidates = BuildBomScenePathCandidates(scene, key);
        SceneNode[] translatedMatches = allNodes
            .Where(node => BomTargetPartMatches(node, target)
                           && PathMatchesAny(node.Metadata?.OccurrencePath, pathCandidates))
            .ToArray();
        if (translatedMatches.Length > 0)
            return translatedMatches;

        translatedMatches = allNodes
            .Where(node => BomTargetPartMatches(node, target)
                           && PathMatchesAny(node.SourceNodePath, pathCandidates))
            .ToArray();
        if (translatedMatches.Length > 0)
            return translatedMatches;

        translatedMatches = ResolveHierarchyBomTargetByPartOrdinal(allNodes, target);
        if (translatedMatches.Length > 0)
            return translatedMatches;

        return Array.Empty<SceneNode>();
    }

    private static SceneNode[] ResolveHierarchyBomTargetByPartOrdinal(
        IReadOnlyCollection<SceneNode> allNodes,
        AndroidBomPanelTarget target)
    {
        if (target.PartOrdinal < 0 || string.IsNullOrWhiteSpace(target.PartKey))
            return Array.Empty<SceneNode>();

        string[] occurrencePaths = allNodes
            .Where(node => BomTargetPartMatches(node, target))
            .Select(node => FirstNonEmpty(node.Metadata?.OccurrencePath, node.SourceNodePath))
            .Where(path => !string.IsNullOrWhiteSpace(path))
            .Distinct(StringComparer.Ordinal)
            .OrderBy(path => path, AndroidPathComparer.Instance)
            .ToArray();

        if (target.PartOrdinal >= occurrencePaths.Length)
            return Array.Empty<SceneNode>();

        string occurrencePath = occurrencePaths[target.PartOrdinal];
        return allNodes
            .Where(node => BomTargetPartMatches(node, target)
                           && (SameText(node.Metadata?.OccurrencePath, occurrencePath)
                               || SameText(node.SourceNodePath, occurrencePath)))
            .ToArray();
    }

    private static string[] BuildBomScenePathCandidates(Scene scene, string bomPath)
    {
        var candidates = new List<string> { bomPath };

        foreach (string sceneRootPath in BuildBomSceneRootPathCandidates(scene))
        {
            string rootBomPath = BomRootPath(bomPath);
            if (string.Equals(bomPath, rootBomPath, StringComparison.Ordinal))
            {
                candidates.Add(sceneRootPath);
            }
            else if (bomPath.StartsWith(rootBomPath + "/", StringComparison.Ordinal))
            {
                candidates.Add(sceneRootPath + bomPath[rootBomPath.Length..]);
            }
        }

        return candidates
            .Where(candidate => !string.IsNullOrWhiteSpace(candidate))
            .Distinct(StringComparer.Ordinal)
            .ToArray();
    }

    private static string[] BuildBomSceneRootPathCandidates(Scene scene)
    {
        var candidates = new List<string>();
        AddPath(scene.Root.Metadata?.OccurrencePath);
        AddPath(scene.Root.SourceNodePath);

        if (scene.Root.Children.Count == 1)
        {
            SceneNode child = scene.Root.Children[0];
            AddPath(child.Metadata?.OccurrencePath);
            AddPath(child.SourceNodePath);
        }

        return candidates
            .Where(candidate => !string.IsNullOrWhiteSpace(candidate))
            .Distinct(StringComparer.Ordinal)
            .OrderByDescending(candidate => candidate.Count(ch => ch == '/'))
            .ToArray();

        void AddPath(string? path)
        {
            if (!string.IsNullOrWhiteSpace(path))
                candidates.Add(path);
        }
    }

    private static string BomRootPath(string bomPath)
    {
        int slash = bomPath.IndexOf('/');
        return slash < 0 ? bomPath : bomPath[..slash];
    }

    private static string FirstNonEmpty(params string?[] values)
        => values.FirstOrDefault(value => !string.IsNullOrWhiteSpace(value)) ?? string.Empty;

    private static bool BomTargetPartMatches(SceneNode node, AndroidBomPanelTarget target)
    {
        if (string.IsNullOrWhiteSpace(target.PartKey))
            return true;

        return SameTextIgnoreCase(node.Metadata?.SourceKey, target.PartKey)
               || SameTextIgnoreCase(node.Metadata?.SourceFullPath, target.PartKey)
               || SameTextIgnoreCase(node.DisplayName, target.PartKey)
               || SameTextIgnoreCase(node.SourceNodeName, target.PartKey)
               || SameTextIgnoreCase(node.Metadata?.OccurrenceNodeKey, target.PartKey)
               || SameTextIgnoreCase(node.Metadata?.OccurrenceNodeName, target.PartKey);
    }

    private static bool PathMatchesAny(string? path, IReadOnlyCollection<string> candidates)
        => !string.IsNullOrWhiteSpace(path)
           && candidates.Contains(path, StringComparer.Ordinal);

    private void SelectNodesFromBom(Scene scene, IReadOnlyList<int> nodeIds)
    {
        if (_activeModalTool != AndroidModalTool.Select)
            ActivateSelectTool("bom selection");

        ClearSelectedMeasurement("bom selection");
        ReplaceSelectedNodeIds(scene, nodeIds, scrollModelExplorerToSelection: true);
    }

    private void SyncModelExplorerSelectionFromViewport(bool scrollToSelection)
    {
        RefreshModelExplorerSelection(_runtimeScene, scrollToSelection);
    }

    private void ReplaceSelectedNodeIds(
        Scene? scene,
        IEnumerable<int> nodeIds,
        bool scrollModelExplorerToSelection,
        int? explicitPresentedId = null,
        bool expandModelExplorerPath = true,
        IReadOnlyList<int>? fallbackRendererMeshIndices = null,
        bool requestRender = true)
    {
        _selectedNodeIds.Clear();
        foreach (int nodeId in nodeIds.Distinct().OrderBy(id => id))
        {
            if (scene is null || scene.GetNode(nodeId) is not null)
                _selectedNodeIds.Add(nodeId);
        }
        SyncUndoSelectionFromSelectedNodes();

        RefreshSelectionDependentUi(
            scene,
            scrollModelExplorerToSelection,
            explicitPresentedId,
            expandModelExplorerPath,
            fallbackRendererMeshIndices,
            requestRender);
    }

    private void RefreshSelectionDependentUi(
        Scene? scene,
        bool scrollModelExplorerToSelection,
        int? explicitPresentedId = null,
        bool expandModelExplorerPath = true,
        IReadOnlyList<int>? fallbackRendererMeshIndices = null,
        bool requestRender = true)
    {
        if (scene is not null)
        {
            SyncRendererSelectionFromSelectedNodes(scene);
            SyncPackageSelectionFromSelectedNodes(scene);
        }
        else
        {
            SetRendererSelection(fallbackRendererMeshIndices ?? Array.Empty<int>());
        }

        SceneNode? selectedNode = ResolveSelectedNode(scene);
        _propertiesPanelBinder?.ShowSelection(selectedNode, scene, _selectedNodeIds.Count);
        RefreshModelExplorerSelection(
            scene,
            scrollModelExplorerToSelection,
            explicitPresentedId,
            expandModelExplorerPath);

        UpdateMainToolButtonStates();
        if (_activeModalTool == AndroidModalTool.BodyMove)
            UpdateBodyMoveGizmoRendererState();
        if (requestRender)
            _viewport?.RequestRender();
    }

    private void SyncUndoSelectionFromSelectedNodes()
    {
        if (_undoSelectionState is null || _syncingUndoSelectionState)
            return;

        try
        {
            _syncingUndoSelectionState = true;
            if (_selectedNodeIds.Count == 0)
                _undoSelectionState.Clear();
            else
                _undoSelectionState.SelectMany(_selectedNodeIds);
        }
        finally
        {
            _syncingUndoSelectionState = false;
        }
    }

    private SceneNode? ResolveSelectedNode(Scene? scene)
        => scene is null
            ? null
            : _selectedNodeIds
                .OrderBy(id => id)
                .Select(id => scene.GetNode(id))
                .FirstOrDefault(node => node is not null);

    private void RefreshModelExplorerSelection(
        Scene? scene,
        bool scrollToSelection,
        int? explicitPresentedId = null,
        bool expandSelectedPath = true)
    {
        _modelExplorerPanel?.SetSelection(
            scene,
            _selectedNodeIds,
            explicitPresentedId,
            expandSelectedPath,
            scrollToSelection);
    }

    private void SyncRendererSelectionFromSelectedNodes(Scene? scene)
    {
        if (_viewport is null)
            return;

        if (scene is null || _selectedNodeIds.Count == 0 || _viewport.Renderer.Scene is not { } gpuScene)
        {
            ClearRendererSelection();
            return;
        }

        var meshIndices = new HashSet<int>();
        foreach (int nodeId in EnumerateRenderableNodeIds(scene, _selectedNodeIds))
        {
            if (gpuScene.TryGetMeshIndexForSourceNodeId(nodeId, out int meshIndex) && meshIndex > 0)
                meshIndices.Add(meshIndex);
        }

        SetRendererSelection(meshIndices.OrderBy(index => index).ToArray());
    }

    private void SetRendererSelection(IReadOnlyList<int> meshIndices)
    {
        if (_viewport is null)
            return;

        if (meshIndices.Count == 0)
        {
            ClearRendererSelection();
            return;
        }

        _viewport.Renderer.SelectedMeshIndex = meshIndices[0];
        _viewport.Renderer.SelectedMeshIndices = meshIndices;
    }

    private void ClearRendererSelection()
    {
        if (_viewport is null)
            return;

        _viewport.Renderer.SelectedMeshIndex = 0;
        _viewport.Renderer.SelectedMeshIndices = Array.Empty<int>();
    }

    private static IEnumerable<int> EnumerateRenderableNodeIds(Scene scene, IEnumerable<int> nodeIds)
    {
        var yielded = new HashSet<int>();
        foreach (int nodeId in nodeIds)
        {
            SceneNode? node = scene.GetNode(nodeId);
            if (node is null)
                continue;

            foreach (int renderableId in EnumerateRenderableNodeIds(node))
            {
                if (yielded.Add(renderableId))
                    yield return renderableId;
            }
        }
    }

    private static IEnumerable<int> EnumerateRenderableNodeIds(SceneNode node)
    {
        if (node.MeshId.HasValue)
            yield return node.Id;

        foreach (SceneNode child in node.Children)
        {
            foreach (int childId in EnumerateRenderableNodeIds(child))
                yield return childId;
        }
    }

    private static bool SameText(string? left, string right)
        => !string.IsNullOrWhiteSpace(left)
           && string.Equals(left, right, StringComparison.Ordinal);

    private static bool SameTextIgnoreCase(string? left, string right)
        => !string.IsNullOrWhiteSpace(left)
           && string.Equals(left, right, StringComparison.OrdinalIgnoreCase);

    private bool IsImportUiBusy() => HasActiveLoad() || _openPickerInFlight || _cloudOpenCts is not null || _saveCts is not null;

    private void ShowLeftToolPanel(LeftToolPanelKind kind, View content, IDisposable? disposableContent = null)
    {
        if (_leftToolPanel is null)
        {
            disposableContent?.Dispose();
            return;
        }

        bool wasClosed = _leftToolPanelKind == LeftToolPanelKind.None;
        _leftToolPanelKind = kind;

        DisposeLeftToolPanelContent();
        _leftToolPanel.RemoveAllViews();
        _leftToolPanel.AddView(content, new FrameLayout.LayoutParams(
            ViewGroup.LayoutParams.MatchParent,
            ViewGroup.LayoutParams.MatchParent));
        _leftToolPanelContent = disposableContent;
        SetCurrentLeftToolPanelWidth(GetCurrentLeftToolPanelWidth());
        SetLeftToolPanelExpanded(true, animate: wasClosed);
        UpdateLeftToolPanelButtonStates();
    }

    private void DisposeLeftToolPanelContent()
    {
        IDisposable? content = _leftToolPanelContent;
        _leftToolPanelContent = null;
        if (content is CloudFilesPanel)
            _cloudPanel = null;
        if (content is null)
            return;

        try
        {
            content.Dispose();
        }
        catch (Exception ex)
        {
            global::Android.Util.Log.Warn("FA.UI", "Failed to dispose left-panel content: " + ex.Message);
        }
    }

    private void SetLeftToolPanelExpanded(bool expanded, bool animate)
    {
        if (_leftToolPanel is null || _leftToolPanelDivider is null)
            return;

        int animationVersion = ++_leftToolPanelAnimationVersion;
        _leftToolPanelWidthAnimator?.Cancel();
        _leftToolPanelWidthAnimator = null;

        if (!expanded)
        {
            int closingWidth = Math.Max(0, _leftToolPanel.Width);
            _leftToolPanelKind = LeftToolPanelKind.None;
            UpdateLeftToolPanelButtonStates();
            DisposeLeftToolPanelContent();

            if (animate && _leftToolPanel.Visibility == ViewStates.Visible && closingWidth > 0)
            {
                AnimateLeftToolPanelWidth(closingWidth, 0, 120, () =>
                {
                    if (_leftToolPanelAnimationVersion != animationVersion)
                        return;

                    _leftToolPanel.Visibility = ViewStates.Gone;
                    _leftToolPanelDivider.Visibility = ViewStates.Gone;
                    SetLeftToolPanelLayoutWidth(0);
                    _leftToolPanel.RemoveAllViews();
                    _viewport?.RequestLayout();
                    _viewport?.RequestRender();
                });
                return;
            }

            _leftToolPanel.Visibility = ViewStates.Gone;
            _leftToolPanelDivider.Visibility = ViewStates.Gone;
            SetLeftToolPanelLayoutWidth(0);
            DisposeLeftToolPanelContent();
            _leftToolPanel.RemoveAllViews();
            _viewport?.RequestLayout();
            _viewport?.RequestRender();
            return;
        }

        int targetWidth = GetCurrentLeftToolPanelWidth();
        _leftToolPanel.Visibility = ViewStates.Visible;
        _leftToolPanelDivider.Visibility = ViewStates.Visible;
        if (animate)
        {
            SetLeftToolPanelLayoutWidth(0);
            AnimateLeftToolPanelWidth(0, targetWidth, 160, null);
        }
        else
        {
            SetLeftToolPanelLayoutWidth(targetWidth);
        }

        _viewport?.RequestLayout();
        _viewport?.RequestRender();
    }

    private void AnimateLeftToolPanelWidth(int startWidth, int endWidth, long durationMs, Action? finished)
    {
        _leftToolPanelWidthAnimator?.Cancel();
        var animator = ValueAnimator.OfFloat(0f, 1f);
        if (animator is null)
        {
            SetLeftToolPanelLayoutWidth(endWidth);
            finished?.Invoke();
            return;
        }

        _leftToolPanelWidthAnimator = animator;
        animator.SetDuration(durationMs);
        animator.Update += (_, e) =>
        {
            float t = e.Animation?.AnimatedFraction ?? 1f;
            int width = startWidth + (int)MathF.Round((endWidth - startWidth) * t);
            SetLeftToolPanelLayoutWidth(width);
        };
        animator.AnimationEnd += (_, _) =>
        {
            if (ReferenceEquals(_leftToolPanelWidthAnimator, animator))
                _leftToolPanelWidthAnimator = null;
            SetLeftToolPanelLayoutWidth(endWidth);
            finished?.Invoke();
        };
        animator.Start();
    }

    private void SetLeftToolPanelLayoutWidth(int width)
    {
        if (_leftToolPanel?.LayoutParameters is not ViewGroup.LayoutParams layoutParams)
            return;

        int safeWidth = Math.Max(0, width);
        if (layoutParams.Width != safeWidth)
        {
            layoutParams.Width = safeWidth;
            _leftToolPanel.LayoutParameters = layoutParams;
        }

        _leftToolPanel.RequestLayout();
    }

    private int GetCurrentLeftToolPanelWidth()
        => _leftToolPanelKind switch
        {
            LeftToolPanelKind.Recent => _recentPanelWidthPx > 0 ? _recentPanelWidthPx : DefaultLeftToolPanelWidth(LeftToolPanelKind.Recent),
            LeftToolPanelKind.Cloud => _cloudPanelWidthPx > 0 ? _cloudPanelWidthPx : DefaultLeftToolPanelWidth(LeftToolPanelKind.Cloud),
            LeftToolPanelKind.ModelExplorer => _modelExplorerPanelWidthPx > 0 ? _modelExplorerPanelWidthPx : DefaultLeftToolPanelWidth(LeftToolPanelKind.ModelExplorer),
            LeftToolPanelKind.Bom => _bomPanelWidthPx > 0 ? _bomPanelWidthPx : DefaultLeftToolPanelWidth(LeftToolPanelKind.Bom),
            LeftToolPanelKind.BomFlat => _bomFlatPanelWidthPx > 0 ? _bomFlatPanelWidthPx : DefaultLeftToolPanelWidth(LeftToolPanelKind.BomFlat),
            LeftToolPanelKind.Settings => _settingsPanelWidthPx > 0 ? _settingsPanelWidthPx : DefaultLeftToolPanelWidth(LeftToolPanelKind.Settings),
            _ => _leftToolPanel?.Width > 0 ? _leftToolPanel.Width : DefaultLeftToolPanelWidth(LeftToolPanelKind.Settings),
        };

    private void SetCurrentLeftToolPanelWidth(int requestedWidth)
    {
        if (_leftToolPanelKind == LeftToolPanelKind.None || _leftToolPanel is null)
            return;

        int width = ClampCurrentLeftToolPanelWidth(requestedWidth);
        if (_leftToolPanelKind == LeftToolPanelKind.Recent)
            _recentPanelWidthPx = width;
        else if (_leftToolPanelKind == LeftToolPanelKind.Cloud)
            _cloudPanelWidthPx = width;
        else if (_leftToolPanelKind == LeftToolPanelKind.ModelExplorer)
            _modelExplorerPanelWidthPx = width;
        else if (_leftToolPanelKind == LeftToolPanelKind.Bom)
            _bomPanelWidthPx = width;
        else if (_leftToolPanelKind == LeftToolPanelKind.BomFlat)
            _bomFlatPanelWidthPx = width;
        else if (_leftToolPanelKind == LeftToolPanelKind.Settings)
            _settingsPanelWidthPx = width;

        SetLeftToolPanelLayoutWidth(width);
        _viewport?.RequestLayout();
        _viewport?.RequestRender();
    }

    private int ClampCurrentLeftToolPanelWidth(int requestedWidth)
    {
        return ClampLeftToolPanelWidth(_leftToolPanelKind, requestedWidth);
    }

    private int ClampLeftToolPanelWidth(LeftToolPanelKind kind, int requestedWidth)
    {
        int minimum = kind is LeftToolPanelKind.Recent or LeftToolPanelKind.Cloud ? Dp(220) : Dp(320);
        int fallbackMaximum = Resources?.DisplayMetrics?.WidthPixels ?? requestedWidth;
        int maximum = fallbackMaximum;

        if (_leftToolPanel?.Parent is View parent && parent.Width > 0)
        {
            int navWidth = _navRail?.Visibility == ViewStates.Visible ? _navRail.Width : 0;
            int navDividerWidth = _navRailDivider?.Visibility == ViewStates.Visible ? _navRailDivider.Width : 0;
            int propertiesWidth = _propertiesPanel?.Visibility == ViewStates.Visible ? _propertiesPanelWidthPx : 0;
            int propertiesDividerWidth = _propertiesPanelDivider?.Visibility == ViewStates.Visible ? _propertiesPanelDivider.Width : 0;
            int minViewportWidth = Dp(160);
            maximum = parent.Width - navWidth - navDividerWidth - propertiesWidth - propertiesDividerWidth - minViewportWidth;
        }

        int boundedMin = Math.Min(minimum, Math.Max(1, maximum));
        return Math.Max(boundedMin, Math.Min(requestedWidth, Math.Max(boundedMin, maximum)));
    }

    private int DefaultLeftToolPanelWidth(LeftToolPanelKind kind)
    {
        var metrics = Resources?.DisplayMetrics;
        float widthDp = metrics is null || metrics.Density <= 0f
            ? 700f
            : metrics.WidthPixels / metrics.Density;

        float desiredDp = kind == LeftToolPanelKind.Recent
            ? (widthDp >= 700f ? 260f : 240f)
            : kind == LeftToolPanelKind.Cloud
                ? (widthDp >= 700f ? 360f : 320f)
            : kind == LeftToolPanelKind.Bom || kind == LeftToolPanelKind.BomFlat
                ? (widthDp >= 700f ? 620f : 440f)
                : kind == LeftToolPanelKind.ModelExplorer
                    ? (widthDp >= 700f ? 440f : 360f)
                    : (widthDp >= 700f ? 520f : 420f);
        return ClampLeftToolPanelWidth(kind, Dp(desiredDp));
    }

    private void UpdateLeftToolPanelButtonStates()
    {
        SetSelected(_navRecentButton, _leftToolPanelKind == LeftToolPanelKind.Recent);
        SetSelected(_navCloudButton, _leftToolPanelKind == LeftToolPanelKind.Cloud);
        SetSelected(_navModelExplorerButton, _leftToolPanelKind == LeftToolPanelKind.ModelExplorer);
        SetSelected(_navBomButton, _leftToolPanelKind == LeftToolPanelKind.Bom);
        SetSelected(_navBomFlatButton, _leftToolPanelKind == LeftToolPanelKind.BomFlat);
        SetSelected(_navSettingsButton, _leftToolPanelKind == LeftToolPanelKind.Settings);
        SetSelected(_navSpenPalmButton, AppSettings.SpenPalmRejectionEnabled);
    }

    private void UpdateUndoRedoButtons()
    {
        bool importBusy = IsImportUiBusy();
        bool canUndo = !importBusy && _undoService?.CanUndo == true;
        bool canRedo = !importBusy && _undoService?.CanRedo == true;

        SetButtonEnabled(_navUndoButton, canUndo);
        SetButtonEnabled(_navRedoButton, canRedo);

        if (_navUndoButton is not null)
            _navUndoButton.ContentDescription = BuildUndoRedoDescription(
                Resource.String.cd_nav_undo,
                _undoService?.PeekUndoLabel);
        if (_navRedoButton is not null)
            _navRedoButton.ContentDescription = BuildUndoRedoDescription(
                Resource.String.cd_nav_redo,
                _undoService?.PeekRedoLabel);
    }

    private string BuildUndoRedoDescription(int actionStringResourceId, string? label)
    {
        string action = GetString(actionStringResourceId) ?? string.Empty;
        return string.IsNullOrWhiteSpace(label)
            ? action
            : action + ": " + label;
    }

    private void UpdateSaveButton()
    {
        bool canSave = !_isSaveInProgress
                       && !HasActiveLoad()
                       && _cloudOpenCts is null
                       && !IsCloudReloadAvailableForActiveSession()
                       && GetCurrentFaArchivePath() is not null
                       && (_currentLocalSaveUri is not null
                           || _activeCloudSession is { LockId.Length: > 0, IsReadOnly: false });
        SetButtonEnabled(_saveButton, canSave);
        if (_saveButton is not null)
        {
            _saveButton.ContentDescription = _isSaveInProgress
                ? "Saving model"
                : GetString(Resource.String.cd_save_model);
        }
    }

    private bool HasStylusInputDevice()
    {
        try
        {
            var inputManager = GetSystemService(InputService) as global::Android.Hardware.Input.InputManager;
            int[]? deviceIds = inputManager?.GetInputDeviceIds();
            if (deviceIds is null)
                return false;

            foreach (int deviceId in deviceIds)
            {
                InputDevice? device = InputDevice.GetDevice(deviceId);
                if (device is null)
                    continue;

                if ((device.Sources & InputSourceType.Stylus) == InputSourceType.Stylus)
                    return true;
            }
        }
        catch (Exception ex) when (ex is not OutOfMemoryException and not StackOverflowException)
        {
            global::Android.Util.Log.Warn("FA.Input", "Could not query stylus input devices: " + ex.Message);
        }

        return false;
    }

    private void ToggleSpenPalmRejection()
    {
        AppSettings.SpenPalmRejectionEnabled = !AppSettings.SpenPalmRejectionEnabled;
        ApplySpenPalmRejectionState(showToast: ShouldShowSpenPalmToggleToast());
    }

    private bool ShouldShowSpenPalmToggleToast()
    {
        long nowMs = SystemClock.ElapsedRealtime();
        if (nowMs - _lastSpenPalmToggleToastMs < SpenPalmToggleToastDebounceMs)
            return false;

        _lastSpenPalmToggleToastMs = nowMs;
        return true;
    }

    private void ApplySpenPalmRejectionState(bool showToast)
    {
        bool enabled = AppSettings.SpenPalmRejectionEnabled;
        bool changed = _appliedSpenPalmRejectionEnabled != enabled;
        if (changed)
            _pointerSource?.CancelActiveGesture();
        if (_pointerSource is not null)
            _pointerSource.SpenPalmRejectionEnabled = enabled;
        if (!enabled)
            ClearSpenPalmGuard();

        _appliedSpenPalmRejectionEnabled = enabled;
        SetSelected(_navSpenPalmButton, enabled);
        if (_navSpenPalmButton is not null)
        {
            int contentDescriptionId = enabled
                ? Resource.String.cd_nav_spen_palm_rejection_on
                : Resource.String.cd_nav_spen_palm_rejection_off;
            _navSpenPalmButton.ContentDescription = GetString(contentDescriptionId);
            SetTooltip(_navSpenPalmButton, contentDescriptionId);
        }

        if (showToast)
        {
            Toast.MakeText(
                this,
                enabled ? Resource.String.spen_palm_rejection_on : Resource.String.spen_palm_rejection_off,
                ToastLength.Short)?.Show();
        }
    }

    private async Task OpenRecentFileAsync(RecentFileEntry entry)
    {
        if (string.IsNullOrWhiteSpace(entry.Uri))
            return;

        AndroidUri? uri = AndroidUri.Parse(entry.Uri);
        if (uri is null)
        {
            RecentFilesStore.Remove(ApplicationContext!, entry.Uri);
            return;
        }

        bool accessRevoked = false;
        bool loaded = await OpenModelUriAsync(uri, ex =>
        {
            accessRevoked = IsFileAccessRevoked(ex);
        });
        if (accessRevoked)
        {
            RecentFilesStore.Remove(ApplicationContext!, entry.Uri);
            Toast.MakeText(this, "Recent file is no longer accessible.", ToastLength.Short)?.Show();
        }
        if (!loaded)
            global::Android.Util.Log.Warn("FA.Recent", "Recent file did not load: " + entry.DisplayName);
    }

