    private void ShowMeasureToolbar()
    {
        // Android intentionally uses an exclusive tool strip for compact
        // screens; desktop keeps the main toolbar visible under a popup.
        global::Android.Util.Log.Info("FA.Measure", "Toolbar opened.");
        EnterToolbarMode(BottomToolbarMode.Measure, AndroidModalTool.Measure);
        ActivateInteractiveMeasureMode(PreferredInteractiveMeasureMode(), "toolbar opened");
    }

    private void ExitMeasureToolbar()
    {
        global::Android.Util.Log.Info("FA.Measure", "Toolbar closed; active measurement cancelled.");
        ActivateSelectTool("measure return");
    }

    private void ShowViewPresetToolbar()
    {
        global::Android.Util.Log.Info("FA.ViewPresets", "Toolbar opened.");
        EnterToolbarMode(BottomToolbarMode.ViewPreset, _activeModalTool);
    }

    private void ExitViewPresetToolbar()
    {
        global::Android.Util.Log.Info("FA.ViewPresets", "Toolbar closed.");
        EnterToolbarMode(ReturnToolbarModeForActiveTool(), _activeModalTool);
    }

    private void SetViewPresetToolbarVisible(bool visible)
    {
        EnterToolbarMode(visible ? BottomToolbarMode.ViewPreset : BottomToolbarMode.Main, _activeModalTool);
    }

    private void ShowSectionToolbar()
    {
        global::Android.Util.Log.Info("FA.Section", "Toolbar opened.");
        EnterToolbarMode(BottomToolbarMode.Section, AndroidModalTool.Section);
    }

    private void ShowRenderModeToolbar()
    {
        global::Android.Util.Log.Info("FA.RenderMode", "Toolbar opened.");
        EnterToolbarMode(BottomToolbarMode.RenderMode, _activeModalTool);
    }

    private void ExitRenderModeToolbar()
    {
        global::Android.Util.Log.Info("FA.RenderMode", "Toolbar closed.");
        EnterToolbarMode(ReturnToolbarModeForActiveTool(), _activeModalTool);
    }

    private BottomToolbarMode ReturnToolbarModeForActiveTool()
        => _activeModalTool switch
        {
            AndroidModalTool.Measure => BottomToolbarMode.Measure,
            AndroidModalTool.Section => BottomToolbarMode.Section,
            AndroidModalTool.Explode => BottomToolbarMode.Explode,
            _ => BottomToolbarMode.Main,
        };

    private void EnterToolbarMode(BottomToolbarMode mode, AndroidModalTool modalTool)
    {
        AndroidModalTool previousTool = _activeModalTool;
        if (previousTool != modalTool)
            CancelActiveModalTool(previousTool, preserveExplode: modalTool == AndroidModalTool.Explode);

        _bottomToolbarMode = mode;
        _activeModalTool = modalTool;

        if (modalTool != AndroidModalTool.Select)
            ClearSelectedMeasurement("tool changed");

        if (modalTool != AndroidModalTool.Measure)
        {
            _measure?.Cancel();
            _measure?.ClearHover();
            RefreshMeasurementOverlays();
        }

        if (modalTool != AndroidModalTool.ZoomWindow)
            ResetZoomWindowOverlay();

        if (modalTool != AndroidModalTool.Section)
            ClearSectionPlacementDraft();

        if (modalTool != AndroidModalTool.BodyMove)
            ClearBodyMoveHover();

        UpdateBottomToolbarVisibility();
        if (modalTool == AndroidModalTool.Select
            || previousTool == AndroidModalTool.Select
            || modalTool == AndroidModalTool.Section
            || previousTool == AndroidModalTool.Section)
        {
            UpdateSectionRendererState();
        }
        if (modalTool == AndroidModalTool.BodyMove || previousTool == AndroidModalTool.BodyMove)
            UpdateBodyMoveGizmoRendererState();
        _viewport?.RequestRender();
    }

    private void ActivateSelectTool(string reason)
    {
        CancelActiveModalTool(_activeModalTool, preserveExplode: false);
        _activeModalTool = AndroidModalTool.Select;
        _bottomToolbarMode = BottomToolbarMode.Main;
        ClearSectionPlacementDraft();
        ClearBodyMoveHover();
        UpdateBottomToolbarVisibility();
        UpdateSectionRendererState();
        UpdateBodyMoveGizmoRendererState();
        RefreshMeasurementOverlays();
        _viewport?.RequestRender();
        global::Android.Util.Log.Info("FA.Toolbar", $"Select active: reason={reason}.");
    }

    private void CancelActiveModalTool(AndroidModalTool tool, bool preserveExplode)
    {
        if (tool == AndroidModalTool.Measure)
        {
            CancelBoundingBoxSelectionMode("measure tool exit");
            _measure?.Cancel();
            _measure?.ClearHover();
        }

        if (tool == AndroidModalTool.ZoomWindow)
            ResetZoomWindowOverlay();

        if (tool == AndroidModalTool.Explode && !preserveExplode)
            ClearExplodeView("tool exit");

        if (tool == AndroidModalTool.Section)
        {
            _sectionGizmoHovered = GlesTransformGizmoHandle.None;
            ClearSectionPlacementDraft();
        }

        if (tool == AndroidModalTool.Select)
        {
            if (_sectionGizmoActive != GlesTransformGizmoHandle.None)
                CancelSectionGizmoDrag();
            _sectionGizmoHovered = GlesTransformGizmoHandle.None;
        }

        if (tool == AndroidModalTool.BodyMove)
        {
            if (_bodyMoveGizmoActive != GlesTransformGizmoHandle.None)
                CancelBodyMoveGizmoDrag();
            ClearBodyMoveHover();
        }
    }

    private void UpdateBottomToolbarVisibility()
    {
        bool mainVisible = _bottomToolbarMode == BottomToolbarMode.Main;
        ViewStates mainVisibility = mainVisible ? ViewStates.Visible : ViewStates.Gone;
        ViewStates measureVisibility = _bottomToolbarMode == BottomToolbarMode.Measure ? ViewStates.Visible : ViewStates.Gone;
        ViewStates viewPresetVisibility = _bottomToolbarMode == BottomToolbarMode.ViewPreset ? ViewStates.Visible : ViewStates.Gone;
        ViewStates sectionVisibility = _bottomToolbarMode == BottomToolbarMode.Section ? ViewStates.Visible : ViewStates.Gone;
        ViewStates explodeVisibility = _bottomToolbarMode == BottomToolbarMode.Explode ? ViewStates.Visible : ViewStates.Gone;
        ViewStates renderModeVisibility = _bottomToolbarMode == BottomToolbarMode.RenderMode ? ViewStates.Visible : ViewStates.Gone;

        SetVisibility(_toolSelectButton, mainVisibility);
        SetVisibility(_toolMoveButton, mainVisibility);
        SetVisibility(_toolZoomWindowButton, mainVisibility);
        SetVisibility(_toolZoomSelectedButton, mainVisibility);
        SetVisibility(_toolScanQrButton, mainVisibility);
        SetVisibility(_toolFitViewButton, mainVisibility);
        SetVisibility(_toolViewPresetsButton, mainVisibility);
        SetVisibility(_toolSectionsButton, mainVisibility);
        SetVisibility(_toolMeasureButton, mainVisibility);
        SetVisibility(_toolExplodeButton, mainVisibility);
        SetVisibility(_toolHideButton, mainVisibility);
        SetVisibility(_toolShowAllButton, mainVisibility);
        SetVisibility(_toolIsolateButton, mainVisibility);
        SetVisibility(_toolIsolateXrayButton, mainVisibility);
        SetVisibility(_toolRenderModesButton, mainVisibility);

        SetVisibility(_measureBackButton, measureVisibility);
        SetVisibility(_measurePointToPointButton, measureVisibility);
        SetVisibility(_measureFaceToPointButton, measureVisibility);
        SetVisibility(_measureFaceToFaceButton, measureVisibility);
        SetVisibility(_measureBoundingBoxButton, measureVisibility);
        SetVisibility(_measureEndpointSnapSwitch, measureVisibility);
        SetVisibility(_measureMidpointSnapSwitch, measureVisibility);
        SetVisibility(_measureClearButton, measureVisibility);

        SetVisibility(_viewPresetReturnButton, viewPresetVisibility);
        SetVisibility(_viewIsoButton, viewPresetVisibility);
        SetVisibility(_viewFrontButton, viewPresetVisibility);
        SetVisibility(_viewRightButton, viewPresetVisibility);
        SetVisibility(_viewLeftButton, viewPresetVisibility);
        SetVisibility(_viewTopButton, viewPresetVisibility);
        SetVisibility(_viewBottomButton, viewPresetVisibility);
        SetVisibility(_viewBackButton, viewPresetVisibility);
        SetVisibility(_viewResetButton, viewPresetVisibility);

        SetVisibility(_sectionBackButton, sectionVisibility);
        SetVisibility(_sectionXButton, sectionVisibility);
        SetVisibility(_sectionYButton, sectionVisibility);
        SetVisibility(_sectionZButton, sectionVisibility);
        SetVisibility(_sectionCustomButton, sectionVisibility);
        SetVisibility(_sectionClearButton, sectionVisibility);
        SetVisibility(_sectionFillSwitch, sectionVisibility);
        SetVisibility(_sectionEdgesSwitch, sectionVisibility);
        SetVisibility(_sectionCurvesSwitch, sectionVisibility);
        SetVisibility(_sectionCapsSwitch, sectionVisibility);

        SetVisibility(_explodeBackButton, explodeVisibility);
        SetVisibility(_explodeSlider, explodeVisibility);
        SetVisibility(_explodeValueLabel, explodeVisibility);

        SetVisibility(_renderModeBackButton, renderModeVisibility);
        SetVisibility(_renderModeShadedButton, renderModeVisibility);
        SetVisibility(_renderModeWireframeButton, renderModeVisibility);
        SetVisibility(_renderModeShadedEdgesButton, renderModeVisibility);
        SetVisibility(_renderModeClayButton, renderModeVisibility);

        UpdateMainToolButtonStates();
        UpdateMeasureButtonStates();
        UpdateViewPresetButtonStates();
        UpdateSectionButtonStates();
        UpdateExplodeButtonState();
        UpdateRenderModeButtonStates();
    }

    private void SetMeasureMode(MeasureToolMode mode)
    {
        if (_measure is null)
            return;

        if (!IsInteractiveMeasureMode(mode))
            return;

        CancelBoundingBoxSelectionMode("interactive measure mode selected");

        if (_measure.ActiveMode == mode)
        {
            global::Android.Util.Log.Info("FA.Measure", $"Toolbar mode reselected: {mode}; measurement tool exited.");
            ActivateSelectTool("measure mode reselected");
            return;
        }
        else
        {
            ActivateInteractiveMeasureMode(mode, "toolbar mode button");
            return;
        }
    }

    private async void OnBoundingBoxMeasureClicked(object? sender, EventArgs e)
    {
        if (_measure is null)
            return;
        if (_measureBoundingBoxBusy)
            return;

        if (_measureBoundingBoxAwaitingSelection)
        {
            CancelBoundingBoxSelectionMode("bbox button reselected");
            ActivateInteractiveMeasureMode(_measureBoundingBoxRestoreMode, "bbox selection cancelled");
            return;
        }

        MeasureToolMode restoreMode = PreferredInteractiveMeasureMode();
        if (_selectedNodeIds.Count == 0)
        {
            global::Android.Util.Log.Info("FA.Measure", "BBox button armed: waiting for node selection.");
            _measureBoundingBoxRestoreMode = restoreMode;
            _measureBoundingBoxAwaitingSelection = true;
            _measure.CancelCurrentDraft();
            _measure.SetMode(MeasureToolMode.None);
            Toast.MakeText(this, Resource.String.measure_bounding_box_select_prompt, ToastLength.Short)?.Show();
            UpdateMeasureButtonStates();
            RefreshMeasurementOverlays();
            return;
        }

        await CommitBoundingBoxFromCurrentSelectionAsync(restoreMode, "bbox button selected nodes");
    }

    private async Task CommitBoundingBoxFromCurrentSelectionAsync(MeasureToolMode restoreMode, string reason)
    {
        if (_measure is null || _measureBoundingBoxBusy)
            return;

        if (_selectedNodeIds.Count == 0)
        {
            Toast.MakeText(this, Resource.String.measure_bounding_box_select_prompt, ToastLength.Short)?.Show();
            return;
        }

        _measureBoundingBoxAwaitingSelection = false;
        global::Android.Util.Log.Info("FA.Measure", $"BBox commit requested: reason={reason}, selectedNodes=[{string.Join(",", _selectedNodeIds)}].");
        ApplyMeasurementSettings();
        _measureBoundingBoxBusy = true;
        UpdateMeasureButtonStates();
        bool committed = false;
        try
        {
            committed = await _measure.TryCommitBoundingBoxFromSelectionAsync(_selectedNodeIds.ToArray());
        }
        catch (Exception ex) when (ex is not OutOfMemoryException and not StackOverflowException)
        {
            global::Android.Util.Log.Warn("FA.Measure", "BBox commit failed: " + ex.Message);
        }
        finally
        {
            _measureBoundingBoxBusy = false;
            if (_bottomToolbarMode == BottomToolbarMode.Measure)
                ActivateInteractiveMeasureMode(restoreMode, "bbox finished");
            else
                RefreshMeasurementOverlays();
        }

        if (!committed)
            ShowBoundingBoxSelectionRequiredDialog();
    }

    private void CancelBoundingBoxSelectionMode(string reason)
    {
        _measureBoundingBoxBusy = false;
        if (!_measureBoundingBoxAwaitingSelection)
            return;

        _measureBoundingBoxAwaitingSelection = false;
        global::Android.Util.Log.Info("FA.Measure", $"BBox selection cancelled: reason={reason}.");
        UpdateMeasureButtonStates();
    }

    private void HandleBoundingBoxSelectionTap(TouchGestureEvent ev)
    {
        if (_viewport is null)
            return;

        float density = Resources?.DisplayMetrics?.Density ?? 1.0f;
        if (density <= 0f) density = 1.0f;
        int px = (int)(ev.Position.X * density);
        int py = (int)(ev.Position.Y * density);

        _viewport.PickAsync(px, py, "bbox-select", hit =>
        {
            if (!_measureBoundingBoxAwaitingSelection)
                return;

            if (hit is not > 0)
            {
                Toast.MakeText(this, Resource.String.measure_bounding_box_select_prompt, ToastLength.Short)?.Show();
                return;
            }

            OnPickResult(hit);
            _ = CommitBoundingBoxFromCurrentSelectionAsync(_measureBoundingBoxRestoreMode, "bbox selection tap");
        });
    }

    private void HandleBodyMoveSelectionTap(TouchGestureEvent ev)
    {
        if (_viewport is null)
            return;

        bool hadSelection = _selectedNodeIds.Count > 0;
        float density = Resources?.DisplayMetrics?.Density ?? 1.0f;
        if (density <= 0f) density = 1.0f;
        int px = (int)(ev.Position.X * density);
        int py = (int)(ev.Position.Y * density);

        _viewport.PickAsync(px, py, "body-move-select", hit =>
        {
            if (_activeModalTool != AndroidModalTool.BodyMove)
                return;

            if (hit is > 0)
            {
                OnPickResult(hit);
                UpdateBodyMoveGizmoRendererState();
                _viewport?.RequestRender();
                return;
            }

            OnPickResult(hit);
            if (hadSelection)
                ActivateSelectTool("body move empty tap");
            else
                ShowBodyMovePromptToast();
        });
    }

    private void ShowBodyMovePromptToast()
    {
        long now = System.Environment.TickCount64;
        if (now - _lastBodyMovePromptToastMs < BodyMovePromptToastDebounceMs)
            return;

        _lastBodyMovePromptToastMs = now;
        Toast.MakeText(this, Resource.String.body_move_select_prompt, ToastLength.Short)?.Show();
    }

    private bool CanMoveSelectedBodies()
    {
        Scene? scene = _runtimeScene;
        return scene is not null
            && _selectedNodeIds.Count > 0
            && BodyMoveSelection.ResolveMovableNodes(scene, _selectedNodeIds).Count > 0;
    }

    private bool CanRestoreSelectedPositions()
    {
        Scene? scene = _runtimeScene;
        if (scene is null || _bodyMove is null || _selectedNodeIds.Count == 0)
            return false;

        IReadOnlyList<SceneNode> movableNodes = BodyMoveSelection.ResolveMovableNodes(scene, _selectedNodeIds);
        foreach (SceneNode node in movableNodes)
        {
            if (_bodyMove.HasMove(node.Id))
                return true;
        }

        return false;
    }

    private void RestoreSelectedPositions()
    {
        Scene? scene = _runtimeScene;
        if (scene is null || _bodyMove is null)
            return;

        IReadOnlyList<SceneNode> movableNodes = BodyMoveSelection.ResolveMovableNodes(scene, _selectedNodeIds);
        if (movableNodes.Count == 0)
            return;

        int[] nodeIds = movableNodes.Select(node => node.Id).ToArray();
        BodyMoveSnapshot[] before = _bodyMove.SnapshotFor(nodeIds).ToArray();
        var identityTransforms = movableNodes
            .Select(node => new BodyMoveSnapshot(node.Id, Matrix4d.Identity))
            .ToList();
        _bodyMove.RestoreTransforms(identityTransforms);
        BodyMoveSnapshot[] after = _bodyMove.SnapshotFor(nodeIds).ToArray();
        if (!SameBodyMoveSnapshots(before, after))
            _undoService?.Record(new BodyMoveChange(before, after), "Restore position");
        UpdateBodyMoveGizmoRendererState();
        UpdateMainToolButtonStates();
        _viewport?.RequestRender();
        global::Android.Util.Log.Info("FA.BodyMove", $"Restore positions: nodes=[{string.Join(",", movableNodes.Select(node => node.Id))}].");
    }

