    private void ToggleBodyMoveTool()
    {
        if (!HasScene())
            return;

        if (_activeModalTool == AndroidModalTool.BodyMove)
        {
            ActivateSelectTool("body move toggled off");
            return;
        }

        ActivateBodyMoveTool("toolbar button");
    }

    private void ActivateBodyMoveTool(string reason)
    {
        if (!HasScene())
            return;

        if (_bodyMoveGizmoActive != GlesTransformGizmoHandle.None)
            CancelBodyMoveGizmoDrag();

        EnterToolbarMode(BottomToolbarMode.Main, AndroidModalTool.BodyMove);
        if (_selectedNodeIds.Count == 0)
            ShowBodyMovePromptToast();
        UpdateBodyMoveGizmoRendererState();
        _viewport?.RequestRender();
        global::Android.Util.Log.Info("FA.BodyMove", $"Body Move active: reason={reason}, selectedNodes=[{string.Join(",", _selectedNodeIds)}].");
    }

    private void ActivateZoomWindowTool()
    {
        if (!HasScene())
            return;

        EnterToolbarMode(BottomToolbarMode.Main, AndroidModalTool.ZoomWindow);
        ShowZoomWindowHintTooltip();
        global::Android.Util.Log.Info("FA.ZoomWindow", "Zoom Window active.");
    }

    private void ShowZoomWindowHintTooltip()
    {
        string? hint = GetString(Resource.String.zoom_window_hint);
        if (string.IsNullOrWhiteSpace(hint))
            return;

        string? accessibilityHint = GetString(Resource.String.zoom_window_hint_accessibility);
        if (_toolZoomWindowButton is not null
            && _styledTooltips.TryGetValue(_toolZoomWindowButton, out StyledTooltipController? tooltip))
        {
            tooltip.ShowNow(hint, accessibilityHint);
            return;
        }

        (_toolZoomWindowButton as View ?? _viewport as View)?.AnnounceForAccessibility(accessibilityHint ?? hint);
    }

    private void OnGestureForNavigation(TouchGestureEvent ev)
    {
        _lastNavigationGestureKind = ev.Kind;
        _lastNavigationGesturePositionDip = ev.Position;
        _lastNavigationGestureTicks = Stopwatch.GetTimestamp();

        if (ev.Kind is TouchGestureKind.OrbitBegin
            or TouchGestureKind.OrbitEnd
            or TouchGestureKind.PanZoomBegin
            or TouchGestureKind.PanZoomEnd
            or TouchGestureKind.MouseOrbitBegin
            or TouchGestureKind.MouseOrbitEnd
            or TouchGestureKind.MousePanBegin
            or TouchGestureKind.MousePanEnd
            or TouchGestureKind.MouseWheel
            or TouchGestureKind.Cancel
            or TouchGestureKind.DoubleTap)
        {
            LogSectionCapUiDiagnostic(
                $"viewport gesture: kind={ev.Kind}, posDip=({ev.Position.X:0.#},{ev.Position.Y:0.#}), delta=({ev.PixelDelta.X:0.#},{ev.PixelDelta.Y:0.#}), pinch={ev.PinchScale:0.###}");
        }

        // S12#3: While a section sub-mode is active, a double-tap's first Tap
        // places the section plane (handled by OnGestureForSelection). Swallow
        // the following DoubleTap here so it does not also re-fit the camera.
        // Only DoubleTap is suppressed, so orbit/pan during axis placement still
        // work; Custom mode also stays covered (ShouldSuppressNavigationGestures
        // already suppresses its camera gestures).
        if (ev.Kind == TouchGestureKind.DoubleTap
            && _activeModalTool == AndroidModalTool.Section
            && _activeSectionSubMode != SectionSubMode.None)
        {
            return;
        }

        _interaction?.OnGesture(ev);
    }

    private void OnGestureForToolbarTools(TouchGestureEvent ev)
    {
        if (_bodyMoveGizmoActive != GlesTransformGizmoHandle.None)
            return;

        if (_activeModalTool != AndroidModalTool.ZoomWindow)
            return;

        switch (ev.Kind)
        {
            case TouchGestureKind.OrbitBegin:
            case TouchGestureKind.MouseToolBegin:
                _zoomWindowStartDip = ev.Position;
                _zoomWindowCurrentDip = ev.Position;
                UpdateZoomWindowOverlay();
                break;
            case TouchGestureKind.OrbitDelta:
            case TouchGestureKind.MouseToolDelta:
                if (_zoomWindowStartDip is null)
                    _zoomWindowStartDip = ev.Position;
                _zoomWindowCurrentDip = ev.Position;
                UpdateZoomWindowOverlay();
                break;
            case TouchGestureKind.OrbitEnd:
            case TouchGestureKind.MouseToolEnd:
                _zoomWindowCurrentDip = ev.Position;
                ApplyZoomWindowSelection();
                ActivateSelectTool("zoom window finished");
                break;
            case TouchGestureKind.Cancel:
                CancelZoomWindowTool("zoom window cancelled");
                break;
        }
    }

    private bool ShouldSuppressNavigationGestures()
        => _activeModalTool == AndroidModalTool.ZoomWindow
           || (_activeModalTool == AndroidModalTool.Section && _activeSectionSubMode == SectionSubMode.Custom)
           || _sectionGizmoActive != GlesTransformGizmoHandle.None
           || _bodyMoveGizmoActive != GlesTransformGizmoHandle.None;

    private void CancelZoomWindowTool(string reason)
    {
        ResetZoomWindowOverlay();
        if (_activeModalTool == AndroidModalTool.ZoomWindow)
            ActivateSelectTool(reason);
    }

    private void UpdateZoomWindowOverlay()
    {
        if (_zoomWindowOverlay is null
            || _zoomWindowStartDip is not { } start
            || _zoomWindowCurrentDip is not { } current)
        {
            return;
        }

        float density = Resources?.DisplayMetrics?.Density ?? 1.0f;
        if (density <= 0f) density = 1.0f;
        var rect = new RectF(
            (float)Math.Min(start.X, current.X) * density,
            (float)Math.Min(start.Y, current.Y) * density,
            (float)Math.Max(start.X, current.X) * density,
            (float)Math.Max(start.Y, current.Y) * density);

        _zoomWindowOverlay.SetRect(rect);
        _zoomWindowOverlay.Visibility = ViewStates.Visible;
        _zoomWindowOverlay.Invalidate();
    }

    private void ResetZoomWindowOverlay()
    {
        _zoomWindowStartDip = null;
        _zoomWindowCurrentDip = null;
        if (_zoomWindowOverlay is not null)
        {
            _zoomWindowOverlay.Visibility = ViewStates.Gone;
            _zoomWindowOverlay.SetRect(null);
        }
    }

    private void ApplyZoomWindowSelection()
    {
        if (_zoomWindowStartDip is not { } start
            || _zoomWindowCurrentDip is not { } end
            || _camera is null
            || _viewport is null
            || _runtimeScene is null)
        {
            return;
        }

        float density = Resources?.DisplayMetrics?.Density ?? 1.0f;
        if (density <= 0f) density = 1.0f;
        double viewportWidthDip = _viewport.Width / density;
        double viewportHeightDip = _viewport.Height / density;
        if (viewportWidthDip <= 0.0 || viewportHeightDip <= 0.0)
            return;

        if (!TryNormalizeMarquee(start, end, viewportWidthDip, viewportHeightDip, out MarqueeDipRect marquee))
            return;

        CameraState? snapshot = SnapshotCamera();
        if (snapshot is null)
            return;

        double scale = Math.Clamp(
            Math.Max(marquee.Width / viewportWidthDip, marquee.Height / viewportHeightDip) * 1.05,
            1e-4,
            1.0);

        if (!TryResolveMarqueeAnchor(
                snapshot,
                _runtimeScene,
                marquee,
                viewportWidthDip,
                viewportHeightDip,
                out Vector3d anchorPoint,
                out double anchorDepth))
        {
            return;
        }

        lock (_camera)
        {
            Vector3d forward = _camera.Forward.Normalized();
            if (forward.LengthSquared < 1e-12)
                return;

            if (_camera.IsPerspective)
            {
                double newDepth = Math.Max(anchorDepth * scale, 1e-4);
                _camera.Target = anchorPoint;
                _camera.Position = anchorPoint - forward * newDepth;
            }
            else
            {
                double eyeTargetDistance = Math.Max(_camera.Distance, 1e-4);
                _camera.OrthoWidth = Math.Max(_camera.OrthoWidth * scale, 1e-4);
                _camera.Target = anchorPoint;
                _camera.Position = anchorPoint - forward * eyeTargetDistance;
            }

            BoundingBox clipBounds = GetCameraClipBounds();
            if (clipBounds.IsValid)
                AndroidCameraClipPlanes.Update(_camera, clipBounds);
        }

        RefreshMeasurementOverlays();
        _viewport.RequestRender();
        global::Android.Util.Log.Info("FA.ZoomWindow", $"Applied: rectDip={marquee.Width:0.#}x{marquee.Height:0.#}, scale={scale:0.###}, anchor={Format(anchorPoint)}.");
    }

    private static bool TryNormalizeMarquee(
        Point2D start,
        Point2D end,
        double viewportWidth,
        double viewportHeight,
        out MarqueeDipRect marquee)
    {
        marquee = default;
        if (viewportWidth <= 0.0 || viewportHeight <= 0.0)
            return false;

        double left = Math.Max(0.0, Math.Min(start.X, end.X));
        double top = Math.Max(0.0, Math.Min(start.Y, end.Y));
        double right = Math.Min(viewportWidth, Math.Max(start.X, end.X));
        double bottom = Math.Min(viewportHeight, Math.Max(start.Y, end.Y));
        double width = right - left;
        double height = bottom - top;
        if (width < 8.0 || height < 8.0)
            return false;

        marquee = new MarqueeDipRect(left, top, width, height);
        return true;
    }

    private bool TryResolveMarqueeAnchor(
        CameraState camera,
        Scene scene,
        MarqueeDipRect marquee,
        double viewportWidth,
        double viewportHeight,
        out Vector3d anchorPoint,
        out double anchorDepth)
    {
        anchorPoint = Vector3d.Zero;
        anchorDepth = 0.0;

        CollectVisibleBounds(scene, out List<BoundingBox> visibleBounds, out BoundingBox mergedBounds);
        if (!mergedBounds.IsValid)
            mergedBounds = scene.Bounds;

        var center = new Point2D(marquee.X + marquee.Width * 0.5, marquee.Y + marquee.Height * 0.5);
        if (!TryCreateWorldRay(camera, center, viewportWidth, viewportHeight, out Vector3d centerRayOrigin, out Vector3d centerRayDirection))
            return false;

        Vector3d forward = camera.Forward.Normalized();
        if (forward.LengthSquared < 1e-12)
            return false;

        if (visibleBounds.Count > 0
            && TryFindMarqueeSampleHit(camera, marquee, viewportWidth, viewportHeight, visibleBounds, center, out Vector3d sampleHit)
            && TryIntersectRayWithPlane(centerRayOrigin, centerRayDirection, sampleHit, forward, out anchorPoint))
        {
            anchorDepth = Vector3d.Dot(anchorPoint - camera.Position, forward);
            if (anchorDepth >= 1e-4)
                return true;
        }

        if (mergedBounds.IsValid
            && TryIntersectRayAabb(centerRayOrigin, centerRayDirection, mergedBounds, out double tBounds))
        {
            anchorPoint = centerRayOrigin + centerRayDirection * tBounds;
            anchorDepth = Vector3d.Dot(anchorPoint - camera.Position, forward);
            if (anchorDepth >= 1e-4)
                return true;
        }

        if (TryIntersectRayWithPlane(centerRayOrigin, centerRayDirection, camera.Target, forward, out anchorPoint))
        {
            anchorDepth = Vector3d.Dot(anchorPoint - camera.Position, forward);
            return anchorDepth >= 1e-4;
        }

        return false;
    }

    private static bool TryFindMarqueeSampleHit(
        CameraState camera,
        MarqueeDipRect marquee,
        double viewportWidth,
        double viewportHeight,
        IReadOnlyList<BoundingBox> visibleBounds,
        Point2D marqueeCenter,
        out Vector3d hitPoint)
    {
        hitPoint = Vector3d.Zero;
        double bestCenterDistanceSquared = double.MaxValue;
        bool found = false;

        ReadOnlySpan<(double U, double V)> samples =
        [
            (0.50, 0.50),
            (0.50, 0.25),
            (0.75, 0.50),
            (0.50, 0.75),
            (0.25, 0.50),
            (0.25, 0.25),
            (0.75, 0.25),
            (0.75, 0.75),
            (0.25, 0.75),
        ];

        foreach ((double u, double v) in samples)
        {
            var samplePoint = new Point2D(marquee.X + marquee.Width * u, marquee.Y + marquee.Height * v);
            if (!TryCreateWorldRay(camera, samplePoint, viewportWidth, viewportHeight, out Vector3d rayOrigin, out Vector3d rayDirection))
                continue;

            if (!TryFindClosestBoundsHit(visibleBounds, rayOrigin, rayDirection, out Vector3d sampleHit))
                continue;

            double dx = samplePoint.X - marqueeCenter.X;
            double dy = samplePoint.Y - marqueeCenter.Y;
            double centerDistanceSquared = dx * dx + dy * dy;
            if (centerDistanceSquared >= bestCenterDistanceSquared)
                continue;

            bestCenterDistanceSquared = centerDistanceSquared;
            hitPoint = sampleHit;
            found = true;
        }

        return found;
    }

    private static void CollectVisibleBounds(Scene scene, out List<BoundingBox> visibleBounds, out BoundingBox mergedBounds)
    {
        visibleBounds = new List<BoundingBox>();
        mergedBounds = BoundingBox.Empty;

        foreach (SceneNode node in scene.GetVisibleNodes())
        {
            if (!SceneBoundsUtilities.TryComputeNodeBounds(scene, node, out BoundingBox bounds))
                continue;

            visibleBounds.Add(bounds);
            mergedBounds = BoundingBox.Merge(mergedBounds, bounds);
        }
    }

    private static bool TryFindClosestBoundsHit(
        IReadOnlyList<BoundingBox> boundsSet,
        Vector3d rayOrigin,
        Vector3d rayDirection,
        out Vector3d hitPoint,
        Func<Vector3d, bool>? hitPointFilter = null)
    {
        hitPoint = Vector3d.Zero;
        double closestT = double.MaxValue;
        bool found = false;

        foreach (BoundingBox bounds in boundsSet)
        {
            if (!TryIntersectRayAabb(rayOrigin, rayDirection, bounds, out double t))
                continue;

            Vector3d candidatePoint = rayOrigin + rayDirection * t;
            if (hitPointFilter is not null && !hitPointFilter(candidatePoint))
                continue;

            if (t >= closestT)
                continue;

            closestT = t;
            hitPoint = candidatePoint;
            found = true;
        }

        return found;
    }

    private static bool TryFindClosestSectionVisibleBoundsHit(
        IEnumerable<BoundingBox> boundsSet,
        Vector3d rayOrigin,
        Vector3d rayDirection,
        IReadOnlyList<SectionPlane> sectionPlanes,
        double sectionToleranceScale,
        out Vector3d hitPoint)
    {
        hitPoint = Vector3d.Zero;
        double closestT = double.MaxValue;
        bool found = false;

        foreach (BoundingBox bounds in boundsSet)
        {
            if (!TryFindSectionVisibleBoundsHit(
                    bounds,
                    rayOrigin,
                    rayDirection,
                    sectionPlanes,
                    sectionToleranceScale,
                    out double t,
                    out Vector3d candidatePoint))
            {
                continue;
            }

            if (t >= closestT)
                continue;

            closestT = t;
            hitPoint = candidatePoint;
            found = true;
        }

        return found;
    }

    private static bool TryFindSectionVisibleBoundsHit(
        BoundingBox bounds,
        Vector3d rayOrigin,
        Vector3d rayDirection,
        IReadOnlyList<SectionPlane> sectionPlanes,
        double sectionToleranceScale,
        out double t,
        out Vector3d hitPoint)
    {
        const double HitDistanceEpsilon = 1e-6;

        t = 0.0;
        hitPoint = Vector3d.Zero;

        if (!TryIntersectRayAabbInterval(rayOrigin, rayDirection, bounds, out double tMin, out double tMax))
            return false;

        if (!AndroidSectionClipper.TryClipRayToVisibleInterval(
                rayOrigin,
                rayDirection,
                tMin,
                tMax,
                sectionPlanes,
                sectionToleranceScale,
                out double visibleMin,
                out double visibleMax))
        {
            return false;
        }

        t = visibleMin > HitDistanceEpsilon ? visibleMin : visibleMax;
        if (t <= HitDistanceEpsilon || t > visibleMax || !double.IsFinite(t))
            return false;

        hitPoint = rayOrigin + rayDirection * t;
        return AndroidSectionClipper.IsPointVisible(hitPoint, sectionPlanes, sectionToleranceScale);
    }

    private static bool TryIntersectRayWithPlane(
        Vector3d rayOrigin,
        Vector3d rayDirection,
        Vector3d planePoint,
        Vector3d planeNormal,
        out Vector3d intersection)
    {
        intersection = Vector3d.Zero;
        double denominator = Vector3d.Dot(rayDirection, planeNormal);
        if (Math.Abs(denominator) < 1e-10)
            return false;

        double t = Vector3d.Dot(planePoint - rayOrigin, planeNormal) / denominator;
        if (t < 1e-6)
            return false;

        intersection = rayOrigin + rayDirection * t;
        return true;
    }

    private static bool TryCreateWorldRay(
        CameraState camera,
        Point2D dipPos,
        double viewportWidthDip,
        double viewportHeightDip,
        out Vector3d rayOrigin,
        out Vector3d rayDir)
    {
        rayOrigin = default;
        rayDir = default;
        if (viewportWidthDip <= 0.0 || viewportHeightDip <= 0.0)
            return false;

        double nx = (dipPos.X * 2.0 / viewportWidthDip) - 1.0;
        double ny = -((dipPos.Y * 2.0 / viewportHeightDip) - 1.0);

        Vector3d position = camera.Position;
        Vector3d target = camera.Target;
        Vector3d up = camera.UpDirection.Normalized();
        Vector3d forward = (target - position).Normalized();
        if (forward.LengthSquared < 1e-12)
            return false;
        Vector3d right = Vector3d.Cross(forward, up).Normalized();
        if (right.LengthSquared < 1e-12)
            return false;
        Vector3d trueUp = Vector3d.Cross(right, forward);

        double aspect = viewportWidthDip / viewportHeightDip;
        if (camera.IsPerspective)
        {
            double halfFovTan = Math.Tan(camera.FieldOfView * 0.5);
            rayOrigin = position;
            rayDir = (forward + right * (nx * halfFovTan * aspect) + trueUp * (ny * halfFovTan)).Normalized();
        }
        else
        {
            double halfW = camera.OrthoWidth * 0.5;
            double halfH = halfW / aspect;
            rayOrigin = position + right * (nx * halfW) + trueUp * (ny * halfH);
            rayDir = forward;
        }

        return true;
    }

    private void ZoomToSelection()
    {
        if (_camera is null)
            return;

        if (!TryGetSelectionBounds(out BoundingBox bounds))
        {
            Toast.MakeText(this, Resource.String.measure_select_body_first, ToastLength.Short)?.Show();
            return;
        }

        double aspect = GetViewportAspect();
        BoundingBox clipBounds = GetCameraClipBounds();
        lock (_camera)
        {
            FitCameraToBoundsPreservingView(_camera, bounds, aspect);
            if (clipBounds.IsValid)
                AndroidCameraClipPlanes.Update(_camera, clipBounds);
        }

        _interaction?.SetNavigationPivot(bounds.Center);
        RefreshMeasurementOverlays();
        _viewport?.RequestRender();
        global::Android.Util.Log.Info("FA.Toolbar", $"Zoom Selected: nodeIds=[{string.Join(",", _selectedNodeIds)}], diag={bounds.Diagonal:0.###}.");
    }

    private bool TryGetSelectionBounds(out BoundingBox bounds)
    {
        bounds = BoundingBox.Empty;
        Scene? scene = _runtimeScene;
        if (scene is null || _selectedNodeIds.Count == 0)
            return false;

        foreach (int nodeId in _selectedNodeIds)
        {
            if (scene.GetNode(nodeId) is SceneNode node
                && SceneBoundsUtilities.TryComputeNodeBounds(scene, node, out BoundingBox nodeBounds))
            {
                bounds.Merge(nodeBounds);
            }
        }

        return bounds.IsValid;
    }

    private bool CanHideSelectedNodes()
    {
        Scene? scene = _runtimeScene;
        if (scene is null || _selectedNodeIds.Count == 0)
            return false;

        if (AndroidScenePackageState.IsFa(scene.PackageInfo))
            return GetSelectedVisibilityOccurrenceIds(scene).Length > 0
                && _selectedNodeIds.Any(IsNodeEffectivelyVisible);

        foreach (int nodeId in GetSelectedVisibilityNodeIds(scene))
        {
            if (IsNodeEffectivelyVisible(nodeId))
                return true;
        }

        return false;
    }

    private bool IsNodeEffectivelyVisible(int nodeId)
    {
        Scene? scene = _runtimeScene;
        SceneNode? node = scene?.GetNode(nodeId);
        if (node is null)
            return false;

        while (node is not null)
        {
            if (!node.Visible)
                return false;

            node = node.Parent;
        }

        return true;
    }

    private bool CanShowAllNodes()
    {
        Scene? scene = _runtimeScene;
        if (scene is null)
            return false;

        return _xrayOpaqueNodeIds.Count > 0
            || _xrayBackgroundNodeIds.Length > 0
            || (AndroidScenePackageState.IsFa(scene.PackageInfo)
                && _packageSession is not null
                && (_packageSession.HiddenOccurrenceIds.Count > 0
                    || _packageSession.IsolatedOccurrenceIds.Count > 0))
            || scene.NodesById.Values.Any(node => !node.Visible);
    }

    private void HideSelectedNodes()
    {
        Scene? scene = _runtimeScene;
        if (scene is null || _selectedNodeIds.Count == 0)
            return;

        if (AndroidScenePackageState.IsFa(scene.PackageInfo) && _packageSession is not null)
        {
            string[] selectedOccurrenceIds = GetSelectedVisibilityOccurrenceIds(scene);
            if (selectedOccurrenceIds.Length == 0)
            {
                ShowAlreadyHiddenFeedback();
                return;
            }

            using IUndoTransaction? faUndo = _undoService?.Begin("Hide selection");
            VisibilityStateSnapshot faBefore = CaptureVisibilitySnapshot();
            ClearXrayIsolationState();
            var hiddenOccurrenceIds = new HashSet<string>(_packageSession.HiddenOccurrenceIds, StringComparer.Ordinal);
            hiddenOccurrenceIds.UnionWith(selectedOccurrenceIds);
            AndroidScenePackageState.ApplyVisibilityState(
                scene,
                _packageSession,
                hiddenOccurrenceIds,
                _packageSession.IsolatedOccurrenceIds);
            ClearSelectionAfterVisibilityMutation(scene);
            AddVisibilityUndo(faUndo, faBefore, "Hide selection");
            FinalizeVisibilityMutation("hide-fa", selectedOccurrenceIds.Length);
            return;
        }

        int[] targetNodeIds = GetSelectedVisibilityNodeIds(scene);
        if (targetNodeIds.Length == 0)
        {
            ShowAlreadyHiddenFeedback();
            return;
        }

        using IUndoTransaction? undo = _undoService?.Begin("Hide selection");
        VisibilityStateSnapshot before = CaptureVisibilitySnapshot();
        ClearXrayIsolationState();
        foreach (int nodeId in targetNodeIds)
        {
            if (scene.GetNode(nodeId) is SceneNode node)
                node.Visible = false;
        }

        ClearSelectionAfterVisibilityMutation(scene);
        AddVisibilityUndo(undo, before, "Hide selection");
        FinalizeVisibilityMutation("hide", targetNodeIds.Length);
    }

    private void ShowAlreadyHiddenFeedback()
        => Toast.MakeText(this, "Selected geometry is already hidden.", ToastLength.Short)?.Show();

    private void ShowAllNodes()
    {
        Scene? scene = _runtimeScene;
        if (scene is null)
            return;

        using IUndoTransaction? undo = _undoService?.Begin("Show all");
        VisibilityStateSnapshot before = CaptureVisibilitySnapshot();
        bool hadXray = _xrayOpaqueNodeIds.Count > 0 || _xrayBackgroundNodeIds.Length > 0;
        ClearXrayIsolationState();

        if (AndroidScenePackageState.IsFa(scene.PackageInfo) && _packageSession is not null)
        {
            int changedCount = _packageSession.HiddenOccurrenceIds.Count + _packageSession.IsolatedOccurrenceIds.Count;
            bool stateChanged = AndroidScenePackageState.ApplyVisibilityState(
                scene,
                _packageSession,
                Array.Empty<string>(),
                Array.Empty<string>());
            if (!stateChanged)
                AndroidScenePackageState.ApplyVisibilityToScene(scene, _packageSession);
            if (changedCount > 0 || hadXray)
                AddVisibilityUndo(undo, before, "Show all");
            else
                undo?.Abort();
            FinalizeVisibilityMutation("show-all-fa", changedCount);
            return;
        }

        int changed = 0;
        foreach (SceneNode node in scene.NodesById.Values)
        {
            if (node.Visible)
                continue;
            node.Visible = true;
            changed++;
        }

        if (changed > 0 || hadXray)
            AddVisibilityUndo(undo, before, "Show all");
        else
            undo?.Abort();
        FinalizeVisibilityMutation("show-all", changed);
    }

    private void IsolateSelectedNodes()
    {
        Scene? scene = _runtimeScene;
        if (scene is null || _selectedNodeIds.Count == 0)
            return;

        if (AndroidScenePackageState.IsFa(scene.PackageInfo) && _packageSession is not null)
        {
            string[] selectedOccurrenceIds = GetSelectedVisibilityOccurrenceIds(scene);
            if (selectedOccurrenceIds.Length == 0)
                return;

            using IUndoTransaction? faUndo = _undoService?.Begin("Isolate selection");
            VisibilityStateSnapshot faBefore = CaptureVisibilitySnapshot();
            ClearXrayIsolationState();
            AndroidScenePackageState.ApplyVisibilityState(
                scene,
                _packageSession,
                Array.Empty<string>(),
                selectedOccurrenceIds);
            ClearSelectionAfterVisibilityMutation(scene);
            AddVisibilityUndo(faUndo, faBefore, "Isolate selection");
            FinalizeVisibilityMutation("isolate-fa", selectedOccurrenceIds.Length);
            return;
        }

        int[] selectedNodeIds = GetSelectedVisibilityNodeIds(scene);
        HashSet<int> visibleNodeIds = GetIsolatedVisibleNodeIds(scene, selectedNodeIds);
        if (visibleNodeIds.Count == 0)
            return;

        using IUndoTransaction? undo = _undoService?.Begin("Isolate selection");
        VisibilityStateSnapshot before = CaptureVisibilitySnapshot();
        ClearXrayIsolationState();
        ApplyIsolatedVisibility(scene, visibleNodeIds);
        ClearSelectionAfterVisibilityMutation(scene);
        AddVisibilityUndo(undo, before, "Isolate selection");
        FinalizeVisibilityMutation("isolate", visibleNodeIds.Count);
    }

    private void IsolateXraySelectedNodes()
    {
        Scene? scene = _runtimeScene;
        if (scene is null || _selectedNodeIds.Count == 0)
            return;

        if (AndroidScenePackageState.IsFa(scene.PackageInfo) && _packageSession is not null)
        {
            string[] selectedOccurrenceIds = GetSelectedVisibilityOccurrenceIds(scene);
            if (selectedOccurrenceIds.Length == 0)
                return;

            using IUndoTransaction? faUndo = _undoService?.Begin("Isolate (x-ray)");
            VisibilityStateSnapshot faBefore = CaptureVisibilitySnapshot();
            bool resetChanged = AndroidScenePackageState.ApplyVisibilityState(
                scene,
                _packageSession,
                Array.Empty<string>(),
                Array.Empty<string>());
            if (!resetChanged)
                AndroidScenePackageState.ApplyVisibilityToScene(scene, _packageSession);
            int[] selectedNodeIdsForOccurrences = AndroidScenePackageState.GetNodeIdsForOccurrences(scene, selectedOccurrenceIds);
            HashSet<int> opaqueNodeIdsForOccurrences = GetIsolatedVisibleNodeIds(scene, selectedNodeIdsForOccurrences);
            if (opaqueNodeIdsForOccurrences.Count == 0)
            {
                _visibilityStateAccess?.RestoreSnapshot(faBefore);
                faUndo?.Abort();
                return;
            }

            int[] backgroundNodeIdsForOccurrences = scene.GetVisibleNodes()
                .Select(node => node.Id)
                .Where(nodeId => !opaqueNodeIdsForOccurrences.Contains(nodeId))
                .OrderBy(nodeId => nodeId)
                .ToArray();

            AndroidScenePackageState.ApplyVisibilityState(
                scene,
                _packageSession,
                Array.Empty<string>(),
                selectedOccurrenceIds);
            SetXrayIsolationState(
                opaqueNodeIdsForOccurrences,
                backgroundNodeIdsForOccurrences,
                DefaultXrayIsolationOpacity);
            EnsureBackgroundNodesVisible(scene, backgroundNodeIdsForOccurrences);
            ClearSelectionAfterVisibilityMutation(scene);
            AddVisibilityUndo(faUndo, faBefore, "Isolate (x-ray)");
            FinalizeVisibilityMutation("isolate-xray-fa", opaqueNodeIdsForOccurrences.Count);
            return;
        }

        int[] selectedNodeIds = GetSelectedVisibilityNodeIds(scene);
        HashSet<int> opaqueNodeIds = GetIsolatedVisibleNodeIds(scene, selectedNodeIds);
        if (opaqueNodeIds.Count == 0)
            return;

        using IUndoTransaction? undo = _undoService?.Begin("Isolate (x-ray)");
        VisibilityStateSnapshot before = CaptureVisibilitySnapshot();
        foreach (SceneNode node in scene.NodesById.Values)
            node.Visible = true;

        int[] backgroundNodeIds = scene.GetVisibleNodes()
            .Select(node => node.Id)
            .Where(nodeId => !opaqueNodeIds.Contains(nodeId))
            .OrderBy(nodeId => nodeId)
            .ToArray();

        ApplyIsolatedVisibility(scene, opaqueNodeIds);
        SetXrayIsolationState(opaqueNodeIds, backgroundNodeIds, DefaultXrayIsolationOpacity);
        // S20#2: x-ray ghosting is driven by the background node-id set, not by
        // SceneNode.Visible, so keep the ghosted background nodes Visible=true
        // (mirrors the FA branch above). Otherwise ApplyIsolatedVisibility leaves
        // them Visible=false and the model tree shows them hidden while the
        // viewport still renders them ghosted -> tree<->viewport desync.
        EnsureBackgroundNodesVisible(scene, backgroundNodeIds);
        ClearSelectionAfterVisibilityMutation(scene);
        AddVisibilityUndo(undo, before, "Isolate (x-ray)");
        FinalizeVisibilityMutation("isolate-xray", opaqueNodeIds.Count);
    }

    private void ClearSelectionAfterVisibilityMutation(Scene scene)
    {
        ReplaceSelectedNodeIds(scene, Array.Empty<int>(), scrollModelExplorerToSelection: false);
    }

    private int[] GetSelectedVisibilityNodeIds(Scene scene)
        => _selectedNodeIds
            .Where(nodeId => scene.GetNode(nodeId) is not null)
            .Distinct()
            .OrderBy(nodeId => nodeId)
            .ToArray();

    private string[] GetSelectedVisibilityOccurrenceIds(Scene scene)
        => AndroidScenePackageState.GetOccurrenceIdsForNodes(scene, _selectedNodeIds);

    private void SyncPackageSelectionFromSelectedNodes(Scene scene)
    {
        if (_packageSession is null || !AndroidScenePackageState.IsFa(scene.PackageInfo))
            return;

        _packageSession.SetSelection(GetSelectedVisibilityOccurrenceIds(scene));
    }

    private static HashSet<int> GetIsolatedVisibleNodeIds(Scene scene, IEnumerable<int> seedNodeIds)
    {
        var visibleNodeIds = new HashSet<int>();
        foreach (int nodeId in seedNodeIds.Distinct())
        {
            SceneNode? node = scene.GetNode(nodeId);
            if (node is null)
                continue;

            visibleNodeIds.Add(node.Id);
            CollectDescendantIds(node, visibleNodeIds);

            for (SceneNode? ancestor = node.Parent; ancestor is not null; ancestor = ancestor.Parent)
                visibleNodeIds.Add(ancestor.Id);
        }

        return visibleNodeIds;
    }

    private static void CollectDescendantIds(SceneNode node, HashSet<int> ids)
    {
        foreach (SceneNode child in node.Children)
        {
            if (ids.Add(child.Id))
                CollectDescendantIds(child, ids);
        }
    }

    private static int ApplyIsolatedVisibility(Scene scene, HashSet<int> visibleNodeIds)
    {
        int changed = 0;
        foreach (SceneNode node in scene.NodesById.Values)
        {
            bool shouldBeVisible = visibleNodeIds.Contains(node.Id);
            if (node.Visible == shouldBeVisible)
                continue;

            node.Visible = shouldBeVisible;
            changed++;
        }

        return changed;
    }

    private static void EnsureBackgroundNodesVisible(Scene scene, IEnumerable<int> backgroundNodeIds)
    {
        foreach (int nodeId in backgroundNodeIds)
        {
            SceneNode? node = scene.GetNode(nodeId);
            if (node is null)
                continue;

            node.Visible = true;
            for (SceneNode? ancestor = node.Parent; ancestor is not null; ancestor = ancestor.Parent)
            {
                if (ancestor.Visible)
                    break;

                ancestor.Visible = true;
            }
        }
    }

    private void SetXrayIsolationState(IEnumerable<int> opaqueNodeIds, IEnumerable<int> backgroundNodeIds, float opacity)
    {
        _xrayOpaqueNodeIds.Clear();
        _xrayOpaqueNodeIds.UnionWith(opaqueNodeIds);
        _xrayBackgroundNodeIds = backgroundNodeIds.Distinct().OrderBy(nodeId => nodeId).ToArray();
        _xrayIsolationOpacity = Math.Clamp(opacity, 0.02f, 0.98f);
    }

    private void ClearXrayIsolationState()
    {
        _xrayOpaqueNodeIds.Clear();
        _xrayBackgroundNodeIds = Array.Empty<int>();
        _xrayIsolationOpacity = DefaultXrayIsolationOpacity;
    }

    private VisibilityStateSnapshot CaptureVisibilitySnapshot()
        => _visibilityStateAccess?.SnapshotAll() ?? VisibilityStateSnapshot.Empty;

    private void AddVisibilityUndo(IUndoTransaction? transaction, VisibilityStateSnapshot before, string description)
        => transaction?.Add(new VisibilityChange(before, CaptureVisibilitySnapshot(), description));

    private void FinalizeVisibilityMutation(string action, int count)
    {
        if (_viewport is not null)
            _viewport.Renderer.HoveredMeshIndex = 0;
        SyncRuntimeSceneVisibilityToRenderer(action);
        RefreshMeasurementOverlays();
        _modelExplorerPanel?.RefreshVisibility();
        UpdateMainToolButtonStates();
        UpdateViewPresetButtonStates();
        _viewport?.RequestRender();
        global::Android.Util.Log.Info(
            "FA.Visibility",
            $"{action}: count={count}, selected=[{string.Join(",", _selectedNodeIds)}], xrayOpaque={_xrayOpaqueNodeIds.Count}, xrayBackground={_xrayBackgroundNodeIds.Length}.");
    }

    private void SyncRuntimeSceneVisibilityToRenderer(string reason)
    {
        if (_viewport is null || _runtimeScene is null)
            return;

        Scene scene = _runtimeScene;
        var viewport = _viewport;
        int[] opaqueNodeIds = _xrayOpaqueNodeIds.OrderBy(nodeId => nodeId).ToArray();
        int[] backgroundNodeIds = _xrayBackgroundNodeIds;
        float opacity = _xrayIsolationOpacity;

        viewport.QueueRendererCommand("sync-visibility-" + reason, _ =>
        {
            if (!ReferenceEquals(_runtimeScene, scene))
            {
                global::Android.Util.Log.Warn("FA.Visibility", $"Skipped stale visibility sync: reason={reason}.");
                return;
            }

            var renderer = viewport.Renderer;
            renderer.Scene?.SyncNodeVisibility(scene);
            renderer.XrayIsolationOpacity = opacity;
            renderer.XrayOpaqueNodeIds = opaqueNodeIds;
            renderer.XrayBackgroundNodeIds = backgroundNodeIds;
        });
        viewport.RequestRender();
    }

    private void SetRenderModeFromToolbar(RenderMode mode)
        => _ = SetRenderModeFromToolbarAsync(mode);

    private async Task SetRenderModeFromToolbarAsync(RenderMode mode)
    {
        var viewport = _viewport;
        int busyVersion = Interlocked.Increment(ref _renderModeBusyVersion);
        _renderModeChangeInFlight = true;
        ShowRenderBusy("Updating render...");
        UpdateMainToolButtonStates();
        UpdateRenderModeButtonStates();

        global::Android.Util.Log.Info("FA.RenderMode", $"Selected mode={mode}; waiting for rendered frame.");

        switch (mode)
        {
            case RenderMode.ShadedWithEdges:
                AppSettings.RenderMode = (int)RenderMode.ShadedWithEdges;
                AppSettings.SetEdgesEnabledFromUi(true);
                break;
            case RenderMode.Shaded:
                // Toolbar contract mirrors desktop: Shaded is surfaces only;
                // ShadedWithEdges is the explicit edge-enabled mode.
                AppSettings.RenderMode = (int)RenderMode.Shaded;
                AppSettings.SetEdgesEnabledFromUi(false);
                break;
            case RenderMode.Wireframe:
                AppSettings.RenderMode = (int)RenderMode.Wireframe;
                break;
            case RenderMode.Clay:
                AppSettings.RenderMode = (int)RenderMode.Clay;
                break;
        }

        try
        {
            ApplySettingsToScene();
            UpdateRenderModeButtonStates();
            ExitRenderModeToolbar();

            if (viewport is not null)
            {
                using var timeout = new CancellationTokenSource(System.TimeSpan.FromSeconds(8));
                Task frameTask = viewport.WaitForNextRenderedFrameAsync(timeout.Token);
                Task minimumVisibleTask = Task.Delay(180);
                await Task.WhenAll(frameTask, minimumVisibleTask);
            }
        }
        catch (System.OperationCanceledException)
        {
            global::Android.Util.Log.Warn("FA.RenderMode", $"Timed out waiting for first rendered frame after mode={mode}.");
        }
        catch (Exception ex)
        {
            global::Android.Util.Log.Warn("FA.RenderMode", $"Render mode update failed for mode={mode}: {ex.Message}");
        }
        finally
        {
            if (busyVersion == Volatile.Read(ref _renderModeBusyVersion))
            {
                _renderModeChangeInFlight = false;
                UpdateMainToolButtonStates();
                UpdateRenderModeButtonStates();
            }

            HideRenderBusy(busyVersion);
        }
    }

    private void BeginQrScan()
    {
        if (!HasScene())
            return;

        if (Build.VERSION.SdkInt >= BuildVersionCodes.M
            && CheckSelfPermission(global::Android.Manifest.Permission.Camera) != Permission.Granted)
        {
            if (ShouldShowRequestPermissionRationale(global::Android.Manifest.Permission.Camera))
                ShowQrCameraPermissionRationale();
            else
                RequestCameraPermissionForQr();
            return;
        }

        ShowQrScannerDialog();
    }

    private void RequestCameraPermissionForQr()
    {
        if (Build.VERSION.SdkInt < BuildVersionCodes.M)
        {
            ShowQrScannerDialog();
            return;
        }

        _pendingQrScanAfterPermission = true;
        RequestPermissions([global::Android.Manifest.Permission.Camera], RequestCameraForQr);
    }

    private void ShowQrCameraPermissionRationale()
    {
        ShowOwnedDialog(
            new AlertDialog.Builder(this)
                .SetTitle(Resource.String.qr_camera_permission_title)!
                .SetMessage(Resource.String.qr_camera_permission_rationale)!
                .SetNegativeButton(Resource.String.qr_camera_permission_manual, (_, _) => ShowQrManualInputDialog())!
                .SetPositiveButton(Resource.String.qr_camera_permission_allow, (_, _) => RequestCameraPermissionForQr())!);
    }

    public override void OnRequestPermissionsResult(int requestCode, string[] permissions, Permission[] grantResults)
    {
        base.OnRequestPermissionsResult(requestCode, permissions, grantResults);

        if (requestCode != RequestCameraForQr)
            return;

        bool shouldOpen = _pendingQrScanAfterPermission;
        _pendingQrScanAfterPermission = false;
        if (!shouldOpen)
            return;

        if (grantResults.Length > 0 && grantResults[0] == Permission.Granted)
        {
            ShowQrScannerDialog();
        }
        else if (Build.VERSION.SdkInt >= BuildVersionCodes.M
                 && !ShouldShowRequestPermissionRationale(global::Android.Manifest.Permission.Camera))
        {
            ShowQrCameraPermissionSettingsDialog();
        }
        else
        {
            ShowQrCameraPermissionDeniedDialog();
        }
    }

    private void ShowQrCameraPermissionDeniedDialog()
    {
        ShowOwnedDialog(
            new AlertDialog.Builder(this)
                .SetTitle(Resource.String.qr_camera_permission_denied_title)!
                .SetMessage(Resource.String.qr_camera_permission_denied_message)!
                .SetNegativeButton(Resource.String.qr_camera_permission_manual, (_, _) => ShowQrManualInputDialog())!
                .SetPositiveButton(Resource.String.qr_camera_permission_allow, (_, _) => RequestCameraPermissionForQr())!);
    }

    private void ShowQrCameraPermissionSettingsDialog()
    {
        ShowOwnedDialog(
            new AlertDialog.Builder(this)
                .SetTitle(Resource.String.qr_camera_permission_denied_title)!
                .SetMessage(Resource.String.qr_camera_permission_settings_message)!
                .SetNegativeButton(Resource.String.qr_camera_permission_manual, (_, _) => ShowQrManualInputDialog())!
                .SetPositiveButton(Resource.String.qr_camera_permission_settings, (_, _) => OpenAppPermissionSettings())!);
    }

    private void OpenAppPermissionSettings()
    {
        try
        {
            StartActivity(new Intent(
                global::Android.Provider.Settings.ActionApplicationDetailsSettings,
                AndroidUri.Parse("package:" + PackageName)));
        }
        catch (Exception ex)
        {
            global::Android.Util.Log.Warn("FA.QR", "Could not open app permission settings: " + ex.Message);
            ShowQrManualInputDialog();
        }
    }

    private void ShowQrScannerDialog()
    {
        if (!HasScene())
            return;

        try
        {
            ShowOwnedDialog(new AndroidQrScannerDialog(
                this,
                ResolveQrPayloadForDialog,
                SelectQrMatch,
                IsolateQrMatch,
                IsolateXrayQrMatch));
        }
        catch (Exception ex)
        {
            global::Android.Util.Log.Warn("FA.QR", "Could not open camera scanner: " + ex.Message);
            ShowQrManualInputDialog();
        }
    }

    private void ShowQrManualInputDialog()
    {
        var input = new EditText(this)
        {
            Hint = "FA1:PART_NUMBER",
        };
        input.SetSingleLine(true);
        input.SetSelectAllOnFocus(true);
        int padding = Dp(20);
        var container = new FrameLayout(this);
        container.SetPadding(padding, Dp(8), padding, 0);
        container.AddView(input, new FrameLayout.LayoutParams(
            ViewGroup.LayoutParams.MatchParent,
            ViewGroup.LayoutParams.WrapContent));

        ShowOwnedDialog(
            new AlertDialog.Builder(this)
                .SetTitle(Resource.String.cd_tool_scan_qr)!
                .SetView(container)!
                .SetNegativeButton(global::Android.Resource.String.Cancel, (_, _) => { })!
                .SetPositiveButton(global::Android.Resource.String.Ok, (_, _) => ResolveQrPayload(input.Text))!);
    }

    private void ResolveQrPayload(string? rawPayload)
    {
        AndroidQrScanResult result = ResolveQrPayloadForDialog(rawPayload);
        if (result.Matches.Count == 0)
        {
            Toast.MakeText(this, result.StatusMessage, ToastLength.Short)?.Show();
            return;
        }

        if (result.Matches.Count > 1)
        {
            ShowQrMatchesDialog(result.ResolvedPartNumber, result.Matches);
            return;
        }

        SelectQrMatch(result.Matches[0].NodeId);
    }

    private AndroidQrScanResult ResolveQrPayloadForDialog(string? rawPayload)
    {
        Scene? scene = _runtimeScene;
        string lastScan = rawPayload?.Trim() ?? string.Empty;
        if (scene is null)
            return new AndroidQrScanResult(lastScan, string.Empty, "Open a model before scanning.", Array.Empty<AndroidQrScanMatch>());

        var sw = System.Diagnostics.Stopwatch.StartNew();
        QrPayloadDecodeResult decoded = DecodeQrPayload(rawPayload);
        if (!decoded.Success)
        {
            string message = decoded.Message ?? "QR payload was not recognized.";
            global::Android.Util.Log.Info("FA.QR", $"Rejected QR payload: {message}");
            return new AndroidQrScanResult(lastScan, string.Empty, message, Array.Empty<AndroidQrScanMatch>());
        }

        string partNumber = decoded.PartNumber!;
        IReadOnlyList<SceneNode> nodes = FindNodesByPartNumber(scene, partNumber);
        AndroidQrScanMatch[] matches = nodes
            .Select(CreateQrScanMatch)
            .ToArray();

        string status = matches.Length switch
        {
            0 => $"Not found: {partNumber}",
            1 => $"1 part matches {partNumber}.",
            _ => $"{matches.Length} parts match {partNumber}.",
        };

        global::Android.Util.Log.Info(
            "FA.QR",
            $"Resolved payload='{partNumber}' matches={matches.Length} in {sw.ElapsedMilliseconds} ms.");

        return new AndroidQrScanResult(lastScan, partNumber, status, matches);
    }

    private void ShowQrMatchesDialog(string partNumber, IReadOnlyList<AndroidQrScanMatch> matches)
    {
        string[] labels = matches
            .Select(match => $"{match.DisplayName}  #{match.NodeId}")
            .ToArray();

        ShowOwnedDialog(
            new AlertDialog.Builder(this)
                .SetTitle($"Matches for {partNumber}")!
                .SetItems(labels, (_, args) =>
                {
                    int index = args.Which;
                    if (index < 0 || index >= matches.Count)
                        return;

                    AndroidQrScanMatch match = matches[index];
                    SelectQrMatch(match.NodeId);
                })!
                .SetNegativeButton(global::Android.Resource.String.Cancel, (_, _) => { })!);
    }

    private void SelectQrMatch(int nodeId)
    {
        if (!TryGetQrActionNode(nodeId, out SceneNode? node) || node is null)
            return;

        SelectNode(node.Id);
        ZoomToSelection();
        global::Android.Util.Log.Info("FA.QR", $"Selected QR match nodeId={node.Id}, name='{node.DisplayName}'.");
    }

    private void IsolateQrMatch(int nodeId)
    {
        if (!TryGetQrActionNode(nodeId, out SceneNode? node) || node is null)
            return;

        SelectNode(node.Id);
        ZoomToSelection();
        IsolateSelectedNodes();
        global::Android.Util.Log.Info("FA.QR", $"Isolated QR match nodeId={node.Id}, name='{node.DisplayName}'.");
    }

    private void IsolateXrayQrMatch(int nodeId)
    {
        if (!TryGetQrActionNode(nodeId, out SceneNode? node) || node is null)
            return;

        SelectNode(node.Id);
        ZoomToSelection();
        IsolateXraySelectedNodes();
        global::Android.Util.Log.Info("FA.QR", $"Isolated X-Ray QR match nodeId={node.Id}, name='{node.DisplayName}'.");
    }

    private bool TryGetQrActionNode(int nodeId, out SceneNode? node)
    {
        node = _runtimeScene?.GetNode(nodeId);
        if (node is not null)
            return true;

        Toast.MakeText(this, "QR match is no longer available.", ToastLength.Short)?.Show();
        global::Android.Util.Log.Warn("FA.QR", $"Action skipped: nodeId={nodeId} is no longer available.");
        return false;
    }

    private static QrPayloadDecodeResult DecodeQrPayload(string? rawPayload)
    {
        if (string.IsNullOrWhiteSpace(rawPayload))
            return new QrPayloadDecodeResult(false, null, "QR payload is empty.");

        if (rawPayload.Length > MaxQrPayloadLength)
            return new QrPayloadDecodeResult(false, null, $"QR payload is too large ({rawPayload.Length} bytes).");

        string payload = rawPayload.Trim();
        int colon = payload.IndexOf(':');
        if (colon > 2
            && payload.StartsWith("FA", StringComparison.OrdinalIgnoreCase)
            && int.TryParse(payload.AsSpan(2, colon - 2), out int version))
        {
            if (version > 1)
                return new QrPayloadDecodeResult(false, null, "Newer QR scheme. Please update Fabrication Assistant.");
            if (version == 1)
                return DecodeQrPartNumber(payload[(colon + 1)..]);
        }

        return DecodeQrPartNumber(payload);
    }

    private static QrPayloadDecodeResult DecodeQrPartNumber(string partNumber)
    {
        string normalized = partNumber.Trim();
        return string.IsNullOrWhiteSpace(normalized)
            ? new QrPayloadDecodeResult(false, null, "QR payload did not contain a part number.")
            : new QrPayloadDecodeResult(true, normalized, null);
    }

    private static IReadOnlyList<SceneNode> FindNodesByPartNumber(Scene scene, string partNumber)
    {
        string normalizedTarget = NormalizeQrKey(partNumber);
        if (string.IsNullOrWhiteSpace(normalizedTarget))
            return Array.Empty<SceneNode>();

        List<SceneNode> allMatches = new();
        foreach (SceneNode node in scene.NodesById.Values.OrderBy(node => node.Id))
        {
            if (node.Metadata?.Properties is null)
                continue;

            foreach (ScenePropertyDto property in node.Metadata.Properties)
            {
                if (!IsQrIdentifierProperty(property))
                    continue;

                string? value = GetQrPropertyValue(property);
                if (NormalizeQrKey(value) != normalizedTarget)
                    continue;

                allMatches.Add(node);
                break;
            }
        }

        return allMatches
            .Where(node => node.NodeType is SceneNodeType.Part or SceneNodeType.Instance)
            .Where(node => IsMeaningfulPartName(node.DisplayName))
            .ToArray();
    }

    private static AndroidQrScanMatch CreateQrScanMatch(SceneNode node)
    {
        string displayName = string.IsNullOrWhiteSpace(node.DisplayName)
            ? $"Node {node.Id}"
            : node.DisplayName;
        return new AndroidQrScanMatch(node.Id, displayName, BuildQrNodePath(node));
    }

    private static string BuildQrNodePath(SceneNode node)
    {
        var names = new Stack<string>();
        for (SceneNode? current = node; current is not null; current = current.Parent)
        {
            if (!string.IsNullOrWhiteSpace(current.DisplayName))
                names.Push(current.DisplayName);
        }

        return names.Count == 0 ? $"Node {node.Id}" : string.Join(" / ", names);
    }

    private static bool IsMeaningfulPartName(string? name)
        => !string.IsNullOrWhiteSpace(name)
           && !AutoGeneratedNodeNamePattern.IsMatch(name.Trim());

    private static bool IsQrIdentifierProperty(ScenePropertyDto property)
    {
        string key = NormalizeQrKey(property.Name);
        string normalized = NormalizeQrKey(property.NameNormalized);
        return IsQrIdentifierPropertyKey(key) || IsQrIdentifierPropertyKey(normalized);
    }

    private static bool IsQrIdentifierPropertyKey(string key)
    {
        return key is "dbpartno"
            or "partnumber"
            or "t3ditemtype"
            or "partno"
            or "itemid"
            or "partid";
    }

    private static string? GetQrPropertyValue(ScenePropertyDto property)
    {
        if (!string.IsNullOrWhiteSpace(property.ValueText))
            return property.ValueText;
        if (property.ValueInteger.HasValue)
            return property.ValueInteger.Value.ToString(System.Globalization.CultureInfo.InvariantCulture);
        if (property.ValueNumber.HasValue && double.IsFinite(property.ValueNumber.Value))
            return property.ValueNumber.Value.ToString("G", System.Globalization.CultureInfo.InvariantCulture);
        if (property.ValueBoolean.HasValue)
            return property.ValueBoolean.Value ? "true" : "false";
        if (!string.IsNullOrWhiteSpace(property.ValueDateTime))
            return property.ValueDateTime;
        return null;
    }

    private static string NormalizeQrKey(string? value)
    {
        if (string.IsNullOrWhiteSpace(value))
            return string.Empty;

        Span<char> buffer = stackalloc char[value.Length];
        int count = 0;
        foreach (char ch in value)
        {
            if (char.IsLetterOrDigit(ch))
                buffer[count++] = char.ToLowerInvariant(ch);
        }

        return new string(buffer[..count]);
    }

    private void ApplyAxisSection(SectionSubMode mode)
    {
        if (!HasScene())
            return;

        ClearSelectedSectionPlane("section placement started");
        _sectionCustomPoints.Clear();
        _sectionHoverPoint = null;
        _hoveredSectionPlaneId = null;
        _activeSectionSubMode = mode;
        EnterToolbarMode(BottomToolbarMode.Section, AndroidModalTool.Section);
        UpdateSectionRendererState();
        UpdateSectionButtonStates();
        global::Android.Util.Log.Info("FA.Section", $"{mode} placement active. Tap geometry to place the plane.");
    }

    private void ApplyCustomSection()
    {
        if (!HasScene())
            return;

        ClearSelectedSectionPlane("custom section placement started");
        _sectionCustomPoints.Clear();
        _sectionHoverPoint = null;
        _hoveredSectionPlaneId = null;
        _activeSectionSubMode = SectionSubMode.Custom;
        EnterToolbarMode(BottomToolbarMode.Section, AndroidModalTool.Section);
        UpdateSectionRendererState();
        UpdateSectionButtonStates();
        global::Android.Util.Log.Info("FA.Section", "Custom placement active. Tap three points to place the plane.");
    }

    private bool TryHandleSectionTap(Point2D dipPosition)
    {
        if (_sections is null)
            return false;

        bool canPlaceSection = _activeModalTool == AndroidModalTool.Section
            && _activeSectionSubMode != SectionSubMode.None;
        bool clearSelectionOnMiss = _activeModalTool == AndroidModalTool.Select
            || (_activeModalTool == AndroidModalTool.Section && _activeSectionSubMode == SectionSubMode.None);
        if (CanSelectSectionPlanes()
            && TrySelectSectionPlaneEdge(dipPosition, clearSelectionOnMiss))
        {
            return true;
        }

        if (!canPlaceSection)
            return false;

        ClearSelectableOverlaySelection("section placement tap");

        if (_sectionRaycaster is null)
            return false;

        if (!TryCreateWorldRay(dipPosition, out Vector3d rayOrigin, out Vector3d rayDirection))
            return true;

        Vector3d? hit = PickSectionPoint(rayOrigin, rayDirection, snapped: _activeSectionSubMode == SectionSubMode.Custom);
        if (hit is null)
        {
            ShowSectionPlacementHint();
            return true;
        }

        if (_activeSectionSubMode == SectionSubMode.Custom)
            AddCustomSectionPoint(hit.Value, rayOrigin);
        else
            AddAxisSectionPlane(_activeSectionSubMode, hit.Value, rayOrigin);

        return true;
    }

    private bool TrySelectSectionPlaneEdge(Point2D dipPosition, bool clearSelectionOnMiss = true)
    {
        double touchTolerancePx = Math.Max(SectionPlaneHoverHitTolerancePx, Dp(SectionPlaneTouchHitToleranceDp));
        if (PickSectionPlaneEdge(dipPosition, touchTolerancePx) is not { } id)
        {
            if (clearSelectionOnMiss)
                ClearSelectedSectionPlane("section edge miss");

            return false;
        }

        _sections!.Select(new[] { id }, additive: false);
        ClearSectionPlacementDraft();
        _sectionGizmoHovered = GlesTransformGizmoHandle.None;
        SetHoveredSectionPlane(null);
        UpdateSectionRendererState();
        UpdateSectionButtonStates();
        global::Android.Util.Log.Info("FA.Section", $"Selected section plane {id} by edge tap.");
        return true;
    }

    private Guid? PickSectionPlaneEdge(Point2D dipPosition, double hitTolerancePx = SectionPlaneHoverHitTolerancePx)
        => PickSectionPlaneEdgeHit(dipPosition, hitTolerancePx, SnapshotCamera())?.Id;

    private SectionPlaneEdgeHit? PickSectionPlaneEdgeHit(
        Point2D dipPosition,
        double hitTolerancePx = SectionPlaneHoverHitTolerancePx,
        CameraState? camera = null)
    {
        if (_sections is null || _sections.Planes.Count == 0)
            return null;

        float density = Resources?.DisplayMetrics?.Density ?? 1.0f;
        if (density <= 0f) density = 1.0f;
        double cursorX = dipPosition.X * density;
        double cursorY = dipPosition.Y * density;
        bool hasBest = false;
        Guid bestId = Guid.Empty;
        double bestDistance = double.PositiveInfinity;
        double bestDepth = double.PositiveInfinity;
        BoundingBox sceneBounds = GetFullSceneBounds();
        double sceneDiagonal = sceneBounds.IsValid ? sceneBounds.Diagonal : 100.0;
        double halfSide = Math.Clamp(sceneDiagonal * AppSettings.SectionPlaneSizeFraction, 1.0, 10_000.0);
        foreach (SectionPlane plane in _sections.Planes)
        {
            Vector3d anchor = ToVector3d(plane.Anchor);
            Vector3d axisX = ToVector3d(plane.AxisX);
            Vector3d axisY = ToVector3d(plane.AxisY);
            Vector3d c0 = anchor - axisX * halfSide - axisY * halfSide;
            Vector3d c1 = anchor + axisX * halfSide - axisY * halfSide;
            Vector3d c2 = anchor + axisX * halfSide + axisY * halfSide;
            Vector3d c3 = anchor - axisX * halfSide + axisY * halfSide;

            ConsiderSegment(plane.Id, c0, c1);
            ConsiderSegment(plane.Id, c1, c2);
            ConsiderSegment(plane.Id, c2, c3);
            ConsiderSegment(plane.Id, c3, c0);
        }

        return hasBest ? new SectionPlaneEdgeHit(bestId, bestDistance, bestDepth) : null;

        void ConsiderSegment(Guid planeId, Vector3d a, Vector3d b)
        {
            if (!TryProjectedSegmentHit(a, b, cursorX, cursorY, out ProjectedSegmentHit hit)
                || hit.Distance > hitTolerancePx)
            {
                return;
            }

            double depth = CameraDepth(hit.WorldPoint, camera);
            if (!IsBetterDepthHit(depth, hit.Distance, bestDepth, bestDistance, hasBest))
                return;

            hasBest = true;
            bestId = planeId;
            bestDistance = hit.Distance;
            bestDepth = depth;
        }
    }

    private double ProjectedSegmentDistance(Vector3d a, Vector3d b, double cursorX, double cursorY)
        => TryProjectedSegmentHit(a, b, cursorX, cursorY, out ProjectedSegmentHit hit)
            ? hit.Distance
            : double.MaxValue;

    private bool TryProjectedSegmentHit(
        Vector3d a,
        Vector3d b,
        double cursorX,
        double cursorY,
        out ProjectedSegmentHit hit)
    {
        hit = default;
        if (!TryProjectWorldToViewport(a, out double ax, out double ay)
            || !TryProjectWorldToViewport(b, out double bx, out double by))
        {
            return false;
        }

        double abX = bx - ax;
        double abY = by - ay;
        double ab2 = abX * abX + abY * abY;
        if (ab2 < 1e-6)
        {
            double collapsedDistance = Math.Sqrt((cursorX - ax) * (cursorX - ax) + (cursorY - ay) * (cursorY - ay));
            Vector3d collapsedWorld = (a + b) * 0.5;
            hit = new ProjectedSegmentHit(collapsedDistance, collapsedWorld);
            return double.IsFinite(collapsedDistance) && IsFinite(collapsedWorld);
        }

        double t = Math.Clamp(((cursorX - ax) * abX + (cursorY - ay) * abY) / ab2, 0.0, 1.0);
        double px = ax + abX * t;
        double py = ay + abY * t;
        double distance = Math.Sqrt((cursorX - px) * (cursorX - px) + (cursorY - py) * (cursorY - py));
        Vector3d worldPoint = a + (b - a) * t;
        hit = new ProjectedSegmentHit(distance, worldPoint);
        return double.IsFinite(distance) && IsFinite(worldPoint);
    }

    private Vector3d? PickSectionPoint(Vector3d rayOrigin, Vector3d rayDirection, bool snapped)
    {
        if (snapped && _sectionSnapPicker is not null)
        {
            if (_sectionSnapPicker.TryHoverSnap(rayOrigin, rayDirection) is { } snap && IsFinite(snap))
                return snap;
        }

        Vector3d? raycastHit = _sectionRaycaster?.Raycast(rayOrigin, rayDirection)?.WorldPoint;
        if (raycastHit is { } hit && IsFinite(hit))
            return hit;

        return snapped && TryPickFallbackSectionPoint(rayOrigin, rayDirection, out Vector3d fallback)
            ? fallback
            : null;
    }

    private bool TryPickFallbackSectionPoint(Vector3d rayOrigin, Vector3d rayDirection, out Vector3d hit)
    {
        hit = default;
        if (_camera is null)
            return false;

        Vector3d planePoint = _runtimeScene?.Bounds is { IsValid: true } bounds
            ? bounds.Center
            : _camera.Target;
        Vector3d planeNormal = _camera.Forward;
        if (!TryNormalize(planeNormal, out planeNormal))
            return false;

        return TryIntersectRayWithPlane(rayOrigin, rayDirection, planePoint, planeNormal, out hit)
               && IsFinite(hit);
    }

    private void AddAxisSectionPlane(SectionSubMode mode, Vector3d hit, Vector3d cameraPosition)
    {
        if (!IsFinite(hit) || !IsFinite(cameraPosition))
            return;

        Vector3d normal = mode switch
        {
            SectionSubMode.X => Vector3d.UnitX,
            SectionSubMode.Y => Vector3d.UnitY,
            SectionSubMode.Z => Vector3d.UnitZ,
            _ => Vector3d.UnitZ,
        };
        if (Vector3d.Dot(normal, cameraPosition - hit) < 0.0)
            normal = -normal;

        var (axisX, axisY) = SectionTangents(normal);
        var plane = new SectionPlane(Guid.NewGuid(), ToVector3(hit), ToVector3(axisX), ToVector3(axisY), ToVector3(normal));
        if (_sections is null)
            return;

        using IUndoTransaction? undo = _undoService?.Begin("Add section");
        IReadOnlyList<SectionPlaneSnapshot> before = _sections.SnapshotAll();
        _sections.Add(plane);
        _sections.Select(new[] { plane.Id }, additive: false);
        undo?.Add(new SectionStateChange(before, _sections.SnapshotAll(), "Add section"));
        ClearSectionPlacementDraft();
        UpdateSectionRendererState();
        UpdateSectionButtonStates();
        global::Android.Util.Log.Info("FA.Section", $"Added {mode} plane at {Format(hit)}, normal={Format(normal)}.");
    }

    private void ShowSectionPlacementHint()
    {
        long now = System.Environment.TickCount64;
        if (now - _lastSectionPlacementHintMs < 2_000)
            return;

        _lastSectionPlacementHintMs = now;
        Toast.MakeText(this, Resource.String.section_place_geometry_hint, ToastLength.Short)?.Show();
    }

    private void AddCustomSectionPoint(Vector3d hit, Vector3d cameraPosition)
    {
        if (!IsFinite(hit) || !IsFinite(cameraPosition))
            return;

        _sectionCustomPoints.Add(hit);
        _sectionHoverPoint = null;
        if (_sectionCustomPoints.Count < 3)
        {
            UpdateSectionRendererState();
            global::Android.Util.Log.Info("FA.Section", $"Custom point {_sectionCustomPoints.Count}/3 at {Format(hit)}.");
            return;
        }

        Vector3d p1 = _sectionCustomPoints[0];
        Vector3d p2 = _sectionCustomPoints[1];
        Vector3d p3 = _sectionCustomPoints[2];
        Vector3d u = p2 - p1;
        Vector3d v = p3 - p1;
        Vector3d normal = Vector3d.Cross(u, v);
        double scale = Math.Max(u.Length, v.Length);
        double areaTolerance = scale * scale * 1e-8;
        if (scale <= 1e-9 || !IsFinite(normal) || normal.Length < areaTolerance)
        {
            _sectionCustomPoints.RemoveAt(2);
            UpdateSectionRendererState();
            Toast.MakeText(this, "Pick a non-collinear third point.", ToastLength.Short)?.Show();
            return;
        }

        normal = normal.Normalized();
        Vector3d centroid = (p1 + p2 + p3) / 3.0;
        if (Vector3d.Dot(normal, cameraPosition - centroid) < 0.0)
            normal = -normal;

        Vector3d axisX = u - normal * Vector3d.Dot(normal, u);
        if (axisX.LengthSquared < 1e-8)
        {
            axisX = Vector3d.UnitX - normal * Vector3d.Dot(normal, Vector3d.UnitX);
            if (axisX.LengthSquared < 1e-8)
                axisX = Vector3d.UnitY - normal * Vector3d.Dot(normal, Vector3d.UnitY);
        }
        axisX = axisX.Normalized();
        Vector3d axisY = Vector3d.Cross(normal, axisX).Normalized();
        var plane = new SectionPlane(Guid.NewGuid(), ToVector3(centroid), ToVector3(axisX), ToVector3(axisY), ToVector3(normal));
        if (_sections is null)
            return;

        using IUndoTransaction? undo = _undoService?.Begin("Add section");
        IReadOnlyList<SectionPlaneSnapshot> before = _sections.SnapshotAll();
        _sections.Add(plane);
        _sections.Select(new[] { plane.Id }, additive: false);
        undo?.Add(new SectionStateChange(before, _sections.SnapshotAll(), "Add section"));
        ClearSectionPlacementDraft();
        UpdateSectionRendererState();
        UpdateSectionButtonStates();
        global::Android.Util.Log.Info("FA.Section", $"Added custom plane at {Format(centroid)}, normal={Format(normal)}.");
    }

    private void ClearSections()
    {
        if (_sections is null || (_sections.Planes.Count == 0 && _sections.SelectedPlaneIds.Count == 0))
            return;

        using IUndoTransaction? undo = _undoService?.Begin("Clear sections");
        IReadOnlyList<SectionPlaneSnapshot> before = _sections.SnapshotAll();
        _sections.ClearAll();
        undo?.Add(new SectionStateChange(before, _sections.SnapshotAll(), "Clear sections"));
        ClearSectionPlacementDraft();
        UpdateSectionRendererState();
        UpdateSectionButtonStates();
        global::Android.Util.Log.Info("FA.Section", "Cleared all section planes.");
    }

    private void OnSectionsChanged()
    {
        if (_sectionGizmoApplyingTransform)
            return;

        if (Looper.MyLooper() != Looper.MainLooper)
        {
            RunOnUiThread(OnSectionsChanged);
            return;
        }

        UpdateSectionRendererState();
        UpdateSectionButtonStates();
    }

    private IReadOnlyList<SectionPlane> GetActiveSectionPlanes()
        => _sections?.Planes is { Count: > 0 } planes
            ? planes
            : Array.Empty<SectionPlane>();

    private void UpdateSectionRendererState()
    {
        if (_viewport is null)
            return;

        GlesViewportRenderer renderer = _viewport.Renderer;
        ApplySectionOverlayTheme(renderer);

        var sectionPlanes = _sections?.Planes
            .Take(8)
            .Select(p => new GlesSectionPlane(p.Normal.X, p.Normal.Y, p.Normal.Z, p.Offset))
            .ToArray()
            ?? Array.Empty<GlesSectionPlane>();

        bool sectionSelectionVisible = CanSelectSectionPlanes();
        HashSet<Guid> selectedIds = sectionSelectionVisible
            ? _sections?.SelectedPlaneIds.ToHashSet() ?? new HashSet<Guid>()
            : new HashSet<Guid>();
        Guid? hoveredPlaneId = sectionSelectionVisible ? _hoveredSectionPlaneId : null;
        var visualPlanes = _sections?.Planes
            .Take(8)
            .Select(p => new GlesSectionVisualPlane(
                new Vector3(p.Anchor.X, p.Anchor.Y, p.Anchor.Z),
                new Vector3(p.AxisX.X, p.AxisX.Y, p.AxisX.Z),
                new Vector3(p.AxisY.X, p.AxisY.Y, p.AxisY.Z),
                new Vector3(p.Normal.X, p.Normal.Y, p.Normal.Z),
                selectedIds.Contains(p.Id) || p.Id == hoveredPlaneId))
            .ToArray()
            ?? Array.Empty<GlesSectionVisualPlane>();

        renderer.SectionPlanes = sectionPlanes;
        renderer.SectionVisualPlanes = visualPlanes;
        renderer.SectionFillVisible = _sections?.FillVisible ?? true;
        renderer.SectionEdgesVisible = _sections?.EdgesVisible ?? true;
        renderer.SectionCurvesVisible = AppSettings.SectionCurvesVisible;
        renderer.SectionCapsVisible = AppSettings.SectionCapsVisible;
        // Section visibility toggles ("Show section curves", caps, etc.) used
        // to need a second click to take effect because the renderer is
        // request-render-on-dirty: the first click updated state but did not
        // dirty the surface. Request the render explicitly so the new state
        // appears on the very next vsync.
        _viewport.RequestRender();
        renderer.SectionPlaneSizeFraction = AppSettings.SectionPlaneSizeFraction;
        renderer.SectionFillColor = new Vector4(
            AppSettings.SectionPlaneR,
            AppSettings.SectionPlaneG,
            AppSettings.SectionPlaneB,
            AppSettings.SectionPlaneOpacity);
        renderer.SectionEdgeColor = new Vector4(
            AppSettings.SectionEdgeR,
            AppSettings.SectionEdgeG,
            AppSettings.SectionEdgeB,
            0.80f);
        renderer.SectionEdgeWidth = AppSettings.SectionEdgeWidth;
        renderer.SectionEdgeHighlightColor = new Vector4(
            AppSettings.DimensionHighlightR,
            AppSettings.DimensionHighlightG,
            AppSettings.DimensionHighlightB,
            1.0f);
        renderer.SectionCapColor = new Vector4(
            AppSettings.SectionCapR,
            AppSettings.SectionCapG,
            AppSettings.SectionCapB,
            1.0f);
        renderer.SectionPlacementCommittedPicks = _sectionCustomPoints.Select(ToVector3).ToArray();
        renderer.SectionPlacementHoverPoint = _sectionHoverPoint.HasValue ? ToVector3(_sectionHoverPoint.Value) : null;
        UpdateSectionGizmoRendererState();
        _viewport.RequestRender();
        UpdateMeasurementLabels(_measurementPresentation);
    }

    private void ApplySectionOverlayTheme(GlesViewportRenderer renderer)
    {
        renderer.SectionPlacementPreviewColor = GetColorVector4(Resource.Color.fa_section_placement_preview);
        renderer.SectionPlacementHoverColor = GetColorVector4(Resource.Color.fa_section_placement_hover);
        renderer.SectionGizmoAxisXColor = GetColorVector4(Resource.Color.fa_section_gizmo_axis_x);
        renderer.SectionGizmoAxisYColor = GetColorVector4(Resource.Color.fa_section_gizmo_axis_y);
        renderer.SectionGizmoAxisZColor = GetColorVector4(Resource.Color.fa_section_gizmo_axis_z);
        renderer.SectionGizmoArcXColor = GetColorVector4(Resource.Color.fa_section_gizmo_arc_x);
        renderer.SectionGizmoArcYColor = GetColorVector4(Resource.Color.fa_section_gizmo_arc_y);
        renderer.SectionGizmoArcZColor = GetColorVector4(Resource.Color.fa_section_gizmo_arc_z);
        renderer.SectionGizmoHoverColor = GetColorVector4(Resource.Color.fa_section_gizmo_hover);
        renderer.SectionGizmoActiveColor = GetColorVector4(Resource.Color.fa_section_gizmo_active);
    }

    private bool UpdateSectionGizmoRendererState()
    {
        if (_viewport is null)
            return false;

        if (!TryComputeSectionGizmoState(
                out Vector3d anchor,
                out Vector3d axisX,
                out Vector3d axisY,
                out Vector3d axisZ,
                out double scale,
                out string failureReason))
        {
            _viewport.Renderer.SectionGizmoScale = 0f;
            _viewport.Renderer.SectionGizmoHovered = GlesTransformGizmoHandle.None;
            _viewport.Renderer.SectionGizmoActive = GlesTransformGizmoHandle.None;
            LogSectionGizmoHidden(failureReason);
            return false;
        }

        _viewport.Renderer.SectionGizmoAnchor = ToVector3(anchor);
        _viewport.Renderer.SectionGizmoAxisX = ToVector3(axisX);
        _viewport.Renderer.SectionGizmoAxisY = ToVector3(axisY);
        _viewport.Renderer.SectionGizmoAxisZ = ToVector3(axisZ);
        _viewport.Renderer.SectionGizmoScale = (float)scale;
        _viewport.Renderer.SectionGizmoHovered = _sectionGizmoHovered;
        _viewport.Renderer.SectionGizmoActive = _sectionGizmoActive;
        return true;
    }

    private bool TryComputeSectionGizmoState(
        out Vector3d anchor,
        out Vector3d axisX,
        out Vector3d axisY,
        out Vector3d axisZ,
        out double scale)
        => TryComputeSectionGizmoState(out anchor, out axisX, out axisY, out axisZ, out scale, out _);

    private bool TryComputeSectionGizmoState(
        out Vector3d anchor,
        out Vector3d axisX,
        out Vector3d axisY,
        out Vector3d axisZ,
        out double scale,
        out string failureReason)
    {
        anchor = default;
        axisX = default;
        axisY = default;
        axisZ = default;
        scale = 0.0;
        failureReason = "unknown";

        if (_viewport is null)
        {
            failureReason = "viewport-null";
            return false;
        }

        if (_camera is null)
        {
            failureReason = "camera-null";
            return false;
        }

        if (_sections is null)
        {
            failureReason = "sections-null";
            return false;
        }

        if (!CanSelectSectionPlanes())
        {
            failureReason = $"selection-disabled tool={_activeModalTool} subMode={_activeSectionSubMode}";
            return false;
        }

        if (_sections.SelectedPlaneIds.Count == 0)
        {
            failureReason = "no-selected-section";
            return false;
        }

        var selected = _sections.Planes
            .Where(p => _sections.SelectedPlaneIds.Contains(p.Id))
            .ToArray();
        if (selected.Length == 0)
        {
            failureReason = $"selected-id-missing count={_sections.SelectedPlaneIds.Count}";
            return false;
        }

        Vector3d sum = Vector3d.Zero;
        foreach (SectionPlane plane in selected)
            sum += ToVector3d(plane.Anchor);
        anchor = sum / selected.Length;
        if (!IsFinite(anchor))
        {
            failureReason = "invalid-anchor";
            return false;
        }

        SectionPlane first = selected[0];
        axisX = ToVector3d(first.AxisX);
        axisY = ToVector3d(first.AxisY);
        axisZ = ToVector3d(first.Normal);
        if (!TryNormalize(axisX, out axisX)
            || !TryNormalize(axisY, out axisY)
            || !TryNormalize(axisZ, out axisZ))
        {
            failureReason = "invalid-axis";
            return false;
        }

        CameraState? camera = SnapshotCamera();
        if (camera is null)
        {
            failureReason = "camera-snapshot-null";
            return false;
        }

        if (_viewport.Width <= 0 || _viewport.Height <= 0)
        {
            failureReason = $"invalid-viewport {_viewport.Width}x{_viewport.Height}";
            return false;
        }

        double aspect = (double)_viewport.Width / _viewport.Height;
        scale = ResolveSectionGizmoScale(camera, anchor, AppSettings.SectionGizmoSizeFraction, aspect);
        if (!double.IsFinite(scale) || scale <= 1e-9)
        {
            failureReason = $"invalid-scale scale={scale:G9}";
            return false;
        }

        failureReason = string.Empty;
        return true;
    }

    private double ResolveSectionGizmoScale(CameraState camera, Vector3d anchor, double fraction, double aspect)
    {
        double scale = camera.WorldSizeForScreenHeightFraction(anchor, fraction, aspect);
        if (double.IsFinite(scale) && scale > 1e-9)
            return scale;

        BoundingBox bounds = GetFullSceneBounds();
        double sceneDiagonal = bounds.IsValid && double.IsFinite(bounds.Diagonal) && bounds.Diagonal > 1e-9
            ? bounds.Diagonal
            : 100.0;

        double fallback = 0.0;
        if (camera.IsPerspective)
        {
            Vector3d forward = camera.Forward;
            if (TryNormalize(forward, out forward)
                && double.IsFinite(camera.FieldOfView)
                && camera.FieldOfView > 1e-6
                && camera.FieldOfView < Math.PI - 1e-6)
            {
                double depth = Vector3d.Dot(anchor - camera.Position, forward);
                if (double.IsFinite(depth) && depth > 1e-6)
                    fallback = 2.0 * depth * Math.Tan(camera.FieldOfView * 0.5) * fraction;
            }
        }
        else if (double.IsFinite(camera.OrthoWidth) && camera.OrthoWidth > 1e-9)
        {
            double safeAspect = double.IsFinite(aspect) && aspect > 1e-9 ? aspect : 1.0;
            fallback = camera.OrthoWidth / safeAspect * fraction;
        }

        if (!double.IsFinite(fallback) || fallback <= 1e-9)
            fallback = sceneDiagonal * fraction;

        return Math.Clamp(fallback, sceneDiagonal * 0.001, sceneDiagonal * 0.5);
    }

    private void LogSectionGizmoHidden(string reason)
    {
        SectionService? sections = _sections;
        if (sections is null || sections.SelectedPlaneIds.Count <= 0)
            return;

        string key = $"{reason}|{_activeModalTool}|{_activeSectionSubMode}|{sections.SelectedPlaneIds.Count}|{_viewport?.Width}x{_viewport?.Height}";
        if (key == _lastSectionGizmoHiddenLogKey)
            return;

        _lastSectionGizmoHiddenLogKey = key;
        global::Android.Util.Log.Warn(
            "FA.Section",
            $"Section gizmo hidden: reason={reason}, selected={sections.SelectedPlaneIds.Count}, tool={_activeModalTool}, subMode={_activeSectionSubMode}, viewport={_viewport?.Width ?? 0}x{_viewport?.Height ?? 0}.");
    }

    private bool UpdateBodyMoveGizmoRendererState()
    {
        if (_viewport is null)
            return false;

        GlesViewportRenderer renderer = _viewport.Renderer;
        ApplySectionOverlayTheme(renderer);

        if (!TryComputeBodyMoveGizmoState(
                out Vector3d anchor,
                out Vector3d axisX,
                out Vector3d axisY,
                out Vector3d axisZ,
                out double scale))
        {
            renderer.BodyMoveGizmoScale = 0f;
            renderer.BodyMoveGizmoHovered = GlesTransformGizmoHandle.None;
            renderer.BodyMoveGizmoActive = GlesTransformGizmoHandle.None;
            return false;
        }

        renderer.BodyMoveGizmoAnchor = ToVector3(anchor);
        renderer.BodyMoveGizmoAxisX = ToVector3(axisX);
        renderer.BodyMoveGizmoAxisY = ToVector3(axisY);
        renderer.BodyMoveGizmoAxisZ = ToVector3(axisZ);
        renderer.BodyMoveGizmoScale = (float)scale;
        renderer.BodyMoveGizmoHovered = _bodyMoveGizmoHovered;
        renderer.BodyMoveGizmoActive = _bodyMoveGizmoActive;
        return true;
    }

    private bool TryComputeBodyMoveGizmoState(
        out Vector3d anchor,
        out Vector3d axisX,
        out Vector3d axisY,
        out Vector3d axisZ,
        out double scale)
    {
        anchor = default;
        axisX = Vector3d.UnitX;
        axisY = Vector3d.UnitY;
        axisZ = Vector3d.UnitZ;
        scale = 0.0;

        Scene? scene = _runtimeScene;
        if (_viewport is null
            || _camera is null
            || scene is null
            || _activeModalTool != AndroidModalTool.BodyMove
            || _selectedNodeIds.Count == 0)
        {
            return false;
        }

        IReadOnlyList<SceneNode> nodes = BodyMoveSelection.ResolveMovableNodes(scene, _selectedNodeIds);
        if (nodes.Count == 0)
            return false;

        anchor = BodyMoveSelection.ComputeCentroid(scene, nodes);
        if (!IsFinite(anchor))
            return false;

        CameraState? camera = SnapshotCamera();
        if (camera is null || _viewport.Width <= 0 || _viewport.Height <= 0)
            return false;

        double aspect = (double)_viewport.Width / _viewport.Height;
        scale = camera.WorldSizeForScreenHeightFraction(anchor, AppSettings.SectionGizmoSizeFraction, aspect);
        return double.IsFinite(scale) && scale > 1e-9;
    }

    private bool OnViewportRawTouch(MotionEvent? motionEvent)
    {
        if (motionEvent is null || _viewport is null)
            return false;

        if (ShouldRejectFingerTouchForSpenPalmRejection(motionEvent))
            return false;

        MotionEventActions action = NormalizeViewportToolPointerAction(motionEvent);
        if (HandleAnnotationTouch(motionEvent))
            return true;

        if (_bodyMoveGizmoActive != GlesTransformGizmoHandle.None)
            return HandleActiveBodyMoveGizmoTouch(motionEvent, action);

        if (_sectionGizmoActive != GlesTransformGizmoHandle.None)
            return HandleActiveSectionGizmoTouch(motionEvent, action);

        if (action == MotionEventActions.Down
            && _activeModalTool == AndroidModalTool.BodyMove
            && !_bodyMoveGizmoInputOpen)
        {
            Point2D bodyDip = MotionEventToDip(motionEvent);
            GlesTransformGizmoHandle bodyHit = PickBodyMoveGizmoHandle(bodyDip);
            if (bodyHit == GlesTransformGizmoHandle.None)
            {
                SetBodyMoveGizmoHovered(GlesTransformGizmoHandle.None);
                return false;
            }

            if (!TryCreateWorldRay(bodyDip, out Vector3d bodyRayOrigin, out Vector3d bodyRayDirection))
                return false;

            BeginBodyMoveGizmoDrag(bodyHit, bodyRayOrigin, bodyRayDirection, bodyDip);
            return true;
        }

        if (action != MotionEventActions.Down
            || !CanSelectSectionPlanes()
            || _sections?.SelectedPlaneIds.Count <= 0)
        {
            return false;
        }

        Point2D dip = MotionEventToDip(motionEvent);
        GlesTransformGizmoHandle hit = PickSectionGizmoHandle(dip);
        if (hit == GlesTransformGizmoHandle.None)
        {
            SetSectionGizmoHovered(GlesTransformGizmoHandle.None);
            return false;
        }

        if (!TryCreateWorldRay(dip, out Vector3d rayOrigin, out Vector3d rayDirection))
            return false;

        BeginSectionGizmoDrag(hit, rayOrigin, rayDirection, dip);
        return true;
    }

    private static MotionEventActions NormalizeViewportToolPointerAction(MotionEvent motionEvent)
    {
        MotionEventActions action = motionEvent.ActionMasked;
        if (!IsMousePointerEvent(motionEvent))
            return action;

        return action switch
        {
            MotionEventActions.ButtonPress when IsActionButton(motionEvent, MotionEventButtonState.Primary)
                                                || IsPrimaryButtonPressed(motionEvent)
                => MotionEventActions.Down,
            MotionEventActions.ButtonRelease when IsActionButton(motionEvent, MotionEventButtonState.Primary)
                => MotionEventActions.Up,
            MotionEventActions.HoverMove or MotionEventActions.Move when IsPrimaryButtonPressed(motionEvent)
                => MotionEventActions.Move,
            _ => action,
        };
    }

    private bool ShouldConsumeViewportTouchViaGestureSource()
        => _activeModalTool == AndroidModalTool.ZoomWindow
           || (_activeModalTool == AndroidModalTool.Section
               && _activeSectionSubMode == SectionSubMode.Custom
               && _sectionGizmoActive == GlesTransformGizmoHandle.None
               && (_sections?.SelectedPlaneIds.Count ?? 0) == 0);

    private bool HandleActiveSectionGizmoTouch(MotionEvent motionEvent, MotionEventActions action)
    {
        Point2D dip = MotionEventToDip(motionEvent);
        switch (action)
        {
            case MotionEventActions.Move:
                if (_sectionGizmoDownDip is { } down)
                {
                    double dx = dip.X - down.X;
                    double dy = dip.Y - down.Y;
                    if (dx * dx + dy * dy > SectionGizmoClickVsDragThresholdDipSquared)
                        _sectionGizmoExceededDragThreshold = true;
                }

                if (_sectionGizmoExceededDragThreshold
                    && TryCreateWorldRay(dip, out Vector3d moveOrigin, out Vector3d moveDirection))
                {
                    UpdateSectionGizmoDrag(moveOrigin, moveDirection);
                }
                return true;

            case MotionEventActions.Up:
            case MotionEventActions.PointerUp:
                if (_sectionGizmoExceededDragThreshold)
                {
                    CommitSectionGizmoDrag();
                }
                else
                {
                    ShowSectionGizmoInputDialog(_sectionGizmoActive);
                }
                return true;

            case MotionEventActions.Cancel:
                CancelSectionGizmoDrag();
                return true;

            default:
                return true;
        }
    }

    private bool HandleActiveBodyMoveGizmoTouch(MotionEvent motionEvent, MotionEventActions action)
    {
        Point2D dip = MotionEventToDip(motionEvent);
        switch (action)
        {
            case MotionEventActions.Move:
                if (_bodyMoveGizmoDownDip is { } down)
                {
                    double dx = dip.X - down.X;
                    double dy = dip.Y - down.Y;
                    if (dx * dx + dy * dy > SectionGizmoClickVsDragThresholdDipSquared)
                        _bodyMoveGizmoExceededDragThreshold = true;
                }

                if (_bodyMoveGizmoExceededDragThreshold
                    && TryCreateWorldRay(dip, out Vector3d moveOrigin, out Vector3d moveDirection))
                {
                    UpdateBodyMoveGizmoDrag(moveOrigin, moveDirection);
                }
                return true;

            case MotionEventActions.Up:
            case MotionEventActions.PointerUp:
                if (_bodyMoveGizmoExceededDragThreshold)
                    CommitBodyMoveGizmoDrag();
                else
                    ShowBodyMoveGizmoInputDialog(_bodyMoveGizmoActive);
                return true;

            case MotionEventActions.Cancel:
                CancelBodyMoveGizmoDrag();
                return true;

            default:
                return true;
        }
    }

    private Point2D MotionEventToDip(MotionEvent motionEvent)
    {
        float density = Resources?.DisplayMetrics?.Density ?? 1.0f;
        if (density <= 0f) density = 1.0f;
        int pointerIndex = PreferredPointerIndex(motionEvent);
        return new Point2D(motionEvent.GetX(pointerIndex) / density, motionEvent.GetY(pointerIndex) / density);
    }

    private int PreferredPointerIndex(MotionEvent motionEvent)
    {
        int pointerIndex = AndroidMotionEvents.PreferredPointerIndex(motionEvent);
        if (pointerIndex >= 0)
            return pointerIndex;

        if (Interlocked.Exchange(ref _preferredPointerFallbackLogged, 1) == 0)
        {
            global::Android.Util.Log.Warn(
                "FA.Input",
                $"MotionEvent pointer index unavailable; falling back to pointer 0. actionIndex={motionEvent.ActionIndex}, pointerCount={motionEvent.PointerCount}.");
        }

        return 0;
    }

    private bool ShouldRejectFingerTouchForSpenPalmRejection(MotionEvent motionEvent)
    {
        if (!AppSettings.SpenPalmRejectionEnabled)
            return false;

        if (ContainsStylusOrEraser(motionEvent))
        {
            if (IsStylusReleaseOrCancel(motionEvent))
                ClearSpenPalmGuard();
            else
                RegisterSpenPalmGuardInput();
            return false;
        }

        int count = motionEvent.PointerCount;
        if (count <= 0)
            return false;

        for (int i = 0; i < count; i++)
        {
            if (motionEvent.GetToolType(i) != MotionEventToolType.Finger)
                return false;
        }

        MotionEventActions action = motionEvent.ActionMasked;
        if (action == MotionEventActions.Down || count >= 2)
        {
            ClearSpenPalmGuard();
            return false;
        }

        bool shouldReject = IsSpenPalmGuardActive();
        if (shouldReject)
            _pointerSource?.CancelActiveGesture();
        return shouldReject;
    }

    private void RegisterSpenPalmGuardInput()
    {
        bool wasActive = _spenPalmGuardActive;
        _spenPalmGuardActive = true;
        _pointerSource?.NotifyStylusInput();
        if (!wasActive)
            _pointerSource?.CancelActiveGesture();
    }

    private void ClearSpenPalmGuard()
    {
        _spenPalmGuardActive = false;
        _pointerSource?.ClearPalmRejectionSuppression();
    }

    private bool IsSpenPalmGuardActive()
        => _spenPalmGuardActive;

    private static bool IsStylusReleaseOrCancel(MotionEvent motionEvent)
    {
        MotionEventActions action = motionEvent.ActionMasked;
        if (action == MotionEventActions.Cancel)
            return true;

        if (action != MotionEventActions.Up && action != MotionEventActions.PointerUp)
            return false;

        int pointerIndex = motionEvent.ActionIndex;
        if (pointerIndex < 0 || pointerIndex >= motionEvent.PointerCount)
            pointerIndex = 0;

        return IsStylusOrEraser(motionEvent.GetToolType(pointerIndex));
    }

    private static bool ContainsStylusOrEraser(MotionEvent motionEvent)
    {
        int count = motionEvent.PointerCount;
        for (int i = 0; i < count; i++)
        {
            if (IsStylusOrEraser(motionEvent.GetToolType(i)))
                return true;
        }

        return false;
    }

    private static bool IsStylusOrEraser(MotionEventToolType toolType)
        => toolType == MotionEventToolType.Stylus
           || toolType == MotionEventToolType.Eraser;

    private void SetSectionGizmoHovered(GlesTransformGizmoHandle handle)
    {
        if (_sectionGizmoHovered == handle)
            return;

        _sectionGizmoHovered = handle;
        if (_sectionGizmoSnapshot is null)
        {
            UpdateSectionGizmoRendererState();
            _viewport?.RequestRender();
        }
    }

    private void SetBodyMoveGizmoHovered(GlesTransformGizmoHandle handle)
    {
        if (_bodyMoveGizmoHovered == handle)
            return;

        _bodyMoveGizmoHovered = handle;
        if (_bodyMoveGizmoSnapshot is null)
        {
            UpdateBodyMoveGizmoRendererState();
            _viewport?.RequestRender();
        }
    }

    private void ClearBodyMoveHover()
    {
        _bodyMoveGizmoHovered = GlesTransformGizmoHandle.None;
        if (_bodyMoveGizmoSnapshot is null)
            UpdateBodyMoveGizmoRendererState();
    }

    private void SetHoveredSectionPlane(Guid? id)
    {
        if (_hoveredSectionPlaneId == id)
            return;

        _hoveredSectionPlaneId = id;
        UpdateSectionRendererState();
    }

    private GlesTransformGizmoHandle PickSectionGizmoHandle(Point2D dipPosition)
    {
        if (!TryComputeSectionGizmoState(
                out Vector3d anchor,
                out Vector3d axisX,
                out Vector3d axisY,
                out Vector3d axisZ,
                out double scale))
        {
            return GlesTransformGizmoHandle.None;
        }

        return PickTransformGizmoHandle(dipPosition, anchor, axisX, axisY, axisZ, scale);
    }

    private GlesTransformGizmoHandle PickBodyMoveGizmoHandle(Point2D dipPosition)
    {
        if (!TryComputeBodyMoveGizmoState(
                out Vector3d anchor,
                out Vector3d axisX,
                out Vector3d axisY,
                out Vector3d axisZ,
                out double scale))
        {
            return GlesTransformGizmoHandle.None;
        }

        return PickTransformGizmoHandle(dipPosition, anchor, axisX, axisY, axisZ, scale);
    }

    private GlesTransformGizmoHandle PickTransformGizmoHandle(
        Point2D dipPosition,
        Vector3d anchor,
        Vector3d axisX,
        Vector3d axisY,
        Vector3d axisZ,
        double scale)
    {
        float density = Resources?.DisplayMetrics?.Density ?? 1.0f;
        if (density <= 0f) density = 1.0f;
        double cursorX = dipPosition.X * density;
        double cursorY = dipPosition.Y * density;

        double bestTranslateDistance = double.MaxValue;
        GlesTransformGizmoHandle bestTranslate = GlesTransformGizmoHandle.None;
        TestTranslateHandle(GlesTransformGizmoHandle.TranslateX, axisX);
        TestTranslateHandle(GlesTransformGizmoHandle.TranslateY, axisY);
        TestTranslateHandle(GlesTransformGizmoHandle.TranslateZ, axisZ);
        if (bestTranslate != GlesTransformGizmoHandle.None)
            return bestTranslate;

        if (!TryCreateWorldRay(dipPosition, out Vector3d rayOrigin, out Vector3d rayDirection))
        {
            rayOrigin = default;
            rayDirection = default;
        }

        double arcRadius = scale * SectionGizmoArcRadiusScale;
        if (HitSectionGizmoArc(rayOrigin, rayDirection, hasRay: rayDirection.LengthSquared > 0.0, anchor, axisX, axisY, axisZ, arcRadius, cursorX, cursorY))
            return GlesTransformGizmoHandle.RotateX;
        if (HitSectionGizmoArc(rayOrigin, rayDirection, hasRay: rayDirection.LengthSquared > 0.0, anchor, axisY, axisZ, axisX, arcRadius, cursorX, cursorY))
            return GlesTransformGizmoHandle.RotateY;
        if (HitSectionGizmoArc(rayOrigin, rayDirection, hasRay: rayDirection.LengthSquared > 0.0, anchor, axisZ, axisX, axisY, arcRadius, cursorX, cursorY))
            return GlesTransformGizmoHandle.RotateZ;

        return GlesTransformGizmoHandle.None;

        void TestTranslateHandle(GlesTransformGizmoHandle handle, Vector3d axis)
        {
            double distance = ProjectedSegmentDistance(anchor, anchor + axis * scale, cursorX, cursorY);
            if (distance <= SectionGizmoTranslateHitTolerancePx && distance < bestTranslateDistance)
            {
                bestTranslateDistance = distance;
                bestTranslate = handle;
            }
        }
    }

    private bool HitSectionGizmoArc(
        Vector3d rayOrigin,
        Vector3d rayDirection,
        bool hasRay,
        Vector3d anchor,
        Vector3d planeNormal,
        Vector3d right,
        Vector3d up,
        double radius,
        double cursorX,
        double cursorY)
    {
        if (hasRay
            && TryIntersectPlane(rayOrigin, rayDirection, anchor, planeNormal, out Vector3d hit))
        {
            Vector3d rel = hit - anchor;
            double rDot = Vector3d.Dot(rel, right);
            double uDot = Vector3d.Dot(rel, up);
            double r = Math.Sqrt(rDot * rDot + uDot * uDot);
            if (rDot >= 0.0 && uDot >= 0.0 && r <= radius * 1.05)
                return true;
        }

        const int samples = 32;
        Vector3d previous = anchor + right * radius;
        double bestDistance = double.MaxValue;
        for (int i = 1; i <= samples; i++)
        {
            double angle = i / (double)samples * Math.PI * 0.5;
            Vector3d current = anchor + (right * Math.Cos(angle) + up * Math.Sin(angle)) * radius;
            double distance = ProjectedSegmentDistance(previous, current, cursorX, cursorY);
            if (distance < bestDistance)
                bestDistance = distance;
            previous = current;
        }

        return bestDistance <= SectionGizmoArcOutlineTolerancePx;
    }

    private static bool TryIntersectPlane(
        Vector3d rayOrigin,
        Vector3d rayDirection,
        Vector3d planePoint,
        Vector3d planeNormal,
        out Vector3d hit)
    {
        hit = default;
        double denom = Vector3d.Dot(planeNormal, rayDirection);
        if (Math.Abs(denom) < 1e-9)
            return false;

        double t = Vector3d.Dot(planePoint - rayOrigin, planeNormal) / denom;
        if (t < 0.0)
            return false;

        hit = rayOrigin + rayDirection * t;
        return true;
    }

    private void BeginSectionGizmoDrag(
        GlesTransformGizmoHandle handle,
        Vector3d rayOrigin,
        Vector3d rayDirection,
        Point2D downDip)
    {
        if (_sections is null
            || handle == GlesTransformGizmoHandle.None
            || _bodyMoveGizmoActive != GlesTransformGizmoHandle.None
            || !TryComputeSectionGizmoState(
                out Vector3d anchor,
                out Vector3d axisX,
                out Vector3d axisY,
                out Vector3d axisZ,
                out _))
        {
            return;
        }

        if (_sectionGizmoActive != GlesTransformGizmoHandle.None)
            CommitSectionGizmoDrag();

        _sectionGizmoUndoSnapshot = _sections.SnapshotAll();
        _sectionGizmoSnapshot = _sections.Planes
            .Where(p => _sections.SelectedPlaneIds.Contains(p.Id))
            .Select(SectionPlaneSnapshot.FromPlane)
            .ToList();
        if (_sectionGizmoSnapshot.Count == 0)
        {
            _sectionGizmoSnapshot = null;
            _sectionGizmoUndoSnapshot = null;
            return;
        }

        _sectionGizmoActive = handle;
        _sectionGizmoHovered = handle;
        _sectionGizmoDownDip = downDip;
        _sectionGizmoExceededDragThreshold = false;
        _sectionGizmoCurrentDelta = 0.0;
        _sectionGizmoDragOrigin = anchor;
        _sectionGizmoDragAxisWorld = SectionGizmoAxisForHandle(handle, axisX, axisY, axisZ);

        if (_sectionGizmoDragAxisWorld.LengthSquared < 1e-12)
        {
            CancelSectionGizmoDrag();
            return;
        }

        if (IsSectionGizmoTranslate(handle))
            _sectionGizmoStartAxisT = ProjectRayOntoAxis(rayOrigin, rayDirection, _sectionGizmoDragOrigin, _sectionGizmoDragAxisWorld);
        else if (IsSectionGizmoRotate(handle))
            _sectionGizmoRotateStartVec = RotateRayHitVector(rayOrigin, rayDirection);

        global::Android.Util.Log.Info("FA.Section", $"Gizmo begin: handle={handle}, selected={_sectionGizmoSnapshot.Count}.");
    }

    private void UpdateSectionGizmoDrag(Vector3d rayOrigin, Vector3d rayDirection)
    {
        if (_sectionGizmoActive == GlesTransformGizmoHandle.None || _sectionGizmoSnapshot is null)
            return;

        if (IsSectionGizmoTranslate(_sectionGizmoActive))
        {
            double currentT = ProjectRayOntoAxis(rayOrigin, rayDirection, _sectionGizmoDragOrigin, _sectionGizmoDragAxisWorld);
            double delta = currentT - _sectionGizmoStartAxisT;
            _sectionGizmoCurrentDelta = delta;
            ApplySectionGizmoTranslate(_sectionGizmoDragAxisWorld * delta);
        }
        else if (IsSectionGizmoRotate(_sectionGizmoActive))
        {
            Vector3d currentVec = RotateRayHitVector(rayOrigin, rayDirection);
            double angleRad = SignedAngle(_sectionGizmoRotateStartVec, currentVec, _sectionGizmoDragAxisWorld);
            _sectionGizmoCurrentDelta = angleRad * 180.0 / Math.PI;
            ApplySectionGizmoRotate(Quaterniond.FromAxisAngle(_sectionGizmoDragAxisWorld, angleRad), _sectionGizmoDragOrigin);
        }

    }

    private void CommitSectionGizmoDrag()
    {
        if (_sections is not null
            && _sectionGizmoSnapshot is not null
            && _sectionGizmoUndoSnapshot is not null
            && Math.Abs(_sectionGizmoCurrentDelta) > 1e-9)
        {
            IReadOnlyList<SectionPlaneSnapshot> before = _sectionGizmoUndoSnapshot;
            IReadOnlyList<SectionPlaneSnapshot> after = _sections.SnapshotAll();
            if (!SameSectionSnapshots(before, after))
            {
                _undoService?.Record(
                    new SectionStateChange(before, after, "Move section"),
                    "Move section");
            }

            global::Android.Util.Log.Info("FA.Section", $"Gizmo commit: handle={_sectionGizmoActive}, delta={_sectionGizmoCurrentDelta:0.###}.");
        }

        ClearSectionGizmoDragState();
        UpdateSectionGizmoRendererState();
        _viewport?.RequestRender();
    }

    private void CancelSectionGizmoDrag()
    {
        if (_sections is not null && _sectionGizmoSnapshot is not null)
        {
            foreach (SectionPlaneSnapshot snap in _sectionGizmoSnapshot)
                _sections.Update(snap.ToPlane());
        }

        global::Android.Util.Log.Info("FA.Section", "Gizmo cancel.");
        ClearSectionGizmoDragState();
        UpdateSectionGizmoRendererState();
        _viewport?.RequestRender();
    }

    private void ClearSectionGizmoDragState()
    {
        _sectionGizmoActive = GlesTransformGizmoHandle.None;
        _sectionGizmoDownDip = null;
        _sectionGizmoExceededDragThreshold = false;
        _sectionGizmoSnapshot = null;
        _sectionGizmoUndoSnapshot = null;
        _sectionGizmoStartAxisT = 0.0;
        _sectionGizmoDragAxisWorld = default;
        _sectionGizmoDragOrigin = default;
        _sectionGizmoRotateStartVec = default;
        _sectionGizmoCurrentDelta = 0.0;
        _sectionGizmoInputOpen = false;
    }

    private void ApplySectionGizmoTranslate(Vector3d worldDelta)
    {
        if (_sections is null || _sectionGizmoSnapshot is null)
            return;

        _sectionGizmoApplyingTransform = true;
        try
        {
            foreach (SectionPlaneSnapshot snap in _sectionGizmoSnapshot)
            {
                var anchor = new Vector3(
                    (float)(snap.Anchor.X + worldDelta.X),
                    (float)(snap.Anchor.Y + worldDelta.Y),
                    (float)(snap.Anchor.Z + worldDelta.Z));
                _sections.Update(snap.ToPlane().WithAnchor(anchor));
            }
        }
        finally
        {
            _sectionGizmoApplyingTransform = false;
        }

        UpdateSectionRendererState();
    }

    private void ApplySectionGizmoRotate(Quaterniond rotation, Vector3d pivot)
    {
        if (_sections is null || _sectionGizmoSnapshot is null)
            return;

        ApplySectionPlaneSnapshotRotation(_sectionGizmoSnapshot, rotation, pivot);
        UpdateSectionRendererState();
    }

    private void ApplySectionPlaneSnapshotRotation(
        IReadOnlyList<SectionPlaneSnapshot> snapshots,
        Quaterniond rotation,
        Vector3d pivot)
    {
        if (_sections is null || snapshots.Count == 0)
            return;

        Matrix4d rot = rotation.ToMatrix4d();
        _sectionGizmoApplyingTransform = true;
        try
        {
            foreach (SectionPlaneSnapshot snap in snapshots)
            {
                Vector3 newAxisX = ToVector3(rot.TransformDirection(ToVector3d(snap.AxisX)));
                Vector3 newAxisY = ToVector3(rot.TransformDirection(ToVector3d(snap.AxisY)));
                Vector3 newNormal = ToVector3(rot.TransformDirection(ToVector3d(snap.Normal)));
                Vector3d offset = ToVector3d(snap.Anchor) - pivot;
                Vector3 newAnchor = ToVector3(pivot + rot.TransformDirection(offset));
                _sections.Update(new SectionPlane(snap.Id, newAnchor, newAxisX, newAxisY, newNormal));
            }
        }
        finally
        {
            _sectionGizmoApplyingTransform = false;
        }
    }

    private delegate bool TryComputeGizmoPopupPositionDelegate(
        GlesTransformGizmoHandle handle,
        int popupWidth,
        int estimatedPopupHeight,
        out int x,
        out int y);

    private void ShowSectionGizmoInputDialog(GlesTransformGizmoHandle handle)
    {
        if (handle == GlesTransformGizmoHandle.None || _sectionGizmoSnapshot is null)
        {
            CancelSectionGizmoDrag();
            return;
        }

        ShowTransformGizmoInputDialog(
            "Section",
            handle,
            open => _sectionGizmoInputOpen = open,
            () => _sectionGizmoActive != GlesTransformGizmoHandle.None,
            CancelSectionGizmoDrag,
            CommitSectionGizmoTypedValue,
            TryComputeSectionGizmoPopupPosition);
    }

    private void ShowBodyMoveGizmoInputDialog(GlesTransformGizmoHandle handle)
    {
        if (handle == GlesTransformGizmoHandle.None || _bodyMoveGizmoSnapshot is null)
        {
            CancelBodyMoveGizmoDrag();
            return;
        }

        ShowTransformGizmoInputDialog(
            "Move",
            handle,
            open => _bodyMoveGizmoInputOpen = open,
            () => _bodyMoveGizmoActive != GlesTransformGizmoHandle.None,
            CancelBodyMoveGizmoDrag,
            CommitBodyMoveGizmoTypedValue,
            TryComputeBodyMoveGizmoPopupPosition);
    }

    private void ShowTransformGizmoInputDialog(
        string titlePrefix,
        GlesTransformGizmoHandle handle,
        Action<bool> setInputOpen,
        Func<bool> hasActiveDrag,
        Action cancelDrag,
        Action<double> commitTypedValue,
        TryComputeGizmoPopupPositionDelegate tryComputePopupPosition)
    {
        setInputOpen(true);
        (string label, string unit) = TransformGizmoInputLabel(handle);

        int popupWidth = Dp(236);
        var root = new LinearLayout(this)
        {
            Orientation = Orientation.Vertical,
            Background = CreateSectionGizmoPopupBackground(),
            ClipToOutline = true,
        };
        root.SetPadding(Dp(10), Dp(8), Dp(10), Dp(10));

        var titleRow = new LinearLayout(this)
        {
            Orientation = Orientation.Horizontal,
        };
        titleRow.SetGravity(GravityFlags.CenterVertical);

        var title = new TextView(this)
        {
            Text = $"{titlePrefix} {label}",
            TextSize = 13.0f,
            Gravity = GravityFlags.CenterVertical,
            Ellipsize = TextUtils.TruncateAt.End,
        };
        title.SetSingleLine(true);
        title.SetTypeface(Typeface.Default, TypefaceStyle.Bold);
        title.SetTextColor(GetColorCompat(Resource.Color.fa_text_primary));
        titleRow.AddView(title, new LinearLayout.LayoutParams(0, Dp(22), 1.0f));

        var hint = new TextView(this)
        {
            Text = unit == "mm" ? "Distance" : "Angle",
            TextSize = 11.0f,
            Gravity = GravityFlags.CenterVertical | GravityFlags.Right,
        };
        hint.SetSingleLine(true);
        hint.SetTextColor(GetColorCompat(Resource.Color.fa_text_secondary));
        titleRow.AddView(hint, new LinearLayout.LayoutParams(Dp(76), Dp(22)));

        root.AddView(titleRow, new LinearLayout.LayoutParams(
            ViewGroup.LayoutParams.MatchParent,
            Dp(22)));

        var inputRow = new LinearLayout(this)
        {
            Orientation = Orientation.Horizontal,
        };
        inputRow.SetGravity(GravityFlags.CenterVertical);

        var input = new EditText(this)
        {
            Text = "0.000",
            InputType = InputTypes.ClassNumber | InputTypes.NumberFlagDecimal | InputTypes.NumberFlagSigned,
            Gravity = GravityFlags.Center,
            Background = CreateSectionGizmoInputBackground(),
            TextSize = 15.0f,
        };
        input.SetSingleLine(true);
        input.SetSelectAllOnFocus(true);
        input.SetTextColor(GetColorCompat(Resource.Color.fa_text_primary));
        input.SetPadding(Dp(8), 0, Dp(8), 0);
        inputRow.AddView(input, new LinearLayout.LayoutParams(0, Dp(40), 1.0f)
        {
            RightMargin = Dp(6),
        });

        var unitLabel = new TextView(this)
        {
            Text = unit,
            TextSize = 12.0f,
            Gravity = GravityFlags.Center,
        };
        unitLabel.SetSingleLine(true);
        unitLabel.SetTextColor(GetColorCompat(Resource.Color.fa_text_secondary));
        inputRow.AddView(unitLabel, new LinearLayout.LayoutParams(Dp(30), Dp(40))
        {
            RightMargin = Dp(6),
        });

        TextView ok = CreateSectionGizmoPopupButton("OK");
        inputRow.AddView(ok, new LinearLayout.LayoutParams(Dp(48), Dp(40))
        {
            RightMargin = Dp(6),
        });

        TextView cancel = CreateSectionGizmoPopupButton("X");
        cancel.ContentDescription = GetString(global::Android.Resource.String.Cancel);
        inputRow.AddView(cancel, new LinearLayout.LayoutParams(Dp(36), Dp(40)));

        root.AddView(inputRow, new LinearLayout.LayoutParams(
            ViewGroup.LayoutParams.MatchParent,
            Dp(40))
        {
            TopMargin = Dp(6),
        });

        var popup = new PopupWindow(
            root,
            popupWidth,
            ViewGroup.LayoutParams.WrapContent,
            focusable: true)
        {
            OutsideTouchable = true,
            Touchable = true,
            ClippingEnabled = true,
        };
        popup.SetBackgroundDrawable(new ColorDrawable(Color.Transparent));
        popup.SoftInputMode = SoftInput.AdjustResize;
        if (Build.VERSION.SdkInt >= BuildVersionCodes.Lollipop)
            popup.Elevation = Dp(10);

        bool resolved = false;
        popup.DismissEvent += (_, _) =>
        {
            setInputOpen(false);
            if (!resolved && hasActiveDrag())
                cancelDrag();
        };

        ok.Click += (_, _) =>
        {
            string text = input.Text?.Trim() ?? string.Empty;
            bool parsed =
                double.TryParse(text, NumberStyles.Float, CultureInfo.InvariantCulture, out double value) ||
                double.TryParse(text, NumberStyles.Float, CultureInfo.CurrentCulture, out value);

            if (!parsed || !double.IsFinite(value))
            {
                Toast.MakeText(this, "Enter a valid number.", ToastLength.Short)?.Show();
                input.SelectAll();
                return;
            }

            double commitValue = IsSectionGizmoTranslate(handle)
                ? value / Math.Max(MillimetersPerSceneUnit, 1e-9)
                : value;
            commitTypedValue(commitValue);
            resolved = true;
            popup.Dismiss();
        };

        cancel.Click += (_, _) =>
        {
            resolved = true;
            cancelDrag();
            popup.Dismiss();
        };

        if (tryComputePopupPosition(handle, popupWidth, Dp(94), out int popupX, out int popupY))
            popup.ShowAtLocation(_viewport, GravityFlags.NoGravity, popupX, popupY);
        else
            popup.ShowAtLocation(Window?.DecorView, GravityFlags.Center, 0, 0);

        input.PostDelayed(() =>
        {
            input.RequestFocus();
            input.SelectAll();
            if (GetSystemService(Context.InputMethodService) is InputMethodManager inputManager)
                inputManager.ShowSoftInput(input, ShowFlags.Implicit);
        }, 120);
    }

    private bool TryComputeSectionGizmoPopupPosition(
        GlesTransformGizmoHandle handle,
        int popupWidth,
        int estimatedPopupHeight,
        out int x,
        out int y)
    {
        x = 0;
        y = 0;
        if (_viewport is null)
            return false;

        double viewportX;
        double viewportY;
        if (TryComputeSectionGizmoState(
                out Vector3d anchor,
                out Vector3d axisX,
                out Vector3d axisY,
                out Vector3d axisZ,
                out double scale))
        {
            Vector3d axis = SectionGizmoAxisForHandle(handle, axisX, axisY, axisZ);
            Vector3d target = axis.LengthSquared > 1e-12
                ? anchor + axis * scale * (IsSectionGizmoRotate(handle) ? SectionGizmoArcRadiusScale : 1.0)
                : anchor;
            if (!TryProjectWorldToViewport(target, out viewportX, out viewportY)
                && !TryProjectWorldToViewport(anchor, out viewportX, out viewportY))
            {
                viewportX = double.NaN;
                viewportY = double.NaN;
            }
        }
        else
        {
            viewportX = double.NaN;
            viewportY = double.NaN;
        }

        if (!double.IsFinite(viewportX) || !double.IsFinite(viewportY))
        {
            if (_sectionGizmoDownDip is not { } downDip)
                return false;

            float density = Resources?.DisplayMetrics?.Density ?? 1.0f;
            if (density <= 0f) density = 1.0f;
            viewportX = downDip.X * density;
            viewportY = downDip.Y * density;
        }

        int[] viewportLocation = new int[2];
        _viewport.GetLocationOnScreen(viewportLocation);
        int screenWidth = Resources?.DisplayMetrics?.WidthPixels ?? _viewport.Width;
        int screenHeight = Resources?.DisplayMetrics?.HeightPixels ?? _viewport.Height;
        int margin = Dp(8);
        int offset = Dp(14);

        int preferredX = viewportLocation[0] + (int)Math.Round(viewportX) + offset;
        if (preferredX + popupWidth + margin > screenWidth)
            preferredX = viewportLocation[0] + (int)Math.Round(viewportX) - popupWidth - offset;

        int preferredY = viewportLocation[1] + (int)Math.Round(viewportY) - estimatedPopupHeight / 2;
        x = Math.Clamp(preferredX, margin, Math.Max(margin, screenWidth - popupWidth - margin));
        y = Math.Clamp(preferredY, margin, Math.Max(margin, screenHeight - estimatedPopupHeight - margin));
        return true;
    }

    private bool TryComputeBodyMoveGizmoPopupPosition(
        GlesTransformGizmoHandle handle,
        int popupWidth,
        int estimatedPopupHeight,
        out int x,
        out int y)
    {
        x = 0;
        y = 0;
        if (_viewport is null)
            return false;

        double viewportX;
