    {
        var states = new StateListDrawable();
        states.AddState(new[] { AndroidStatePressed }, CreateSectionGizmoButtonFill(GetColorCompat(Resource.Color.fa_section_gizmo_button_pressed_fill), GetColorCompat(Resource.Color.fa_accent_600)));
        states.AddState(new[] { AndroidStateHovered }, CreateSectionGizmoButtonFill(GetColorCompat(Resource.Color.fa_section_gizmo_button_state_fill), GetColorCompat(Resource.Color.fa_accent_500)));
        states.AddState(new[] { AndroidStateFocused }, CreateSectionGizmoButtonFill(GetColorCompat(Resource.Color.fa_section_gizmo_button_state_fill), GetColorCompat(Resource.Color.fa_accent_500)));
