    private void CommitSectionGizmoTypedValue(double value)
    {
        if (_sectionGizmoActive == GlesTransformGizmoHandle.None || _sectionGizmoSnapshot is null)
            return;

        if (IsSectionGizmoTranslate(_sectionGizmoActive))
        {
            _sectionGizmoCurrentDelta = value;
            ApplySectionGizmoTranslate(_sectionGizmoDragAxisWorld * value);
        }
        else if (IsSectionGizmoRotate(_sectionGizmoActive))
        {
            double radians = value * Math.PI / 180.0;
            _sectionGizmoCurrentDelta = value;
            ApplySectionGizmoRotate(Quaterniond.FromAxisAngle(_sectionGizmoDragAxisWorld, radians), _sectionGizmoDragOrigin);
        }

        CommitSectionGizmoDrag();
    }

    private void BeginBodyMoveGizmoDrag(
        GlesTransformGizmoHandle handle,
        Vector3d rayOrigin,
        Vector3d rayDirection,
        Point2D downDip)
    {
        Scene? scene = _runtimeScene;
        if (_bodyMove is null
            || scene is null
            || handle == GlesTransformGizmoHandle.None
            || _sectionGizmoActive != GlesTransformGizmoHandle.None
            || !TryComputeBodyMoveGizmoState(
                out Vector3d anchor,
                out Vector3d axisX,
                out Vector3d axisY,
                out Vector3d axisZ,
                out _))
        {
            return;
        }

        if (_bodyMoveGizmoActive != GlesTransformGizmoHandle.None)
            CommitBodyMoveGizmoDrag();

        IReadOnlyList<SceneNode> movableNodes = BodyMoveSelection.ResolveMovableNodes(scene, _selectedNodeIds);
        _bodyMoveGizmoSnapshot = _bodyMove.SnapshotFor(movableNodes.Select(node => node.Id)).ToList();
        if (_bodyMoveGizmoSnapshot.Count == 0)
        {
            _bodyMoveGizmoSnapshot = null;
            return;
        }

        _bodyMoveGizmoActive = handle;
        _bodyMoveGizmoHovered = handle;
        _bodyMoveGizmoDownDip = downDip;
        _bodyMoveGizmoExceededDragThreshold = false;
        _bodyMoveGizmoCurrentDelta = 0.0;
        _bodyMoveGizmoDragOrigin = anchor;
        _bodyMoveGizmoDragAxisWorld = SectionGizmoAxisForHandle(handle, axisX, axisY, axisZ);

        if (_bodyMoveGizmoDragAxisWorld.LengthSquared < 1e-12)
        {
            CancelBodyMoveGizmoDrag();
            return;
        }

        if (IsSectionGizmoTranslate(handle))
            _bodyMoveGizmoStartAxisT = ProjectRayOntoAxis(rayOrigin, rayDirection, _bodyMoveGizmoDragOrigin, _bodyMoveGizmoDragAxisWorld);
        else if (IsSectionGizmoRotate(handle))
            _bodyMoveGizmoRotateStartVec = RotateRayHitVector(rayOrigin, rayDirection, _bodyMoveGizmoDragAxisWorld, _bodyMoveGizmoDragOrigin);

        UpdateBodyMoveGizmoRendererState();
        _viewport?.RequestRender();
        global::Android.Util.Log.Info("FA.BodyMove", $"Gizmo begin: handle={handle}, selected={_bodyMoveGizmoSnapshot.Count}.");
    }

    private void UpdateBodyMoveGizmoDrag(Vector3d rayOrigin, Vector3d rayDirection)
    {
        if (_bodyMoveGizmoActive == GlesTransformGizmoHandle.None || _bodyMoveGizmoSnapshot is null)
            return;

        if (IsSectionGizmoTranslate(_bodyMoveGizmoActive))
        {
            double currentT = ProjectRayOntoAxis(rayOrigin, rayDirection, _bodyMoveGizmoDragOrigin, _bodyMoveGizmoDragAxisWorld);
            double delta = currentT - _bodyMoveGizmoStartAxisT;
            _bodyMoveGizmoCurrentDelta = delta;
            ApplyBodyMoveGizmoTranslate(_bodyMoveGizmoDragAxisWorld * delta);
        }
        else if (IsSectionGizmoRotate(_bodyMoveGizmoActive))
        {
            Vector3d currentVec = RotateRayHitVector(rayOrigin, rayDirection, _bodyMoveGizmoDragAxisWorld, _bodyMoveGizmoDragOrigin);
            double angleRad = SignedAngle(_bodyMoveGizmoRotateStartVec, currentVec, _bodyMoveGizmoDragAxisWorld);
            _bodyMoveGizmoCurrentDelta = angleRad * 180.0 / Math.PI;
            ApplyBodyMoveGizmoRotate(Quaterniond.FromAxisAngle(_bodyMoveGizmoDragAxisWorld, angleRad), _bodyMoveGizmoDragOrigin);
        }
    }

    private void CommitBodyMoveGizmoDrag()
    {
        bool changed = _bodyMoveGizmoSnapshot is not null && Math.Abs(_bodyMoveGizmoCurrentDelta) > 1e-9;
        if (changed)
        {
            BodyMoveSnapshot[] before = _bodyMoveGizmoSnapshot!.ToArray();
            BodyMoveSnapshot[] after = _bodyMove?.SnapshotFor(before.Select(s => s.NodeId)).ToArray()
                ?? Array.Empty<BodyMoveSnapshot>();
            if (!SameBodyMoveSnapshots(before, after))
                _undoService?.Record(new BodyMoveChange(before, after), "Move parts");

            global::Android.Util.Log.Info("FA.BodyMove", $"Gizmo commit: handle={_bodyMoveGizmoActive}, delta={_bodyMoveGizmoCurrentDelta:0.###}.");
            OnBodyMovesCommitted(before.Select(s => s.NodeId).ToArray());
        }

        ClearBodyMoveGizmoDragState();
        UpdateBodyMoveGizmoRendererState();
        _viewport?.RequestRender();
    }

    private void CancelBodyMoveGizmoDrag()
    {
        if (_bodyMove is not null && _bodyMoveGizmoSnapshot is not null)
        {
            _bodyMove.RestoreTransforms(_bodyMoveGizmoSnapshot);
            SyncRuntimeSceneTransformsToRenderer("body move cancel");
        }

        global::Android.Util.Log.Info("FA.BodyMove", "Gizmo cancel.");
        ClearBodyMoveGizmoDragState();
        UpdateBodyMoveGizmoRendererState();
        _viewport?.RequestRender();
    }

    private void ClearBodyMoveGizmoDragState()
    {
        _bodyMoveGizmoActive = GlesTransformGizmoHandle.None;
        _bodyMoveGizmoDownDip = null;
        _bodyMoveGizmoExceededDragThreshold = false;
        _bodyMoveGizmoSnapshot = null;
        _bodyMoveGizmoStartAxisT = 0.0;
        _bodyMoveGizmoDragAxisWorld = default;
        _bodyMoveGizmoDragOrigin = default;
        _bodyMoveGizmoRotateStartVec = default;
        _bodyMoveGizmoCurrentDelta = 0.0;
        _bodyMoveGizmoInputOpen = false;
    }

    private void ApplyBodyMoveGizmoTranslate(Vector3d worldDelta)
    {
        if (_bodyMove is null || _bodyMoveGizmoSnapshot is null)
            return;

        Matrix4d delta = Matrix4d.CreateTranslation(worldDelta);
        foreach (BodyMoveSnapshot snap in _bodyMoveGizmoSnapshot)
            _bodyMove.SetMove(snap.NodeId, delta * snap.MoveTransform);

        SyncRuntimeSceneTransformsToRenderer("body move drag");
        UpdateBodyMoveGizmoRendererState();
    }

    private void ApplyBodyMoveGizmoRotate(Quaterniond rotation, Vector3d pivot)
    {
        if (_bodyMove is null || _bodyMoveGizmoSnapshot is null)
            return;

        Matrix4d recipe =
            Matrix4d.CreateTranslation(pivot)
            * rotation.ToMatrix4d()
            * Matrix4d.CreateTranslation(new Vector3d(-pivot.X, -pivot.Y, -pivot.Z));

        foreach (BodyMoveSnapshot snap in _bodyMoveGizmoSnapshot)
            _bodyMove.SetMove(snap.NodeId, recipe * snap.MoveTransform);

        SyncRuntimeSceneTransformsToRenderer("body move drag");
        UpdateBodyMoveGizmoRendererState();
    }

    private void CommitBodyMoveGizmoTypedValue(double value)
    {
        if (_bodyMoveGizmoActive == GlesTransformGizmoHandle.None || _bodyMoveGizmoSnapshot is null)
            return;

        if (IsSectionGizmoTranslate(_bodyMoveGizmoActive))
        {
            _bodyMoveGizmoCurrentDelta = value;
            ApplyBodyMoveGizmoTranslate(_bodyMoveGizmoDragAxisWorld * value);
        }
        else if (IsSectionGizmoRotate(_bodyMoveGizmoActive))
        {
            double radians = value * Math.PI / 180.0;
            _bodyMoveGizmoCurrentDelta = value;
            ApplyBodyMoveGizmoRotate(Quaterniond.FromAxisAngle(_bodyMoveGizmoDragAxisWorld, radians), _bodyMoveGizmoDragOrigin);
        }

        CommitBodyMoveGizmoDrag();
    }

    private void OnBodyMovesCommitted(IReadOnlyList<int> nodeIds)
    {
        _measure?.ClearRaycastAccelerationCache("body move");
        _sectionRaycaster?.ClearAccelerationCache("body move");
        RefreshMeasurementOverlays();
        SyncRuntimeSceneTransformsToRenderer("body move commit");
    }

    private static bool SameBodyMoveSnapshots(
        IReadOnlyList<BodyMoveSnapshot> before,
        IReadOnlyList<BodyMoveSnapshot> after)
    {
        if (before.Count != after.Count)
            return false;

        var afterByNode = after.ToDictionary(s => s.NodeId);
        foreach (BodyMoveSnapshot left in before)
        {
            if (!afterByNode.TryGetValue(left.NodeId, out BodyMoveSnapshot right)
                || !SameMatrix(left.MoveTransform, right.MoveTransform))
            {
                return false;
            }
        }

        return true;
    }

    private static bool SameSectionSnapshots(
        IReadOnlyList<SectionPlaneSnapshot> before,
        IReadOnlyList<SectionPlaneSnapshot> after)
    {
        if (before.Count != after.Count)
            return false;

        var afterById = after.ToDictionary(s => s.Id);
        foreach (SectionPlaneSnapshot left in before)
        {
            if (!afterById.TryGetValue(left.Id, out SectionPlaneSnapshot right)
                || !left.Equals(right))
            {
                return false;
            }
        }

        return true;
    }

    private static bool SameMatrix(Matrix4d left, Matrix4d right)
        => Math.Abs(left.M11 - right.M11) <= 1e-9
           && Math.Abs(left.M12 - right.M12) <= 1e-9
           && Math.Abs(left.M13 - right.M13) <= 1e-9
           && Math.Abs(left.M14 - right.M14) <= 1e-9
           && Math.Abs(left.M21 - right.M21) <= 1e-9
           && Math.Abs(left.M22 - right.M22) <= 1e-9
           && Math.Abs(left.M23 - right.M23) <= 1e-9
           && Math.Abs(left.M24 - right.M24) <= 1e-9
           && Math.Abs(left.M31 - right.M31) <= 1e-9
           && Math.Abs(left.M32 - right.M32) <= 1e-9
           && Math.Abs(left.M33 - right.M33) <= 1e-9
           && Math.Abs(left.M34 - right.M34) <= 1e-9
           && Math.Abs(left.M41 - right.M41) <= 1e-9
           && Math.Abs(left.M42 - right.M42) <= 1e-9
           && Math.Abs(left.M43 - right.M43) <= 1e-9
           && Math.Abs(left.M44 - right.M44) <= 1e-9;

    private double MillimetersPerSceneUnit
        => _viewport?.Renderer.Scene?.MillimetersPerSceneUnit is double mm && double.IsFinite(mm) && mm > 1e-9
            ? mm
            : 1.0;

    private static (string Label, string Unit) TransformGizmoInputLabel(GlesTransformGizmoHandle handle) => handle switch
    {
        GlesTransformGizmoHandle.TranslateX => ("dx", "mm"),
        GlesTransformGizmoHandle.TranslateY => ("dy", "mm"),
        GlesTransformGizmoHandle.TranslateZ => ("dz", "mm"),
        GlesTransformGizmoHandle.RotateX => ("rx", "deg"),
        GlesTransformGizmoHandle.RotateY => ("ry", "deg"),
        GlesTransformGizmoHandle.RotateZ => ("rz", "deg"),
        _ => ("value", string.Empty),
    };

    private static Vector3d SectionGizmoAxisForHandle(
        GlesTransformGizmoHandle handle,
        Vector3d axisX,
        Vector3d axisY,
        Vector3d axisZ)
        => handle switch
        {
            GlesTransformGizmoHandle.TranslateX or GlesTransformGizmoHandle.RotateX => axisX,
            GlesTransformGizmoHandle.TranslateY or GlesTransformGizmoHandle.RotateY => axisY,
            GlesTransformGizmoHandle.TranslateZ or GlesTransformGizmoHandle.RotateZ => axisZ,
            _ => Vector3d.Zero,
        };

    private static bool IsSectionGizmoTranslate(GlesTransformGizmoHandle handle)
        => handle is GlesTransformGizmoHandle.TranslateX
            or GlesTransformGizmoHandle.TranslateY
            or GlesTransformGizmoHandle.TranslateZ;

    private static bool IsSectionGizmoRotate(GlesTransformGizmoHandle handle)
        => handle is GlesTransformGizmoHandle.RotateX
            or GlesTransformGizmoHandle.RotateY
            or GlesTransformGizmoHandle.RotateZ;

    private Vector3d RotateRayHitVector(Vector3d rayOrigin, Vector3d rayDirection)
        => RotateRayHitVector(rayOrigin, rayDirection, _sectionGizmoDragAxisWorld, _sectionGizmoDragOrigin);

    private static Vector3d RotateRayHitVector(
        Vector3d rayOrigin,
        Vector3d rayDirection,
        Vector3d dragAxisWorld,
        Vector3d dragAxisOrigin)
    {
        double denom = Vector3d.Dot(dragAxisWorld, rayDirection);
        Vector3d hit;
        if (Math.Abs(denom) < 1e-9)
        {
            double distanceToPlane = Vector3d.Dot(rayOrigin - dragAxisOrigin, dragAxisWorld);
            hit = rayOrigin - dragAxisWorld * distanceToPlane;
        }
        else
        {
            double t = Vector3d.Dot(dragAxisOrigin - rayOrigin, dragAxisWorld) / denom;
            hit = rayOrigin + rayDirection * t;
        }

        Vector3d v = hit - dragAxisOrigin;
        return v.LengthSquared > 1e-12 ? v.Normalized() : Vector3d.UnitX;
    }

    private static double SignedAngle(Vector3d from, Vector3d to, Vector3d axis)
    {
        double dot = Math.Clamp(Vector3d.Dot(from, to), -1.0, 1.0);
        double angle = Math.Acos(dot);
        Vector3d cross = Vector3d.Cross(from, to);
        return Vector3d.Dot(cross, axis) < 0.0 ? -angle : angle;
    }

    private static double ProjectRayOntoAxis(
        Vector3d rayOrigin,
        Vector3d rayDirection,
        Vector3d origin,
        Vector3d axis)
    {
        Vector3d w0 = origin - rayOrigin;
        double a = Vector3d.Dot(axis, axis);
        double b = Vector3d.Dot(axis, rayDirection);
        double c = Vector3d.Dot(rayDirection, rayDirection);
        double d = Vector3d.Dot(axis, w0);
        double e = Vector3d.Dot(rayDirection, w0);
        double denom = a * c - b * b;
        if (Math.Abs(denom) < 1e-9)
            return 0.0;
        return (b * e - c * d) / denom;
    }

    private static bool TryNormalize(Vector3d value, out Vector3d normalized)
    {
        if (value.LengthSquared < 1e-12)
        {
            normalized = default;
            return false;
        }

        normalized = value.Normalized();
        return double.IsFinite(normalized.X) && double.IsFinite(normalized.Y) && double.IsFinite(normalized.Z);
    }

    private static double CameraDepth(Vector3d worldPoint, CameraState? camera)
    {
        if (camera is null || !IsFinite(worldPoint))
            return double.PositiveInfinity;

        Vector3d forward = camera.Forward;
        if (!TryNormalize(forward, out forward))
            return double.PositiveInfinity;

        double depth = Vector3d.Dot(worldPoint - camera.Position, forward);
        return double.IsFinite(depth) && depth >= 0.0
            ? depth
            : double.PositiveInfinity;
    }

    private static bool IsCloserDepth(double candidateDepth, double bestDepth)
    {
        bool candidateFinite = double.IsFinite(candidateDepth);
        bool bestFinite = double.IsFinite(bestDepth);
        if (candidateFinite != bestFinite)
            return candidateFinite;

        return candidateFinite && candidateDepth < bestDepth - 1e-9;
    }

    private static bool IsBetterDepthHit(
        double candidateDepth,
        double candidateDistance,
        double bestDepth,
        double bestDistance,
        bool hasBest)
    {
        if (!hasBest)
            return true;

        if (IsCloserDepth(candidateDepth, bestDepth))
            return true;

        if (IsCloserDepth(bestDepth, candidateDepth))
            return false;

        return candidateDistance < bestDistance;
    }

    private void ClearSectionPlacementDraft()
    {
        bool changed = _activeSectionSubMode != SectionSubMode.None
            || _sectionCustomPoints.Count > 0
            || _sectionHoverPoint.HasValue
            || _hoveredSectionPlaneId.HasValue;

        _activeSectionSubMode = SectionSubMode.None;
        _sectionCustomPoints.Clear();
        _sectionHoverPoint = null;
        _hoveredSectionPlaneId = null;
        if (changed)
            UpdateSectionRendererState();
    }

    private void RestorePendingSectionState()
    {
        if (_sections is null || _pendingRestoredSectionPlanes is not { Length: > 0 } records)
            return;

        var planes = new List<SectionPlane>(records.Length);
        foreach (string record in records)
        {
            if (TryDeserializeSectionPlane(record, out SectionPlane plane))
                planes.Add(plane);
        }

        if (planes.Count > 0)
        {
            _sections.AddRange(planes);
            if (_pendingRestoredSelectedSectionPlanes is { Length: > 0 } selectedRecords)
            {
                var validIds = planes.Select(p => p.Id).ToHashSet();
                Guid[] selectedIds = selectedRecords
                    .Select(id => Guid.TryParse(id, out Guid parsed) ? parsed : Guid.Empty)
                    .Where(id => id != Guid.Empty && validIds.Contains(id))
                    .ToArray();
                if (selectedIds.Length > 0)
                    _sections.Select(selectedIds, additive: false);
            }
        }

        ClearPendingSectionState();
    }

    private void ClearPendingSectionState()
    {
        _pendingRestoredSectionPlanes = null;
        _pendingRestoredSelectedSectionPlanes = null;
    }

    private static string SerializeSectionPlane(SectionPlane plane)
    {
        static string F(float value) => value.ToString("R", CultureInfo.InvariantCulture);

        return string.Join('|',
            plane.Id.ToString("D"),
            F(plane.Anchor.X), F(plane.Anchor.Y), F(plane.Anchor.Z),
            F(plane.AxisX.X), F(plane.AxisX.Y), F(plane.AxisX.Z),
            F(plane.AxisY.X), F(plane.AxisY.Y), F(plane.AxisY.Z),
            F(plane.Normal.X), F(plane.Normal.Y), F(plane.Normal.Z));
    }

    private static bool TryDeserializeSectionPlane(string? record, out SectionPlane plane)
    {
        plane = default;
        if (string.IsNullOrWhiteSpace(record))
            return false;

        string[] parts = record.Split('|');
        if (parts.Length != 13 || !Guid.TryParse(parts[0], out Guid id))
            return false;

        Span<float> values = stackalloc float[12];
        for (int i = 0; i < values.Length; i++)
        {
            if (!float.TryParse(parts[i + 1], NumberStyles.Float, CultureInfo.InvariantCulture, out float value)
                || !float.IsFinite(value))
            {
                return false;
            }

            values[i] = value;
        }

        var anchor = new Vector3(values[0], values[1], values[2]);
        var axisX = new Vector3(values[3], values[4], values[5]);
        var axisY = new Vector3(values[6], values[7], values[8]);
        var normal = new Vector3(values[9], values[10], values[11]);
        if (axisX.LengthSquared() <= 1e-12f
            || axisY.LengthSquared() <= 1e-12f
            || normal.LengthSquared() <= 1e-12f)
        {
            return false;
        }

        plane = new SectionPlane(id, anchor, axisX, axisY, normal);
        return true;
    }

    private static (Vector3d AxisX, Vector3d AxisY) SectionTangents(Vector3d normal)
    {
        Vector3d reference = Math.Abs(normal.X) < 0.9 ? Vector3d.UnitX : Vector3d.UnitY;
        Vector3d axisX = Vector3d.Cross(reference, normal).Normalized();
        Vector3d axisY = Vector3d.Cross(normal, axisX).Normalized();
        return (axisX, axisY);
    }

    private static Vector3 ToVector3(Vector3d value)
        => new((float)value.X, (float)value.Y, (float)value.Z);

    private static Vector3d ToVector3d(Vector3 value)
        => new(value.X, value.Y, value.Z);

    private static bool IsFinite(Vector3d value)
        => double.IsFinite(value.X) && double.IsFinite(value.Y) && double.IsFinite(value.Z);

    private static Vector3d ToVector3d(double[] value)
        => new(value[0], value[1], value[2]);

    private static bool IsFiniteVector(double[]? value, bool requireNonZero = false)
    {
        if (value is not { Length: 3 })
            return false;

        var vector = new Vector3d(value[0], value[1], value[2]);
        return IsFinite(vector) && (!requireNonZero || vector.LengthSquared > 1e-24);
    }

    private static bool TryBuildSectionPlane(ViewerSectionPlaneDto dto, out SectionPlane plane)
    {
        plane = default;
        if (!IsFiniteVector(dto.Anchor)
            || !IsFiniteVector(dto.AxisX, requireNonZero: true)
            || !IsFiniteVector(dto.AxisY, requireNonZero: true)
            || !IsFiniteVector(dto.Normal, requireNonZero: true))
        {
            return false;
        }

        plane = new SectionPlane(
            dto.Id == Guid.Empty ? Guid.NewGuid() : dto.Id,
            ToVector3(ToVector3d(dto.Anchor)),
            ToVector3(ToVector3d(dto.AxisX)),
            ToVector3(ToVector3d(dto.AxisY)),
            ToVector3(ToVector3d(dto.Normal)));
        return true;
    }

    private static bool IsFiniteVector(float[]? value, bool requireNonZero = false)
    {
        if (value is not { Length: 3 })
            return false;

        return float.IsFinite(value[0])
               && float.IsFinite(value[1])
               && float.IsFinite(value[2])
               && (!requireNonZero || value[0] * value[0] + value[1] * value[1] + value[2] * value[2] > 1e-12f);
    }

    private static Vector3d ToVector3d(float[] value)
        => new(value[0], value[1], value[2]);

    private void ToggleExplodeTool()
    {
        if (!CanUseExplodeView())
            return;

        if (_activeModalTool == AndroidModalTool.Explode)
        {
            ActivateSelectTool("explode toggled off");
            return;
        }

        EnterToolbarMode(BottomToolbarMode.Explode, AndroidModalTool.Explode);
        SetExplodeAmount(0.0, "tool opened");
    }

    private bool CanUseExplodeView()
        => _runtimeScene is not null && _runtimeScene.NodesById.Values.Count(node => node.MeshId.HasValue) > 1;

    private void EnsureExplodeLayout()
    {
        Scene? scene = _runtimeScene;
        if (scene is null)
            return;

        if (ReferenceEquals(_explodeLayoutScene, scene) && _explodeLayout is not null)
            return;

        _explodeLayout = AndroidViewportExplodeView.Build(scene);
        _explodeLayoutScene = scene;
        global::Android.Util.Log.Info("FA.Explode", $"Layout built: units={_explodeLayout.Units.Count}, explodable={_explodeLayout.HasExplodableUnits}.");
    }

    private void SetExplodeAmount(double amount, string reason)
    {
        _explodeAmount = double.IsFinite(amount) ? Math.Clamp(amount, 0.0, 1.0) : 0.0;
        UpdateExplodeButtonState();
        if (_activeModalTool == AndroidModalTool.Explode)
            ApplyExplodeViewAmount(reason);
    }

    private void ApplyExplodeViewAmount(string reason)
    {
        Scene? scene = _runtimeScene;
        if (scene is null)
            return;

        EnsureExplodeLayout();
        if (_explodeLayout is null)
            return;

        AndroidViewportExplodeView.Apply(scene, _explodeLayout, _explodeAmount);
        SyncRuntimeSceneTransformsToRenderer("explode " + reason);
        if (!string.Equals(reason, "slider", StringComparison.Ordinal))
            global::Android.Util.Log.Info("FA.Explode", $"Applied amount={_explodeAmount:0.###}: reason={reason}.");
    }

    private void ClearExplodeView(string reason, bool syncRenderer = true)
    {
        if (_explodeLayoutScene is not null && _explodeLayout is not null)
            AndroidViewportExplodeView.Clear(_explodeLayoutScene, _explodeLayout);

        _explodeAmount = 0.0;
        if (syncRenderer)
            SyncRuntimeSceneTransformsToRenderer("explode clear " + reason);
        UpdateExplodeButtonState();
        global::Android.Util.Log.Info("FA.Explode", $"Cleared: reason={reason}.");
    }

    private void SyncRuntimeSceneTransformsToRenderer(string reason)
    {
        if (_viewport is null || _runtimeScene is null)
            return;

        Scene scene = _runtimeScene;
        if (Interlocked.Exchange(ref _runtimeTransformSyncQueued, 1) != 0)
        {
            _viewport.RequestRender();
            return;
        }

        _viewport.QueueRendererCommand(
            "sync-transforms-" + reason,
            _ =>
            {
                Interlocked.Exchange(ref _runtimeTransformSyncQueued, 0);
                if (!ReferenceEquals(_runtimeScene, scene))
                {
                    global::Android.Util.Log.Warn("FA.Transform", $"Skipped stale transform sync: reason={reason}.");
                    return;
                }

                _viewport.Renderer.Scene?.SyncNodeTransforms(scene);
            },
            logSlow: !string.Equals(reason, "explode slider", StringComparison.Ordinal));
        _viewport.RequestRender();
    }

    private bool HasScene() => _runtimeScene is not null;

    private void ApplyViewPreset(StandardView view)
    {
        if (SetStandardView(view, fitAll: true))
            SetViewPresetToolbarVisible(false);
    }

    private void ApplyViewPresetReset()
    {
        bool applied = _isInFixedView && _activeFixedView is { } activeView
            ? SetStandardView(activeView, fitAll: true)
            : ResetCameraToDefaultView();

        if (applied)
            SetViewPresetToolbarVisible(false);
    }

    private bool SetStandardView(StandardView view, bool fitAll)
    {
        CameraState? camera = _camera;
        if (camera is null)
            return false;

        BoundingBox fitBounds = GetVisibleSceneBounds();
        if (fitAll && !fitBounds.IsValid)
            return false;

        bool isLockEntry = view != StandardView.Isometric;
        double aspect = GetViewportAspect();
        BoundingBox clipBounds = GetCameraClipBounds();

        bool effectivePerspective;
        lock (camera)
        {
            if (isLockEntry)
            {
                if (!_isInFixedView)
                    _isoIsPerspective = camera.IsPerspective;

                _activeFixedView = view;
                ApplyFixedViewProjection(camera, isPerspective: false, aspect, clipBounds);
            }
            else
            {
                ApplyFixedViewProjection(camera, _isoIsPerspective, aspect, clipBounds);
                _activeFixedView = null;
            }

            camera.SetStandardView(view);
            if (fitAll)
                FitCameraToBoundsPreservingView(camera, fitBounds, aspect);
            if (clipBounds.IsValid)
                AndroidCameraClipPlanes.Update(camera, clipBounds);

            _isInFixedView = isLockEntry;
            effectivePerspective = camera.IsPerspective;
        }

        SetRendererProjectionAppearance(effectivePerspective);
        UpdateViewPresetButtonStates();
        RefreshMeasurementOverlays();
        _viewport?.RequestRender();

        global::Android.Util.Log.Info(
            "FA.ViewPresets",
            $"Applied {view}: fixed={_isInFixedView}, projection={(effectivePerspective ? "Perspective" : "Orthographic")}, isoSnapshot={(_isoIsPerspective ? "Perspective" : "Orthographic")}, fitDiag={(fitBounds.IsValid ? fitBounds.Diagonal : 0.0):0.###}.");

        return true;
    }

    private bool ResetCameraToDefaultView()
    {
        CameraState? camera = _camera;
        if (camera is null)
            return false;

        BoundingBox fitBounds = GetVisibleSceneBounds();
        if (!fitBounds.IsValid)
            return false;

        double aspect = GetViewportAspect();
        BoundingBox clipBounds = GetCameraClipBounds();
        bool effectivePerspective;

        lock (camera)
        {
            Vector3d preferredUp = GetPreferredUpDirectionForCurrentScene();
            camera.Position = new Vector3d(5, 5, 5);
            camera.Target = Vector3d.Zero;
            camera.WorldUpDirection = preferredUp;
            camera.UpDirection = preferredUp;
            camera.FieldOfView = Math.PI / 4.0;
            camera.OrthoWidth = 10.0;
            FitCameraToBoundsPreservingView(camera, fitBounds, aspect);
            if (clipBounds.IsValid)
                AndroidCameraClipPlanes.Update(camera, clipBounds);
            effectivePerspective = camera.IsPerspective;
        }

        SetRendererProjectionAppearance(effectivePerspective);
        RefreshMeasurementOverlays();
        _viewport?.RequestRender();

        global::Android.Util.Log.Info(
            "FA.ViewPresets",
            $"Reset view: fixed={_isInFixedView}, projection={(effectivePerspective ? "Perspective" : "Orthographic")}, fitDiag={fitBounds.Diagonal:0.###}.");

        return true;
    }

    private static void ApplyFixedViewProjection(CameraState camera, bool isPerspective, double aspect, BoundingBox clipBounds)
    {
        if (camera.IsPerspective != isPerspective)
            camera.SetProjectionMode(isPerspective, aspect);
        if (clipBounds.IsValid)
            AndroidCameraClipPlanes.Update(camera, clipBounds);
    }

    private void SetRendererProjectionAppearance(bool isPerspective)
    {
        if (_viewport is null)
            return;

        var appearance = _viewport.Renderer.Appearance;
        appearance.IsPerspective = isPerspective;
        var viewport = _viewport;
        viewport.QueueRendererCommand(
            "set-projection-appearance",
            _ => viewport.Renderer.Appearance = appearance,
            logSlow: false);
        viewport.RequestRender();
        LogProjectionState(AppSettings.IsPerspective, GetViewportAspect());
    }

    private void ActivateInteractiveMeasureMode(MeasureToolMode mode, string reason)
    {
        if (_measure is null || !IsInteractiveMeasureMode(mode))
            return;

        _lastInteractiveMeasureMode = mode;
        AppSettings.MeasureModeSelectionIndex = MeasureModeToSettingsIndex(mode);
        if (_measure.ActiveMode != mode)
            _measure.SetMode(mode);
        else
            _measure.ClearHover();

        global::Android.Util.Log.Info("FA.Measure", $"Interactive mode active: reason={reason}, mode={mode}.");
        UpdateMeasureButtonStates();
        RefreshMeasurementOverlays();
    }

    private MeasureToolMode PreferredInteractiveMeasureMode()
    {
        MeasureToolMode activeMode = _measure?.ActiveMode ?? MeasureToolMode.None;
        return IsInteractiveMeasureMode(activeMode)
            ? activeMode
            : _lastInteractiveMeasureMode;
    }

    private static bool IsInteractiveMeasureMode(MeasureToolMode mode)
        => mode == MeasureToolMode.PointToPoint
           || mode == MeasureToolMode.FaceToPoint
           || mode == MeasureToolMode.FaceToFace;

