    private void SetFullscreenUiActive(bool active)
    {
        if (_fullscreenUiActive == active)
            return;

        if (active)
        {
            SetLeftToolPanelExpanded(false, animate: false);
            _propertiesPanelExpandedBeforeFullscreen = _propertiesPanelExpanded && _propertiesPanel is not null;
            SetPropertiesPanelExpanded(false);
        }

        _fullscreenUiActive = active;
        ViewStates chromeVisibility = active ? ViewStates.Gone : ViewStates.Visible;

        ApplySystemBarsForFullscreen(active);
        SetVisibility(_topAppBar, chromeVisibility);
        SetVisibility(_navRail, chromeVisibility);
        SetVisibility(_navRailDivider, chromeVisibility);

        if (!active && _propertiesPanelExpandedBeforeFullscreen && _propertiesPanel is not null)
            SetPropertiesPanelExpanded(true);
        if (!active)
            _propertiesPanelExpandedBeforeFullscreen = false;

        UpdateFullscreenButtonState();
        _viewport?.RequestLayout();
        _viewport?.RequestRender();

        global::Android.Util.Log.Info("FA.UI", $"Full-screen UI {(active ? "enabled" : "disabled")}.");
    }

    private void ApplySystemBarsForFullscreen(bool active)
    {
        View? decor = Window?.DecorView;
        if (decor is null)
            return;

        if (active)
            ApplyBottomAppBarFullscreenInset(active: true);

#pragma warning disable CS0618
        decor.SystemUiVisibility = active
            ? (StatusBarVisibility)(
                SystemUiFlags.ImmersiveSticky
                | SystemUiFlags.Fullscreen
                | SystemUiFlags.HideNavigation
                | SystemUiFlags.LayoutFullscreen
                | SystemUiFlags.LayoutHideNavigation
                | SystemUiFlags.LayoutStable)
            : StatusBarVisibility.Visible;
#pragma warning restore CS0618

        if (!active)
            ApplyBottomAppBarFullscreenInset(active: false);

        decor.RequestApplyInsets();
    }

    private void CaptureBottomAppBarBaseBottomMargin()
    {
        if (_bottomAppBarBaseBottomMarginCaptured || _bottomAppBar?.LayoutParameters is not ViewGroup.MarginLayoutParams lp)
            return;

        _bottomAppBarBaseBottomMargin = lp.BottomMargin;
        _bottomAppBarBaseBottomMarginCaptured = true;
    }

    private void ApplyBottomAppBarFullscreenInset(bool active)
    {
        if (_bottomAppBar is null)
            return;

        CaptureBottomAppBarBaseBottomMargin();

        int currentInset = ResolveNavigationBarInsetBottomPx();
        if (currentInset > 0)
            _lastNavigationBarInsetBottomPx = currentInset;

        int fullscreenInset = Math.Max(currentInset, _lastNavigationBarInsetBottomPx);
        int targetBottomMargin = _bottomAppBarBaseBottomMargin + (active ? fullscreenInset : 0);
        if (_bottomAppBar.LayoutParameters is ViewGroup.MarginLayoutParams lp
            && lp.BottomMargin != targetBottomMargin)
        {
            lp.BottomMargin = targetBottomMargin;
            _bottomAppBar.LayoutParameters = lp;
            _bottomAppBar.RequestLayout();
        }
    }

    private int ResolveNavigationBarInsetBottomPx()
    {
        WindowInsets? insets = Window?.DecorView?.RootWindowInsets ?? _bottomAppBar?.RootWindowInsets;
        if (insets is null)
            return 0;

        if (Build.VERSION.SdkInt >= BuildVersionCodes.R)
        {
            var navInsets = insets.GetInsets(WindowInsets.Type.NavigationBars());
            return Math.Max(0, navInsets.Bottom);
        }

#pragma warning disable CS0618, CA1422
        return Math.Max(0, insets.SystemWindowInsetBottom);
#pragma warning restore CS0618, CA1422
    }

    private void UpdateFullscreenButtonState()
    {
        if (_toolFullscreenButton is null)
            return;

        int iconId = _fullscreenUiActive
            ? Resource.Drawable.ic_fullscreen_exit
            : Resource.Drawable.ic_fullscreen;
        int contentDescriptionId = _fullscreenUiActive
            ? Resource.String.cd_tool_exit_fullscreen
            : Resource.String.cd_tool_fullscreen;

        _toolFullscreenButton.Icon = AndroidX.AppCompat.Content.Res.AppCompatResources.GetDrawable(this, iconId);
        _toolFullscreenButton.ContentDescription = GetString(contentDescriptionId);
        _toolFullscreenButton.Selected = _fullscreenUiActive;
        SetTooltip(_toolFullscreenButton, contentDescriptionId);
    }

    private void RebindStyledTooltips()
    {
        DisposeStyledTooltips();
        ApplyMainTooltips();
        ApplyMeasureTooltips();
        ApplyViewPresetTooltips();
        ApplySectionTooltips();
        ApplyExplodeTooltips();
        ApplyRenderModeTooltips();
        ApplySpenPalmRejectionState(showToast: false);
        UpdateFullscreenButtonState();
    }

    private void SetTooltip(View? view, int stringId)
    {
        if (view is null)
            return;

        string? text = GetString(stringId);
        if (string.IsNullOrWhiteSpace(text))
            return;

        if (view.ContentDescription is null)
            view.ContentDescription = text;

        if (_styledTooltips.TryGetValue(view, out StyledTooltipController? tooltip))
        {
            tooltip.UpdateText(text);
            return;
        }

        _styledTooltips[view] = new StyledTooltipController(this, view, text, DismissStyledTooltipsExcept);
    }

    private void DismissStyledTooltips()
    {
        foreach (StyledTooltipController tooltip in _styledTooltips.Values)
            tooltip.Dismiss();
    }

    private void DismissStyledTooltipsExcept(StyledTooltipController activeTooltip)
    {
        foreach (StyledTooltipController tooltip in _styledTooltips.Values)
        {
            if (!ReferenceEquals(tooltip, activeTooltip))
                tooltip.Dismiss();
        }
    }

    private void DisposeStyledTooltips()
    {
        foreach (StyledTooltipController tooltip in _styledTooltips.Values)
            tooltip.Dispose();

        _styledTooltips.Clear();
    }

    private static void SetVisibility(View? view, ViewStates visibility)
    {
        if (view is not null)
            view.Visibility = visibility;
    }

    private static void SetSelected(View? view, bool selected)
    {
        if (view is not null)
            view.Selected = selected;
    }

    private static void SetEnabled(View? view, bool enabled)
    {
        if (view is null)
            return;

        view.Enabled = enabled;
        view.Alpha = enabled ? 1f : 0.55f;
    }

    private void OnGestureForSelection(TouchGestureEvent ev)
    {
        if (_viewport is null) return;

        if (_activeModalTool == AndroidModalTool.ZoomWindow)
            return;

        if (_activeModalTool == AndroidModalTool.Section
            && _activeSectionSubMode == SectionSubMode.Custom
            && ev.Kind != TouchGestureKind.Tap)
        {
            return;
        }

        if (ev.Kind is TouchGestureKind.LongPress or TouchGestureKind.SecondaryTap)
        {
            HandleViewportContextRequest(ev);
            return;
        }

        if (ev.Kind != TouchGestureKind.Tap) return;

        if (TryHandleAnnotationTap(ev.Position))
            return;

        if (TryHandleSectionTap(ev.Position))
            return;

        if (_activeModalTool == AndroidModalTool.Measure
            || _activeModalTool == AndroidModalTool.Section)
        {
            ClearSelectableOverlaySelection("viewport tap");
        }

        if (_measureBoundingBoxAwaitingSelection)
        {
            HandleBoundingBoxSelectionTap(ev);
            return;
        }

        if (_measure is { IsActive: true })
        {
            HandleMeasureTap(ev);
            return;
        }

        if (_activeModalTool == AndroidModalTool.BodyMove)
        {
            HandleBodyMoveSelectionTap(ev);
            return;
        }

        if (!CanPickViewportModelBodies())
            return;

        ClearSelectedMeasurement("viewport tap");

        // Tap positions are in DIPs (AndroidPointerSource scales MotionEvent
        // pixels by 1/density). The pick FBO is sized in physical pixels, so
        // convert back. Resources.DisplayMetrics.Density is constant for the
        // session on a Samsung tablet.
        float density = Resources?.DisplayMetrics?.Density ?? 1.0f;
        if (density <= 0f) density = 1.0f;
        int px = (int)(ev.Position.X * density);
        int py = (int)(ev.Position.Y * density);

        string pickReason = _activeModalTool == AndroidModalTool.Explode ? "explode-tap" : "tap";
        _viewport.PickAsync(px, py, pickReason, hit => OnPickResult(hit));
    }

    private bool CanPickViewportModelBodies()
        => _activeModalTool == AndroidModalTool.Select
           || _activeModalTool == AndroidModalTool.Explode;

    private void HandleViewportContextRequest(TouchGestureEvent ev)
    {
        if (_viewport is null)
            return;

        if (_activeModalTool != AndroidModalTool.Select || _measure is { IsActive: true })
        {
            global::Android.Util.Log.Info(
                "FA.ContextMenu",
                $"Ignored: kind={ev.Kind}, activeTool={_activeModalTool}, measureActive={_measure?.IsActive == true}.");
            return;
        }

        _viewport.PerformHapticFeedback(FeedbackConstants.LongPress);

        float density = Resources?.DisplayMetrics?.Density ?? 1.0f;
        if (density <= 0f) density = 1.0f;
        int px = (int)(ev.Position.X * density);
        int py = (int)(ev.Position.Y * density);
        global::Android.Util.Log.Info(
            "FA.ContextMenu",
            $"Request: kind={ev.Kind}, px={px}, py={py}, dip=({ev.Position.X:0.#},{ev.Position.Y:0.#}).");
        _viewport.PickAsync(px, py, "context", hit =>
        {
            if (hit is > 0)
                OnPickResult(hit);

            ShowViewportContextMenu(ev.Position, hit);
        });
    }

    private void ShowViewportContextMenu(Point2D dipPosition, int? hitMeshIndex)
    {
        if (_viewport is null || _contextMenuAnchor is null)
            return;

        PositionContextMenuAnchor(dipPosition);

        bool hasScene = HasScene();
        bool hasSelection = _selectedNodeIds.Count > 0;
        var actions = new List<(string Title, Action Action)>();
        AddAction(Resource.String.context_undo, _undoService?.CanUndo == true, UndoLastAction);
        AddAction(Resource.String.context_redo, _undoService?.CanRedo == true, RedoLastAction);
        AddAction(Resource.String.context_move, CanMoveSelectedBodies(), () => ActivateBodyMoveTool("context menu"));
        AddAction(Resource.String.context_restore_position, CanRestoreSelectedPositions(), RestoreSelectedPositions);
        AddAction(Resource.String.context_properties, hasSelection, OpenSelectedProperties);
        AddAction(Resource.String.context_zoom_selected, hasScene && hasSelection, ZoomToSelection);
        AddAction(Resource.String.context_hide, hasSelection && CanHideSelectedNodes(), HideSelectedNodes);
        AddAction(Resource.String.context_isolate, hasScene && hasSelection, IsolateSelectedNodes);
        AddAction(Resource.String.context_isolate_xray, hasScene && hasSelection, IsolateXraySelectedNodes);
        AddAction(Resource.String.context_show_all, hasScene && CanShowAllNodes(), ShowAllNodes);

        if (actions.Count == 0)
        {
            global::Android.Util.Log.Info(
                "FA.ContextMenu",
                $"Skipped: no available actions, kind={(hitMeshIndex is > 0 ? "hit" : "empty")}, hitMesh={hitMeshIndex?.ToString() ?? "<none>"}, selected=[{string.Join(",", _selectedNodeIds)}].");
            return;
        }

        var menuRoot = new LinearLayout(this)
        {
            Orientation = Orientation.Vertical,
            ClipToOutline = true,
        };
        menuRoot.SetMinimumWidth(Dp(ContextMenuMinWidthDp));
        int padX = Dp(3);
        int padY = Dp(3);
        menuRoot.SetPadding(padX, padY, padX, padY);
        menuRoot.Background = CreateContextMenuBackground();

        var popup = new PopupWindow(
            menuRoot,
            ViewGroup.LayoutParams.WrapContent,
            ViewGroup.LayoutParams.WrapContent,
            focusable: true)
        {
            OutsideTouchable = true,
            Touchable = true,
            ClippingEnabled = true,
        };
        popup.SetBackgroundDrawable(new ColorDrawable(Color.Transparent));
        if (Build.VERSION.SdkInt >= BuildVersionCodes.Lollipop)
            popup.Elevation = Dp(8);

        foreach ((string title, Action action) in actions)
            AddContextMenuRow(menuRoot, title, popup, action);

        global::Android.Util.Log.Info(
            "FA.ContextMenu",
            $"Show: actions={actions.Count}, kind={(hitMeshIndex is > 0 ? "hit" : "empty")}, hitMesh={hitMeshIndex?.ToString() ?? "<none>"}, selected=[{string.Join(",", _selectedNodeIds)}], dip=({dipPosition.X:0.#},{dipPosition.Y:0.#}).");
        popup.ShowAsDropDown(_contextMenuAnchor, 0, 0);

        void AddAction(int titleResId, bool enabled, Action action)
        {
            if (!enabled)
                return;

            string title = GetString(titleResId) ?? string.Empty;
            if (!string.IsNullOrWhiteSpace(title))
                actions.Add((title, action));
        }
    }

    private void UndoLastAction()
    {
        if (_undoService?.CanUndo != true)
            return;

        string? label = _undoService.PeekUndoLabel;
        _undoService.Undo();
        RefreshAfterUndoRedo("undo", label);
    }

    private void RedoLastAction()
    {
        if (_undoService?.CanRedo != true)
            return;

        string? label = _undoService.PeekRedoLabel;
        _undoService.Redo();
        RefreshAfterUndoRedo("redo", label);
    }

    private void RefreshAfterUndoRedo(string direction, string? label)
    {
        _measure?.ClearRaycastAccelerationCache(direction);
        _sectionRaycaster?.ClearAccelerationCache(direction);

        Scene? scene = _runtimeScene;
        if (scene is not null)
        {
            SyncRuntimeSceneTransformsToRenderer(direction);
            SyncRuntimeSceneVisibilityToRenderer(direction);
            RefreshSelectionDependentUi(
                scene,
                scrollModelExplorerToSelection: false,
                requestRender: false);
        }

        RefreshMeasurementOverlays();
        UpdateSectionRendererState();
        UpdateBodyMoveGizmoRendererState();
        UpdateBottomToolbarVisibility();
        UpdateMainToolButtonStates();
        UpdateUndoRedoButtons();
        UpdateMeasureButtonStates();
        UpdateViewPresetButtonStates();
        UpdateSectionButtonStates();
        _viewport?.RequestRender();

        global::Android.Util.Log.Info("FA.Undo", $"{direction}: label='{label ?? "<none>"}'.");
    }

    private void PositionContextMenuAnchor(Point2D dipPosition)
    {
        if (_contextMenuAnchor is null || _viewport is null)
            return;

        float density = Resources?.DisplayMetrics?.Density ?? 1.0f;
        if (density <= 0f) density = 1.0f;
        int x = Math.Clamp((int)Math.Round(dipPosition.X * density), 0, Math.Max(_viewport.Width - 1, 0));
        int y = Math.Clamp((int)Math.Round(dipPosition.Y * density), 0, Math.Max(_viewport.Height - 1, 0));

        if (_contextMenuAnchor.LayoutParameters is FrameLayout.LayoutParams lp)
        {
            lp.LeftMargin = x;
            lp.TopMargin = y;
            _contextMenuAnchor.LayoutParameters = lp;
        }
    }

    private void AddContextMenuRow(LinearLayout parent, string title, PopupWindow popup, Action action)
    {
        var row = new TextView(this)
        {
            Text = title,
            TextSize = 12.5f,
            Gravity = GravityFlags.CenterVertical,
            Ellipsize = TextUtils.TruncateAt.End,
            Enabled = true,
            Clickable = true,
            Focusable = true,
        };
        row.SetSingleLine(true);
        row.SetIncludeFontPadding(false);
        row.SetMinHeight(Dp(ContextMenuRowHeightDp));
        row.ContentDescription = title;
        row.ImportantForAccessibility = ImportantForAccessibility.Yes;
        row.SetTextColor(GetColorCompat(Resource.Color.fa_text_primary));
        row.SetPadding(Dp(9), 0, Dp(9), 0);
        row.Background = CreateContextMenuRowBackground();
        row.Click += (_, _) =>
        {
            popup.Dismiss();
            action();
        };

        parent.AddView(row, new LinearLayout.LayoutParams(
            ViewGroup.LayoutParams.MatchParent,
            Dp(ContextMenuRowHeightDp)));
    }

    private GradientDrawable CreateContextMenuBackground()
    {
        var background = new GradientDrawable();
        background.SetShape(ShapeType.Rectangle);
        background.SetColor(GetColorCompat(Resource.Color.fa_context_menu_background));
        background.SetCornerRadius(Dp(ContextMenuCornerRadiusDp));
        background.SetStroke(Dp(1), GetColorCompat(Resource.Color.fa_context_menu_border));
        return background;
    }

    private Drawable CreateContextMenuRowBackground()
    {
        var states = new StateListDrawable();
        states.AddState(new[] { AndroidStatePressed }, CreateContextMenuRowFill());
        states.AddState(new[] { AndroidStateHovered }, CreateContextMenuRowFill());
        states.AddState(new[] { AndroidStateFocused }, CreateContextMenuRowFill());
        states.AddState(Array.Empty<int>(), new ColorDrawable(Color.Transparent));
        return states;
    }

    private GradientDrawable CreateContextMenuRowFill()
    {
        var fill = new GradientDrawable();
        fill.SetShape(ShapeType.Rectangle);
        fill.SetColor(GetColorCompat(Resource.Color.fa_context_menu_row_fill));
        fill.SetCornerRadius(Dp(7));
        return fill;
    }

    private void OpenSelectedProperties()
    {
        Scene? scene = _runtimeScene;
        // S15#1: resolve deterministically (ResolveSelectedNode orders by id) and
        // surface the multi-select count, instead of FirstOrDefault over the
        // selection set picking an arbitrary node.
        SceneNode? selectedNode = ResolveSelectedNode(scene);
        _propertiesPanelBinder?.ShowSelection(selectedNode, scene, _selectedNodeIds.Count);
        SetPropertiesPanelExpanded(true);
    }

    private void HandleMeasureTap(TouchGestureEvent ev)
    {
        if (_viewport is null || _measure is null)
            return;

        global::Android.Util.Log.Info(
            "FA.Measure",
            $"Measure tap: mode={_measure.ActiveMode}, dip=({ev.Position.X:0.#},{ev.Position.Y:0.#}), viewportPx={_viewport.Width}x{_viewport.Height}, runtimeScene={(_runtimeScene is null ? "null" : "ok")}.");

        if (!TryCreateWorldRay(ev.Position, out Vector3d rayOrigin, out Vector3d rayDirection))
        {
            global::Android.Util.Log.Warn("FA.Measure", "Measure tap ignored: could not create world ray.");
            return;
        }

        float density = Resources?.DisplayMetrics?.Density ?? 1.0f;
        if (density <= 0f) density = 1.0f;
        int px = (int)(ev.Position.X * density);
        int py = (int)(ev.Position.Y * density);

        _viewport.PickAsync(px, py, "measure", hitMeshIndex =>
        {
            if (_measure is not { IsActive: true })
                return;

            int? preferredNodeId = null;
            if (hitMeshIndex is int meshIndex
                && meshIndex > 0
                && _viewport?.Renderer.Scene?.TryGetSourceNodeIdForMeshIndex(meshIndex, out int nodeId) == true)
            {
                preferredNodeId = nodeId;
            }

            global::Android.Util.Log.Info(
                "FA.Measure",
                $"Measure tap ray: origin={Format(rayOrigin)}, dir={Format(rayDirection)}, pickMesh={hitMeshIndex?.ToString() ?? "<none>"}, preferredNode={preferredNodeId?.ToString() ?? "<none>"}.");
            _measure.HandleClick(rayOrigin, rayDirection, preferredNodeId);
            RefreshMeasurementOverlays();
        });
    }

    /// <summary>
    /// Navigation pivot pick. Keep this path bounded because OrbitBegin /
    /// PanZoomBegin run on the input path; exact mesh raycasts can lazily build
    /// acceleration structures after a model opens and cause the first orbit to
    /// hitch. Measurement and section tools still use exact raycasting.
    /// </summary>
    private Vector3d? PickPivotAt(Point2D dipPos)
    {
        long startTicks = Stopwatch.GetTimestamp();
        string resultKind = "miss";
        try
        {
        if (!TryCreateWorldRay(dipPos, out Vector3d rayOrigin, out Vector3d rayDir))
            return null;

        if (_runtimeScene is null)
            return null;

        // Match the desktop fallback contract: hidden/isolate-away nodes do
        // not participate in fallback pivot selection.
        CollectVisibleBounds(_runtimeScene, out List<BoundingBox> visibleBounds, out _);
        IReadOnlyList<SectionPlane> sectionPlanes = GetActiveSectionPlanes();
        double sectionToleranceScale = _runtimeScene.Bounds.IsValid ? _runtimeScene.Bounds.Diagonal : 1.0;
        if (TryFindClosestSectionVisibleBoundsHit(
                visibleBounds,
                rayOrigin,
                rayDir,
                sectionPlanes,
                sectionToleranceScale,
                out Vector3d boundsHit))
        {
            resultKind = "runtime-bounds";
            return boundsHit;
        }

        if (_viewport?.Renderer.Scene is not { } scene)
            return null;

        double closestT = double.MaxValue;
        Vector3d? fallbackHitPoint = null;
        foreach (var mesh in scene.Meshes)
        {
            if (!mesh.Visible)
                continue;
            if (!mesh.WorldBounds.IsValid) continue;
            if (TryFindSectionVisibleBoundsHit(
                    mesh.WorldBounds,
                    rayOrigin,
                    rayDir,
                    sectionPlanes,
                    sectionToleranceScale,
                    out double t,
                    out Vector3d candidateHit)
                && t < closestT)
            {
                closestT = t;
                fallbackHitPoint = candidateHit;
            }
        }
        if (fallbackHitPoint is not null)
            resultKind = "gpu-bounds";
        return fallbackHitPoint;
        }
        finally
        {
            double elapsedMs = (Stopwatch.GetTimestamp() - startTicks) * 1000.0 / Stopwatch.Frequency;
            if (elapsedMs >= 8.0)
            {
                global::Android.Util.Log.Warn(
                    "FA.Navigation",
                    $"Pivot pick took {elapsedMs:0.0}ms via {resultKind}; exact mesh raycast skipped for navigation.");
            }
        }
    }

    private bool TryCreateWorldRay(Point2D dipPos, out Vector3d rayOrigin, out Vector3d rayDir)
    {
        rayOrigin = default;
        rayDir = default;

        if (_viewport is null || _camera is null) return false;
        CameraState? camera = SnapshotCamera();
        if (camera is null) return false;

        float density = Resources?.DisplayMetrics?.Density ?? 1.0f;
        if (density <= 0f) density = 1.0f;
        double widthDip = _viewport.Width / density;
        double heightDip = _viewport.Height / density;
        if (widthDip <= 0 || heightDip <= 0) return false;

        // NDC: (-1,-1) bottom-left, (+1,+1) top-right. Android tap Y is
        // top-down, so flip Y for the OpenGL convention.
        double nx = (dipPos.X * 2.0 / widthDip) - 1.0;
        double ny = -((dipPos.Y * 2.0 / heightDip) - 1.0);

        Vector3d position = camera.Position;
        Vector3d target = camera.Target;
        Vector3d up = camera.UpDirection.Normalized();
        Vector3d forward = (target - position).Normalized();
        if (forward.LengthSquared < 1e-12) return false;
        Vector3d right = Vector3d.Cross(forward, up).Normalized();
        if (right.LengthSquared < 1e-12) return false;
        Vector3d trueUp = Vector3d.Cross(right, forward);

        if (camera.IsPerspective)
        {
            double halfFovTan = System.Math.Tan(camera.FieldOfView * 0.5);
            double aspect = widthDip / heightDip;
            rayOrigin = position;
            rayDir = (forward + right * (nx * halfFovTan * aspect) + trueUp * (ny * halfFovTan)).Normalized();
        }
        else
        {
            double aspect = widthDip / heightDip;
            double halfW = camera.OrthoWidth * 0.5;
            double halfH = halfW / aspect;
            rayOrigin = position + right * (nx * halfW) + trueUp * (ny * halfH);
            rayDir = forward;
        }

        return true;
    }

    /// <summary>
    /// Slab-method ray vs AABB. Mirrors Core's RayBoxIntersection.TryHit
    /// (which we can't link because it lives in the Math namespace excluded
    /// from the Android shim per Plan 1's exclusions). tMin starts at 0 so
    /// AABBs entirely behind the camera are rejected; HitDistanceEpsilon
    /// prevents near-coincident origins from registering self-hits.
    /// </summary>
    private static bool TryIntersectRayAabb(Vector3d o, Vector3d d, BoundingBox box, out double t)
    {
        const double HitDistanceEpsilon = 1e-6;

        t = 0.0;
        if (!TryIntersectRayAabbInterval(o, d, box, out double tMin, out double tMax))
            return false;

        // tMin is the entry. If tMin is at-or-below epsilon the camera is
        // inside the box, in which case tMax (exit) is the meaningful hit.
        t = tMin > HitDistanceEpsilon ? tMin : tMax;
        return t > HitDistanceEpsilon && t < double.MaxValue;
    }

    private static bool TryIntersectRayAabbInterval(
        Vector3d o,
        Vector3d d,
        BoundingBox box,
        out double tMin,
        out double tMax)
    {
        const double DirectionEpsilon = 1e-12;
        const double HitDistanceEpsilon = 1e-6;

        tMin = 0.0;
        tMax = double.MaxValue;
        if (!box.IsValid) return false;

        for (int axis = 0; axis < 3; axis++)
        {
            double origin = axis == 0 ? o.X : axis == 1 ? o.Y : o.Z;
            double dir = axis == 0 ? d.X : axis == 1 ? d.Y : d.Z;
            double mn = axis == 0 ? box.Min.X : axis == 1 ? box.Min.Y : box.Min.Z;
            double mx = axis == 0 ? box.Max.X : axis == 1 ? box.Max.Y : box.Max.Z;

            if (System.Math.Abs(dir) < DirectionEpsilon)
            {
                if (origin < mn || origin > mx) return false;
                continue;
            }

            double invD = 1.0 / dir;
            double t0 = (mn - origin) * invD;
            double t1 = (mx - origin) * invD;
            if (t0 > t1) (t0, t1) = (t1, t0);

            if (t0 > tMin) tMin = t0;
            if (t1 < tMax) tMax = t1;
            if (tMax < tMin) return false;
        }

        return tMax > HitDistanceEpsilon && tMax < double.MaxValue;
    }

    private void OnPickResult(int? meshIndex)
    {
        if (_viewport is null) return;

        ClearSelectedMeasurement("model pick");

        int selected = meshIndex ?? 0;
        string? selectionLabel = null;
        SceneNode? selectedNode = null;
        int[] selectedNodeIds = Array.Empty<int>();
        if (selected > 0
            && _viewport.Renderer.Scene?.TryGetSourceNodeIdForMeshIndex(selected, out int nodeId) == true)
        {
            selectedNodeIds = [nodeId];
            selectedNode = _runtimeScene?.GetNode(nodeId);
            selectionLabel = string.IsNullOrWhiteSpace(selectedNode?.DisplayName)
                ? $"Node #{nodeId}"
                : selectedNode!.DisplayName;
        }

        ReplaceSelectedNodeIds(
            _runtimeScene,
            selectedNodeIds,
            scrollModelExplorerToSelection: true,
            fallbackRendererMeshIndices: selected > 0 ? [selected] : Array.Empty<int>());

        global::Android.Util.Log.Info(
            "FA.Measure",
            selected == 0
                ? "Selection cleared."
                : $"Selection picked: meshIndex={selected}, nodeIds=[{string.Join(",", _selectedNodeIds)}], label='{selectionLabel ?? "<mesh only>"}'.");
    }

    private void SelectNode(int nodeId)
    {
        if (_viewport is null)
            return;

        ClearSelectedMeasurement("node selection");
        ReplaceSelectedNodeIds(_runtimeScene, [nodeId], scrollModelExplorerToSelection: true);
    }

    private bool OnViewportHover(MotionEvent? motionEvent)
    {
        if (motionEvent is null || _viewport is null) return false;

        MotionEventActions action = motionEvent.ActionMasked;
        if (action != MotionEventActions.HoverEnter
            && action != MotionEventActions.HoverMove
            && action != MotionEventActions.HoverExit)
        {
            return false;
        }

        bool isStylusHover = IsStylusHoverEvent(motionEvent);
        bool isMouseHover = IsMousePointerEvent(motionEvent);
        if (!isStylusHover && !isMouseHover)
            return false;
        if (isMouseHover && !AppSettings.MouseHoverEnabled)
            return false;

        if (isStylusHover && !_stylusHoverLogged)
        {
            _stylusHoverLogged = true;
            global::Android.Util.Log.Info("FA.SPen", "Samsung S Pen/stylus hover input detected.");
        }

        if (action == MotionEventActions.HoverExit)
        {
            ClearSpenPalmGuard();
            _stylusSecondaryContextActive = false;
            global::Android.Util.Log.Debug("FA.Measure", "Measure hover exit.");
            _measure?.ClearHover();
            _measure?.HoverMeasurement(null);
            _sectionHoverPoint = null;
            _sectionGizmoHovered = GlesTransformGizmoHandle.None;
            if (_bodyMoveGizmoActive == GlesTransformGizmoHandle.None)
                _bodyMoveGizmoHovered = GlesTransformGizmoHandle.None;
            _hoveredSectionPlaneId = null;
            UpdateBodyMoveGizmoRendererState();
            UpdateSectionRendererState();
            RefreshMeasurementOverlays();
            CancelHoverPick();
            SetHoveredMesh(0);
            return true;
        }

        if (HandleAnnotationHover(motionEvent))
            return true;

        bool secondaryButtonPressed = IsViewportSecondaryButtonPressed(motionEvent);
        if (!secondaryButtonPressed)
        {
            _stylusSecondaryContextActive = false;
        }
        else if (isStylusHover
                 && _activeModalTool == AndroidModalTool.Select
                 && _measure is not { IsActive: true })
        {
            if (!_stylusSecondaryContextActive)
            {
                _stylusSecondaryContextActive = true;
                CancelHoverPick();
                SetHoveredMesh(0);
                var dip = MotionEventToDip(motionEvent);
                HandleViewportContextRequest(new TouchGestureEvent(TouchGestureKind.SecondaryTap, dip, Vector2D.Zero, 1.0));
            }

            return true;
        }

        if (_activeModalTool == AndroidModalTool.BodyMove
            && _bodyMoveGizmoActive == GlesTransformGizmoHandle.None
            && !_bodyMoveGizmoInputOpen)
        {
            CancelHoverPick();
            SetHoveredMesh(0);
            var dip = MotionEventToDip(motionEvent);
            SetBodyMoveGizmoHovered(PickBodyMoveGizmoHandle(dip));
            return true;
        }

        if (CanSelectSectionPlanes()
            && _sectionGizmoActive == GlesTransformGizmoHandle.None
            && !_sectionGizmoInputOpen)
        {
            CancelHoverPick();
            SetHoveredMesh(0);
            var dip = MotionEventToDip(motionEvent);
            GlesTransformGizmoHandle hoveredHandle = PickSectionGizmoHandle(dip);
            SetSectionGizmoHovered(hoveredHandle);
            if (hoveredHandle != GlesTransformGizmoHandle.None)
            {
                SetHoveredSectionPlane(null);
                return true;
            }

            if (PickSectionPlaneEdge(dip) is { } hoveredSection)
            {
                SetHoveredSectionPlane(hoveredSection);
                return true;
            }

            SetHoveredSectionPlane(null);
        }

        if (_activeModalTool == AndroidModalTool.Section && _activeSectionSubMode != SectionSubMode.None)
        {
            CancelHoverPick();
            SetHoveredMesh(0);
            SetHoveredSectionPlane(null);
            HandleSectionHover(motionEvent);
            return true;
        }

        if (_measure is { IsActive: true })
        {
            CancelHoverPick();
            SetHoveredMesh(0);
            SetHoveredMeasurementLabel(null);

            float density = Resources?.DisplayMetrics?.Density ?? 1.0f;
            if (density <= 0f) density = 1.0f;
            var dip = new Point2D(motionEvent.GetX() / density, motionEvent.GetY() / density);
            if (TryCreateWorldRay(dip, out Vector3d rayOrigin, out Vector3d rayDirection))
            {
                _measure.HandleHover(rayOrigin, rayDirection);
            }
            else
            {
                global::Android.Util.Log.Warn("FA.Measure", "Measure hover ignored: could not create world ray.");
                _measure.ClearHover();
            }

            return true;
        }

        if (!CanPickViewportModelBodies())
        {
            CancelHoverPick();
            SetHoveredMesh(0);
            SetHoveredMeasurementLabel(null);
            return true;
        }

        if (TryHoverMeasurementLabel(motionEvent.GetX(), motionEvent.GetY()))
        {
            CancelHoverPick();
            SetHoveredMesh(0);
            return true;
        }

        QueueHoverPick((int)motionEvent.GetX(), (int)motionEvent.GetY());
        return true;
    }

    private static bool IsViewportSecondaryButtonPressed(MotionEvent motionEvent)
        => motionEvent.IsButtonPressed(MotionEventButtonState.Secondary)
            || motionEvent.IsButtonPressed(MotionEventButtonState.StylusPrimary)
            || motionEvent.IsButtonPressed(MotionEventButtonState.StylusSecondary);

    private void HandleSectionHover(MotionEvent motionEvent)
    {
        float density = Resources?.DisplayMetrics?.Density ?? 1.0f;
        if (density <= 0f) density = 1.0f;
        var dip = new Point2D(motionEvent.GetX() / density, motionEvent.GetY() / density);
        Vector3d? hover = null;
        if (TryCreateWorldRay(dip, out Vector3d rayOrigin, out Vector3d rayDirection))
            hover = PickSectionPoint(rayOrigin, rayDirection, snapped: _activeSectionSubMode == SectionSubMode.Custom);

        if (SamePoint(_sectionHoverPoint, hover))
            return;

        _sectionHoverPoint = hover;
        UpdateSectionRendererState();
    }

    private static bool SamePoint(Vector3d? a, Vector3d? b)
    {
        if (!a.HasValue || !b.HasValue)
            return a.HasValue == b.HasValue;

        return (a.Value - b.Value).LengthSquared < 1e-8;
    }

    private void QueueHoverPick(int x, int y)
    {
        if (_viewport is null) return;

        _pendingHoverPickX = x;
        _pendingHoverPickY = y;
        _pendingHoverPickVersion++;
        if (_hoverPickInFlight)
            return;

        StartNextHoverPick();
    }

    private void StartNextHoverPick()
    {
        if (_viewport is null || _pendingHoverPickX < 0 || _pendingHoverPickY < 0)
        {
            _hoverPickInFlight = false;
            return;
        }

        int x = _pendingHoverPickX;
        int y = _pendingHoverPickY;
        _pendingHoverPickX = -1;
        _pendingHoverPickY = -1;
        _hoverPickInFlight = true;
        int session = _hoverSessionVersion;
        int pickVersion = _pendingHoverPickVersion;

        _viewport.PickAsync(x, y, "hover", hit => OnHoverPickResult(session, pickVersion, hit));
    }

    private void OnHoverPickResult(int session, int pickVersion, int? meshIndex)
    {
        if (session != _hoverSessionVersion)
            return;

        _hoverPickInFlight = false;
        if (!CanPickViewportModelBodies())
        {
            SetHoveredMesh(0);
            return;
        }

        // Always apply the pick result: the prior dedup ("only accept when
        // no newer event is queued") was discarding correct results during
        // continuous motion because each pick takes longer than the gap
        // between motion events. The next chained pick will overwrite this
        // value if the cursor has moved to a different mesh in the meantime,
        // so transient flicker is bounded by one pick cycle.
        SetHoveredMesh(meshIndex ?? 0);
        if (_pendingHoverPickX >= 0 && _pendingHoverPickY >= 0)
            StartNextHoverPick();
    }

    private void CancelHoverPick()
    {
        _hoverSessionVersion++;
        _pendingHoverPickVersion++;
        _hoverPickInFlight = false;
        _pendingHoverPickX = -1;
        _pendingHoverPickY = -1;
    }

    private void SetHoveredMesh(int meshIndex)
    {
        if (_viewport is null) return;
        if (_viewport.Renderer.HoveredMeshIndex == meshIndex)
            return;

        _viewport.Renderer.HoveredMeshIndex = meshIndex;
        _viewport.RequestRender();
    }

    private static bool IsStylusHoverEvent(MotionEvent motionEvent)
    {
        int count = motionEvent.PointerCount;
        for (int i = 0; i < count; i++)
        {
            MotionEventToolType toolType = motionEvent.GetToolType(i);
            if (IsStylusOrEraser(toolType))
            {
                return true;
            }
        }

        return false;
    }

    private static bool IsStylusOrMousePointer(MotionEvent motionEvent)
    {
        if ((motionEvent.Source & InputSourceType.Mouse) == InputSourceType.Mouse)
            return true;

        int pointerIndex = motionEvent.ActionIndex;
        if (pointerIndex < 0 || pointerIndex >= motionEvent.PointerCount)
            pointerIndex = 0;

        MotionEventToolType toolType = motionEvent.GetToolType(pointerIndex);
        return IsStylusOrEraser(toolType) || toolType == MotionEventToolType.Mouse;
    }

    private static bool IsPrimaryMouseButtonPress(MotionEvent motionEvent)
        => IsMousePointerEvent(motionEvent)
           && motionEvent.ActionMasked == MotionEventActions.ButtonPress
           && (IsActionButton(motionEvent, MotionEventButtonState.Primary)
               || IsPrimaryButtonPressed(motionEvent));

    private static bool IsPrimaryMouseButtonRelease(MotionEvent motionEvent)
        => IsMousePointerEvent(motionEvent)
           && motionEvent.ActionMasked == MotionEventActions.ButtonRelease
           && (IsActionButton(motionEvent, MotionEventButtonState.Primary)
               || (((MotionEventButtonState)motionEvent.ActionButton) == 0
                   && !IsPrimaryButtonPressed(motionEvent)));

    private void TrackMouseTouchDispatch(MotionEvent? motionEvent)
    {
        if (motionEvent is null || !IsMousePointerEvent(motionEvent))
            return;

        switch (motionEvent.ActionMasked)
        {
            case MotionEventActions.Down:
                if (IsPrimaryButtonPressed(motionEvent))
                {
                    _lastMouseTouchDownTime = motionEvent.DownTime;
                    ClearGenericMousePressIfDownTimeMatches(motionEvent.DownTime);
                }
                break;

            case MotionEventActions.Up:
            case MotionEventActions.PointerUp:
                _lastMouseTouchUpDownTime = motionEvent.DownTime;
                ClearGenericMousePressIfDownTimeMatches(motionEvent.DownTime);
                break;

            case MotionEventActions.Cancel:
                ClearGenericMousePress();
                break;
        }
    }

    private bool HandleUnhandledMouseClick(MotionEvent? motionEvent)
    {
        if (motionEvent is null || !IsMousePointerEvent(motionEvent))
            return false;

        return motionEvent.ActionMasked switch
        {
            MotionEventActions.ButtonPress => HandleUnhandledMouseButtonPress(motionEvent),
            MotionEventActions.ButtonRelease => HandleUnhandledMouseButtonRelease(motionEvent),
            MotionEventActions.Cancel => ClearGenericMousePressHandled(),
            _ => false,
        };
    }

    private bool HandleUnhandledMouseButtonPress(MotionEvent motionEvent)
    {
        if (!IsActionButton(motionEvent, MotionEventButtonState.Primary)
            && !IsPrimaryButtonPressed(motionEvent))
        {
            return false;
        }

        View? target = FindClickableViewAtMousePosition(motionEvent);
        if (target is null)
            return false;

        ClearGenericMousePress();
        _genericMousePressedView = target;
        _genericMousePressedDownTime = motionEvent.DownTime;
        _genericMousePressedRawX = motionEvent.RawX;
        _genericMousePressedRawY = motionEvent.RawY;
        target.Pressed = true;
        return true;
    }

    private bool HandleUnhandledMouseButtonRelease(MotionEvent motionEvent)
    {
        if (_genericMousePressedView is not { } pressedView)
            return false;

        bool shouldPerformClick = IsActionButton(motionEvent, MotionEventButtonState.Primary)
                                  && _genericMousePressedDownTime != _lastMouseTouchDownTime
                                  && _genericMousePressedDownTime != _lastMouseTouchUpDownTime
                                  && IsScreenPointInsideView(pressedView, motionEvent.RawX, motionEvent.RawY)
                                  && IsWithinMouseClickSlop(motionEvent.RawX, motionEvent.RawY);
        ClearGenericMousePress();
        if (!shouldPerformClick)
            return true;

        pressedView.PerformClick();
        return true;
    }

    private void ClearGenericMousePressIfDownTimeMatches(long downTime)
    {
        if (_genericMousePressedDownTime == downTime)
            ClearGenericMousePress();
    }

    private bool ClearGenericMousePressHandled()
    {
        bool hadPress = _genericMousePressedView is not null;
        ClearGenericMousePress();
        return hadPress;
    }

    private void ClearGenericMousePress()
    {
        if (_genericMousePressedView is { } pressedView)
            pressedView.Pressed = false;

        _genericMousePressedView = null;
        _genericMousePressedDownTime = -1;
        _genericMousePressedRawX = 0f;
        _genericMousePressedRawY = 0f;
    }

    private View? FindClickableViewAtMousePosition(MotionEvent motionEvent)
    {
        View? root = Window?.DecorView;
        if (root is null)
            return null;

        return FindClickableViewAtScreenPoint(root, motionEvent.RawX, motionEvent.RawY);
    }

    private static View? FindClickableViewAtScreenPoint(View view, float rawX, float rawY)
    {
        if (!IsScreenPointInsideView(view, rawX, rawY))
            return null;

        if (view is ViewGroup group)
        {
            for (int i = group.ChildCount - 1; i >= 0; i--)
            {
                View? child = group.GetChildAt(i);
                if (child is null || child.Visibility != ViewStates.Visible)
                    continue;

                View? hit = FindClickableViewAtScreenPoint(child, rawX, rawY);
                if (hit is not null)
                    return hit;
            }
        }

        return IsMouseClickTarget(view) ? view : null;
    }

    private static bool IsMouseClickTarget(View view)
        => view.Visibility == ViewStates.Visible
           && view.Enabled
           && view.Clickable;

    private static bool IsScreenPointInsideView(View view, float rawX, float rawY)
    {
        var rect = new Rect();
        if (!view.GetGlobalVisibleRect(rect))
            return false;

        return rect.Contains((int)MathF.Floor(rawX), (int)MathF.Floor(rawY));
    }

    private bool IsWithinMouseClickSlop(float rawX, float rawY)
    {
        int slop = ViewConfiguration.Get(this)?.ScaledTouchSlop ?? Dp(8);
        float dx = rawX - _genericMousePressedRawX;
        float dy = rawY - _genericMousePressedRawY;
        return dx * dx + dy * dy <= slop * slop;
    }

    private static bool IsMousePointerEvent(MotionEvent motionEvent)
    {
        if ((motionEvent.Source & InputSourceType.Mouse) == InputSourceType.Mouse)
            return true;

        int count = motionEvent.PointerCount;
        for (int i = 0; i < count; i++)
        {
            if (motionEvent.GetToolType(i) == MotionEventToolType.Mouse)
                return true;
        }

        return false;
    }

    private static bool IsPrimaryButtonPressed(MotionEvent motionEvent)
        => motionEvent.IsButtonPressed(MotionEventButtonState.Primary);

    private static bool IsActionButton(MotionEvent motionEvent, MotionEventButtonState button)
        => (((MotionEventButtonState)motionEvent.ActionButton) & button) == button;

    private async void OnOpenClicked(object? sender, EventArgs e)
    {
        if (_picker is null || _import is null || _viewport is null || _camera is null) return;
        if (IsImportUiBusy()) return;

        SetLeftToolPanelExpanded(false, animate: true);

        AndroidUri? uri;
        _openPickerInFlight = true;
        SetImportNavigationEnabled(false);
        try
        {
            uri = await _picker.PickAsync(new[] { "model/gltf-binary", "model/gltf+json", "application/zip", "application/octet-stream", "*/*" });
        }
        catch (System.OperationCanceledException)
        {
            SetImportNavigationEnabled(true);
            return;
        }
        catch (Exception ex)
        {
            SetImportNavigationEnabled(true);
            ShowError("Could not open file picker", ex.Message);
            return;
        }
        finally
        {
            _openPickerInFlight = false;
        }
        if (uri is null)
        {
            SetImportNavigationEnabled(true);
            return;
        }

        RecentFilesStore.TryTakePersistableReadWritePermission(this, uri);
        await OpenModelUriAsync(uri);
    }

    private async Task<bool> OpenModelUriAsync(
        AndroidUri uri,
        Action<Exception>? onImportError = null,
        bool replaceActiveLoad = true,
        bool addToRecent = true,
        string? displayNameOverride = null,
        bool persistForRestore = true,
        bool copyToImportCache = true,
        int presentationFrameCount = 1)
    {
        if (_import is null || _viewport is null || _camera is null)
            return false;

        if (addToRecent)
            await CloseActiveCloudSessionAsync("opening local model").ConfigureAwait(true);

        var cts = new CancellationTokenSource();
        int loadVersion;
        if (replaceActiveLoad)
        {
            loadVersion = BeginReplacingActiveLoad(cts, out CancellationTokenSource? previousLoad);
            previousLoad?.Cancel();
        }
        else if (!TryBeginExclusiveLoad(cts, out loadVersion))
        {
            cts.Dispose();
            return false;
        }

        string? errorMessage = null;
        bool loaded = false;
        bool loadSlotAcquired = false;

        ShowLoading("Preparing model...");

        try
        {
            await _loadSemaphore.WaitAsync(cts.Token);
            loadSlotAcquired = true;
            cts.Token.ThrowIfCancellationRequested();
            if (!IsCurrentLoad(loadVersion, cts)) return false;

            var progress = new Progress<string>(message =>
            {
                if (IsCurrentLoad(loadVersion, cts))
                    UpdateLoadingDetail(message);
            });

            // S3#2: ImportAsync's synchronous prelude (ContentResolver Query /
            // GetType / OpenInputStream metadata + size resolution) runs blocking
            // binder IPC before its first real await. Hop onto a worker thread so
            // a slow cloud-provider URI cannot jank the UI right after file pick.
            // The Progress<string> still marshals reports back to the UI thread,
            // and this await resumes on the UI thread for the rest of the load.
            var document = await Task.Run(
                () => _import.ImportAsync(uri, progress, cts.Token, copyToImportCache),
                cts.Token);
            cts.Token.ThrowIfCancellationRequested();
            if (!IsCurrentLoad(loadVersion, cts)) return false;
            string modelDisplayName = string.IsNullOrWhiteSpace(displayNameOverride)
                ? ResolveModelDisplayName(uri, document)
                : displayNameOverride;
            Vector3d preferredUp = GetPreferredUpDirectionForModelName(modelDisplayName);
            Scene? runtimeScene = TryCreateRuntimeScene(document);
            if (runtimeScene is not null)
                runtimeScene.FilePath = modelDisplayName;

            UpdateLoadingDetail("Preparing GPU resources...");
            BoundingBox bounds = await LoadDocumentOnRendererAsync(document, cts.Token, () => IsCurrentLoad(loadVersion, cts));
            cts.Token.ThrowIfCancellationRequested();
            if (!IsCurrentLoad(loadVersion, cts)) return false;

            _activeModelDisplayName = modelDisplayName;
            UpdateAppTitle();
            if (!IsCurrentLoad(loadVersion, cts)) return false;
            AttachRuntimeScene(runtimeScene);
            bool restoredFromArchive = await ApplyViewerStateFromArchiveAsync(document, runtimeScene, cts.Token).ConfigureAwait(true);
            bool restoredCamera = restoredFromArchive || TryRestorePendingCameraState(bounds);
            if (!restoredCamera)
            {
                lock (_camera)
                    FrameCameraToBounds(_camera, bounds, GetViewportAspect(), preferredUp);
            }
            RestorePendingSelectionState(runtimeScene);
            RestorePendingExplodeState();
            ApplySettingsToScene();
            await WaitForPresentedModelFramesAsync(Math.Max(1, presentationFrameCount), cts.Token);
            cts.Token.ThrowIfCancellationRequested();
            if (!IsCurrentLoad(loadVersion, cts)) return false;

            UpdateLoadingDetail("Model ready");
            if (addToRecent)
            {
                // Recording a recent file probes existing entries' access via
                // blocking ContentResolver round-trips (up to the 5s per-entry
                // timeout for offline/cloud URIs). Run off the UI thread so a
                // slow entry can't jank the just-finished load; the store's
                // static Gate lock serializes it against the panel's load.
                var recentContext = ApplicationContext!;
                var recentUri = uri;
                _ = Task.Run(() =>
                {
                    try
                    {
                        RecentFilesStore.Add(recentContext, recentUri);
                    }
                    catch (Exception ex)
                    {
                        global::Android.Util.Log.Warn("FA.Recent", "Failed to record recent file: " + ex.Message);
                    }
                });
            }
            _lastLoadedUriText = persistForRestore ? uri.ToString() : null;
            _currentLocalSaveUri = addToRecent ? uri : null;
            _lastLoadedDocument = document;
            _lastLoadedDocumentReleasedForMemoryPressure = false;
            loaded = true;
            UpdateSaveButton();
        }
        catch (System.OperationCanceledException) when (cts.IsCancellationRequested)
        {
            // Newer load requests and explicit cancels should not show an error.
        }
        catch (Exception ex)
        {
            onImportError?.Invoke(ex);
            if (IsCurrentLoad(loadVersion, cts))
                errorMessage = IsFileAccessRevoked(ex)
                    ? "File no longer accessible. Re-open it from storage to grant access again."
                    : ex.Message;
        }
        finally
        {
            if (loadSlotAcquired)
                _loadSemaphore.Release();

            ClearActiveLoad(cts);

            cts.Dispose();

            if (!_isDestroyed && loadVersion == Volatile.Read(ref _loadVersion))
            {
                HideLoading();
                UpdateSaveButton();
            }
        }

        if (errorMessage is not null && !_isDestroyed)
            ShowError("Import failed", errorMessage);

        return loaded;
    }

    private async Task WaitForPresentedModelFramesAsync(int frameCount, CancellationToken ct)
    {
        if (_viewport is null)
            return;

        UpdateLoadingDetail(frameCount > 1 ? "Rendering model..." : "Rendering first frame...");
        using var firstFrameTimeout = CancellationTokenSource.CreateLinkedTokenSource(ct);
        firstFrameTimeout.CancelAfter(TimeSpan.FromSeconds(frameCount > 1 ? 45 : 3));
        try
        {
            for (int i = 0; i < frameCount; i++)
                await _viewport.WaitForNextRenderedFrameAsync(firstFrameTimeout.Token);
        }
        catch (System.OperationCanceledException) when (!ct.IsCancellationRequested && firstFrameTimeout.IsCancellationRequested)
        {
            global::Android.Util.Log.Warn(
                "FA.Import",
                frameCount > 1
                    ? "Timed out waiting for model presentation frames; continuing because the model load completed."
                    : "Timed out waiting for the first rendered frame; continuing because the model load completed.");
        }
    }

    private async Task PresentLoadingOverlayBeforeWorkAsync(CancellationToken ct)
    {
        await RunOnUiThreadAsync(() =>
        {
            if (_loadingOverlay is null)
                return;

            _loadingOverlay.BringToFront();
            _loadingOverlay.Invalidate();
        }).ConfigureAwait(true);

        // Give the Android UI/compositor one short turn to draw the overlay
        // before cloud close/download/import work starts.
        await Task.Delay(120, ct).ConfigureAwait(true);
    }

    private Task<BoundingBox> LoadDocumentOnRendererAsync(DocumentDto document, CancellationToken ct, Func<bool>? shouldAttach = null)
    {
        if (_viewport is null)
            throw new ObjectDisposedException(nameof(ViewportSurfaceView));

        var viewport = _viewport;
        var tcs = new TaskCompletionSource<BoundingBox>(TaskCreationOptions.RunContinuationsAsynchronously);
        var registration = ct.Register(() => tcs.TrySetCanceled(ct));

        bool queued = viewport.QueueRendererCommand("load-document", gl =>
        {
            GpuScene? newScene = null;
            try
            {
                if (ct.IsCancellationRequested || shouldAttach?.Invoke() == false)
                {
                    tcs.TrySetCanceled(ct);
                    return;
                }

                newScene = new GpuScene(gl);
                newScene.Load(document);
                if (ct.IsCancellationRequested || shouldAttach?.Invoke() == false)
                {
                    tcs.TrySetCanceled(ct);
                    return;
                }

                BoundingBox bounds = newScene.Bounds;
                var renderer = viewport.Renderer;
                var oldScene = renderer.Scene;
                renderer.Scene = newScene;
                newScene = null;
                renderer.SelectedMeshIndex = 0;
                renderer.SelectedMeshIndices = Array.Empty<int>();
                renderer.HoveredMeshIndex = 0;

                try
                {
                    oldScene?.Dispose();
                }
                catch (Exception disposeEx)
                {
                    global::Android.Util.Log.Warn("FA.Import", "Failed to dispose previous GPU scene: " + disposeEx.Message);
                }

                tcs.TrySetResult(bounds);
            }
            catch (Exception ex)
            {
                tcs.TrySetException(ex);
            }
            finally
            {
                try { newScene?.Dispose(); }
                catch (Exception disposeEx)
                {
                    global::Android.Util.Log.Warn("FA.Import", "Failed to dispose partial GPU scene: " + disposeEx.Message);
                }
            }
        });
        if (!queued)
        {
            registration.Dispose();
            return Task.FromException<BoundingBox>(new ObjectDisposedException(nameof(ViewportSurfaceView)));
        }

        return CompleteRendererLoadAsync(tcs.Task, registration);
    }

    private static async Task<BoundingBox> CompleteRendererLoadAsync(
        Task<BoundingBox> task,
        CancellationTokenRegistration registration)
    {
        try
        {
            return await task;
        }
        finally
        {
            registration.Dispose();
        }
    }

    private Scene? TryCreateRuntimeScene(DocumentDto document)
    {
        if (document.Nodes.Count == 0)
        {
            global::Android.Util.Log.Warn("FA.Measure", "Measurement disabled for this import because the document has no scene nodes.");
            return null;
        }

        try
        {
            global::Android.Util.Log.Info(
                "FA.Measure",
                $"Runtime scene build begin: documentNodes={document.Nodes.Count}, documentMeshes={document.Meshes.Count}, units='{document.Stats?.UnitSystem ?? "<null>"}'.");
            return Scene.FromDocument(document);
        }
        catch (Exception ex) when (ex is not OutOfMemoryException and not StackOverflowException)
        {
            global::Android.Util.Log.Warn(
                "FA.Measure",
                Java.Lang.Throwable.FromException(ex),
                "Measurement scene graph creation failed: " + ex.Message);
            return null;
        }
    }

    private string ResolveModelDisplayName(AndroidUri uri, DocumentDto document)
    {
        string? displayName = TryResolveDisplayName(uri);
        if (!string.IsNullOrWhiteSpace(displayName))
            return displayName;

        if (!string.IsNullOrWhiteSpace(document.PackageInfo?.SourceName))
            return NormalizeImportedSourceName(document.PackageInfo.SourceName);

        return uri.LastPathSegment ?? uri.ToString() ?? "model";
    }

    private static string NormalizeImportedSourceName(string sourceName)
    {
        string fileName = System.IO.Path.GetFileName(sourceName);
        if (string.IsNullOrWhiteSpace(fileName))
            return sourceName;

        Match match = ImportCacheDisplayNamePattern.Match(fileName);
        return match.Success
            ? match.Groups["stem"].Value + match.Groups["extension"].Value
            : fileName;
    }

    private string? TryResolveDisplayName(AndroidUri uri)
    {
        try
        {
            using var cursor = ContentResolver?.Query(uri, null, null, null, null);
            if (cursor is null || !cursor.MoveToFirst())
                return null;

            int index = cursor.GetColumnIndex(IOpenableColumns.DisplayName);
            string? value = index >= 0 ? cursor.GetString(index) : null;
            return string.IsNullOrWhiteSpace(value) ? null : value;
        }
        catch
        {
            return null;
        }
    }

    private static bool IsCloudTempUriText(string uriText)
        => uriText.Contains("/fa-cloud-open/", StringComparison.OrdinalIgnoreCase)
           || uriText.Contains("\\fa-cloud-open\\", StringComparison.OrdinalIgnoreCase);

    private Vector3d GetPreferredUpDirectionForCurrentScene()
        => GetPreferredUpDirectionForModelName(
            _runtimeScene?.FilePath
            ?? _activeModelDisplayName
            ?? _lastLoadedUriText);

    private static Vector3d GetPreferredUpDirectionForModelName(string? modelName)
    {
        if (string.IsNullOrWhiteSpace(modelName))
            return Vector3d.UnitZ;

        string extension;
        try
        {
            extension = System.IO.Path.GetExtension(modelName);
        }
        catch
        {
            extension = string.Empty;
        }

        return extension.Equals(".glb", StringComparison.OrdinalIgnoreCase)
               || extension.Equals(".gltf", StringComparison.OrdinalIgnoreCase)
            ? Vector3d.UnitY
            : Vector3d.UnitZ;
    }

    private bool TryRestorePendingCameraState(BoundingBox bounds)
    {
        if (_pendingRestoredCamera is not { Length: >= 17 } values || _camera is null)
            return false;

        _pendingRestoredCamera = null;
        if (!TryReadCameraVector(values, 0, requireNonZero: false, out Vector3d position)
            || !TryReadCameraVector(values, 3, requireNonZero: false, out Vector3d target)
            || !TryReadCameraVector(values, 6, requireNonZero: true, out Vector3d up)
            || !TryReadCameraVector(values, 9, requireNonZero: true, out Vector3d worldUp)
            || !double.IsFinite(values[12])
            || !double.IsFinite(values[13])
            || !double.IsFinite(values[14])
            || !double.IsFinite(values[15]))
        {
            global::Android.Util.Log.Warn("FA.Camera", "Ignored invalid restored camera state.");
            return false;
        }
        if ((position - target).LengthSquared <= 1e-18)
        {
            global::Android.Util.Log.Warn("FA.Camera", "Ignored restored camera state with degenerate eye/target.");
            return false;
        }

        double fov = Math.Clamp(values[12], Math.PI / 180.0, Math.PI * 170.0 / 180.0);
        double orthoWidth = Math.Max(values[13], 1e-6);
        double nearPlane = Math.Max(values[14], 1e-6);
        double farPlane = Math.Max(values[15], nearPlane + 1e-3);
        bool isPerspective = values[16] >= 0.5;

        lock (_camera)
        {
            _camera.Position = position;
            _camera.Target = target;
            _camera.UpDirection = up;
            _camera.WorldUpDirection = worldUp;
            _camera.FieldOfView = fov;
            _camera.OrthoWidth = orthoWidth;
            _camera.NearPlane = nearPlane;
            _camera.FarPlane = farPlane;
            _camera.IsPerspective = isPerspective;
            BoundingBox clipBounds = AndroidCameraClipPlanes.IncludeGroundGrid(
                bounds,
                AppSettings.ShowGrid,
                AppSettings.ShiftGridToModelMin);
            if (clipBounds.IsValid)
                AndroidCameraClipPlanes.Update(_camera, clipBounds);
        }

        _isInFixedView = false;
        _activeFixedView = null;
        _isoIsPerspective = isPerspective;
        SetRendererProjectionAppearance(isPerspective);
        _viewport?.RequestRender();
        global::Android.Util.Log.Info("FA.Camera", "Restored camera state after activity recreation.");
        return true;
    }

    private static bool TryReadCameraVector(double[] values, int start, bool requireNonZero, out Vector3d value)
    {
        value = default;
        if (values.Length <= start + 2
            || !double.IsFinite(values[start])
            || !double.IsFinite(values[start + 1])
            || !double.IsFinite(values[start + 2]))
        {
            return false;
        }

        value = new Vector3d(values[start], values[start + 1], values[start + 2]);
        return IsFinite(value) && (!requireNonZero || value.LengthSquared > 1e-24);
    }

    private void RestorePendingSelectionState(Scene? scene)
    {
        if (scene is null)
        {
            _pendingRestoredSelectedNodeIds = null;
            _pendingRestoredSelectedOccurrences = null;
            return;
        }

        int[] nodeIds = Array.Empty<int>();
        if (AndroidScenePackageState.IsFa(scene.PackageInfo)
            && _pendingRestoredSelectedOccurrences is { Length: > 0 } occurrences)
        {
            string[] normalized = AndroidScenePackageState.NormalizeOccurrenceIds(occurrences);
            _packageSession?.SetSelection(normalized);
            nodeIds = AndroidScenePackageState.GetNodeIdsForOccurrences(scene, normalized);
        }
        else if (_pendingRestoredSelectedNodeIds is { Length: > 0 } selectedNodeIds)
        {
            nodeIds = selectedNodeIds
                .Where(nodeId => scene.GetNode(nodeId) is not null)
                .Distinct()
                .OrderBy(nodeId => nodeId)
                .ToArray();
        }

        _pendingRestoredSelectedNodeIds = null;
        _pendingRestoredSelectedOccurrences = null;
        if (nodeIds.Length == 0)
            return;

        ReplaceSelectedNodeIds(scene, nodeIds, scrollModelExplorerToSelection: true);
        global::Android.Util.Log.Info("FA.Selection", $"Restored selection after activity recreation: nodes=[{string.Join(",", _selectedNodeIds)}].");
    }

    private void RestorePendingExplodeState()
    {
        if (_pendingRestoredExplodeAmount is not { } amount)
            return;

        _pendingRestoredExplodeAmount = null;
        if (amount <= 0.0 || !CanUseExplodeView())
            return;

        SetExplodeAmount(amount, "activity recreation");
    }

    private async Task<bool> ApplyViewerStateFromArchiveAsync(
        DocumentDto document,
        Scene? scene,
        CancellationToken ct)
    {
        string? archivePath = document.PackageInfo?.ArchiveFilePath;
        if (scene is null
            || !AndroidScenePackageState.IsFa(document.PackageInfo)
            || string.IsNullOrWhiteSpace(archivePath)
            || !File.Exists(archivePath))
        {
            return false;
        }

        FaViewerStatePayload payload;
        try
        {
            payload = await FaViewerStateReader.ReadAsync(archivePath, ct).ConfigureAwait(false);
        }
        catch (Exception ex) when (ex is not System.OperationCanceledException)
        {
            global::Android.Util.Log.Warn("FA.Save", "Could not read viewer state: " + ex.GetBaseException().Message);
            return false;
        }

        bool cameraApplied = false;
        await RunOnUiThreadAsync(() =>
        {
            ct.ThrowIfCancellationRequested();
            if (payload.Visibility is not null)
                ApplyViewerVisibility(scene, payload.Visibility);
            if (payload.Sections is not null)
                ApplyViewerSections(payload.Sections);
            if (payload.Measurements is not null)
                ApplyViewerMeasurements(payload.Measurements);
            if (payload.Camera is not null)
                cameraApplied = ApplyViewerCamera(payload.Camera);

            if (payload.Visibility is not null)
            {
                SyncRuntimeSceneVisibilityToRenderer("viewer state load");
                RefreshSelectionDependentUi(scene, scrollModelExplorerToSelection: true, requestRender: false);
            }

            if (payload.Sections is not null)
                UpdateSectionRendererState();
            if (payload.Measurements is not null)
                RefreshMeasurementOverlays();

            if (payload.Visibility is not null || payload.Sections is not null || payload.Measurements is not null || cameraApplied)
                _viewport?.RequestRender();
        }).ConfigureAwait(false);

        return cameraApplied;
    }

    private bool ApplyViewerCamera(ViewerCameraDto dto)
    {
        if (_camera is null
            || !IsFiniteVector(dto.Position)
            || !IsFiniteVector(dto.Target)
            || !IsFiniteVector(dto.Up, requireNonZero: true)
            || !IsFiniteVector(dto.WorldUp, requireNonZero: true)
            || !double.IsFinite(dto.FieldOfViewRadians)
            || dto.FieldOfViewRadians <= 0.0
            || dto.FieldOfViewRadians >= Math.PI
            || !double.IsFinite(dto.Near)
            || !double.IsFinite(dto.Far)
            || dto.Near <= 0.0
            || dto.Far <= dto.Near
            || !double.IsFinite(dto.OrthoWidth)
            || dto.OrthoWidth <= 0.0)
        {
            return false;
        }

        lock (_camera)
        {
            _camera.Position = ToVector3d(dto.Position);
            _camera.Target = ToVector3d(dto.Target);
            _camera.UpDirection = ToVector3d(dto.Up);
            _camera.WorldUpDirection = ToVector3d(dto.WorldUp);
            _camera.FieldOfView = dto.FieldOfViewRadians;
            _camera.NearPlane = dto.Near;
            _camera.FarPlane = dto.Far;
            _camera.IsPerspective = dto.IsPerspective;
            _camera.OrthoWidth = dto.OrthoWidth;
        }

        _isInFixedView = false;
        _activeFixedView = null;
        _isoIsPerspective = dto.IsPerspective;
        SetRendererProjectionAppearance(dto.IsPerspective);
        UpdateViewPresetButtonStates();

        return true;
    }

    private void ApplyViewerVisibility(Scene scene, ViewerVisibilityDto dto)
    {
        if (_packageSession is null || !AndroidScenePackageState.IsFa(scene.PackageInfo))
            return;

        string[] hidden = AndroidScenePackageState.NormalizeOccurrenceIds(dto.HiddenOccurrenceIds ?? []);
        string[] isolated = AndroidScenePackageState.NormalizeOccurrenceIds(dto.IsolatedOccurrenceIds ?? []);
        string[] selected = AndroidScenePackageState.NormalizeOccurrenceIds(dto.SelectedOccurrenceIds ?? []);
        _packageSession.SetVisibility(hidden, isolated);
        _packageSession.SetSelection(selected);
        if (dto.ExpandedNodeIds is { Count: > 0 })
            _packageSession.SetExpandedPresentedNodes(dto.ExpandedNodeIds);
        AndroidScenePackageState.ApplyVisibilityToScene(scene, _packageSession);

        int[] selectedNodeIds = selected.Length == 0
            ? Array.Empty<int>()
            : AndroidScenePackageState.GetNodeIdsForOccurrences(scene, selected);
        ReplaceSelectedNodeIds(scene, selectedNodeIds, scrollModelExplorerToSelection: true, requestRender: false);
    }

    private void ApplyViewerSections(ViewerSectionsDto dto)
    {
        if (_sections is null)
            return;

        var snapshots = new List<SectionPlaneSnapshot>();
        foreach (ViewerSectionPlaneDto plane in dto.Planes ?? [])
        {
            if (TryBuildSectionPlane(plane, out SectionPlane sectionPlane))
                snapshots.Add(SectionPlaneSnapshot.FromPlane(sectionPlane));
        }

        _sections.RestoreFromSnapshot(snapshots);
        if (dto.FillVisible.HasValue)
            _sections.FillVisible = dto.FillVisible.Value;
        if (dto.EdgesVisible.HasValue)
            _sections.EdgesVisible = dto.EdgesVisible.Value;
    }

    private void ApplyViewerMeasurements(ViewerMeasurementsDto dto)
    {
        IMeasurementStore? store = _measure?.Store;
        if (store is null)
            return;

        var rebuilt = new List<MeasurementResult>();
        foreach (ViewerMeasurementDto item in dto.Items ?? [])
        {
            if (TryRebuildViewerMeasurement(item) is { } measurement)
                rebuilt.Add(measurement);
        }

        if (rebuilt.Count == 0 && dto.Items is { Count: > 0 })
            return;

        store.Clear();
        foreach (MeasurementResult measurement in rebuilt)
            store.Add(measurement);
    }

    private static MeasurementResult? TryRebuildViewerMeasurement(ViewerMeasurementDto dto)
    {
        var id = new MeasurementId(dto.Id == Guid.Empty ? Guid.NewGuid() : dto.Id);
        switch (dto.Kind)
        {
            case "annotation":
                double[]? anchor = dto.Anchor;
                if (!IsFiniteVector(anchor) || string.IsNullOrWhiteSpace(dto.Text))
                    return null;
                return new AnnotationMeasurement(
                    id,
                    ToVector3d(anchor!),
                    dto.Text!,
                    dto.OccurrenceId,
                    dto.Color,
                    dto.Author,
                    ParseTimestamp(dto.CreatedUtc),
                    ParseTimestamp(dto.UpdatedUtc),
                    dto.IsVisible);

            case "point-to-point":
                if (dto.Points.Count < 2 || !IsFiniteVector(dto.Points[0]) || !IsFiniteVector(dto.Points[1]))
                    return null;
                Vector3d a = ToVector3d(dto.Points[0]);
                Vector3d b = ToVector3d(dto.Points[1]);
                double meters = dto.Distance is double distance && distance > 0.0 && double.IsFinite(distance)
                    ? distance
                    : Vector3d.Distance(a, b);
                return new PointToPointMeasurement(
                    id,
                    new ScenePoint(a),
                    new ScenePoint(b),
                    new SceneLength(meters),
                    b - a,
                    dto.IsVisible);

            case "bounding-box":
                if (!IsFiniteVector(dto.BoxOrigin)
                    || !IsFiniteVector(dto.BoxAxisX, requireNonZero: true)
                    || !IsFiniteVector(dto.BoxAxisY, requireNonZero: true)
                    || !IsFiniteVector(dto.BoxAxisZ, requireNonZero: true)
                    || !IsPositiveFinite(dto.BoxLengthX)
                    || !IsPositiveFinite(dto.BoxLengthY)
                    || !IsPositiveFinite(dto.BoxLengthZ))
                {
                    return null;
                }

                Vector3d center = ToVector3d(dto.BoxOrigin!);
                Vector3d axisX = ToVector3d(dto.BoxAxisX!);
                Vector3d axisY = ToVector3d(dto.BoxAxisY!);
                Vector3d axisZ = ToVector3d(dto.BoxAxisZ!);
                if (!TryNormalize(axisX, out axisX)
                    || !TryNormalize(axisY, out axisY)
                    || !TryNormalize(axisZ, out axisZ))
                {
                    return null;
                }

                double lengthX = dto.BoxLengthX!.Value;
                double lengthY = dto.BoxLengthY!.Value;
                double lengthZ = dto.BoxLengthZ!.Value;
                var box = new OrientedBox(
                    center,
                    axisX,
                    axisY,
                    axisZ,
                    new Vector3d(lengthX * 0.5, lengthY * 0.5, lengthZ * 0.5));
                BoundingBoxBasisSource basisSource = Enum.TryParse(
                    dto.BoxBasisSource,
                    ignoreCase: true,
                    out BoundingBoxBasisSource parsedBasis)
                    ? parsedBasis
                    : BoundingBoxBasisSource.BestFit;
                return new BoundingBoxMeasurement(
                    id,
                    box,
                    new SceneLength(lengthX),
                    new SceneLength(lengthY),
                    new SceneLength(lengthZ),
                    basisSource,
                    dto.IsVisible);

            default:
                return null;
        }
    }

    private static bool IsPositiveFinite(double? value)
        => value is double number && double.IsFinite(number) && number > 0.0;

    private static DateTimeOffset ParseTimestamp(string? text)
        => DateTimeOffset.TryParse(text, CultureInfo.InvariantCulture, DateTimeStyles.RoundtripKind, out DateTimeOffset value)
            ? value
            : default;

    private double[]? CaptureCameraState()
    {
        CameraState? camera = _camera;
        if (camera is null)
            return null;

        lock (camera)
        {
            return
            [
                camera.Position.X, camera.Position.Y, camera.Position.Z,
                camera.Target.X, camera.Target.Y, camera.Target.Z,
                camera.UpDirection.X, camera.UpDirection.Y, camera.UpDirection.Z,
                camera.WorldUpDirection.X, camera.WorldUpDirection.Y, camera.WorldUpDirection.Z,
                camera.FieldOfView,
                camera.OrthoWidth,
                camera.NearPlane,
                camera.FarPlane,
                camera.IsPerspective ? 1.0 : 0.0,
            ];
        }
    }

    private void AttachRuntimeScene(Scene? scene)
    {
        ReleaseFixedViewLockForSceneChange();
        ClearExplodeView("scene change", syncRenderer: false);
        _sections?.Reset();
        _sectionCustomPoints.Clear();
        _activeSectionSubMode = SectionSubMode.None;
        ClearBodyMoveGizmoDragState();
        _runtimeScene = scene;
        _undoService?.Clear();
        BindPackageSessionForScene(scene);
        if (scene is not null)
        {
            RestorePendingSectionState();
            RestorePendingSectionSubMode();
        }
        else
        {
            ClearPendingSectionState();
            _pendingRestoredSectionSubMode = null;
        }
        _explodeLayout = null;
        _explodeLayoutScene = null;
        _selectedMeasurementDeleteTarget = null;
        ClearXrayIsolationState();
        _measure?.OnSceneAttached(scene);
        _sectionRaycaster?.ClearAccelerationCache("scene attached");

        global::Android.Util.Log.Info(
            "FA.Measure",
            scene is null
                ? "Runtime scene attached: null."
                : $"Runtime scene attached: nodes={scene.NodesById.Count}, visibleMeshNodes={scene.GetVisibleNodes().Count}, meshes={scene.MeshesById.Count}, units='{scene.Stats?.UnitSystem ?? "<null>"}'.");

        if (_viewport is not null)
        {
            _viewport.Renderer.SelectedMeshIndex = 0;
            _viewport.Renderer.SelectedMeshIndices = Array.Empty<int>();
            _viewport.Renderer.HoveredMeshIndex = 0;
            _viewport.Renderer.BodyMoveGizmoScale = 0f;
            _viewport.Renderer.BodyMoveGizmoHovered = GlesTransformGizmoHandle.None;
            _viewport.Renderer.BodyMoveGizmoActive = GlesTransformGizmoHandle.None;
        }

        _modelExplorerPanel?.SetScene(scene);
        ReplaceSelectedNodeIds(
            scene,
            Array.Empty<int>(),
            scrollModelExplorerToSelection: false,
            requestRender: false);

        RefreshMeasurementOverlays();
        UpdateSectionRendererState();
        SyncRuntimeSceneVisibilityToRenderer("scene attached");
        UpdateBottomToolbarVisibility();
        UpdateSaveButton();
    }

    private void RestorePendingSectionSubMode()
    {
        if (_pendingRestoredSectionSubMode is not { } mode)
            return;

        _pendingRestoredSectionSubMode = null;
        _activeSectionSubMode = mode;
        UpdateSectionButtonStates();
        UpdateSectionRendererState();
    }

    private void BindPackageSessionForScene(Scene? scene)
    {
        if (_packageSession is null)
            return;

        if (scene is null || !AndroidScenePackageState.IsFa(scene.PackageInfo))
        {
            _packageSession.BindToPackage(null);
            ClearPendingPackageVisibilityState();
            return;
        }

        string? packageId = string.IsNullOrWhiteSpace(scene.PackageInfo?.PackageId)
            ? null
            : scene.PackageInfo!.PackageId;
        _packageSession.BindToPackage(packageId);
        RestorePendingPackageVisibilityState(packageId);
        AndroidScenePackageState.ApplyVisibilityToScene(scene, _packageSession);
    }

    private void RestorePendingPackageVisibilityState(string? packageId)
    {
        if (_packageSession is null
            || _pendingRestoredHiddenOccurrences is null
            || _pendingRestoredIsolatedOccurrences is null)
        {
            return;
        }

        bool packageMatches = string.IsNullOrWhiteSpace(_pendingRestoredPackageId)
            || string.Equals(_pendingRestoredPackageId, packageId, StringComparison.Ordinal);
        if (packageMatches)
        {
            _packageSession.SetVisibility(
                _pendingRestoredHiddenOccurrences,
                _pendingRestoredIsolatedOccurrences);
        }

        ClearPendingPackageVisibilityState();
    }

    private void ClearPendingPackageVisibilityState()
    {
        _pendingRestoredPackageId = null;
        _pendingRestoredHiddenOccurrences = null;
        _pendingRestoredIsolatedOccurrences = null;
    }

    private void ReleaseFixedViewLockForSceneChange()
    {
        if (!_isInFixedView)
            return;

        _isInFixedView = false;
        _activeFixedView = null;

        if (_camera is { } camera)
        {
            double aspect = GetViewportAspect();
            lock (camera)
                camera.SetProjectionMode(_isoIsPerspective, aspect);
            SetRendererProjectionAppearance(_isoIsPerspective);
        }

        UpdateViewPresetButtonStates();
        global::Android.Util.Log.Info(
            "FA.ViewPresets",
            $"Fixed view released on scene change; restored projection={(_isoIsPerspective ? "Perspective" : "Orthographic")}.");
    }

    private void OnCameraChanged(object? sender, System.ComponentModel.PropertyChangedEventArgs e)
    {
        if (Looper.MyLooper() != Looper.MainLooper)
        {
            RunOnUiThread(() =>
            {
                RefreshSectionGizmoForCamera();
                ScheduleMeasurementCameraOverlayUpdate();
            });
            return;
        }

        RefreshSectionGizmoForCamera();
        ScheduleMeasurementCameraOverlayUpdate();
    }

    private void RefreshSectionGizmoForCamera()
    {
        bool requestRender = false;
        if (_sections?.SelectedPlaneIds.Count > 0
            && CanSelectSectionPlanes()
            && UpdateSectionGizmoRendererState())
        {
            requestRender = true;
        }

        if (_activeModalTool == AndroidModalTool.BodyMove
            && UpdateBodyMoveGizmoRendererState())
        {
            requestRender = true;
        }

        if (requestRender)
            _viewport?.RequestRender();
    }

    private void ScheduleMeasurementCameraOverlayUpdate()
    {
        if (_measurementPresentation.Count == 0
            && _sectionAnnotations.Count == 0
            && (_measurementLabelLayer?.ChildCount ?? 0) == 0)
        {
            return;
        }

        if (Interlocked.Exchange(ref _measurementCameraOverlayUpdateQueued, 1) != 0)
            return;

        bool posted = _viewport?.Post(() =>
        {
            Interlocked.Exchange(ref _measurementCameraOverlayUpdateQueued, 0);
            UpdateMeasurementCameraOverlays();
        }) == true;

        if (!posted)
        {
            Interlocked.Exchange(ref _measurementCameraOverlayUpdateQueued, 0);
            UpdateMeasurementCameraOverlays();
        }
    }

    private void UpdateMeasurementCameraOverlays()
    {
        if (_measurementPresentation.Count == 0
            && _sectionAnnotations.Count == 0
            && (_measurementLabelLayer?.ChildCount ?? 0) == 0)
        {
            return;
        }

        UpdateMeasurementLabelPositions(_measurementPresentation);
        UpdateSectionAnnotationPositions();
    }

    private void RefreshMeasurementOverlays()
    {
        if (Looper.MyLooper() != Looper.MainLooper)
        {
            RunOnUiThread(RefreshMeasurementOverlays);
            return;
        }

        IReadOnlyList<PresentationSnapshot> presentation = _measure?.BuildPresentation()
            ?? Array.Empty<PresentationSnapshot>();
        IReadOnlyList<FaceHighlight> faceHighlights = _measure?.BuildFaceHighlights()
            ?? Array.Empty<FaceHighlight>();
        _measurementPresentation = presentation;

        if (_viewport is not null)
        {
            _viewport.Renderer.MeasurementPresentation = presentation;
            _viewport.Renderer.FaceHighlights = faceHighlights;
            _viewport.RequestRender();
        }

        LogMeasurementOverlayState(presentation, faceHighlights);
        UpdateMeasurementLabels(presentation);
    }

    private void UpdateMeasurementLabels(IReadOnlyList<PresentationSnapshot> presentation)
    {
        if (_measurementLabelLayer is null)
            return;

        _measurementLabelLayer.RemoveAllViews();
        _measurementLabels.Clear();
        _sectionAnnotations.Clear();
        MeasurementLabelKey? deleteTarget = ResolveMeasurementDeleteTarget(presentation);
        _selectedMeasurementDeleteTarget = deleteTarget;
        bool labelsSelectable = CanSelectMeasurementLabels();
        if (_viewport is null || _viewport.Width <= 0 || _viewport.Height <= 0)
        {
            LogMeasurementLabelState(presentation, 0, CountLabels(presentation));
            return;
        }

        foreach (PresentationSnapshot snapshot in presentation)
        {
            int labelIndex = 0;
            foreach (LabelPrimitive label in snapshot.Labels)
            {
                MeasurementLabelKey? key = snapshot.Id is { } id
                    ? new MeasurementLabelKey(id, labelIndex)
                    : null;
                labelIndex++;

                TextView textView = CreateMeasurementLabel(label.Text, snapshot.Style, key is not null && labelsSelectable);
                if (key is { } selectableKey && labelsSelectable)
                {
                    textView.Click += (_, _) => SelectMeasurementLabel(selectableKey);
                    textView.SetOnTouchListener(new MeasurementLabelTouchProxy(this, selectableKey, isDeleteButton: false));
                    textView.SetOnGenericMotionListener(new MeasurementLabelGenericMotionProxy(this, selectableKey, isDeleteButton: false));
                    textView.SetOnHoverListener(new MeasurementLabelHoverProxy(this, selectableKey));
                }

                int maxWidth = System.Math.Max(Dp(80), _measurementLabelLayer.Width - Dp(16));
                textView.SetMaxWidth(maxWidth);
                textView.Measure(
                    View.MeasureSpec.MakeMeasureSpec(maxWidth, MeasureSpecMode.AtMost),
                    View.MeasureSpec.MakeMeasureSpec(0, MeasureSpecMode.Unspecified));

                var lp = new FrameLayout.LayoutParams(
                    ViewGroup.LayoutParams.WrapContent,
                    ViewGroup.LayoutParams.WrapContent);
                _measurementLabelLayer.AddView(textView, lp);

                TextView? deleteButton = null;
                if (key is { } deleteKey && deleteTarget is { } target && deleteKey.Equals(target))
                {
                    deleteButton = CreateMeasurementDeleteButton(deleteKey);
                    deleteButton.SetOnTouchListener(new MeasurementLabelTouchProxy(this, deleteKey, isDeleteButton: true));
                    deleteButton.SetOnGenericMotionListener(new MeasurementLabelGenericMotionProxy(this, deleteKey, isDeleteButton: true));
                    deleteButton.SetOnHoverListener(new MeasurementLabelHoverProxy(this, deleteKey));
                    int buttonSize = Dp(MeasurementDeleteButtonSizeDp);
                    _measurementLabelLayer.AddView(deleteButton, new FrameLayout.LayoutParams(buttonSize, buttonSize));
                }

                _measurementLabels.Add(new MeasurementLabelBinding(key, label.Anchor, textView, deleteButton));
            }
        }

        AddSectionAnnotationViews();
        UpdateMeasurementLabelPositions(presentation);
        UpdateSectionAnnotationPositions();
    }

    private void UpdateMeasurementLabelPositions(IReadOnlyList<PresentationSnapshot> presentation)
    {
        if (_measurementLabelLayer is null)
            return;

        if (_measurementLabels.Count == 0)
        {
            LogMeasurementLabelState(presentation, 0, CountLabels(presentation));
            return;
        }

        if (_viewport is null || _viewport.Width <= 0 || _viewport.Height <= 0)
        {
            foreach (MeasurementLabelBinding binding in _measurementLabels)
            {
                binding.View.Visibility = ViewStates.Invisible;
                if (binding.DeleteButton is not null)
                    binding.DeleteButton.Visibility = ViewStates.Invisible;
            }
            LogMeasurementLabelState(presentation, 0, _measurementLabels.Count);
            return;
        }

        int projected = 0;
        int skipped = 0;
        foreach (MeasurementLabelBinding binding in _measurementLabels)
        {
            TextView textView = binding.View;
            if (!TryProjectWorldToViewport(binding.Anchor, out double screenX, out double screenY))
            {
                skipped++;
                if (textView.Visibility != ViewStates.Invisible)
                    textView.Visibility = ViewStates.Invisible;
                if (binding.DeleteButton is not null && binding.DeleteButton.Visibility != ViewStates.Invisible)
                    binding.DeleteButton.Visibility = ViewStates.Invisible;
                continue;
            }

            projected++;
            if (textView.Visibility != ViewStates.Visible)
                textView.Visibility = ViewStates.Visible;
            if (binding.DeleteButton is not null && binding.DeleteButton.Visibility != ViewStates.Visible)
                binding.DeleteButton.Visibility = ViewStates.Visible;

            int measuredWidth = textView.MeasuredWidth;
            int measuredHeight = textView.MeasuredHeight;
            if (measuredWidth <= 0 || measuredHeight <= 0)
            {
                int maxWidth = System.Math.Max(Dp(80), _measurementLabelLayer.Width - Dp(16));
                textView.Measure(
                    View.MeasureSpec.MakeMeasureSpec(maxWidth, MeasureSpecMode.AtMost),
                    View.MeasureSpec.MakeMeasureSpec(0, MeasureSpecMode.Unspecified));
                measuredWidth = System.Math.Max(Dp(24), textView.MeasuredWidth);
                measuredHeight = System.Math.Max(Dp(18), textView.MeasuredHeight);
            }

            double left = System.Math.Clamp(
                screenX - measuredWidth * 0.5,
                Dp(4),
                System.Math.Max(Dp(4), _viewport.Width - measuredWidth - Dp(4)));
            double top = System.Math.Clamp(
                screenY - measuredHeight - Dp(8),
                Dp(4),
                System.Math.Max(Dp(4), _viewport.Height - measuredHeight - Dp(4)));

            textView.TranslationX = (float)left;
            textView.TranslationY = (float)top;

            if (binding.DeleteButton is { } deleteButton)
            {
                int buttonSize = Dp(MeasurementDeleteButtonSizeDp);
                int gap = Dp(MeasurementDeleteButtonGapDp);
                double buttonLeft = left + measuredWidth + gap;
                double minLeft = Dp(4);
                double maxLeft = System.Math.Max(minLeft, _viewport.Width - buttonSize - Dp(4));
                if (buttonLeft > maxLeft)
                    buttonLeft = left - buttonSize - gap;
                buttonLeft = System.Math.Clamp(buttonLeft, minLeft, maxLeft);

                double buttonTop = System.Math.Clamp(
                    top + (measuredHeight - buttonSize) * 0.5,
                    Dp(4),
                    System.Math.Max(Dp(4), _viewport.Height - buttonSize - Dp(4)));

                deleteButton.TranslationX = (float)buttonLeft;
                deleteButton.TranslationY = (float)buttonTop;
            }
        }

        LogMeasurementLabelState(presentation, projected, skipped);
    }

    private void UpdateSectionAnnotationPositions()
    {
        if (_viewport is null || _sectionAnnotations.Count == 0)
            return;

        BoundingBox sceneBounds = GetFullSceneBounds();
        double sceneDiagonal = sceneBounds.IsValid ? sceneBounds.Diagonal : 100.0;
        double halfSide = Math.Clamp(sceneDiagonal * AppSettings.SectionPlaneSizeFraction, 1.0, 10_000.0);
        foreach (SectionAnnotationBinding binding in _sectionAnnotations)
        {
            SectionPlane plane = binding.Plane;
            Vector3d anchor = ToVector3d(plane.Anchor);
            Vector3d axisX = ToVector3d(plane.AxisX);
            Vector3d axisY = ToVector3d(plane.AxisY);
            var corners = new[]
            {
                anchor - axisX * halfSide - axisY * halfSide,
                anchor + axisX * halfSide - axisY * halfSide,
                anchor + axisX * halfSide + axisY * halfSide,
                anchor - axisX * halfSide + axisY * halfSide,
            };

            var projectedCorners = new List<SectionCornerProjection>(corners.Length);
            foreach (Vector3d corner in corners)
            {
                if (!TryProjectWorldToViewport(corner, out double screenX, out double screenY))
                    continue;

                projectedCorners.Add(new SectionCornerProjection(corner, new Point2D(screenX, screenY)));
            }

            if (projectedCorners.Count == 0)
            {
                binding.DeleteButton.Visibility = ViewStates.Invisible;
                binding.FlipButton.Visibility = ViewStates.Invisible;
                continue;
            }

            // Attach controls to real projected plane corners: delete at the
            // screen-space upper-right corner, flip at the other upper corner.
            SectionCornerProjection deleteCorner = PickProjectedSectionCorner(projectedCorners, static corner => corner.Screen.X - corner.Screen.Y);
            SectionCornerProjection flipCorner = PickProjectedSectionCorner(projectedCorners, static corner => -corner.Screen.X - corner.Screen.Y, deleteCorner.Screen);
            binding.DeleteAnchor = deleteCorner.World;
            binding.FlipAnchor = flipCorner.World;
            int buttonSize = Dp(SectionCornerButtonSizeDp);
            PlaceSectionCornerButton(binding.DeleteButton, deleteCorner.Screen, buttonSize);
            PlaceSectionCornerButton(binding.FlipButton, flipCorner.Screen, buttonSize);
        }
    }

    private static SectionCornerProjection PickProjectedSectionCorner(
        IReadOnlyList<SectionCornerProjection> corners,
        Func<SectionCornerProjection, double> scoreSelector,
        Point2D? excluded = null)
    {
        SectionCornerProjection best = default;
        double bestScore = double.NegativeInfinity;
        bool hasBest = false;
        foreach (SectionCornerProjection corner in corners)
        {
            if (corners.Count > 1 && excluded.HasValue && corner.Screen.Equals(excluded.Value))
                continue;

            double score = scoreSelector(corner);
            if (!hasBest || score > bestScore)
            {
                best = corner;
                bestScore = score;
                hasBest = true;
            }
        }

        return hasBest ? best : corners[0];
    }

    private void PlaceSectionCornerButton(TextView button, Point2D corner, int buttonSize)
    {
        if (_viewport is null)
            return;

        if (button.Visibility != ViewStates.Visible)
            button.Visibility = ViewStates.Visible;

        double minLeft = Dp(4);
        double maxLeft = Math.Max(minLeft, _viewport.Width - buttonSize - Dp(4));
        double left = Math.Clamp(corner.X - buttonSize * 0.5, minLeft, maxLeft);
        double top = Math.Clamp(
            corner.Y - buttonSize * 0.5,
            Dp(4),
            Math.Max(Dp(4), _viewport.Height - buttonSize - Dp(4)));

        button.TranslationX = (float)left;
        button.TranslationY = (float)top;
    }

