    private bool HandleAnnotationTouch(MotionEvent? motionEvent)
    {
        if (motionEvent is null)
            return false;
        if (ShouldRejectFingerTouchForSpenPalmRejection(motionEvent))
            return true;

        MotionEventActions action = motionEvent.ActionMasked;
        float hitSlopPx = Dp(MeasurementTouchHitSlopDp);

        switch (action)
        {
            case MotionEventActions.ButtonPress:
            {
                if (!IsStylusOrMousePointer(motionEvent))
                    return _pressedAnnotationTarget is not null;

                if (IsMousePointerEvent(motionEvent))
                {
                    if (!IsPrimaryMouseButtonPress(motionEvent))
                        return false;

                    AnnotationHitTarget? mouseHit = HitAnnotationTarget(
                        motionEvent.GetX(),
                        motionEvent.GetY(),
                        hitSlopPx);
                    if (mouseHit is not { } mouseTarget)
                        return false;

                    _measurementLabelLayer?.Parent?.RequestDisallowInterceptTouchEvent(true);
                    return BeginAnnotationPointerPress(mouseTarget);
                }

                AnnotationHitTarget? hit = HitAnnotationTarget(
                    motionEvent.GetX(),
                    motionEvent.GetY(),
                    hitSlopPx);
                if (hit is not { } target)
                    return false;

                return ActivateAnnotationTargetFromStylusButton(target, motionEvent);
            }

            case MotionEventActions.ButtonRelease:
                if (!IsStylusOrMousePointer(motionEvent))
                    return _pressedAnnotationTarget is not null;

                if (IsMousePointerEvent(motionEvent))
                {
                    if (!IsPrimaryMouseButtonRelease(motionEvent))
                        return false;

                    AnnotationHitTarget? mouseHit = HitAnnotationTarget(
                        motionEvent.GetX(),
                        motionEvent.GetY(),
                        hitSlopPx);
                    return CompleteAnnotationPointerPress(mouseHit);
                }

                return ClearAnnotationPointerPress();

            case MotionEventActions.Down:
            {
                AnnotationHitTarget? hit = HitAnnotationTarget(
                    motionEvent.GetX(),
                    motionEvent.GetY(),
                    hitSlopPx);
                if (hit is not { } target)
                    return false;

                _measurementLabelLayer?.Parent?.RequestDisallowInterceptTouchEvent(true);
                return BeginAnnotationPointerPress(target);
            }

            case MotionEventActions.Move:
                return _pressedAnnotationTarget is not null;

            case MotionEventActions.Up:
            case MotionEventActions.PointerUp:
            {
                if (_pressedAnnotationTarget is null)
                    return false;

                AnnotationHitTarget? hit = HitAnnotationTarget(
                    motionEvent.GetX(),
                    motionEvent.GetY(),
                    hitSlopPx);
                return CompleteAnnotationPointerPress(hit);
            }

            case MotionEventActions.Cancel:
                if (_pressedAnnotationTarget is null)
                    return false;

                return ClearAnnotationPointerPress();

            default:
                return _pressedAnnotationTarget is not null;
        }
    }

    private bool HandleMeasurementLabelViewGenericMotion(MeasurementLabelKey key, bool isDeleteButton, MotionEvent? motionEvent)
    {
        if (motionEvent is null || !CanSelectMeasurementLabels() || !IsStylusOrMousePointer(motionEvent))
            return false;

        MotionEventActions action = motionEvent.ActionMasked;
        if (action == MotionEventActions.ButtonRelease)
        {
            if (IsMousePointerEvent(motionEvent))
            {
                if (!IsPrimaryMouseButtonRelease(motionEvent))
                    return false;

                AnnotationHitTarget target = isDeleteButton
                    ? AnnotationHitTarget.MeasurementDelete(key)
                    : AnnotationHitTarget.MeasurementLabel(key);
                return CompleteAnnotationPointerPress(target);
            }

            return ClearAnnotationPointerPress();
        }

        if (action != MotionEventActions.ButtonPress)
            return false;

        if (IsMousePointerEvent(motionEvent))
        {
            if (!IsPrimaryMouseButtonPress(motionEvent))
                return false;

            return BeginAnnotationPointerPress(
                isDeleteButton
                    ? AnnotationHitTarget.MeasurementDelete(key)
                    : AnnotationHitTarget.MeasurementLabel(key));
        }

        return ActivateAnnotationTargetFromStylusButton(
            isDeleteButton
                ? AnnotationHitTarget.MeasurementDelete(key)
                : AnnotationHitTarget.MeasurementLabel(key),
            motionEvent);
    }

    private bool HandleMeasurementLabelViewTouch(MeasurementLabelKey key, bool isDeleteButton, MotionEvent? motionEvent)
    {
        if (motionEvent is null || !CanSelectMeasurementLabels())
            return false;
        if (ShouldRejectFingerTouchForSpenPalmRejection(motionEvent))
            return true;

        MotionEventActions action = motionEvent.ActionMasked;
        var target = isDeleteButton
            ? AnnotationHitTarget.MeasurementDelete(key)
            : AnnotationHitTarget.MeasurementLabel(key);
        switch (action)
        {
            case MotionEventActions.ButtonPress:
                if (!IsStylusOrMousePointer(motionEvent))
                    return _pressedAnnotationTarget is not null;

                if (IsMousePointerEvent(motionEvent))
                {
                    if (!IsPrimaryMouseButtonPress(motionEvent))
                        return false;

                    return BeginAnnotationPointerPress(target);
                }

                return ActivateAnnotationTargetFromStylusButton(target, motionEvent);

            case MotionEventActions.ButtonRelease:
                if (!IsStylusOrMousePointer(motionEvent))
                    return _pressedAnnotationTarget is not null;

                if (IsMousePointerEvent(motionEvent))
                {
                    if (!IsPrimaryMouseButtonRelease(motionEvent))
                        return false;

                    return CompleteAnnotationPointerPress(target);
                }

                return ClearAnnotationPointerPress();

            case MotionEventActions.Down:
                return BeginAnnotationPointerPress(target);

            case MotionEventActions.Move:
                return _pressedAnnotationTarget is not null;

            case MotionEventActions.Up:
            case MotionEventActions.PointerUp:
                if (_pressedAnnotationTarget is not { } pressed || !pressed.Equals(target))
                {
                    _pressedAnnotationTarget = null;
                    return false;
                }

                return CompleteAnnotationPointerPress(target);

            case MotionEventActions.Cancel:
                return ClearAnnotationPointerPress();

            default:
                return _pressedAnnotationTarget is not null;
        }
    }

    private bool HandleSectionAnnotationButtonTouch(Guid id, bool isFlipButton, MotionEvent? motionEvent)
    {
        if (motionEvent is null || !CanInteractWithSectionAnnotations())
            return false;
        if (ShouldRejectFingerTouchForSpenPalmRejection(motionEvent))
            return true;

        AnnotationHitTarget target = isFlipButton
            ? AnnotationHitTarget.SectionFlip(id)
            : AnnotationHitTarget.SectionDelete(id);
        switch (motionEvent.ActionMasked)
        {
            case MotionEventActions.ButtonPress:
                if (!IsStylusOrMousePointer(motionEvent))
                    return _pressedAnnotationTarget is not null;

                if (IsMousePointerEvent(motionEvent))
                {
                    if (!IsPrimaryMouseButtonPress(motionEvent))
                        return false;

                    return BeginAnnotationPointerPress(target);
                }

                return ActivateAnnotationTargetFromStylusButton(target, motionEvent);

            case MotionEventActions.ButtonRelease:
                if (!IsStylusOrMousePointer(motionEvent))
                    return _pressedAnnotationTarget is not null;

                if (IsMousePointerEvent(motionEvent))
                {
                    if (!IsPrimaryMouseButtonRelease(motionEvent))
                        return false;

                    return CompleteAnnotationPointerPress(target);
                }

                return ClearAnnotationPointerPress();

            case MotionEventActions.Down:
                return BeginAnnotationPointerPress(target);

            case MotionEventActions.Move:
                return _pressedAnnotationTarget is not null;

            case MotionEventActions.Up:
            case MotionEventActions.PointerUp:
                if (_pressedAnnotationTarget is not { } pressed || !pressed.Equals(target))
                {
                    _pressedAnnotationTarget = null;
                    return false;
                }

                return CompleteAnnotationPointerPress(target);

            case MotionEventActions.Cancel:
                return ClearAnnotationPointerPress();

            default:
                return _pressedAnnotationTarget is not null;
        }
    }

    private bool HandleSectionAnnotationButtonGenericMotion(Guid id, bool isFlipButton, MotionEvent? motionEvent)
    {
        if (motionEvent is null || !CanInteractWithSectionAnnotations() || !IsStylusOrMousePointer(motionEvent))
            return false;

        MotionEventActions action = motionEvent.ActionMasked;
        if (action != MotionEventActions.ButtonPress && action != MotionEventActions.ButtonRelease)
            return false;

        if (action == MotionEventActions.ButtonRelease)
        {
            if (IsMousePointerEvent(motionEvent))
            {
                if (!IsPrimaryMouseButtonRelease(motionEvent))
                    return false;

                AnnotationHitTarget target = isFlipButton
                    ? AnnotationHitTarget.SectionFlip(id)
                    : AnnotationHitTarget.SectionDelete(id);
                return CompleteAnnotationPointerPress(target);
            }

            return ClearAnnotationPointerPress();
        }

        if (IsMousePointerEvent(motionEvent))
        {
            if (!IsPrimaryMouseButtonPress(motionEvent))
                return false;

            return BeginAnnotationPointerPress(
                isFlipButton
                    ? AnnotationHitTarget.SectionFlip(id)
                    : AnnotationHitTarget.SectionDelete(id));
        }

        return ActivateAnnotationTargetFromStylusButton(
            isFlipButton
                ? AnnotationHitTarget.SectionFlip(id)
                : AnnotationHitTarget.SectionDelete(id),
            motionEvent);
    }

    private bool HandleSectionAnnotationButtonHover(Guid id, MotionEvent? motionEvent)
    {
        if (motionEvent is null || !CanInteractWithSectionAnnotations() || !IsStylusOrMousePointer(motionEvent))
            return false;

        MotionEventActions action = motionEvent.ActionMasked;
        if (action == MotionEventActions.HoverExit)
        {
            SetHoveredSectionPlane(null);
            return true;
        }

        if (action != MotionEventActions.HoverEnter && action != MotionEventActions.HoverMove)
            return false;

        CancelHoverPick();
        SetHoveredMesh(0);
        SetHoveredSectionPlane(id);
        return true;
    }

    private bool HandleMeasurementLabelLayerGenericMotion(MotionEvent? motionEvent)
    {
        if (motionEvent is null || !IsStylusOrMousePointer(motionEvent))
            return false;

        MotionEventActions action = motionEvent.ActionMasked;
        if (action != MotionEventActions.ButtonPress && action != MotionEventActions.ButtonRelease)
            return false;

        if (action == MotionEventActions.ButtonRelease)
        {
            if (IsMousePointerEvent(motionEvent))
            {
                if (!IsPrimaryMouseButtonRelease(motionEvent))
                    return false;

                AnnotationHitTarget? released = HitAnnotationTarget(
                    motionEvent.GetX(),
                    motionEvent.GetY(),
                    Dp(MeasurementTouchHitSlopDp));
                return CompleteAnnotationPointerPress(released);
            }

            return ClearAnnotationPointerPress();
        }

        if (IsMousePointerEvent(motionEvent) && !IsPrimaryMouseButtonPress(motionEvent))
            return false;

        AnnotationHitTarget? hit = HitAnnotationTarget(
            motionEvent.GetX(),
            motionEvent.GetY(),
            Dp(MeasurementTouchHitSlopDp));
        if (hit is not { } target)
            return false;

        if (IsMousePointerEvent(motionEvent))
            return BeginAnnotationPointerPress(target);

        return ActivateAnnotationTargetFromStylusButton(target, motionEvent);
    }

    private bool BeginAnnotationPointerPress(AnnotationHitTarget target)
    {
        _pressedAnnotationTarget = target;
        CancelHoverPick();
        SetHoveredMesh(0);
        ApplyAnnotationHover(target);
        return true;
    }

    private bool CompleteAnnotationPointerPress(AnnotationHitTarget? releasedTarget)
    {
        if (_pressedAnnotationTarget is not { } pressed)
            return false;

        _pressedAnnotationTarget = null;
        if (releasedTarget is { } released && released.Equals(pressed))
            ActivateAnnotationTarget(pressed);

        return true;
    }

    private bool ClearAnnotationPointerPress()
    {
        bool hadPress = _pressedAnnotationTarget is not null;
        _pressedAnnotationTarget = null;
        return hadPress;
    }

    private bool ActivateAnnotationTargetFromStylusButton(AnnotationHitTarget target, MotionEvent motionEvent)
    {
        long eventTime = motionEvent.EventTime;
        if (_lastStylusButtonActivationEventTime == eventTime
            && _lastStylusButtonActivationTarget is { } lastTarget
            && lastTarget.Equals(target))
        {
            return true;
        }

        _lastStylusButtonActivationEventTime = eventTime;
        _lastStylusButtonActivationTarget = target;
        _pressedAnnotationTarget = target;
        CancelHoverPick();
        SetHoveredMesh(0);
        ApplyAnnotationHover(target);
        ActivateAnnotationTarget(target);
        return true;
    }

    private bool TryHandleAnnotationTap(Point2D dipPosition)
    {
        float density = Resources?.DisplayMetrics?.Density ?? 1.0f;
        if (density <= 0f) density = 1.0f;
        float x = (float)(dipPosition.X * density);
        float y = (float)(dipPosition.Y * density);
        if (HitAnnotationTarget(x, y, Dp(MeasurementTouchHitSlopDp)) is not { } target)
            return false;

        ActivateAnnotationTarget(target);
        return true;
    }

    private bool HandleAnnotationHover(MotionEvent motionEvent)
    {
        if (!IsStylusOrMousePointer(motionEvent))
            return false;

        if (HitAnnotationTarget(motionEvent.GetX(), motionEvent.GetY(), hitSlopPx: 0f) is not { } target)
            return false;

        _stylusSecondaryContextActive = false;
        CancelHoverPick();
        SetHoveredMesh(0);
        ApplyAnnotationHover(target);
        return true;
    }

    private AnnotationHitTarget? HitAnnotationTarget(float x, float y, float hitSlopPx)
    {
        CameraState? camera = SnapshotCamera();
        AnnotationHitTarget? bestTarget = null;
        double bestDepth = double.PositiveInfinity;

        if (HitSectionDeleteButton(x, y, hitSlopPx) is { } sectionDelete)
            Consider(
                AnnotationHitTarget.SectionDelete(sectionDelete.Id),
                CameraDepth(sectionDelete.Anchor, camera));

        if (HitSectionFlipButton(x, y, hitSlopPx) is { } sectionFlip)
            Consider(
                AnnotationHitTarget.SectionFlip(sectionFlip.Id),
                CameraDepth(sectionFlip.Anchor, camera));

        if (CanSelectMeasurementLabels()
            && HitMeasurementLabelTarget(x, y, hitSlopPx, camera) is { } measurementTarget)
        {
            Consider(
                measurementTarget.IsDeleteButton
                    ? AnnotationHitTarget.MeasurementDelete(measurementTarget.Key)
                    : AnnotationHitTarget.MeasurementLabel(measurementTarget.Key),
                CameraDepth(measurementTarget.Anchor, camera));
        }

        double sectionHitTolerance = hitSlopPx > 0f
            ? Math.Max(SectionPlaneHoverHitTolerancePx, Dp(SectionPlaneTouchHitToleranceDp))
            : SectionPlaneHoverHitTolerancePx;
        if (CanInteractWithSectionAnnotations()
            && PickSectionPlaneEdgeHit(PixelToDip(x, y), sectionHitTolerance, camera) is { } hoveredSection)
        {
            Consider(AnnotationHitTarget.SectionPlane(hoveredSection.Id), hoveredSection.Depth);
        }

        return bestTarget;

        void Consider(AnnotationHitTarget target, double depth)
        {
            if (bestTarget is not null && !IsCloserDepth(depth, bestDepth))
                return;

            bestTarget = target;
            bestDepth = depth;
        }
    }

    private void ApplyAnnotationHover(AnnotationHitTarget target)
    {
        switch (target.Kind)
        {
            case AnnotationTargetKind.MeasurementLabel:
            case AnnotationTargetKind.MeasurementDelete:
                SetHoveredSectionPlane(null);
                if (target.MeasurementKey is { } key)
                    SetHoveredMeasurementLabel(key);
                break;

            case AnnotationTargetKind.SectionPlane:
            case AnnotationTargetKind.SectionDelete:
            case AnnotationTargetKind.SectionFlip:
                SetHoveredMeasurementLabel(null);
                if (target.SectionPlaneId is { } id)
                    SetHoveredSectionPlane(id);
                break;
        }
    }

    private void ActivateAnnotationTarget(AnnotationHitTarget target)
    {
        switch (target.Kind)
        {
            case AnnotationTargetKind.MeasurementLabel:
                if (target.MeasurementKey is { } labelKey)
                    SelectMeasurementLabel(labelKey);
                break;

            case AnnotationTargetKind.MeasurementDelete:
                if (target.MeasurementKey is { } deleteKey)
                    DeleteMeasurementLabel(deleteKey);
                break;

            case AnnotationTargetKind.SectionPlane:
                if (target.SectionPlaneId is { } planeId)
                    SelectSectionPlaneAnnotation(planeId);
                break;

            case AnnotationTargetKind.SectionDelete:
                if (target.SectionPlaneId is { } sectionDeleteId)
                    DeleteSectionPlane(sectionDeleteId);
                break;

            case AnnotationTargetKind.SectionFlip:
                if (target.SectionPlaneId is { } sectionFlipId)
                    FlipSectionPlane(sectionFlipId);
                break;
        }
    }

    private bool HandleMeasurementLabelHover(MeasurementLabelKey key, MotionEvent? motionEvent)
    {
        if (motionEvent is null)
            return false;

        MotionEventActions action = motionEvent.ActionMasked;
        if (action != MotionEventActions.HoverEnter
            && action != MotionEventActions.HoverMove
            && action != MotionEventActions.HoverExit)
        {
            return false;
        }

        if (!IsStylusOrMousePointer(motionEvent) || !CanSelectMeasurementLabels())
            return false;

        if (action == MotionEventActions.HoverExit)
        {
            SetHoveredMeasurementLabel(null);
            return true;
        }

        CancelHoverPick();
        SetHoveredMesh(0);
        SetHoveredMeasurementLabel(key);
        return true;
    }

    private void SetHoveredMeasurementLabel(MeasurementLabelKey? key)
    {
        MeasurementId? id = key?.Id;
        if (_measure?.HoverMeasurement(id) == true)
            RefreshMeasurementOverlays();
    }

    private bool TryHoverMeasurementLabel(float x, float y)
    {
        if (!CanSelectMeasurementLabels())
            return false;

        MeasurementLabelKey? hit = HitMeasurementLabel(x, y);
        if (hit is { } key)
        {
            SetHoveredMeasurementLabel(key);
            return true;
        }

        SetHoveredMeasurementLabel(null);
        return false;
    }

    private MeasurementLabelKey? HitMeasurementLabel(float x, float y)
        => HitMeasurementLabelTarget(x, y, hitSlopPx: 0f)?.Key;

    private MeasurementLabelHitTarget? HitMeasurementLabelTarget(
        float x,
        float y,
        float hitSlopPx,
        CameraState? camera = null)
    {
        camera ??= SnapshotCamera();
        MeasurementLabelHitTarget? best = null;
        double bestDepth = double.PositiveInfinity;
        for (int i = _measurementLabels.Count - 1; i >= 0; i--)
        {
            MeasurementLabelBinding binding = _measurementLabels[i];
            if (binding.Key is not { } key)
                continue;

            if (ViewContainsPoint(binding.DeleteButton, x, y, hitSlopPx))
                Consider(new MeasurementLabelHitTarget(key, binding.Anchor, IsDeleteButton: true));

            if (ViewContainsPoint(binding.View, x, y, hitSlopPx))
                Consider(new MeasurementLabelHitTarget(key, binding.Anchor, IsDeleteButton: false));
        }

        return best;

        void Consider(MeasurementLabelHitTarget candidate)
        {
            double depth = CameraDepth(candidate.Anchor, camera);
            if (best is not null && !IsCloserDepth(depth, bestDepth))
                return;

            best = candidate;
            bestDepth = depth;
        }
    }

    private static bool ViewContainsPoint(View? view, float x, float y, float hitSlopPx = 0f)
    {
        if (view is null || view.Visibility != ViewStates.Visible)
            return false;

        float left = view.Left + view.TranslationX;
        float top = view.Top + view.TranslationY;
        int width = view.Width > 0 ? view.Width : view.MeasuredWidth;
        int height = view.Height > 0 ? view.Height : view.MeasuredHeight;
        return width > 0
            && height > 0
            && x >= left - hitSlopPx
            && x <= left + width + hitSlopPx
            && y >= top - hitSlopPx
            && y <= top + height + hitSlopPx;
    }

    private void DeleteMeasurementLabel(MeasurementLabelKey key)
    {
        if (_measure is null)
            return;

        _selectedMeasurementDeleteTarget = null;
        _measure.RemoveMeasurement(key.Id);
        RefreshMeasurementOverlays();
    }

    private bool CanInteractWithSectionAnnotations()
        => CanSelectSectionPlanes();

    private bool CanSelectSectionPlanes()
        => (_activeModalTool == AndroidModalTool.Select
            || _activeModalTool == AndroidModalTool.Measure
            || _activeModalTool == AndroidModalTool.Section)
           && _sections is { Planes.Count: > 0, EdgesVisible: true };

    private void SelectSectionPlaneAnnotation(Guid id)
    {
        if (_sections is null || !_sections.Planes.Any(plane => plane.Id == id))
            return;

        bool alreadySelected = _sections.SelectedPlaneIds.Count == 1
            && _sections.SelectedPlaneIds.Contains(id);
        _sections.Select(new[] { id }, additive: false);
        ClearSectionPlacementDraft();
        _sectionGizmoHovered = GlesTransformGizmoHandle.None;
        SetHoveredSectionPlane(id);
        UpdateSectionRendererState();
        UpdateSectionButtonStates();
        _viewport?.PerformHapticFeedback(FeedbackConstants.ContextClick);
        if (!alreadySelected)
            global::Android.Util.Log.Info("FA.Section", $"Selected section plane {id} by annotation tap.");
    }

    private void DeleteSectionPlane(Guid id)
    {
        if (_sections is null || !_sections.Planes.Any(plane => plane.Id == id))
            return;

        using IUndoTransaction? undo = _undoService?.Begin("Delete section");
        IReadOnlyList<SectionPlaneSnapshot> before = _sections.SnapshotAll();
        if (_hoveredSectionPlaneId == id)
            _hoveredSectionPlaneId = null;
        _sections.Remove(new[] { id });
        undo?.Add(new SectionStateChange(before, _sections.SnapshotAll(), "Delete section"));
        UpdateSectionRendererState();
        UpdateSectionButtonStates();
        global::Android.Util.Log.Info("FA.Section", $"Deleted section plane {id} by annotation button.");
    }

    private void FlipSectionPlane(Guid id)
    {
        if (_sections is null)
            return;

        bool found = false;
        SectionPlane plane = default;
        foreach (SectionPlane candidate in _sections.Planes)
        {
            if (candidate.Id != id)
                continue;

            plane = candidate;
            found = true;
            break;
        }

        if (!found)
            return;

        Vector3d axisX = ToVector3d(plane.AxisX);
        if (!TryNormalize(axisX, out axisX))
        {
            global::Android.Util.Log.Warn("FA.Section", $"Skipped section plane flip for {id}: invalid AxisX.");
            return;
        }

        if (_sectionGizmoActive != GlesTransformGizmoHandle.None)
            CommitSectionGizmoDrag();

        using IUndoTransaction? undo = _undoService?.Begin("Flip section");
        IReadOnlyList<SectionPlaneSnapshot> before = _sections.SnapshotAll();
        Vector3d anchor = ToVector3d(plane.Anchor);
        var snapshots = new[] { SectionPlaneSnapshot.FromPlane(plane) };
        ApplySectionPlaneSnapshotRotation(
            snapshots,
            Quaterniond.FromAxisAngle(axisX, Math.PI),
            anchor);
        undo?.Add(new SectionStateChange(before, _sections.SnapshotAll(), "Flip section"));

        _sections.Select(new[] { id }, additive: false);
        ClearSectionPlacementDraft();
        _sectionGizmoHovered = GlesTransformGizmoHandle.None;
        SetHoveredSectionPlane(id);
        UpdateSectionRendererState();
        UpdateSectionButtonStates();
        _viewport?.PerformHapticFeedback(FeedbackConstants.ContextClick);
        global::Android.Util.Log.Info("FA.Section", $"Flipped section plane {id} by 180 degrees around gizmo X axis.");
    }

    private SectionAnnotationButtonHit? HitSectionDeleteButton(float x, float y, float hitSlopPx)
    {
        if (!CanInteractWithSectionAnnotations())
            return null;

        SectionAnnotationButtonHit? best = null;
        double bestDepth = double.PositiveInfinity;
        CameraState? camera = SnapshotCamera();
        for (int i = _sectionAnnotations.Count - 1; i >= 0; i--)
        {
            SectionAnnotationBinding binding = _sectionAnnotations[i];
            if (ViewContainsPoint(binding.DeleteButton, x, y, hitSlopPx))
                Consider(new SectionAnnotationButtonHit(
                    binding.Id,
                    binding.DeleteAnchor ?? ToVector3d(binding.Plane.Anchor)));
        }

        return best;

        void Consider(SectionAnnotationButtonHit candidate)
        {
            double depth = CameraDepth(candidate.Anchor, camera);
            if (best is not null && !IsCloserDepth(depth, bestDepth))
                return;

            best = candidate;
            bestDepth = depth;
        }
    }

    private SectionAnnotationButtonHit? HitSectionFlipButton(float x, float y, float hitSlopPx)
    {
        if (!CanInteractWithSectionAnnotations())
            return null;

        SectionAnnotationButtonHit? best = null;
        double bestDepth = double.PositiveInfinity;
        CameraState? camera = SnapshotCamera();
        for (int i = _sectionAnnotations.Count - 1; i >= 0; i--)
        {
            SectionAnnotationBinding binding = _sectionAnnotations[i];
            if (ViewContainsPoint(binding.FlipButton, x, y, hitSlopPx))
                Consider(new SectionAnnotationButtonHit(
                    binding.Id,
                    binding.FlipAnchor ?? ToVector3d(binding.Plane.Anchor)));
        }

        return best;

        void Consider(SectionAnnotationButtonHit candidate)
        {
            double depth = CameraDepth(candidate.Anchor, camera);
            if (best is not null && !IsCloserDepth(depth, bestDepth))
                return;

            best = candidate;
            bestDepth = depth;
        }
    }

    private Point2D PixelToDip(float x, float y)
    {
        float density = Resources?.DisplayMetrics?.Density ?? 1.0f;
        if (density <= 0f) density = 1.0f;
        return new Point2D(x / density, y / density);
    }

    private void ClearSelectedMeasurement(string reason)
    {
        if (_selectedMeasurementDeleteTarget is null && _measure?.SelectedMeasurementId is null)
            return;

        _selectedMeasurementDeleteTarget = null;
        _measure?.ClearMeasurementSelection();
        global::Android.Util.Log.Info("FA.Measure", $"Measurement label selection cleared: reason={reason}.");
        RefreshMeasurementOverlays();
    }

    private void ClearSelectedSectionPlane(string reason)
    {
        if (_sections is null)
            return;

        bool hadSelection = _sections.SelectedPlaneIds.Count > 0;
        bool hadHover = _hoveredSectionPlaneId.HasValue;
        if (!hadSelection && !hadHover)
            return;

        _sections.ClearSelection();
        _hoveredSectionPlaneId = null;
        _sectionGizmoHovered = GlesTransformGizmoHandle.None;
        global::Android.Util.Log.Info("FA.Section", $"Section selection cleared: reason={reason}.");
        UpdateSectionRendererState();
        UpdateSectionButtonStates();
    }

    private void ClearSelectableOverlaySelection(string reason)
    {
        ClearSelectedMeasurement(reason);
        ClearSelectedSectionPlane(reason);
    }

    private bool CanSelectMeasurementLabels()
        => _activeModalTool == AndroidModalTool.Select
           || _activeModalTool == AndroidModalTool.Measure
           || _activeModalTool == AndroidModalTool.Section;

    private MeasurementLabelKey? ResolveMeasurementDeleteTarget(IReadOnlyList<PresentationSnapshot> presentation)
    {
        if (_measure?.SelectedMeasurementId is not { } selectedId)
            return null;

        if (_selectedMeasurementDeleteTarget is { } current
            && current.Id.Equals(selectedId)
            && PresentationContainsLabelKey(presentation, current))
        {
            return current;
        }

        foreach (PresentationSnapshot snapshot in presentation)
        {
            if (snapshot.Id is { } id && id.Equals(selectedId) && snapshot.Labels.Count > 0)
                return new MeasurementLabelKey(id, 0);
        }

        return null;
    }

    private static bool PresentationContainsLabelKey(
        IReadOnlyList<PresentationSnapshot> presentation,
        MeasurementLabelKey key)
    {
        foreach (PresentationSnapshot snapshot in presentation)
        {
            if (snapshot.Id is { } id
                && id.Equals(key.Id)
                && key.LabelIndex >= 0
                && key.LabelIndex < snapshot.Labels.Count)
            {
                return true;
            }
        }

        return false;
    }

    private bool TryProjectWorldToViewport(Vector3d world, out double screenX, out double screenY)
    {
        screenX = 0;
        screenY = 0;
        if (_viewport is null || _camera is null || _viewport.Width <= 0 || _viewport.Height <= 0)
            return false;

        try
        {
            CameraState? camera = SnapshotCamera();
            if (camera is null)
                return false;

            double aspect = (double)_viewport.Width / _viewport.Height;
            Matrix4d view = camera.GetViewMatrix();
            Matrix4d projection = camera.GetProjectionMatrix(aspect);
            Matrix4d viewProjection = projection * view;
            if (!viewProjection.TryProjectPoint(world, out Vector3d ndc))
                return false;

            if (!double.IsFinite(ndc.X) || !double.IsFinite(ndc.Y) || !double.IsFinite(ndc.Z))
                return false;
            if (ndc.Z < -1.05 || ndc.Z > 1.05)
                return false;

            double x = (ndc.X * 0.5 + 0.5) * _viewport.Width;
            double y = (0.5 - ndc.Y * 0.5) * _viewport.Height;
            if (!double.IsFinite(x) || !double.IsFinite(y))
                return false;

            screenX = x;
            screenY = y;
            return true;
        }
        catch (Exception ex) when (ex is not OutOfMemoryException and not StackOverflowException)
        {
            global::Android.Util.Log.Warn("FA.Measure", "Measurement label projection failed: " + ex.Message);
            return false;
        }
    }

    private int LabelColor(PresentationStyle style) => style switch
    {
        PresentationStyle.Preview => GetColor(Resource.Color.fa_measure_label_preview),
        PresentationStyle.Selected => DimensionHighlightColor(),
        PresentationStyle.Hovered => DimensionHighlightColor(0.75f),
        PresentationStyle.Warning => GetColor(Resource.Color.fa_measure_label_warning),
        PresentationStyle.SnapHint => GetColor(Resource.Color.fa_measure_label_snap_hint),
        _ => GetColor(Resource.Color.fa_measure_label_default),
    };

    private static int DimensionHighlightColor(float scale = 1.0f)
        => Color.Rgb(
            UnitColorByte(AppSettings.DimensionHighlightR, scale),
            UnitColorByte(AppSettings.DimensionHighlightG, scale),
            UnitColorByte(AppSettings.DimensionHighlightB, scale));

    private static int UnitColorByte(float value, float scale)
        => (int)System.Math.Clamp(
            System.Math.Round(System.Math.Clamp(value, 0.0f, 1.0f) * System.Math.Max(scale, 0.0f) * 255.0f),
            0.0,
            255.0);

    private void LogMeasurementOverlayState(
        IReadOnlyList<PresentationSnapshot> presentation,
        IReadOnlyList<FaceHighlight> faceHighlights)
    {
        CountPresentation(presentation, out int balls, out int disks, out int lines, out int labels);
        int faceVertices = 0;
        foreach (FaceHighlight highlight in faceHighlights)
            faceVertices += highlight.WorldVertices.Count;

        string key = $"{presentation.Count}|{balls}|{disks}|{lines}|{labels}|{faceHighlights.Count}|{faceVertices}|{_measure?.ActiveMode}";
        if (key == _lastMeasurementOverlayLogKey)
            return;

        _lastMeasurementOverlayLogKey = key;
        global::Android.Util.Log.Info(
            "FA.Measure",
            $"Overlay assigned: snapshots={presentation.Count}, balls={balls}, disks={disks}, lines={lines}, labels={labels}, faceHighlights={faceHighlights.Count}, faceVertices={faceVertices}, mode={_measure?.ActiveMode.ToString() ?? "<null>"}.");
    }

    private void LogMeasurementLabelState(
        IReadOnlyList<PresentationSnapshot> presentation,
        int projected,
        int skipped)
    {
        int labels = CountLabels(presentation);
        string key = $"{labels}|{projected}|{skipped}|{_measurementLabelLayer?.ChildCount ?? 0}|{_viewport?.Width ?? 0}x{_viewport?.Height ?? 0}";
        if (key == _lastMeasurementLabelLogKey)
            return;

        _lastMeasurementLabelLogKey = key;
        global::Android.Util.Log.Info(
            "FA.Measure",
            $"Labels updated: total={labels}, projected={projected}, skipped={skipped}, views={_measurementLabelLayer?.ChildCount ?? 0}, viewport={_viewport?.Width ?? 0}x{_viewport?.Height ?? 0}.");
    }

    private static int CountLabels(IReadOnlyList<PresentationSnapshot> presentation)
    {
        CountPresentation(presentation, out _, out _, out _, out int labels);
        return labels;
    }

    private static void CountPresentation(
        IReadOnlyList<PresentationSnapshot> presentation,
        out int balls,
        out int disks,
        out int lines,
        out int labels)
    {
        balls = 0;
        disks = 0;
        lines = 0;
        labels = 0;
        foreach (PresentationSnapshot snapshot in presentation)
        {
            balls += snapshot.Balls.Count;
            disks += snapshot.Disks.Count;
            lines += snapshot.Lines.Count;
            labels += snapshot.Labels.Count;
        }
    }

