    private static void FrameCameraToBounds(CameraState camera, BoundingBox bounds, double aspect, Vector3d preferredUp)
    {
        if (!bounds.IsValid) return;
        double diagonal = bounds.Diagonal;
        if (!double.IsFinite(diagonal) || diagonal <= 0.0)
            diagonal = 1.0;
        camera.MinOrthoWidth = diagonal * 0.001;
        camera.MaxOrthoWidth = diagonal * 100.0;
        camera.FitToBox(bounds, aspect);
        if (preferredUp.LengthSquared <= 1e-12 || !IsFinite(preferredUp))
            preferredUp = Vector3d.UnitZ;
        preferredUp = preferredUp.Normalized();
        camera.UpDirection = preferredUp;
        camera.WorldUpDirection = preferredUp;
    }

    private static void FitCameraToBoundsPreservingView(CameraState camera, BoundingBox bounds, double aspect)
    {
        if (!bounds.IsValid) return;
        double diagonal = bounds.Diagonal;
        if (!double.IsFinite(diagonal) || diagonal <= 0.0)
            diagonal = 1.0;
        camera.MinOrthoWidth = diagonal * 0.001;
        camera.MaxOrthoWidth = diagonal * 100.0;
        camera.FitToBox(bounds, aspect);
    }

    private BoundingBox GetFullSceneBounds()
    {
        if (_viewport?.Renderer.Scene?.Bounds is { IsValid: true } rendererBounds)
            return rendererBounds;
        if (_runtimeScene?.Bounds is { IsValid: true } runtimeBounds)
            return runtimeBounds;
        return BoundingBox.Empty;
    }

    private BoundingBox GetCameraClipBounds()
        => AndroidCameraClipPlanes.IncludeGroundGrid(
            GetFullSceneBounds(),
            AppSettings.ShowGrid,
            AppSettings.ShiftGridToModelMin);

    private BoundingBox GetVisibleSceneBounds()
    {
        Scene? scene = _runtimeScene;
        if (scene is null)
            return GetFullSceneBounds();

        BoundingBox bounds = BoundingBox.Empty;
        foreach (SceneNode node in scene.GetVisibleNodes())
        {
            if (node.MeshId is not int meshId)
                continue;
            MeshDto? mesh = scene.GetMesh(meshId);
            if (mesh is not { Bounds.IsValid: true })
                continue;

            BoundingBox worldBounds = SceneBoundsUtilities.TransformBounds(mesh.Bounds, node.EffectiveWorldTransform);
            bounds.Merge(worldBounds);
        }

        return bounds.IsValid ? bounds : GetFullSceneBounds();
    }

    private void ShowError(string title, string message)
    {
        ShowOwnedDialog(
            new AlertDialog.Builder(this)
                .SetTitle(title)!
                .SetMessage(message)!
                .SetPositiveButton("OK", (_, _) => { })!);
    }

    private void CreateRenderBusyOverlay(FrameLayout container)
    {
        _renderBusyOverlay = new FrameLayout(this)
        {
            Visibility = ViewStates.Gone,
            Clickable = false,
            Focusable = false,
            Alpha = 0f,
        };
        container.AddView(_renderBusyOverlay, new FrameLayout.LayoutParams(
            ViewGroup.LayoutParams.MatchParent,
            ViewGroup.LayoutParams.MatchParent));

        var card = new MaterialCardView(this);
        card.SetCardBackgroundColor(GetColorCompat(Resource.Color.fa_surface_background));
        card.Radius = Dp(8);
        card.StrokeWidth = Dp(1);
        card.SetStrokeColor(ColorStateList.ValueOf(GetColorCompat(Resource.Color.fa_border)));
        card.Elevation = Dp(5);

        var cardParams = new FrameLayout.LayoutParams(
            ViewGroup.LayoutParams.WrapContent,
            Dp(48),
            GravityFlags.Bottom | GravityFlags.CenterHorizontal);
        cardParams.BottomMargin = Dp(18);
        _renderBusyOverlay.AddView(card, cardParams);

        var row = new LinearLayout(this) { Orientation = Orientation.Horizontal };
        row.SetGravity(GravityFlags.CenterVertical);
        row.SetPadding(Dp(14), 0, Dp(16), 0);
        card.AddView(row, new FrameLayout.LayoutParams(
            ViewGroup.LayoutParams.WrapContent,
            ViewGroup.LayoutParams.MatchParent));

        var spinner = new ProgressBar(this) { Indeterminate = true };
        spinner.IndeterminateTintList = ColorStateList.ValueOf(GetColorCompat(Resource.Color.fa_accent_500));
        var spinnerParams = new LinearLayout.LayoutParams(Dp(24), Dp(24));
        spinnerParams.RightMargin = Dp(10);
        row.AddView(spinner, spinnerParams);

        _renderBusyDetail = new TextView(this)
        {
            Text = "Updating render...",
            Ellipsize = TextUtils.TruncateAt.End,
        };
        _renderBusyDetail.SetSingleLine(true);
        _renderBusyDetail.SetTextColor(GetColorCompat(Resource.Color.fa_text_primary));
        _renderBusyDetail.SetTextSize(ComplexUnitType.Px, Dp(13));
        row.AddView(_renderBusyDetail, new LinearLayout.LayoutParams(
            ViewGroup.LayoutParams.WrapContent,
            ViewGroup.LayoutParams.WrapContent));
    }

    private void ShowRenderBusy(string detail)
    {
        void Apply()
        {
            if (_renderBusyDetail is not null)
                _renderBusyDetail.Text = detail;

            if (_renderBusyOverlay is null)
                return;

            _renderBusyOverlay.Animate()?.Cancel();
            _renderBusyOverlay.Visibility = ViewStates.Visible;
            _renderBusyOverlay.Alpha = 0f;
            _renderBusyOverlay.Animate()?.Alpha(1f)?.SetDuration(100)?.Start();
        }

        if (Looper.MyLooper() == Looper.MainLooper)
            Apply();
        else
            RunOnUiThread(Apply);
    }

    private void HideRenderBusy(int busyVersion)
    {
        void Apply()
        {
            if (busyVersion != Volatile.Read(ref _renderModeBusyVersion) || _renderBusyOverlay is null)
                return;

            _renderBusyOverlay.Animate()?.Cancel();
            _renderBusyOverlay.Alpha = 0f;
            _renderBusyOverlay.Visibility = ViewStates.Gone;
        }

        if (Looper.MyLooper() == Looper.MainLooper)
            Apply();
        else
            RunOnUiThread(Apply);
    }

    private void CreateLoadingOverlay()
    {
        var content = FindViewById<ViewGroup>(global::Android.Resource.Id.Content);
        if (content is null) return;

        _loadingOverlay = new FrameLayout(this)
        {
            Visibility = ViewStates.Gone,
            Clickable = true,
            Focusable = true,
            Alpha = 0f,
        };
        _loadingOverlay.SetBackgroundColor(GetColorCompat(Resource.Color.fa_overlay_scrim));
        content.AddView(_loadingOverlay, new FrameLayout.LayoutParams(
            ViewGroup.LayoutParams.MatchParent,
            ViewGroup.LayoutParams.MatchParent));

        var card = new MaterialCardView(this);
        card.SetCardBackgroundColor(GetColorCompat(Resource.Color.fa_surface_background));
        card.Radius = Dp(8);
        card.StrokeWidth = Dp(1);
        card.SetStrokeColor(ColorStateList.ValueOf(GetColorCompat(Resource.Color.fa_border)));
        card.Elevation = Dp(6);

        int screenWidth = Resources?.DisplayMetrics?.WidthPixels ?? Dp(360);
        int cardWidth = Math.Min(Dp(360), Math.Max(Dp(280), screenWidth - Dp(48)));
        var cardParams = new FrameLayout.LayoutParams(cardWidth, ViewGroup.LayoutParams.WrapContent, GravityFlags.Center);
        _loadingOverlay.AddView(card, cardParams);

        var inner = new LinearLayout(this) { Orientation = Orientation.Vertical };
        inner.SetPadding(Dp(18), Dp(16), Dp(18), Dp(14));
        card.AddView(inner);

        var row = new LinearLayout(this) { Orientation = Orientation.Horizontal };
        row.SetGravity(GravityFlags.CenterVertical);
        inner.AddView(row, new LinearLayout.LayoutParams(
            ViewGroup.LayoutParams.MatchParent,
            ViewGroup.LayoutParams.WrapContent));

        var spinner = new ProgressBar(this) { Indeterminate = true };
        spinner.IndeterminateTintList = ColorStateList.ValueOf(GetColorCompat(Resource.Color.fa_accent_500));
        var spinnerParams = new LinearLayout.LayoutParams(Dp(34), Dp(34));
        spinnerParams.RightMargin = Dp(14);
        row.AddView(spinner, spinnerParams);

        var textGroup = new LinearLayout(this) { Orientation = Orientation.Vertical };
        textGroup.LayoutParameters = new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WrapContent, 1f);
        row.AddView(textGroup);

        var title = new TextView(this) { Text = "Loading model" };
        title.SetTextColor(GetColorCompat(Resource.Color.fa_text_primary));
        title.SetTypeface(title.Typeface, TypefaceStyle.Bold);
        title.SetTextSize(ComplexUnitType.Px, Dp(16));
        textGroup.AddView(title);

        _loadingDetail = new TextView(this)
        {
            Text = "Starting...",
            Ellipsize = TextUtils.TruncateAt.End,
        };
        _loadingDetail.SetSingleLine(true);
        _loadingDetail.SetTextColor(GetColorCompat(Resource.Color.fa_text_secondary));
        _loadingDetail.SetTextSize(ComplexUnitType.Px, Dp(12));
        textGroup.AddView(_loadingDetail);

        _loadingCancelButton = new MaterialButton(this, null, Resource.Attribute.materialButtonOutlinedStyle)
        {
            Text = "Cancel",
        };
        _loadingCancelButton.SetMinWidth(0);
        _loadingCancelButton.SetPadding(Dp(12), 0, Dp(12), 0);
        _loadingCancelButton.SetTextColor(GetColorCompat(Resource.Color.fa_accent_500));
        _loadingCancelButton.SetTextSize(ComplexUnitType.Px, Dp(12));
        _loadingCancelButton.Click += OnLoadingCancelClicked;
        var cancelParams = new LinearLayout.LayoutParams(ViewGroup.LayoutParams.WrapContent, Dp(36));
        cancelParams.LeftMargin = Dp(12);
        row.AddView(_loadingCancelButton, cancelParams);

        var bar = new ProgressBar(this, null, global::Android.Resource.Attribute.ProgressBarStyleHorizontal)
        {
            Indeterminate = true,
        };
        bar.IndeterminateTintList = ColorStateList.ValueOf(GetColorCompat(Resource.Color.fa_accent_500));
        var barParams = new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MatchParent, Dp(3));
        barParams.TopMargin = Dp(14);
        inner.AddView(bar, barParams);
    }

    private void OnLoadingCancelClicked(object? sender, EventArgs e)
    {
        CancellationTokenSource? loadCts = SnapshotActiveLoad();
        CancellationTokenSource? cloudCts = _cloudOpenCts;
        if (loadCts is null && cloudCts is null)
            return;

        if (_loadingCancelButton is not null)
            _loadingCancelButton.Enabled = false;
        UpdateLoadingDetail("Canceling...");
        if (loadCts is not null)
            loadCts.Cancel();
        else
            cloudCts?.Cancel();
    }

    private void ShowLoading(string detail)
    {
        UpdateLoadingDetail(detail);
        if (_loadingCancelButton is not null)
            _loadingCancelButton.Enabled = true;
        SetImportNavigationEnabled(false);

        if (_loadingOverlay is null) return;
        _loadingOverlay.Animate()?.Cancel();
        _loadingOverlay.Visibility = ViewStates.Visible;
        _loadingOverlay.BringToFront();
        _loadingOverlay.Alpha = 0f;
        _loadingOverlay.Animate()?.Alpha(1f)?.SetDuration(140)?.Start();
    }

    private void HideLoading()
    {
        SetImportNavigationEnabled(true);
        if (_loadingOverlay is null) return;
        _loadingOverlay.Animate()?.Cancel();
        _loadingOverlay.Alpha = 0f;
        _loadingOverlay.Visibility = ViewStates.Gone;
    }

    private void UpdateLoadingDetail(string message)
    {
        if (_loadingDetail is null) return;
        string text = SimplifyLoadingDetail(message);

        void Apply()
        {
            if (_loadingDetail.TextFormatted?.ToString() != text)
                _loadingDetail.Text = text;
        }

        if (Looper.MyLooper() == Looper.MainLooper)
            Apply();
        else
            RunOnUiThread(Apply);
    }

    private static string SimplifyLoadingDetail(string? message)
    {
        if (string.IsNullOrWhiteSpace(message))
            return "Loading...";

        string normalized = message.Trim().ToLowerInvariant();
        if (normalized.Contains("cancel"))
            return "Canceling...";
        if (normalized.Contains("first frame") || normalized.Contains("render"))
            return "Rendering...";
        if (normalized.Contains("gpu") || normalized.Contains("resource") || normalized.Contains("upload"))
            return "Uploading...";
        if (normalized.Contains("copy"))
            return "Copying...";
        if (normalized.Contains("draco") || normalized.Contains("compress") || normalized.Contains("decod"))
            return "Decoding...";
        if (normalized.Contains("manifest")
            || normalized.Contains("metadata")
            || normalized.Contains("bom")
            || normalized.Contains("drawing")
            || normalized.Contains("inspect")
            || normalized.Contains("read"))
        {
            return "Reading...";
        }
        if (normalized.Contains("cache") || normalized.Contains("normaliz") || normalized.Contains("link"))
            return "Preparing...";
        if (normalized.Contains("ready") || normalized.Contains("imported"))
            return "Ready";

        return "Importing...";
    }

    private bool IsCurrentLoad(int loadVersion, CancellationTokenSource cts)
    {
        lock (_loadGate)
        {
            return !_isDestroyed
                   && loadVersion == Volatile.Read(ref _loadVersion)
                   && ReferenceEquals(_loadCts, cts);
        }
    }

    private bool HasActiveLoad()
    {
        lock (_loadGate)
            return _loadCts is not null;
    }

    private int BeginReplacingActiveLoad(CancellationTokenSource cts, out CancellationTokenSource? previous)
    {
        lock (_loadGate)
        {
            int loadVersion = unchecked(_loadVersion + 1);
            if (loadVersion == 0)
                loadVersion = 1;

            _loadVersion = loadVersion;
            previous = _loadCts;
            _loadCts = cts;
            return loadVersion;
        }
    }

    private bool TryBeginExclusiveLoad(CancellationTokenSource cts, out int loadVersion)
    {
        lock (_loadGate)
        {
            if (_isDestroyed || _loadCts is not null)
            {
                loadVersion = Volatile.Read(ref _loadVersion);
                return false;
            }

            loadVersion = unchecked(_loadVersion + 1);
            if (loadVersion == 0)
                loadVersion = 1;

            _loadVersion = loadVersion;
            _loadCts = cts;
            return true;
        }
    }

    private bool ClearActiveLoad(CancellationTokenSource cts)
    {
        lock (_loadGate)
        {
            if (!ReferenceEquals(_loadCts, cts))
                return false;

            _loadCts = null;
            return true;
        }
    }

    private CancellationTokenSource? SnapshotActiveLoad()
    {
        lock (_loadGate)
            return _loadCts;
    }

    private CancellationTokenSource? TakeActiveLoad()
    {
        lock (_loadGate)
        {
            CancellationTokenSource? cts = _loadCts;
            _loadCts = null;
            unchecked { _loadVersion++; }
            return cts;
        }
    }

    private void ObserveLifecycleTask(Task task, string operation)
    {
        _ = ObserveLifecycleTaskAsync(task, operation);
    }

    private static async Task ObserveLifecycleTaskAsync(Task task, string operation)
    {
        try
        {
            await task.ConfigureAwait(false);
        }
        catch (System.OperationCanceledException)
        {
        }
        catch (Exception ex)
        {
            global::Android.Util.Log.Warn(
                "FA.Lifecycle",
                Java.Lang.Throwable.FromException(ex),
                $"{operation} failed: {ex.GetBaseException().Message}");
        }
    }

    private static bool IsFileAccessRevoked(Exception ex)
        => ex is Java.Lang.SecurityException
           || ex is UnauthorizedAccessException
           || ex is FileNotFoundException
           || (ex is IOException ioEx && IsAccessRevokedMessage(ioEx.Message))
           || ex.InnerException is not null && IsFileAccessRevoked(ex.InnerException);

    private static bool IsAccessRevokedMessage(string? message)
    {
        if (string.IsNullOrWhiteSpace(message))
            return false;

        return message.Contains("permission", StringComparison.OrdinalIgnoreCase)
               || message.Contains("denied", StringComparison.OrdinalIgnoreCase)
               || message.Contains("revoked", StringComparison.OrdinalIgnoreCase)
               || message.Contains("not found", StringComparison.OrdinalIgnoreCase)
               || message.Contains("no such file", StringComparison.OrdinalIgnoreCase);
    }

    private void SetImportNavigationEnabled(bool enabled)
    {
        SetButtonEnabled(_navOpenButton, enabled);
        SetButtonEnabled(_navRecentButton, enabled);
        SetButtonEnabled(_navCloudButton, enabled);
        SetButtonEnabled(_navUndoButton, enabled && _undoService?.CanUndo == true);
        SetButtonEnabled(_navRedoButton, enabled && _undoService?.CanRedo == true);
        SetButtonEnabled(_navModelExplorerButton, enabled);
        SetButtonEnabled(_navBomButton, enabled);
        SetButtonEnabled(_navBomFlatButton, enabled);
        SetButtonEnabled(_navSpenPalmButton, enabled);
        SetButtonEnabled(_navSettingsButton, enabled);
        SetButtonEnabled(_cloudAccountButton, enabled);
    }

    private static void SetButtonEnabled(MaterialButton? button, bool enabled)
    {
        if (button is null) return;
        button.Enabled = enabled;
        button.Alpha = enabled ? 1f : 0.55f;
    }

    public override void OnConfigurationChanged(Configuration newConfig)
    {
        base.OnConfigurationChanged(newConfig);

        _pointerSource?.RefreshDensity(this);
        _recentPanelWidthPx = ClampLeftToolPanelWidth(LeftToolPanelKind.Recent, _recentPanelWidthPx);
        _cloudPanelWidthPx = ClampLeftToolPanelWidth(LeftToolPanelKind.Cloud, _cloudPanelWidthPx);
        _modelExplorerPanelWidthPx = ClampLeftToolPanelWidth(LeftToolPanelKind.ModelExplorer, _modelExplorerPanelWidthPx);
        _bomPanelWidthPx = ClampLeftToolPanelWidth(LeftToolPanelKind.Bom, _bomPanelWidthPx);
        _bomFlatPanelWidthPx = ClampLeftToolPanelWidth(LeftToolPanelKind.BomFlat, _bomFlatPanelWidthPx);
        _settingsPanelWidthPx = ClampLeftToolPanelWidth(LeftToolPanelKind.Settings, _settingsPanelWidthPx);
        if (_leftToolPanelKind != LeftToolPanelKind.None)
            SetCurrentLeftToolPanelWidth(GetCurrentLeftToolPanelWidth());

        _propertiesPanelWidthPx = ClampPropertiesPanelWidth(_propertiesPanelWidthPx);
        SetPropertiesPanelWidth(_propertiesPanelWidthPx);

        ApplySystemBarsForFullscreen(_fullscreenUiActive);
        UpdateBottomToolbarVisibility();
        RebindStyledTooltips();
        RefreshMeasurementOverlays();
        _viewport?.RequestLayout();
        _viewport?.Post(() =>
        {
            if (!_isDestroyed)
                _viewport?.RequestRender();
        });
    }

    protected override void OnPause()
    {
        DismissStyledTooltips();
        CancelHoverPick();
        SetHoveredMesh(0);
        CancelZoomWindowTool("app paused");
        int pausedRenderVersion = Interlocked.Increment(ref _renderModeBusyVersion);
        _renderModeChangeInFlight = false;
        UpdateMainToolButtonStates();
        UpdateRenderModeButtonStates();
        HideRenderBusy(pausedRenderVersion);
        if (SnapshotActiveLoad() is { } loadCts)
        {
            UpdateLoadingDetail("Canceling...");
            loadCts.Cancel();
        }
        if (_cloudOpenCts is { } cloudCts)
        {
            UpdateLoadingDetail("Canceling...");
            cloudCts.Cancel();
        }
        _viewport?.OnPause();
        base.OnPause();
    }

    protected override void OnStop()
    {
        if (!IsFinishing)
            ObserveLifecycleTask(SuspendActiveCloudSessionAsync("activity stopped"), "cloud-session-stop");
        base.OnStop();
    }

    protected override void OnResume()
    {
        base.OnResume();
        _viewport?.OnResume();
        if (_fullscreenUiActive)
            ApplySystemBarsForFullscreen(true);
        ApplySettingsToScene();
        ObserveLifecycleTask(EnsureActiveCloudSessionOnResumeAsync(), "cloud-session-resume");
        ObserveLifecycleTask(ReloadRendererSceneAfterContextLossAsync(), "resume-renderer-reload");
    }

    protected override void OnSaveInstanceState(Bundle outState)
    {
        base.OnSaveInstanceState(outState);
        if (!string.IsNullOrWhiteSpace(_lastLoadedUriText))
            outState.PutString(SavedStateLastLoadedUriKey, _lastLoadedUriText);
        if (!string.IsNullOrWhiteSpace(_activeModelDisplayName))
            outState.PutString(SavedStateModelDisplayNameKey, _activeModelDisplayName);
        if (CaptureCameraState() is { } cameraState)
            outState.PutDoubleArray(SavedStateCameraKey, cameraState);
        if (_selectedNodeIds.Count > 0)
            outState.PutIntArray(SavedStateSelectedNodeIdsKey, _selectedNodeIds.OrderBy(id => id).ToArray());
        var selectedOccurrenceIds = _packageSession?.SelectedOccurrenceIds;
        if (_runtimeScene is { } selectionScene
            && AndroidScenePackageState.IsFa(selectionScene.PackageInfo)
            && selectedOccurrenceIds is { Count: > 0 })
        {
            outState.PutStringArray(
                SavedStateSelectedOccurrencesKey,
                selectedOccurrenceIds.OrderBy(id => id, StringComparer.Ordinal).ToArray());
        }
        if (_explodeAmount > 0.0)
            outState.PutDouble(SavedStateExplodeAmountKey, Math.Clamp(_explodeAmount, 0.0, 1.0));
        if (_activeSectionSubMode != SectionSubMode.None)
            outState.PutString(SavedStateSectionSubModeKey, _activeSectionSubMode.ToString());

        if (_sections?.Planes.Count > 0)
        {
            outState.PutStringArray(
                SavedStateSectionPlanesKey,
                _sections.Planes.Select(SerializeSectionPlane).ToArray());
            outState.PutStringArray(
                SavedStateSelectedSectionPlanesKey,
                _sections.SelectedPlaneIds.Select(id => id.ToString("D")).ToArray());
        }

        if (_runtimeScene is { } scene
            && AndroidScenePackageState.IsFa(scene.PackageInfo)
            && _packageSession is not null)
        {
            outState.PutString(SavedStatePackageIdKey, _packageSession.PackageId);
            outState.PutStringArray(
                SavedStateHiddenOccurrencesKey,
                _packageSession.HiddenOccurrenceIds.OrderBy(id => id, StringComparer.Ordinal).ToArray());
            outState.PutStringArray(
                SavedStateIsolatedOccurrencesKey,
                _packageSession.IsolatedOccurrenceIds.OrderBy(id => id, StringComparer.Ordinal).ToArray());
        }
    }

    public override void OnTrimMemory(TrimMemory level)
    {
        base.OnTrimMemory(level);
        if ((int)level >= (int)TrimMemory.UiHidden
            || level == TrimMemory.RunningLow
            || level == TrimMemory.RunningCritical)
        {
            _measure?.ClearRaycastAccelerationCache(level.ToString());
            _sectionRaycaster?.ClearAccelerationCache(level.ToString());
            _import?.PruneImportCache();
        }

        if (level == TrimMemory.RunningCritical && _viewport is { } viewport)
        {
            _lastLoadedDocumentReleasedForMemoryPressure = _lastLoadedDocument is not null;
            _lastLoadedDocument = null;
            viewport.QueueRendererCommand(
                "trim-gpu-resources",
                _ => viewport.Renderer.TrimTransientGpuResources(),
                logSlow: false);
        }
    }

    public override void OnLowMemory()
    {
        base.OnLowMemory();
        _measure?.ClearRaycastAccelerationCache("low-memory");
    }

    private void OnViewportSurfaceCreated()
        => ObserveLifecycleTask(ReloadRendererSceneAfterContextLossAsync(), "surface-created-renderer-reload");

    private async Task ReloadRendererSceneAfterContextLossAsync()
    {
        var viewport = _viewport;
        Scene? runtimeScene = _runtimeScene;
        DocumentDto? retainedDocument = _lastLoadedDocument;
        string? lastLoadedUriText = _lastLoadedUriText;
        bool documentReleasedForMemoryPressure = _lastLoadedDocumentReleasedForMemoryPressure;
        if (_isDestroyed
            || viewport is null
            || viewport.Renderer.Scene is not null
            || runtimeScene is null
            || HasActiveLoad())
        {
            return;
        }

        var cts = new CancellationTokenSource();
        if (!TryBeginExclusiveLoad(cts, out int loadVersion))
        {
            cts.Dispose();
            return;
        }

        bool loadSlotAcquired = false;
        bool reloadFromUri = false;

        try
        {
            await _loadSemaphore.WaitAsync(cts.Token);
            loadSlotAcquired = true;
            cts.Token.ThrowIfCancellationRequested();
            if (!IsCurrentLoad(loadVersion, cts)
                || _isDestroyed
                || !ReferenceEquals(_runtimeScene, runtimeScene)
                || viewport.Renderer.Scene is not null)
            {
                return;
            }

            if (retainedDocument is not null)
            {
                try
                {
                    global::Android.Util.Log.Warn(
                        "FA.Renderer",
                        "Renderer scene is missing after GL context recreation; re-uploading retained model data.");
                    await LoadDocumentOnRendererAsync(
                        retainedDocument,
                        cts.Token,
                        () => IsCurrentLoad(loadVersion, cts) && ReferenceEquals(_runtimeScene, runtimeScene));

                    cts.Token.ThrowIfCancellationRequested();
                    if (!IsCurrentLoad(loadVersion, cts)
                        || _isDestroyed
                        || !ReferenceEquals(_runtimeScene, runtimeScene))
                    {
                        return;
                    }

                    ApplySettingsToScene();
                    SyncRuntimeSceneTransformsToRenderer("context reload");
                    SyncRuntimeSceneVisibilityToRenderer("context reload");
                    RefreshSelectionDependentUi(
                        runtimeScene,
                        scrollModelExplorerToSelection: false,
                        requestRender: false);
                    UpdateSectionRendererState();
                    UpdateBodyMoveGizmoRendererState();
                    RefreshMeasurementOverlays();
                    viewport.RequestRender();
                    return;
                }
                catch (System.OperationCanceledException) when (cts.IsCancellationRequested)
                {
                    return;
                }
                catch (Exception ex)
                {
                    global::Android.Util.Log.Warn(
                        "FA.Renderer",
                        "Retained model re-upload failed after context recreation; falling back to URI reload: " + ex.Message);
                }
            }

            if (string.IsNullOrWhiteSpace(lastLoadedUriText))
            {
                if (!_isDestroyed)
                {
                    string message = documentReleasedForMemoryPressure
                        ? "Android reclaimed the cached model data under memory pressure. Open the model again to restore the view."
                        : "Open the model again to restore the view after Android reclaimed graphics memory.";
                    ShowError("Model reload required", message);
                }
                return;
            }

            reloadFromUri = true;
        }
        catch (System.OperationCanceledException) when (cts.IsCancellationRequested)
        {
            return;
        }
        finally
        {
            if (loadSlotAcquired)
                _loadSemaphore.Release();

            ClearActiveLoad(cts);
            cts.Dispose();
        }

        if (!reloadFromUri)
            return;

        AndroidUri? uri = AndroidUri.Parse(lastLoadedUriText);
        if (uri is null)
            return;

        global::Android.Util.Log.Warn(
            "FA.Renderer",
            documentReleasedForMemoryPressure
                ? "Renderer scene is missing after memory pressure; reloading the last model from its URI."
                : "Renderer scene is missing after resume; reloading the last model after GL context recreation.");
        bool reloaded = await OpenModelUriAsync(uri, replaceActiveLoad: false);
        if (!reloaded && !_isDestroyed)
            global::Android.Util.Log.Warn("FA.Renderer", "Context-loss URI reload did not complete; the user may need to reopen the model.");
    }

    private void ClearAndroidViewListeners()
