    private void RemoveOwnedOverlayViews()
    {
        RemoveFromParent(_measurementLabelLayer);
        RemoveFromParent(_zoomWindowOverlay);
        RemoveFromParent(_contextMenuAnchor);
        RemoveFromParent(_loadingOverlay);
        RemoveFromParent(_renderBusyOverlay);
