    private AlertDialog ShowOwnedDialog(AlertDialog.Builder builder)
    {
        ArgumentNullException.ThrowIfNull(builder);
        AlertDialog dialog = builder.Create();
        return ShowOwnedDialog(dialog);
    }

    private T ShowOwnedDialog<T>(T dialog) where T : global::Android.App.Dialog
    {
        _ownedDialogs.Add(dialog);
        dialog.Show();
        return dialog;
    }

    private sealed class DialogDismissListener : Java.Lang.Object, IDialogInterfaceOnDismissListener
    {
        private readonly Action _onDismiss;

        public DialogDismissListener(Action onDismiss)
            => _onDismiss = onDismiss;

        public void OnDismiss(IDialogInterface? dialog)
            => _onDismiss();
    }

    private void DismissOwnedDialogs()
    {
        foreach (global::Android.App.Dialog dialog in _ownedDialogs.ToArray())
        {
            try
            {
                if (dialog.IsShowing)
                    dialog.Dismiss();
            }
            catch (Exception ex) when (ex is not OutOfMemoryException and not StackOverflowException)
            {
                global::Android.Util.Log.Warn("FA.Dialog", "Failed to dismiss owned dialog: " + ex.Message);
            }
        }

        _ownedDialogs.Clear();
    }

    private static void RemoveFromParent(View? view)
    {
        if (view?.Parent is ViewGroup parent)
            parent.RemoveView(view);
    }

    protected override void OnDestroy()
    {
        _isDestroyed = true;
        _activityDestroyCts.Cancel();
        Interlocked.Increment(ref _loadVersion);
        var loadCts = TakeActiveLoad();
        loadCts?.Cancel();
        loadCts?.Dispose();
        CancellationTokenSource? cloudOpenCts = Interlocked.Exchange(ref _cloudOpenCts, null);
        cloudOpenCts?.Cancel();
        cloudOpenCts?.Dispose();
        ReleaseActiveCloudSessionForDestroy();
        DismissOwnedDialogs();

        if (_camera is not null)
            _camera.PropertyChanged -= OnCameraChanged;
        if (_sections is not null)
            _sections.Changed -= OnSectionsChanged;
        if (_bodyMove is not null)
            _bodyMove.MovesCommitted -= OnBodyMovesCommitted;
        if (_undoService is not null)
        {
            _undoService.HistoryChanged -= OnUndoHistoryChanged;
            _undoService.UndoFailed -= OnUndoFailed;
        }
        if (_undoSelectionState is not null)
            _undoSelectionState.SelectionChanged -= OnUndoSelectionChanged;
        _bodyMove = null;
        _undoSelectionState = null;
        _visibilityStateAccess = null;
        _measurementStoreAccess = null;
        _undoService = null;

        DisposeLeftToolPanelContent();
        ClearAndroidViewListeners();
        if (_pointerSource is not null)
            _pointerSource.GestureRecognized -= OnGestureForToolbarTools;
        if (_pointerSource is not null)
            _pointerSource.GestureRecognized -= OnGestureForNavigation;
        if (_pointerSource is not null)
            _pointerSource.GestureRecognized -= OnGestureForSelection;
        _pointerSource?.Dispose();
        _pointerSource = null;
        _measure?.Dispose();
        _measure = null;
        _modelExplorerPanel?.Dispose();
        _modelExplorerPanel = null;
        _picker?.Dispose();
        _picker = null;
        if (_cloudClient is not null)
            _cloudClient.SessionChanged -= OnCloudSessionChanged;
        if (_cloudNotifications is not null)
            _cloudNotifications.EventReceived -= OnCloudNotificationReceived;
        _cloudNotifications = null;
        _cloudClient = null;
        DisposeStyledTooltips();
        RemoveOwnedOverlayViews();

        if (_viewport is not null)
        {
            var viewport = _viewport;
            viewport.RendererSurfaceCreated -= OnViewportSurfaceCreated;
            try
            {
                viewport.DisposeRendererOnGlThread();
            }
            catch (Exception ex)
            {
                global::Android.Util.Log.Warn("FA.Import", "Failed to queue final GPU scene disposal: " + ex.Message);
            }
        }

        if (_services is IDisposable disposableServices)
            disposableServices.Dispose();
        _services = null;

        // S2#2: dispose the long-lived synchronization primitives (readonly
        // fields that were only Cancel()'d above, never disposed) so the
        // activity does not leak a CancellationTokenSource + two SemaphoreSlim
        // handles on each recreation.
        _activityDestroyCts.Dispose();
        _loadSemaphore.Dispose();
        _cloudSessionGate.Dispose();

        base.OnDestroy();
    }

    /// <summary>
    /// Pull every AppSettings value the renderer + interaction adapter can
    /// consume live. Called on every OnResume so changes made in settings
    /// take effect the moment the user returns.
    /// </summary>
    private void ApplySettingsToScene()
    {
        if (_viewport is not null)
        {
            var viewport = _viewport;
            // AppSettings.Apply assigns every SceneAppearance field; starting
            // from default avoids allocating color arrays that are overwritten
            // before the renderer snapshot is queued.
            SceneAppearance appearance = default;
            AppSettings.Apply(ref appearance);
            bool requestedPerspective = appearance.IsPerspective;
            bool effectivePerspective = _isInFixedView ? false : requestedPerspective;
            appearance.IsPerspective = effectivePerspective;
            appearance = appearance.CreateRendererSnapshot();
            if (_camera is not null)
            {
                double aspect = GetViewportAspect();
                lock (_camera)
                {
                    if (!_isInFixedView)
                        _isoIsPerspective = requestedPerspective;

                    _camera.SetProjectionMode(effectivePerspective, aspect);
                    BoundingBox clipBounds = GetCameraClipBounds();
                    if (clipBounds.IsValid)
                        AndroidCameraClipPlanes.Update(_camera, clipBounds);
                    LogProjectionState(requestedPerspective, aspect);
                }
            }
            bool highlightSelection = AppSettings.ShowSelectionHighlight;
            Vector3 dimensionHighlightColor = new(
                AppSettings.DimensionHighlightR,
                AppSettings.DimensionHighlightG,
                AppSettings.DimensionHighlightB);
            Vector4 measurementFaceSelectionColor = new(
                AppSettings.MeasurementFaceSelectionR,
                AppSettings.MeasurementFaceSelectionG,
                AppSettings.MeasurementFaceSelectionB,
                0.38f);
            Vector4 measurementFaceHoverColor = new(
                AppSettings.MeasurementFaceHoverR,
                AppSettings.MeasurementFaceHoverG,
                AppSettings.MeasurementFaceHoverB,
                0.30f);
            viewport.QueueRendererCommand("apply-settings", _ =>
            {
                viewport.Renderer.Appearance = appearance;
                viewport.Renderer.HighlightSelection = highlightSelection;
                viewport.Renderer.DimensionHighlightColor = dimensionHighlightColor;
                viewport.Renderer.MeasurementFaceSelectionColor = measurementFaceSelectionColor;
                viewport.Renderer.MeasurementFaceHoverColor = measurementFaceHoverColor;
            });
            viewport.RequestRender();
        }
        ApplySectionSettings();
        UpdateBodyMoveGizmoRendererState();
        ApplyMeasurementSettings();
        ApplySpenPalmRejectionState(showToast: false);
        RefreshMeasurementOverlays();
        if (_interaction is not null)
        {
            _interaction.OrbitSensitivityMultiplier = AppSettings.OrbitSensitivity;
            _interaction.PanSensitivityMultiplier = AppSettings.PanSensitivity;
            _interaction.ZoomSensitivityMultiplier = AppSettings.ZoomSensitivity;
            _interaction.MouseOrbitSpeedMultiplier = AppSettings.MouseOrbitSpeed;
            _interaction.MousePanSpeedMultiplier = AppSettings.MousePanSpeed;
            _interaction.MouseWheelZoomSpeedMultiplier = AppSettings.MouseWheelZoomSpeed;
            _interaction.MouseWheelZoomInverted = AppSettings.MouseInvertWheelZoom;
        }
        if (_pointerSource is not null)
            _pointerSource.MouseClickDragThresholdDip = AppSettings.MouseDragThresholdDip;

        // S11#1: preferences may have changed the render mode / edges, so refresh
        // the render-mode toolbar selected-state to match (it otherwise only
        // updated on an explicit toolbar click).
        UpdateRenderModeButtonStates();
    }

    private void ApplySectionSettings()
    {
        if (_sections is not null)
        {
            if (_sections.FillVisible != AppSettings.SectionFillVisible)
                _sections.FillVisible = AppSettings.SectionFillVisible;

            if (_sections.EdgesVisible != AppSettings.SectionEdgesVisible)
                _sections.EdgesVisible = AppSettings.SectionEdgesVisible;

            if (!_sections.EdgesVisible && (_sections.SelectedPlaneIds.Count > 0 || _hoveredSectionPlaneId.HasValue))
            {
                ClearSelectedSectionPlane("section edges hidden");
                RefreshMeasurementOverlays();
            }
        }

        UpdateSectionButtonStates();
        UpdateSectionRendererState();
    }

    private void ApplyMeasurementSettings()
    {
        _measure?.ApplySettings(
            AppSettings.MeasureMultiMeasureEnabled,
            AppSettings.MeasureShowDeltaBreakdown,
            MeasureBoxModeFromSettings(),
            AppSettings.MeasurePointSnapEnabled,
            AppSettings.MeasureEndpointSnapEnabled,
            AppSettings.MeasureMidpointSnapEnabled,
            AppSettings.MeasureSnapEdgeFactor,
            AppSettings.MeasureSnapEndpointFactor,
            AppSettings.CadEdgeWeldToleranceScale,
            AppSettings.MeasureSnapVisibleEdgesOnly,
            AppSettings.MeasureSnapVisibilityProbe,
            AppSettings.MeasureSnapOcclusionToleranceFactor);
        _measure?.ApplySectionVisibility(
            AppSettings.SectionCurvesVisible,
            AppSettings.SectionCapsVisible);

        if (_measure is null || !_measure.IsActive)
            _lastInteractiveMeasureMode = MeasureModeFromSettings();
    }

    private static MeasureToolMode MeasureModeFromSettings() => AppSettings.MeasureModeSelectionIndex switch
    {
        1 => MeasureToolMode.FaceToPoint,
        2 => MeasureToolMode.FaceToFace,
        _ => MeasureToolMode.PointToPoint,
    };

    private static int MeasureModeToSettingsIndex(MeasureToolMode mode) => mode switch
    {
        MeasureToolMode.FaceToPoint => 1,
        MeasureToolMode.FaceToFace => 2,
        _ => 0,
    };

    private static BoundingBoxMode MeasureBoxModeFromSettings() => AppSettings.MeasureBoxModeSelectionIndex == 0
        ? BoundingBoxMode.AxisAligned
        : BoundingBoxMode.BestFit;

    private double GetViewportAspect()
    {
        if (_viewport is { Width: > 0, Height: > 0 })
            return (double)_viewport.Width / _viewport.Height;
        return 1.0;
    }

    private double GetViewportWidthDip()
    {
        if (_viewport is not { Width: > 0 })
            return 0.0;

        float density = Resources?.DisplayMetrics?.Density ?? 1.0f;
        if (density <= 0f)
            density = 1.0f;

        return _viewport.Width / density;
    }

    private CameraState? SnapshotCamera()
    {
        CameraState? camera = _camera;
        if (camera is null)
            return null;

        lock (camera)
            return camera.Clone();
    }

    private int Dp(float dp) => (int)(dp * (Resources?.DisplayMetrics?.Density ?? 1.0f));

    private Color GetColorCompat(int resId) => new(GetColor(resId));

    private Vector4 GetColorVector4(int resId)
    {
        Color color = GetColorCompat(resId);
        return new Vector4(
            color.R / 255.0f,
            color.G / 255.0f,
            color.B / 255.0f,
            color.A / 255.0f);
    }

    private static void SetMarginTop(View view, int px)
    {
        if (view.LayoutParameters is ViewGroup.MarginLayoutParams margin)
        {
            margin.TopMargin = px;
            view.LayoutParameters = margin;
            return;
        }

        var layoutParams = new ViewGroup.MarginLayoutParams(
            ViewGroup.LayoutParams.MatchParent,
            ViewGroup.LayoutParams.WrapContent);
        layoutParams.TopMargin = px;
        view.LayoutParameters = layoutParams;
    }

    private static void SetMarginBottom(View view, int px)
    {
        if (view.LayoutParameters is ViewGroup.MarginLayoutParams margin)
        {
            margin.BottomMargin = px;
            view.LayoutParameters = margin;
            return;
        }

        var layoutParams = new ViewGroup.MarginLayoutParams(
            ViewGroup.LayoutParams.MatchParent,
            ViewGroup.LayoutParams.WrapContent);
        layoutParams.BottomMargin = px;
        view.LayoutParameters = layoutParams;
    }

    private void LogProjectionState(bool requestedPerspective, double aspect)
    {
        CameraState? camera = SnapshotCamera();
        if (camera is null) return;

        string key = $"{requestedPerspective}|{camera.IsPerspective}|{camera.OrthoWidth:0.######}|{camera.NearPlane:0.######}|{camera.FarPlane:0.######}|{aspect:0.######}";
        if (key == _lastProjectionLogKey)
            return;

        _lastProjectionLogKey = key;
        global::Android.Util.Log.Info(
            "FA.Camera",
            $"Projection state: requested={(requestedPerspective ? "Perspective" : "Orthographic")}, effective={(camera.IsPerspective ? "Perspective" : "Orthographic")}, orthoWidth={camera.OrthoWidth:0.###}, near={camera.NearPlane:0.###}, far={camera.FarPlane:0.###}, aspect={aspect:0.###}.");
    }

    private sealed class AndroidVisibilityStateAccess : IVisibilityStateAccess
    {
        private readonly MainActivity _activity;

        public AndroidVisibilityStateAccess(MainActivity activity)
            => _activity = activity;

        public bool GetVisible(int nodeId)
            => _activity._runtimeScene?.GetNode(nodeId)?.Visible ?? true;

        public void SetVisible(int nodeId, bool visible)
        {
            if (_activity._runtimeScene?.GetNode(nodeId) is SceneNode node)
                node.Visible = visible;
        }

        public IReadOnlySet<string> FaHiddenOccurrenceIds
            => _activity._packageSession?.HiddenOccurrenceIds
               ?? new HashSet<string>(StringComparer.Ordinal);

        public IReadOnlySet<string> FaIsolatedOccurrenceIds
            => _activity._packageSession?.IsolatedOccurrenceIds
               ?? new HashSet<string>(StringComparer.Ordinal);

        public void SetFaVisibilityState(IReadOnlyCollection<string> hidden, IReadOnlyCollection<string> isolated)
        {
            Scene? scene = _activity._runtimeScene;
            if (scene is null
                || _activity._packageSession is not { } packageSession
                || !AndroidScenePackageState.IsFa(scene.PackageInfo))
            {
                return;
            }

            bool changed = AndroidScenePackageState.ApplyVisibilityState(scene, packageSession, hidden, isolated);
            if (!changed)
                AndroidScenePackageState.ApplyVisibilityToScene(scene, packageSession);
        }

        public IReadOnlySet<int> XrayOpaqueIds => _activity._xrayOpaqueNodeIds;
        public IReadOnlyList<int> XrayBackgroundIds => _activity._xrayBackgroundNodeIds;
        public double XrayOpacity => _activity._xrayIsolationOpacity;

        public void SetXrayIsolationState(IEnumerable<int> opaqueIds, IEnumerable<int> backgroundIds, double opacity)
            => _activity.SetXrayIsolationState(opaqueIds, backgroundIds, (float)opacity);

        public void ClearXrayIsolation()
            => _activity.ClearXrayIsolationState();

        public VisibilityStateSnapshot SnapshotFor(IEnumerable<int> nodeIds)
        {
            var visibility = new Dictionary<int, bool>();
            Scene? scene = _activity._runtimeScene;
            if (scene is not null)
            {
                foreach (int nodeId in nodeIds.Distinct())
                {
                    if (scene.GetNode(nodeId) is SceneNode node)
                        visibility[nodeId] = node.Visible;
                }
            }

            return CreateSnapshot(visibility);
        }

        public VisibilityStateSnapshot SnapshotAll()
        {
            var visibility = new Dictionary<int, bool>();
            Scene? scene = _activity._runtimeScene;
            if (scene is not null)
            {
                foreach ((int nodeId, SceneNode node) in scene.NodesById)
                {
                    if (!node.Visible)
                        visibility[nodeId] = false;
                }
            }

            return CreateSnapshot(visibility);
        }

        public void RestoreSnapshot(VisibilityStateSnapshot snapshot)
        {
            Scene? scene = _activity._runtimeScene;
            if (scene is not null)
            {
                foreach (SceneNode node in scene.NodesById.Values)
                    node.Visible = true;

                foreach ((int nodeId, bool visible) in snapshot.NodeVisibility)
                {
                    if (scene.GetNode(nodeId) is SceneNode node)
                        node.Visible = visible;
                }

                if (_activity._packageSession is { } packageSession
                    && AndroidScenePackageState.IsFa(scene.PackageInfo))
                {
                    bool changed = AndroidScenePackageState.ApplyVisibilityState(
                        scene,
                        packageSession,
                        snapshot.FaHiddenOccurrenceIds,
                        snapshot.FaIsolatedOccurrenceIds);
                    if (!changed)
                        AndroidScenePackageState.ApplyVisibilityToScene(scene, packageSession);
                }
            }

            int[] opaqueIds = scene is null
                ? Array.Empty<int>()
                : snapshot.XrayOpaqueIds.Where(id => scene.GetNode(id) is not null).ToArray();
            int[] backgroundIds = scene is null
                ? Array.Empty<int>()
                : snapshot.XrayBackgroundIds.Where(id => scene.GetNode(id) is not null).ToArray();
            if (opaqueIds.Length == 0 && backgroundIds.Length == 0)
                _activity.ClearXrayIsolationState();
            else
                _activity.SetXrayIsolationState(opaqueIds, backgroundIds, (float)snapshot.XrayOpacity);
        }

        private VisibilityStateSnapshot CreateSnapshot(IReadOnlyDictionary<int, bool> nodeVisibility)
        {
            PackageSessionState? packageSession = _activity._packageSession;
            return new VisibilityStateSnapshot(
                new Dictionary<int, bool>(nodeVisibility),
                packageSession is null
                    ? new HashSet<string>(StringComparer.Ordinal)
                    : new HashSet<string>(packageSession.HiddenOccurrenceIds, StringComparer.Ordinal),
                packageSession is null
                    ? new HashSet<string>(StringComparer.Ordinal)
                    : new HashSet<string>(packageSession.IsolatedOccurrenceIds, StringComparer.Ordinal),
                new HashSet<int>(_activity._xrayOpaqueNodeIds),
                _activity._xrayBackgroundNodeIds.ToArray(),
                _activity._xrayIsolationOpacity);
        }
    }

    private sealed class AndroidMeasurementStoreAccess : IMeasurementStore
    {
        private readonly MainActivity _activity;

        public AndroidMeasurementStoreAccess(MainActivity activity)
            => _activity = activity;

        private IMeasurementStore? Store => _activity._measure?.Store;

        public IReadOnlyList<MeasurementResult> Snapshot()
            => Store?.Snapshot() ?? Array.Empty<MeasurementResult>();

        public MeasurementId? SelectedId => Store?.SelectedId;
        public MeasurementId? HoveredId => Store?.HoveredId;
        public event EventHandler MeasurementsChanged { add { } remove { } }
        public void Add(MeasurementResult measurement) => Store?.Add(measurement);
        public void Remove(MeasurementId id) => Store?.Remove(id);
        public void Clear() => Store?.Clear();
        public void ToggleVisibility(MeasurementId id) => Store?.ToggleVisibility(id);
        public void Select(MeasurementId? id) => Store?.Select(id);
        public void Hover(MeasurementId? id) => Store?.Hover(id);
    }

    private sealed class ZoomWindowOverlayView : View
    {
        private readonly Paint _fill = new() { AntiAlias = true };

        private readonly Paint _stroke = new()
        {
            StrokeWidth = 2f,
            AntiAlias = true,
        };

        private RectF? _rect;

        public ZoomWindowOverlayView(Context context) : base(context)
        {
            _fill.Color = new Color(context.GetColor(Resource.Color.fa_zoom_window_fill));
            _stroke.Color = new Color(context.GetColor(Resource.Color.fa_accent_500));
            _stroke.SetStyle(Paint.Style.Stroke);
            _fill.SetStyle(Paint.Style.Fill);
        }

        public void SetRect(RectF? rect)
        {
            _rect = rect is null ? null : new RectF(rect);
            Invalidate();
        }

        protected override void OnDraw(Canvas canvas)
        {
            base.OnDraw(canvas);
            if (_rect is not { } rect)
                return;

            canvas.DrawRect(rect, _fill);
            canvas.DrawRect(rect, _stroke);
        }
    }

    /// <summary>
    /// Wraps AndroidPointerSource.OnTouch as a View.IOnTouchListener. The
    /// listener must derive from Java.Lang.Object so it can be passed
    /// through JNI; MainActivity itself already does, but using a small
    /// dedicated object keeps the activity's class hierarchy clean.
    /// </summary>
    private sealed class TouchProxy : Java.Lang.Object, View.IOnTouchListener
    {
        private readonly AndroidPointerSource _source;
        private readonly MainActivity _activity;
        public TouchProxy(AndroidPointerSource source, MainActivity activity)
        {
            _source = source;
            _activity = activity;
        }

        public bool OnTouch(View? v, MotionEvent? e)
        {
            if (_activity.ShouldConsumeViewportTouchViaGestureSource())
            {
                _source.OnTouch(e);
                return true;
            }

            return _activity.OnViewportRawTouch(e) || _source.OnTouch(e);
        }
    }

    private sealed class HoverProxy : Java.Lang.Object, View.IOnHoverListener
    {
        private readonly MainActivity _activity;
        public HoverProxy(MainActivity activity) => _activity = activity;
        public bool OnHover(View? v, MotionEvent? e) => _activity.OnViewportHover(e);
    }

